-- ============================================================
-- Son18b (2/4): Günə-özəl push bildirişlərinin ru+tr tərcüməsi
-- pregnancy_day_notifications (294) + mommy_day_notifications (4370) — Azure/Fable
-- ============================================================

UPDATE public.mommy_day_notifications AS x SET title_ru = v.t, body_ru = v.b
FROM (VALUES
  ('802d0f46-e525-43d0-8f5c-440b82228035'::uuid, 'Терапия песком и листьями 🍂', 'Выбирайтесь из четырёх стен! Найдите среди мест для мам парк с песочницей или просторной зелёной зоной и поддержите сенсорное развитие малыша.'),
  ('ee6e42f5-c128-4ecd-8cea-dcd4ee6be618', 'Отпустите стремление к совершенству ✨', 'Сегодня вы повысили голос на ребёнка? Не мучайте себя чувством вины. Запишите свои переживания в «Дневнике настроения», простите себя и настройтесь на новый день.'),
  ('031932e3-d91b-494c-9f35-dc03d53026b4', 'Обувь стала тесной? 👟', 'В последнее время малыш часто спотыкается во время бега? Возможно, его стопа выросла! Добавьте новые размеры обуви и данные о росте в «Трекер веса», чтобы проанализировать темпы роста.'),
  ('db0a30ff-e18a-4830-abdc-881dc8827a75', 'Питание для мозга: Омега-3 🐟', 'Рыба важна для активного интеллектуального развития. Приготовьте по рецепту вкусные котлеты из рыбы без костей, запечённые в духовке, для малыша, который уже начал прикорм.'),
  ('eb71840a-d8fc-43f9-897d-715c008b72b7', 'Пора замедлиться! 🌙', 'Активный день подходит к концу. Включите таймер сна, завершите шумные игры и переходите к спокойным занятиям (например, собиранию пазлов).'),
  ('36d9b82f-d63f-40d9-bafa-df3b3dc844b9', 'Вкусный перекус за 5 минут! 🥗', 'Днём перекусываете на ходу? Приготовьте тост с авокадо и яйцом по здоровому рецепту для женщин — он надолго насытит и придаст энергии.'),
  ('5db92d40-f36e-4671-8f65-a3cb3f1c91ed', 'Открытия в мире физики во время купания 🛁', 'Добавьте в «Альбом малыша» его серьёзное и сосредоточенное выражение лица, когда он переливает воду из одного пластикового стаканчика в другой. Эти маленькие моменты открытий незабываемы!'),
  ('e18f3a19-4a7e-44e4-9703-5c88f6dda037', 'Слишком много времени проводит перед экраном? 📱', 'Попытка забрать телефон вызывает сильную истерику? Узнайте у Anacan AI, как без стресса ограничить экранное время и установить здоровые границы.'),
  ('2c1e9be8-ccf0-412a-a942-30cea5075e5b', 'Время общаться! 👶', 'Малыш уже стремится быть рядом с другими детьми. Найдите среди мест для мам пространство с детским игровым центром и порадуйте его.'),
  ('cb4b4d68-2b36-4d3f-aa77-92d10314464f', 'Новая еда — новая реакция 💩', 'Вчера малыш съел что-то непривычное или аллергенное? Во время утренней смены подгузника обратите внимание на стул, отметьте в приложении изменения цвета/консистенции и следите за состоянием.'),
  ('fec1f9db-8b95-410a-b753-aded5a7dc606', 'Боится темноты? 🌌', 'Плачет или беспокоится, когда вы выключаете свет в комнате? Включите среди Белых шумов звуки материнской утробы (сердцебиение), чтобы подарить малышу знакомое тепло и чувство защищённости.'),
  ('5c635a69-e5ff-42eb-9277-29e39d9986fa', 'Чистить зубы — весело! 🪥', 'Не подпускает щётку ко рту? Посмотрите в Рекомендуемых товарах щётки-напальчники или модели с подсветкой и музыкой, чтобы превратить гигиеническую процедуру в игру.'),
  ('f2a19104-ece3-4a8f-9966-8cad392a68af', 'Ночная тишина 🍵', 'Малыш уснул, таймер остановлен. Теперь не нужно никуда спешить — пора отдохнуть. Заварите ромашковый чай из раздела полезных рецептов и насладитесь полной тишиной.'),
  ('f524b282-4173-4386-b8dd-255261b77d1d', 'Я оденусь сам! 👕', 'Каждое утро одевание превращается в большую ссору? В разделе Блоги прочитайте о практических способах справиться с такими кризисами, предоставляя малышу выбор.'),
  ('46919051-4727-4a43-8ba3-d5a1f5451c16', 'Громкий скандал в магазине? 🛒', 'Малыш падает на пол в общественном месте, потому что ему не купили желаемое? Не обращайте внимания на взгляды окружающих — поговорите с Anacan AI и получите поддержку, чтобы сохранить спокойствие в этот момент.'),
  ('874df706-e26e-4b72-a02c-7f8309fc95d5', 'Фразы из двух слов! 🗣️', 'Сегодня малыш впервые сказал что-то вроде Мама, иди или Брось мяч? Сразу сохраните это прекрасное достижение в развитии речи в Альбоме малыша в виде видео со звуком.'),
  ('af368cd3-f751-4611-9e47-9c8fda037ebd', 'Мелкая моторика в действии! 🧩', 'Позвольте малышу самостоятельно есть горошек, кукурузу или нарезанные фрукты. Это развивает мелкую моторику. Следите за размером порции с помощью Контроля питания.'),
  ('1f770df3-c7ef-4bf3-8564-f5ddd0b6a323', 'Поддержка иммунитета! 🍊', 'Погода меняется? С помощью инструмента Контроль питания рассчитайте сегодняшнее потребление витамина C и добавьте в меню цитрусовые, киви или сладкий перец.'),
  ('28cf8172-0a76-4afd-b2de-765879c7939a', 'Поблагодарите себя! 💖', 'Вы такая заботливая и замечательная мама! Откройте Дневник настроения, запишите даже самый маленький добрый поступок, который вы сегодня совершили ради своего малыша, и гордитесь собой.'),
  ('f00a5e44-ed12-4c77-9249-e4246b2b108d', 'Первое знакомство с горшком 🚽', 'Даже если пока рано, горшок в ванной поможет малышу визуально к нему привыкнуть. Посмотрите в Рекомендуемых товарах удобные и интересные модели, которые привлекут его внимание.'),
  ('6d72635f-ba12-4c8b-b7ef-f626dd634dce', 'Утренняя энергия особенная! ⚡', 'Отказывается от овсяной каши? Найдите среди рецептов для малышей смузи с фруктами и арахисовой пастой и легко достигните целевого количества калорий в инструменте Контроль питания.'),
  ('9867089b-80a4-4895-985d-1e1d5fa3df95', 'Глаза закрываются? 😴', 'Когда малыш уснёт, прилягте и вы. Если заснуть не получается, приготовьте зелёный чай, богатый антиоксидантами, из раздела полезных рецептов для женщин и восстановите силы.'),
  ('a5fedf21-2dca-46ed-9476-0b415ced68a5', 'Не хочет ложиться спать? 🛌', '19-й месяц известен скачками сна. Запустите Таймер сна и проверьте график — возможно, пришло время сократить продолжительность дневного сна!'),
  ('39db43fc-07a0-417e-90da-c0bbbd5f14a4', 'Подозрение на боль в животе? 💩', 'При утренней смене подгузника внесите данные о стуле. Если есть риск запора, спросите у Anacan AI о быстрых естественных способах облегчения состояния и техниках массажа и примените их.'),
  ('613cd9e2-958a-41bd-b191-0de3ff8ec07f', 'Сколько раз вы услышали Нет? 🙉', 'Справляться с упрямым малышом непросто — для этого нужно терпение. Запишите своё внутреннее напряжение в Дневнике настроения и дайте выход чувствам, не осуждая себя.'),
  ('e893b0aa-e3fc-4f78-a970-b681a0ed0450', 'Чемпион по лазанию! 🧗', 'Домашней мебели уже недостаточно? Найдите среди Мест для мам крытый развлекательный центр с мягкой полосой препятствий, где малыш сможет безопасно реализовать своё желание лазать.'),
  ('6bb4b5b9-3f8e-4a1c-a637-e0752d1d87ee', 'Юный модельер за работой! 👗', 'Хочет сам выбирать одежду и сочетает неподходящие цвета? Украсьте этот забавный образ весёлыми стикерами из фотосессии малыша и превратите снимок в самый смешной кадр альбома.'),
  ('f830cd97-a8bb-4789-bdc5-7806bcd89cfe', 'Перевозбуждение 🎇', 'Мозгу, который был очень активен днём, сложно затормозить ночью. Включите в разделе «Белый шум» звук фена или вентилятора и посмотрите, как монотонный шум успокаивает малыша.'),
  ('f8565841-4602-47d5-af45-99f7dea5b129', 'Левша или правша? 🤚', 'В какой руке малыш держит ложку? Обязательно прочитайте в разделе «Блоги» нашу новую научную статью о том, как и когда формируется ведущая рука.'),
  ('1915583e-53f5-46af-8212-835dfd587e22', 'Волосы всё ещё выпадают? 💇‍♀️', 'Ваш организм всё ещё восстанавливается. Позаботьтесь сегодня о себе: выберите среди полезных рецептов для женщин вариант завтрака, богатый цинком и биотином.'),
  ('cfbeabf3-def0-4cbe-a106-fd34987dd776', 'Время музыкальных инструментов 🥁', 'Малыш любит стучать деревянными ложками по кастрюлям? Посмотрите в разделе «Рекомендуемые товары» ксилофоны и барабаны с безопасным для детского слуха уровнем громкости.'),
  ('daa6a0d6-25d4-401e-ba81-8a8ca5108695', 'Первые звуки животных 🐮', 'Увидев собаку или кошку, малыш пытается подражать их звукам? Снимите это замечательное проявление познавательного развития на короткое видео и добавьте в Альбом малыша, чтобы сохранить воспоминание.'),
  ('2ed7fd17-90ba-451d-9c88-a1f94a180fe0', 'Аппетит снизился — а что с весом? 📉', 'В этом возрасте дети становятся более избирательными в еде. Внесите актуальные показатели в Трекер веса и убедитесь, что развитие малыша на самом деле идёт в пределах нормы.'),
  ('50209dd4-d2d7-4719-bf4e-21df8c72686a', 'Ритуалы подготовки ко сну 🧸', 'Каждый вечер соблюдайте одну и ту же последовательность! Запустите таймер сна, предложите малышу пожелать спокойной ночи любимому мишке и отметьте, как постоянство облегчает засыпание.'),
  ('cc01349a-6eef-4c61-aa08-b3f505c2eb5f', 'Битва «Я сам буду есть!» 🥣', 'Позволите есть самостоятельно — еда окажется повсюду, не позволите — малыш начнёт кричать. Узнайте прямо сейчас из психологических рекомендаций Anacan AI, как справиться с этим кризисом без стресса.'),
  ('3abde512-ebd4-4cf1-986e-fb1953695f78', 'Разноцветный щит иммунитета 🛡️', 'С помощью инструмента контроля питания проверьте, получил ли малыш сегодня достаточно витамина C. Подходящие блюда с оранжевыми и красными овощами ищите в рецептах для малышей.'),
  ('56129e04-2f90-42b1-b51e-b835940e284e', 'Освободитесь от ментальной нагрузки 🧘‍♀️', '«Нужно сделать ещё это, приготовить ещё то» — мысли не дают покоя? Запишите все свои планы и страхи в Дневник настроения. Составление списка сразу снижает стресс.'),
  ('deb6cbd4-3a89-4915-9bdf-626d87829918', 'Любовь к воде и грязи 💦', 'Не бойтесь, что малыш испачкается! Найдите место на свежем воздухе в разделе «Места для мам» и позвольте ему исследовать природу, развивая сенсорное восприятие.'),
  ('1576f605-27d8-4159-b3bd-3dd9e63c91dd', 'Больше жидкости — легче пищеварение 💧', 'Полный переход на твёрдую пищу иногда затрудняет пищеварение. Делайте записи в Трекере подгузников, чтобы легко определить, нужно ли увеличить потребление воды.'),
  ('93141c59-a17f-414d-9f6c-c865a0650eeb', 'Театр теней начинается! 🐰', 'Выключите свет в комнате и с помощью фонарика создавайте на стене теневые фигурки. Обязательно снимите для Альбома малыша его милое удивлённое выражение лица при виде этого волшебства.'),
  ('a14c30d1-ff1f-46da-8b1e-98116e38ee0d', 'Так и хочется порвать страницы? 📖', 'Малыш хочет не читать книги, а рвать их? Прочитайте в разделе «Блоги» новые советы о том, почему в этом возрасте важны картонные и тактильные книги.'),
  ('8e7d531f-d445-43eb-a4d5-05ffff377c4f', 'От звуков к тишине 🎶', 'Резкий переход от звуков телевизора или игрушек к тишине может напугать малыша. Включите в комнате звук поезда из раздела «Белый шум», чтобы мягко перейти к атмосфере сна.'),
  ('c6f920b8-00cf-46b0-a823-bf8cf1fd5ecf', 'Проблемы с умением делиться 🧸', 'В парке малыш бежит к игрушкам других детей, но не хочет делиться своими? Узнайте у Anacan AI, как научить ребёнка 1.5 лет играть по очереди.'),
  ('ca671510-91c4-4377-9f69-b4bd47b292a2', 'Перерыв на чашечку кофе ☕', 'Как поживает ваша внутренняя батарейка? Отложите домашние дела. Приготовьте энергетический кекс с арахисовой пастой из раздела полезных рецептов для женщин и просто насладитесь ароматным кофе.'),
  ('38141003-a43c-4589-a477-21da541a08db', 'Волшебство кинетического песка 🏖️', 'Создадим дома маленький пляж? Загляните в Рекомендуемые товары и выберите набор кинетического песка, который укрепляет мышцы пальцев и легко убирается.'),
  ('75f9f2e1-a04a-4711-9125-3d8c610326d9', 'Узнаёт части своего тела! 👃', 'Гордо показывает нос, когда вы спрашиваете: «Где твой носик?» Устройте небольшую съёмку в комнате с помощью фотосессии малыша и сразу сохраните эту милую позу в альбоме.'),
  ('ae036003-f237-47e6-8031-7feeb47126cc', 'Как понять, что малыш наелся? ⏱️', 'Если малыш начал бросать или выплёвывать еду, значит, он уже наелся. Остановите таймер кормления, отметьте, что норма выполнена, и проанализируйте его аппетит.'),
  ('05bc3cfd-c566-4963-b6b2-87889d369e27', 'Вам тоже нужно общение 💬', 'Общение с другими мамами пойдёт на пользу и вам! Выберите среди Мест, дружественных мамам, центр с игровыми группами и подарите вам обоим возможность общаться.'),
  ('5b6366a9-6eb4-4593-8335-c41fd3447da1', 'Какая у вас сегодня победа? 🏆', 'Удалось уложить малыша без слёз? Или накормить целой миской еды? Запишите даже самый маленький успех в Дневник настроения и устройте себе овацию стоя.'),
  ('98a39354-24f3-4f3c-9cfb-1e084764a56b', 'Рост начинается с обуви 📏', 'Возможно, малыш не хочет надевать обувь, потому что она стала тесной! Проверьте таблицу размеров в инструменте Отслеживание веса и следите за физическим развитием.'),
  ('5bcd3758-fc71-4b21-a0a4-008b6ec5eec1', 'Для волос и кожи 🥑', 'Позаботьтесь о своём теле, уставшем от ежедневной рутины. Приготовьте салат молодости с авокадо и грецкими орехами — настоящий кладезь антиоксидантов из раздела полезных рецептов для женщин.'),
  ('a832a387-bccf-4a1a-823c-3930e73e4c07', '«Дай воды», «Мама, иди» 🗣️', 'Малыш уже пытается соединять два слова и составлять короткие предложения? Это потрясающий скачок в развитии речи! Всегда поддерживайте его попытки и побуждайте говорить.'),
  ('d1f9f7f1-6831-4583-9dbd-fab805703b8d', 'Неиссякаемая энергия 🔋', 'Малыш не устаёт бегать? Запустите таймер сна и приглушите свет в комнате. Постепенно настройте его на сон под шелест леса из раздела Белые шумы.'),
  ('34104368-1e25-46df-8c68-910d16cd40b1', 'Как пищеварение? 🚽', 'У малыша запор? Отметьте это во время утренней смены подгузника и обязательно добавьте в его меню продукты, богатые клетчаткой (грушу, овсянку), с помощью инструмента Контроль питания.'),
  ('79b083b6-1c72-4250-a120-ca8846206ce5', 'Как вы себя чувствуете? 🧘‍♀️', 'Сегодня вы слишком часто говорили «нет»? Не мучайтесь чувством вины. Излейте душу в Дневнике настроения и вспомните, как много вы отдаёте своему малышу каждый день.'),
  ('bfb35c45-0163-48f3-be24-eff4697cb9e8', 'Юные художники природы 🍂', 'Листья, камни и веточки — лучшие игрушки! Найдите среди Мест, дружественных мамам, зелёный парк и отправляйтесь на настоящую прогулку-исследование под открытым небом.'),
  ('01861a89-1cc1-4443-8c58-c79d90402305', 'Истерики в магазине 🛒', 'Малыш бросился на пол из-за того, что вы не купили желаемое? Не паникуйте. Не обращая внимания на взгляды окружающих, спокойно присядьте, чтобы оказаться на уровне его глаз.'),
  ('32e724db-ca0f-4d6b-9d07-716443a9dcdd', 'Освободитесь от эмоционального груза 📝', 'День был трудным? Выплесните эмоции, записав сегодняшний стресс в Дневник настроения. Все мамы проходят через это, и вы не одиноки.'),
  ('a0570819-b575-49b5-bbf4-bc21cf5fc939', 'Прыжки на двух ногах 🦘', 'Малыш пытается подпрыгнуть на месте обеими ногами одновременно? Выглядит очень забавно, правда? Обязательно сохраните этот момент с помощью фотосессии малыша.'),
  ('1eeadb7c-f8e9-45ae-bbde-edff2903cb9d', 'Отказывается спать? 🥱', 'Малыш не хочет ложиться спать днём и сопротивляется? Попросите Anacan AI предоставить точную информацию об окнах сна у детей в возрасте 20 месяцев и составить распорядок дня.'),
  ('2edb626b-eafe-49c0-a743-e6dae9f9eddd', 'Музыкальное спокойствие 🎶', 'Самый простой способ справиться с вечерними капризами — включить любимую мелодию, обнять малыша и медленно потанцевать вместе.'),
  ('b174df30-8e63-488e-ae9b-4d227f3136f1', 'Пир для мамы 🥑', 'Вы делаете всё, чтобы малыш был сыт. А как же вы? Выберите среди полезных рецептов богатый железом обед, который придаст вам сил, спокойно сядьте и поешьте.'),
  ('5d951093-5ada-49f6-9750-d303bcf8d918', 'Большие коренные зубы? 🦷', 'Малыш без видимой причины всё грызёт и плачет? Возможно, прорезываются самые дальние коренные зубы. Отметьте этот процесс в трекере прорезывания зубов и подготовьте охлаждённые прорезыватели.'),
  ('9fe66081-4fad-49c8-891d-2ca85484f87d', 'Герой сказки 🪄', 'Сегодня вечером создайте в «Умных сказках» особенную историю, главным героем которой станет ваш малыш: смелый кроха, который любит чистить зубы.'),
  ('c638741f-2af1-4bf3-a4de-09ffcb406144', 'Смелее на прогулку ⛅', 'Остались дома из-за странной погоды? Пусть инструмент «Погода и одежда» мгновенно подскажет вам скорость ветра, которую не видно из окна, и подходящий комплект одежды — и смело отправляйтесь в парк.'),
  ('3d75b744-8440-4e62-83c6-4a08b865c0f7', 'Йогуртовая маска! 🥣', 'Малыш размазал еду по лицу и волосам? Вместо того чтобы сердиться, добавьте этот гениальный шедевр в Альбом малыша, украсьте забавными стикерами и сохраните на память.'),
  ('69c1e419-f8f2-4b2f-90e3-9b51e78ff197', 'Таймер остановлен — отдохните 🍵', 'Вы остановили таймер сна и вышли из комнаты. А теперь забудьте о домашних делах! Заварите себе ромашковый чай и позвольте тёплому пару унести накопившуюся за день усталость.'),
  ('934796d5-42af-4c49-9cb9-67f18b657e36', 'Чешутся дёсны? 🦷', 'Возможно, прорезываются последние коренные зубы. Чтобы уменьшить зуд дёсен, приготовьте по рецептам для малышей прохладный, полезный фруктовый лёд (popsicles) без сахара.'),
  ('06d75280-127a-43d4-a7f0-42d2871b24c5', 'Самостоятельный шеф-повар! 👨‍🍳', 'Малыш не хочет отдавать вам ложку? Приготовьте по рецептам для малышей котлетки, которые удобно брать руками. Анализируйте продолжительность самостоятельного приёма пищи с помощью таймера кормления и следите за аппетитом малыша.'),
  ('4b7fd5a1-3084-40d7-9f2d-e7fb4777d2eb', 'Забавные гримасы 🤪', 'Малыш корчит рожицы перед зеркалом? Не упустите этот весёлый момент! Украсьте снимок забавными стикерами из фотосессии малыша и превратите его в самый весёлый кадр альбома.'),
  ('739af07d-8466-4c3f-a164-5e408385ca93', 'Всюду карабкается? 🧗‍♀️', 'Диван, стол, шкаф... Настоящий альпинист! В разделе «Блоги» прочитайте, как безопасно удовлетворить дома эту рискованную, но важную для развития моторики потребность.'),
  ('8ac7016a-7613-48aa-a952-59cc5f8a6354', 'Штанины стали короткими? 👖', 'Скачок роста в самом разгаре! Внесите текущие показатели роста и веса в Трекер веса и с гордостью посмотрите, как поднимается график развития.'),
  ('db467018-0ec9-41a9-a3a3-3ef1c48cda53', 'В поисках развивающей игрушки 🧩', 'Нужны игрушки, которые не просто издают звуки, а заставляют думать. Обязательно загляните в раздел «Рекомендуемые товары» и обратите внимание на логические головоломки и сортеры для детей старше 1.5 лет.'),
  ('df8f7402-1277-45bd-a743-5c24bdaf48e1', 'Сердито кусается? 🦖', 'Малыш бьёт или кусает других, когда злится? Так он выражает чувства, которые пока не может передать словами. Узнайте у Anacan AI, как мягко скорректировать такое поведение.'),
  ('45af46ac-18bf-499b-a5c7-56bbe71e4564', 'Пора успокоиться 🎶', 'Маленьким ножкам, которые бегали весь день, пора отдохнуть. Включите в разделе «Белый шум» звук салона автомобиля и благодаря его монотонности создайте идеальную атмосферу для сна.'),
  ('47b68bdb-a1fd-4da7-9316-dcca5fdae94f', 'Вам тоже нужны друзья 👯‍♀️', 'Хотите общаться с другими мамами, пока малыш играет в парке? Найдите в разделе «Места для мам» центры с игровыми группами и заводите новые знакомства.'),
  ('49af58d4-c188-43d7-a0b2-43f4cd255337', 'Одного утреннего кофе мало! ☕', 'Если начать день с кофе натощак, энергия быстро иссякнет. Выберите среди полезных рецептов для женщин питательный овсяный кекс, который готовится за 5 минут.'),
  ('869af623-de96-421f-808b-d64172a8f765', 'Вы молодец! 👏', 'Сегодня дома остался беспорядок? Не переживайте! Весёлые минуты, проведённые с малышом, гораздо ценнее. Обязательно похвалите себя в Дневнике настроения.'),
  ('aaf473f6-79bc-44cf-97f4-687dfa4eb293', 'Не любит пить воду? 💧', 'Утренний подгузник был почти сухим? Значит, малышу может требоваться больше жидкости. Отметьте это в трекере подгузников и посмотрите в приложении рецепты фруктовой воды и разные модели поильников.'),
  ('ff614b36-4091-473e-b7fa-91411bd4e2a9', 'Кости укрепляются! 🦴', 'С помощью трекера питания проверьте, получил ли сегодня малыш достаточно кальция и витамина D. Эти два элемента неразрывно связаны с быстрым физическим развитием.'),
  ('348430a9-4730-49e1-90ac-91076b5c5d7c', 'Разложим по цветам! 🔴🔵', 'Красные игрушки — в одну сторону, синие — в другую. В разделе блогов прочитайте об домашних играх для малышей 19.5 месяцев, развивающих внимание и логику, и попробуйте поиграть в них.'),
  ('907f2a4d-a45c-43e1-8024-d6c91a18d072', 'Громкая истерика в магазине? 🛒', 'Малыш упал на пол и расплакался в общественном месте? Не обращайте внимания на взгляды окружающих. Расскажите об этом Anacan AI и узнайте, как спокойно справляться с такими кризисами.'),
  ('e6ec7f70-00dc-438b-af17-5f764a9d8216', 'Дневной сон становится короче? ⏱️', 'Малыш не хочет ложиться спать днём? Следите за статистикой таймера сна. Возможно, ему пора окончательно перейти на один дневной сон и раньше укладываться вечером.'),
  ('46ef9700-c667-4312-ac63-98bd03625249', 'Споры из-за обуви 👟', 'Собираясь на улицу, малыш непременно хочет надеть зимнюю обувь летом? Иногда позволяйте ему выбирать самостоятельно — это укрепляет его волю.'),
  ('5541587a-ad73-4e1d-9174-d4fe1c028c3e', 'Сопротивляется сну? 🛌', 'Малыш не хочет ложиться, потому что играть интереснее, чем спать! Запустите таймер сна и включите в разделе «Белый шум» звуки океанских волн, чтобы помочь ему постепенно успокоиться.'),
  ('c2f59a7d-198f-4c77-831a-cca0b1b7e5e6', 'Появился интерес к туалету? 🚽', 'Малыш хочет идти с вами в ванную? Это часть наглядной подготовки. Прочитайте в разделе блогов, когда и как начинать приучение к горшку, чтобы заранее подготовиться.'),
  ('3b603489-95c3-4a32-b0e0-5191fc844b75', 'Борьба за самостоятельное одевание 👕', 'Началось упрямое «Не хочу эту футболку!»? Спросите у Anacan AI, как уменьшить количество утренних споров из-за одежды и предоставить малышу право самостоятельного выбора.'),
  ('89933e6a-484e-4f2e-bf20-8262f6a74c72', 'Запас омега-3 🐟', 'Развитие мозга продолжается. Проверьте в трекере питания, съел ли малыш за эту неделю достаточно рыбы или грецких орехов, и обязательно отметьте, если их было недостаточно.'),
  ('fa46cf0a-85f0-484c-8aa5-b60eb52b320b', 'Как выплеснуть энергию дома? 🏃‍♂️', 'Не можете выйти на улицу? Посмотрите в разделе рекомендованных товаров мини-батуты или горки для помещений и направьте энергию малыша в нужное русло.'),
  ('00691751-d785-4fc6-8036-d313adccdad6', 'Проверяем утренний сюрприз 🧻', 'Сухих подгузников становится больше или пищеварение замедлилось? Отметьте утреннюю смену в трекере подгузников, чтобы сразу оценить потребность малыша в жидкости и клетчатке.'),
  ('0bde6683-6d18-4d98-bc39-b122396c0b17', 'Время отдохнуть 🍵', 'Суета позади! Приготовьте напиток по одному из полезных рецептов, прилягте на диван и просто насладитесь тишиной.'),
  ('0eecf770-9ba2-463c-9b39-bbe24d01b4e1', 'Крики «Моё!» 🧸', 'Отбирает в парке чужие игрушки? Узнайте у Anacan AI самые эффективные психологические приёмы, которые помогут справиться с эгоцентрическими кризисами этого возраста.'),
  ('0a81bd63-014b-4d25-b347-1808455aea49', 'Побег из четырёх стен 🏃‍♀️', 'Дома малышу трудно выплеснуть энергию. Найдите в разделе «Места, дружественные к мамам» безопасный игровой центр, где он сможет побегать, а вы — выпить кофе.'),
  ('657f4585-c7bb-41c0-9574-51e8f943398b', 'Неаккуратно, зато самостоятельно! 🥣', 'Настаивает на том, чтобы есть самостоятельно? Включите таймер кормления, следите за продолжительностью процесса и отмечайте, как эта самостоятельность развивает его мелкую моторику.'),
  ('7feaa5c7-f1f9-4df2-a08a-b9cef56c0ce4', 'Ночные пробуждения вернулись? ⏱️', 'Возможно, это регресс сна в 20 месяцев. Посмотрите график таймера сна и проверьте, не пора ли сократить дневной сон на 15 минут.'),
  ('385a8205-8e28-4c23-94fa-a2a8fe32e28c', 'Не мучайтесь чувством вины 📝', 'Сегодня вы немного повысили голос? Не вините себя. Выплесните свои переживания в Дневнике настроения и помните: для вашего малыша нет мамы лучше вас.'),
  ('49b18c8f-b30b-4368-9445-6af88b1d8115', 'Фразы из 2 слов! 🗣️', '«Мама, иди», «Дай мяч» — словарный запас малыша быстро растёт. Сразу добавьте эти милые попытки заговорить в Альбом малыша в виде видео со звуком и сохраните их на всю жизнь.'),
  ('5d516faa-7c77-4db9-b201-49bff969e3d8', 'Кальций для костей 🦴', 'Кости активного малыша должны быть крепкими. Проверьте в трекере питания, сколько кальция он получил сегодня с сыром и йогуртом, и при необходимости дополните рацион до нормы.'),
  ('ad033330-a436-4b30-84e7-2df370198c16', 'В поисках развивающей игрушки 🧩', 'Любит вставлять фигурки в подходящие отверстия? Откройте в разделе «Рекомендуемые товары» подходящие по возрасту деревянные пазлы, которые помогут ещё лучше развить мышление малыша.'),
  ('d22a5573-d857-4918-90d2-9def6a084f6f', 'Искусство успокаивать мозг 🎶', 'Из-за избытка впечатлений ребёнку бывает трудно уснуть ночью. Приглушите свет и включите шум океанских волн в разделе «Белые шумы», чтобы мягко подготовить его к глубокому сну.'),
  ('fb035079-cf24-4146-9049-8d721e68f53f', 'Художник весь в краске! 🎨', 'Малыш испачкал одежду, пока рисовал каракули? Вместо того чтобы сердиться, украсьте этот забавный момент весёлыми стикерами в Фотосессии малыша и загрузите снимок в альбом.'),
  ('0b2c56b1-a7a8-4553-8880-13254eeb155b', 'Одежда стала мала? 📏', 'Если брюки стали коротки, у малыша скачок роста! Внесите текущие параметры в Трекер веса и с гордостью наблюдайте, как поднимается график развития.'),
  ('9f2ceaa6-0d99-46a0-884c-3460db78351b', 'Понимает вас, но не говорит? 🧠', 'Пассивный словарный запас развивается быстрее активного. Обязательно прочитайте в разделе «Блоги» статью о домашних играх, которые помогают развивать речь ребёнка в 20 месяцев.'),
  ('f641f443-9a8d-4060-a2b5-fe5d5562fa9d', 'Операция «Спрятанные витамины» 🥕', 'Отодвигает зелень и овощи в сторону? Узнайте в Рецептах для малышей, как искусно спрятать шпинат и морковь во вкусных блинчиках.'),
  ('68ef19de-c144-4be9-8878-9cc1b34a6483', 'Сколько времени требуется, чтобы уснуть? ⏱️', 'Малыш долго ворочается в кровати? Включите таймер сна и отметьте, сколько времени заняло засыпание. Возможно, вечерние игры стоит заканчивать раньше.'),
  ('70a3e410-6335-466b-99bc-28ac0c3d913f', 'Почему малыш внезапно плачет? 🤖', 'Просыпается ночью с криком и не успокаивается? Сразу напишите эксперту Anacan AI о своих подозрениях на ночной ужас и узнайте, как правильно действовать.'),
  ('80e71246-05ae-4bc6-857d-5ce3af704b5e', 'Источник маминой энергии 🥗', 'Вы выбились из сил из-за постоянной беготни? Выбирайте не сладости, а белок! Приготовьте смузи с арахисовой пастой по рецепту здорового питания для женщин — он мгновенно зарядит вас энергией.'),
  ('145211fa-74d2-4e28-8a64-c14921db5185', 'Похвалите себя! 🌟', 'Сегодня вам удалось накормить малыша без слёз? Запишите даже самую маленькую победу в Дневник настроения и стоя поаплодируйте своим материнским навыкам.'),
  ('4f60f5e8-df5e-4892-aa2e-dcffda8f877b', 'Водный баланс жизненно важен 💧', 'Активные игры и бег могут привести к обезвоживанию. Сделайте утреннюю запись в Трекере подгузников и загляните в Рекомендованные товары, чтобы выбрать спортивную бутылку, которую малыш сможет легко открыть сам.'),
  ('edd993f1-ac76-4300-8ed0-6009d7897f2b', 'Общение с другими мамами ☕', 'Устали разговаривать только с малышом? Найдите в разделе «Места для мам» детские кафе, где часто собираются мамы, и подарите себе возможность пообщаться.'),
  ('6f516c4d-5db5-4d3e-8fca-8c461e614752', 'Достаточно ли запасов железа? 🥩', 'Чтобы у активного малыша не развилась анемия, проверьте в инструменте Контроля питания, сколько железа он получил сегодня (мясо, бобовые), и скорректируйте меню.'),
  ('b003834c-8ce3-4da4-a17e-0b837c04f7f7', 'Проверим запасы кальция 🧀', 'Быстро растущим костям нужен кальций! С помощью инструмента Контроля питания проверьте, достаточно ли сегодня было сыра и йогурта, и восполните недостающее.'),
  ('b5cae897-2c37-4223-8c5a-201bd9d0229a', 'Таинственные звуки леса 🍃', 'День был слишком шумным и полным капризов? Включите шелест листьев в разделе «Белый шум», чтобы помочь расслабиться нервной системе малыша и вашей собственной.'),
  ('20cf6725-2fdc-45bb-965b-09069424fe0a', 'Перекус без сахара 🍪', 'Покупное печенье не понадобится. Откройте для себя полезные сладости с финиками и овсянкой из рецептов для малышей — их можно приготовить дома всего за 10 минут.'),
  ('9a0a29d7-d513-4158-b204-99c831639c23', 'Вместе, но по отдельности 👶', 'В парке малыш не играет с другими детьми, а лишь наблюдает со стороны? Это параллельная игра! Спросите Anacan AI интересные факты об этом этапе социализации.'),
  ('f527de5c-afa8-4884-a173-da37070a2826', 'Маленький помощник по дому 🧹', 'Пока вы подметаете, малыш протирает стол салфеткой? Сразу снимите этот милый момент проявления ответственности и добавьте его в Альбом малыша как один из самых трогательных поводов для гордости.'),
  ('18518788-d8e2-4971-93f7-6fbf0592ca33', 'Удары и толчки 🛑', 'В гневе малыш внезапно начинает драться? Обратитесь к Anacan AI, чтобы узнать, как с помощью игр справиться с этим характерным для 20-го месяца поведением.'),
  ('a6200253-33e2-4142-a4a9-811aa67d4feb', 'Сегодняшний герой — вы 🧘‍♀️', 'Малыш уснул. Отложите все домашние дела. Запишите свои чувства в Дневник настроения, включите спокойную музыку и посвятите этот вечер только себе.'),
  ('eefd67fd-3835-4f65-abf3-9ced6b705e30', 'Испытание терпения за столом ⏱️', 'Малыш съедает одну ложку за 5 минут? Включите Таймер кормления, наберитесь терпения и подробно проанализируйте изменения аппетита с помощью отчёта в приложении.'),
  ('070b2f75-0440-4e85-b828-292900301f9e', 'Начались игры воображения 🧸', 'Малыш поит водой плюшевого мишку или лечит вас? Сохраните эти чудесные проявления эмпатии на будущее, добавив видео со звуком в Альбом малыша.'),
  ('388f83f4-0bb5-4306-abf6-b75f9dc65017', 'Проверка запасов железа 🥩', 'Для активной работы мышц и здорового развития важно предотвратить анемию. С помощью инструмента Контроля питания проверьте, сколько железа малыш получил сегодня (мясо, бобовые), и сразу восполните недостающее.'),
  ('9cb7efe6-c6c0-4032-89de-12eeec5119ee', 'От звуков к тишине 🎶', 'После звуков телевизора и игрушек внезапная тишина пугает малыша. Включите в комнате звук фена из раздела «Белый шум» и посмотрите, как монотонный шум помогает создать благоприятную атмосферу для сна.'),
  ('847e9a71-981a-4920-b6be-a1986674dd92', 'Бесконечное шоу за столом ⏱️', 'Малыш играет с едой, бросает её на пол, но не ест. Включите таймер кормления, наберитесь терпения и точно отслеживайте изменения аппетита в этот период самостоятельности с помощью графика в приложении.'),
  ('890ee8d7-3315-4b7a-994a-c41900d8c960', 'В поисках развивающей игрушки 🧩', 'Малыш уже научился вставлять фигурки в подходящие отверстия? Откройте раздел «Рекомендуемые товары» и найдите пазлы по возрасту, которые помогут ему развивать мышление.'),
  ('8ad462c4-33b5-4c76-be29-aa192feb14a1', 'Обувь стала тесной? 📏', 'В последнее время малыш часто спотыкается во время бега? Возможно, его стопа выросла! Внесите текущие показатели роста и размера в «Трекер развития», чтобы следить за физическим развитием.'),
  ('2e662854-2d0b-4e0d-be84-f71f33b1ed5b', 'Почему малыш внезапно плачет? 🤖', 'Малыш весело играл, но вдруг расстроился и заплакал? Напишите нашему экспертному помощнику Anacan AI, чтобы разобраться в причинах эмоциональных перепадов.'),
  ('b30cbe06-794a-4924-bc78-63ebe289b716', 'Развитие интеллекта продолжается 🧠', 'Малыш любит всё сортировать! Обязательно прочитайте в разделе «Блоги» статью о домашних играх, которые развивают восприятие цветов и форм у детей в возрасте 20-21 месяца.'),
  ('dcfe0150-6b59-46be-be17-cba289272768', 'Энергии лишь на 5 минут 🔋', 'Кофе натощак лишит вас энергии уже к полудню. Выберите в разделе полезных рецептов вкусный и сытный овсяный кекс, который можно быстро приготовить.'),
  ('41523bc6-ac22-4b48-a7b5-8663ed9c74c3', 'Песочная терапия 🏖️', 'Не бойтесь испачкаться! Найдите в разделе «Места для мам» площадку с песочницей. Игры с песком полезнее для сенсорного развития, чем дорогие игрушки.'),
  ('863859ae-c920-41fe-b876-915ee50bba17', 'Юный художник весь в краске! 📸', 'Малыш разрисовал себя и стену? Вместо того чтобы сердиться, загрузите этот забавный творческий момент в «Альбом малыша» и добавьте весёлые стикеры.'),
  ('af623bf2-6a45-452d-a9c0-bd16d67bf74d', 'Блинный монстрик 🥞', 'Малыш отказывается от завтрака? Найдите в разделе рецептов для малышей рецепт банановых панкейков без сахара. Он сможет брать их руками и есть самостоятельно, а заодно у него разыграется аппетит.'),
  ('a7786d73-a362-4a32-a77f-3c09e4ab2ffb', 'Урок физики с водой 🛁', 'Малышу не надоедает переливать воду из одного стаканчика в другой во время купания? Загляните в раздел «Рекомендуемые товары» и выберите весёлые и успокаивающие игрушки для воды.'),
  ('ccc521b5-a8ef-4b74-a8d7-bf2ba2f22793', 'Кальциевый щит 🦴', 'Кальций необходим для здоровья зубов и костей. С помощью инструмента контроля питания проверьте, получил ли сегодня малыш необходимую норму йогурта и сыра.'),
  ('e8d46282-de1c-4981-9242-f0dff7014b1d', 'Проанализируем режим ⏱️', 'Вечерний период бодрствования слишком затянулся? Запустите таймер сна и следите за графиком. Возможно, настало время сократить дневной сон на 15 минут.'),
  ('a1bb5dc0-7875-44dc-a4df-f9fa8c0a427f', 'Сигналы пищеварительной системы 💩', 'Полный переход на твёрдую пищу может затруднить пищеварение. Добавьте утреннюю запись в трекер подгузников и проверьте, нужно ли скорректировать баланс жидкости и клетчатки.'),
  ('c4d895de-4842-4a9b-ae46-1557c6e3d2cc', 'Природное успокоительное 🍃', 'День выдался капризным и шумным? Включите шелест листьев в разделе «Белый шум», чтобы помочь нервной системе малыша и вашей собственной расслабиться.'),
  ('f1307d3d-156d-45b5-82ac-2f5c2abfa1a3', 'Битва за одевание 👗', '«Не хочу эту кофту!» — упрямство не заканчивается? Чтобы избежать утренних капризов, превратите одевание в игру, сказав малышу, что вы устроите ему фотосессию.'),
  ('0daafb47-5c27-4a37-935b-b3612abf5506', 'Герой дня 🌟', 'Каждый новый навык, который малыш осваивает изо дня в день, — результат ваших стараний. Откройте «Дневник настроения», запишите даже самый маленький добрый поступок, который вы сегодня совершили для него, и гордитесь собой!'),
  ('3b1eb831-8b25-40be-89a6-b50384eeb49b', 'Хочет говорить, но... 🗣️', 'Пассивный словарный запас больше активного? Даже если малыш пока произносит слова неправильно, в разделе «Блоги» вы узнаете, как поддержать этот удивительный скачок в развитии речи.'),
  ('a4477b67-ebfc-489b-b2e5-165c0ebb273f', 'Стремление к самостоятельности 🥣', 'Не отдаёт вам ложку? Запустите таймер кормления и проанализируйте, сколько времени занимает эта проба самостоятельности. А на рассыпанную еду просто смотрите с улыбкой.'),
  ('527e5a17-444d-47c4-8578-4ebb1ee870b1', 'Сладкий сон или война? 🛌', 'Если укладывание превратилось в настоящий кризис, прямо сейчас спросите у Anacan AI о ритуалах отхода ко сну и психологических приёмах для детей в возрасте 21 месяца.'),
  ('9c6e3d93-ba09-4cda-8c01-9c820b1e3ed6', 'Как прошла ночь? 🌙', 'Если утром подгузник очень тяжёлый, возможно, стоит скорректировать количество жидкости перед сном. Сделайте запись в трекере подгузников и проверьте водный баланс малыша в течение дня.'),
  ('ac8ebb1f-1fc4-47f7-86d8-2eb0fa26e0a4', 'Мелкая моторика 🧩', 'Малыш уже научился вставлять фигурки в нужные отверстия. Откройте раздел «Рекомендуемые товары» и найдите подходящие по возрасту пазлы, которые помогут ему развивать мышление.'),
  ('b322d3bf-6cd3-46c1-9a5f-bb9f3a106c60', 'Время замедлиться 🎶', 'Активный день может утомить мозг малыша. Включите в разделе «Белый шум» шелест леса, чтобы создать в комнате идеальный успокаивающий фон для сна.'),
  ('d93eedfc-78de-4d26-810d-89c2b8c71690', 'Угостите себя кофе ☕', 'Вы выбились из сил, проведя весь день в заботах! Найдите на карте «Места для мам» кафе с детской игровой зоной и порадуйте себя небольшим отдыхом.'),
  ('fcfa5044-061e-4832-8787-ddd94f46ab93', 'Новое слово 🗣️', 'Какое новое слово малыш произнёс сегодня?'),
  ('205f33e0-59b6-4cce-bdf2-72feb1805167', 'В поисках полезных сладостей 🍪', 'Нужен вкусный перекус без сахара? Откройте рецепты для малышей и найдите печенье с бананом и финиками, которое можно приготовить за 10 минут.'),
  ('db60a4c8-3ab7-4727-9545-2ff3fea13946', 'Упрямое «Нет!» 🛑', 'Малыш всё отрицает и кричит? Посоветуйтесь с нашим помощником Anacan AI об упрямстве в 21 месяц и узнайте, как справляться с эмоциональными кризисами.'),
  ('ec464aff-d0a0-4b3d-ac5c-7d32cf5dcf36', 'Проверим режим сна ⏱️', 'Малыш часто просыпается по ночам? Проанализируйте график в таймере сна. Возможно, стоит немного сократить дневной сон, чтобы к вечеру малыш сильнее уставал.'),
  ('87662f03-ab51-47a9-bb0d-dc1172cdf859', 'Кладезь витаминов 🥗', 'Рассчитайте сегодняшнюю потребность в витаминах с помощью инструмента контроля питания и спланируйте меню. Обязательно проверьте баланс омега-3 и витамина D.'),
  ('a1ffdcb1-2aeb-4842-a0b3-6bc2096bceb7', 'Игрушки на развитие логики 🧩', 'Этот возраст идеально подходит для логических игр. Откройте раздел «Рекомендуемые товары», найдите подходящие по возрасту пазлы и сортеры и помогите малышу развивать мышление.'),
  ('b4b68202-2497-420c-9cf0-d0f43130a249', 'Излейте душу 📝', 'Не каждый день бывает идеальным, и это нормально. Запишите в «Дневнике настроения» всё, что сегодня вас тревожит, освободитесь от стресса и спокойно отдохните.'),
  ('4dbfd2fe-196e-4f4f-9fd6-89ab8dff4f94', 'Скачок роста! 📏', 'Вам кажется, что ваш ребёнок внезапно подрос? Внесите новые показатели в «Трекер развития» и с гордостью взгляните на график здорового роста.'),
  ('9167bebc-9c9c-4cbb-8cf3-b64e9ea99677', 'Время зарядиться энергией 🔋', 'Не забывайте о себе! Найдите среди полезных рецептов вкусный белковый смузи, который можно быстро приготовить на завтрак, и восстановите силы.'),
  ('03d03133-0370-4630-9d2e-153f9459d86d', 'Просыпается с криком?', 'Не включая свет в комнате, включите звук материнской утробы в разделе «Белый шум», чтобы малыш почувствовал себя в безопасности и снова уснул.'),
  ('8ed6f8ef-f210-4aaa-96f8-4667b80d657e', 'На всё «Нет»! 🛑', 'Отвергает все ваши предложения? Вместо того чтобы бороться с упрямством, прямо сейчас спросите у Anacan AI, как правильно предлагать малышу выбор.'),
  ('a3aeb0cd-d49a-4a1a-a82c-e3dc837e022c', 'Жидкость перед сном 🚰', 'Если утром подгузник очень тяжёлый, возможно, стоит скорректировать количество воды, выпиваемой вечером. Внесите данные в трекер подгузников и просмотрите статистику за день.'),
  ('0b3896bc-de1d-4dd2-b68d-bd0aa3890750', 'Дневной сон затягивается? ⏱️', 'Малыш сопротивляется укладыванию вечером? Запустите таймер сна и проследите за режимом. Возможно, он слишком поздно просыпается после дневного сна?'),
  ('7c7fefdb-4a4d-41d2-bca8-742c9430dc8d', 'Кальций и кости 🦴', 'Для быстрого физического развития необходим кальций. С помощью трекера питания рассчитайте потребность малыша в сыре и йогурте, а если кальция не хватает — загляните в «Рецепты для малышей».'),
  ('c7f42861-81dc-4ed2-b93f-7c30709d92ed', 'Чувствуете истощение? 🔋', 'Энергия на исходе? Не спешите за сладостями. Приготовьте энергетические шарики без сахара из раздела «Полезные рецепты для женщин»: они быстро придадут сил и помогут вам зарядиться.'),
  ('2ecfbac7-2e44-4661-8705-95fe2f59e9a9', 'Откажитесь от стремления к идеалу 🧘‍♀️', 'Дома беспорядок? Ничего страшного! Запишите свои чувства в «Дневнике настроения». Помните: счастливая мама важнее идеального порядка в доме.'),
  ('31e46f9b-eb74-4b8a-8369-6c0eb709b2d1', 'Вам тоже нужен перерыв ☕', 'Выйдите из дома и немного переведите дух! Найдите поблизости кафе с детским уголком в разделе «Места для мам» и спокойно насладитесь горячим кофе.'),
  ('f9b61a4f-eba1-4cee-bf4a-958278a9300c', 'Маленький шеф-повар 👩‍🍳', 'Помогает вам на кухне и мешает еду в кастрюлях? Украсьте этот забавный момент, когда малыш весь в муке, поварскими стикерами из раздела «Фотосессия малыша».'),
  ('2c0cd78a-df37-49ab-8eae-44063551c7d9', 'Мастер пазлов 🧩', 'Малыш всё лучше подбирает подходящие фигуры? Чтобы развивать его мышление, найдите в разделе «Рекомендуемые товары» геометрические головоломки для детей 21 месяца.'),
  ('eeefba30-2a67-4d29-87df-2dbd7f03271f', 'Любит рвать книги 📖', 'Вместо чтения рвёт страницы? Прямо сейчас прочитайте в разделе «Блоги», как решить эту проблему, не отбив у малыша интерес к книгам.'),
  ('f7f548f7-29ae-4098-8eb1-12f16f94c4b9', 'Этап игр с едой 🥣', 'Отбрасывает ложку и трогает еду руками? Включите таймер кормления, проанализируйте изменения аппетита и с терпением отнеситесь к этому этапу сенсорного развития.'),
  ('3512adbc-96b2-42e9-8a54-b673dc404876', 'Вечерний смех 📸', 'Не упустите забавную выходку малыша перед сном! Сразу снимите видео и добавьте его в «Альбом малыша», чтобы завершить утомительный день с улыбкой.'),
  ('42cda594-bd4d-4a45-a1f6-1f894ad11fe7', 'Скоро появятся новые слова! 🗣️', 'Малыш произносит много звуков, но ещё не говорит целых слов? Узнайте у Anacan AI о самых эффективных домашних играх и упражнениях со слогами, которые помогут перевести пассивный словарный запас в активный.'),
  ('ad6e0b2f-1d5f-4db6-82ee-93ed492c1c54', 'Обувь стала тесной? 👟', 'В последнее время малыш часто спотыкается во время бега? Возможно, его стопа выросла! Внесите текущие параметры в «Трекер развития» и следите за изменениями.'),
  ('8ae66558-ee37-4cd1-9102-46bab1a97b21', 'Вкусно за 5 минут! 🥗', 'Днём перекусываете на ходу? Приготовьте тост с авокадо из раздела «Полезные рецепты для женщин» — он надолго насытит вас и быстро придаст энергии.'),
  ('e61cda6e-e7ca-46f3-a40c-42185a9f8216', '5 минут для прилива энергии ⚡', 'Когда малыш спит днём, не спешите заниматься домашними делами. Приготовьте по одному из полезных рецептов смузи, богатый антиоксидантами, и восстановите силы.'),
  ('733a062a-9528-4b89-8399-8894cdcd37ab', 'Читаем вместе 📖', 'Малыш хочет сам перелистывать страницы книги? В разделе блогов прочитайте замечательную статью о том, как в этом возрасте привить любовь к чтению через игру.'),
  ('840a48c0-60b0-4169-a7a4-bfd97c049d9d', 'Исследуем природу 🌳', 'Малышу уже тесно в четырёх стенах? Найдите просторный и безопасный парк среди пространств, дружественных мамам, и помогите ему выплеснуть энергию на природе.'),
  ('fc70b034-70d7-48ac-b093-b541c3d08e54', 'Утренняя проверка 💧', 'Сменили первый за день подгузник? Внесите в приложение данные о выделениях, чтобы легко отслеживать, достаточно ли малыш получает жидкости и хорошо ли работает его пищеварение.'),
  ('8139b24d-f8c3-4b60-b4f1-38bd25e609a6', 'Не выпускает ложку из рук? 🥄', 'Включите таймер кормления. Проанализируйте, сколько времени занимают попытки есть самостоятельно, и проверьте в приложении, соответствует ли питание малыша суточной норме.'),
  ('9cda88a3-f6c1-4cc3-92c3-5cb54bd45a91', 'Песочная терапия 🏖️', 'Не бойтесь испачкаться! Откройте для себя лучшие товары для игр с кинетическим песком и других сенсорных занятий в разделе рекомендованных товаров.'),
  ('f71cc78c-d1eb-4694-b94a-1843f80e2db1', 'Успокаивающие волны 🌊', 'Малыш не может уснуть после дня, полного активных открытий? Выберите шум океанских волн среди белых шумов, создайте в комнате волшебную атмосферу спокойствия и настройте его на сон.'),
  ('3787f491-d618-4351-acd6-86ff87689c17', 'Удары и толчки 🛑', 'Когда малыш злится, он внезапно замахивается или кусается? Спросите у Anacan AI, как с любовью справиться с таким поведением, характерным для 21-го месяца жизни.'),
  ('e29e6044-f61d-47fa-b1d7-8e16d2c4b2ce', 'Достаточно ли белка? 🍗', 'Белок необходим для роста малыша! С помощью инструмента контроля питания оцените сбалансированность его ежедневного рациона и восполните недостаток питательных веществ.'),
  ('e90a6ec1-ff62-4f86-8635-bb93512c7c35', 'Анализ сна с таймером ⏱️', 'Пора спать! Запустите таймер сна, проанализируйте режим малыша, чтобы убедиться, что он спит достаточно, и отдохните сами.'),
  ('0ac93f21-93e2-449d-b93b-ae00befc33f7', 'Боится темноты? 🌌', 'Малыш тревожится, когда вы выключаете свет в комнате? Включите среди белых шумов звук материнской утробы (биение сердца), чтобы подарить ему тёплое чувство защищённости.'),
  ('5831d6e0-9735-485f-be90-56915bc7047f', 'Теперь ваша очередь 🥗', 'Малыш уснул — пора на кухню! Среди полезных рецептов для женщин найдите богатый белком салат или детокс-воду, которые помогут быстро восстановить силы.'),
  ('5c1e8139-b38e-4666-8558-f6706af826d7', 'Маленький художник за работой 🖍️', 'Малыш любит рисовать каракули? Не сердитесь, даже если он испачкался краской! Сразу добавьте этот творческий момент в Альбом малыша и превратите его в воспоминание на всю жизнь.'),
  ('04f3e5a5-25b9-471b-9c8e-e6c96050313b', 'Разноцветный щит иммунитета 🛡️', 'С помощью инструмента контроля питания проверьте, получил ли сегодня малыш достаточно витамина C. Загляните в рецепты для малышей и выберите блюдо из разноцветных овощей.'),
  ('41231bd2-e2dd-4432-bc31-3952982f012e', 'Зубки почистили? 🪥', 'Малыш убегает, как только видит зубную щётку? Найдите музыкальные щётки или щётки-напальчники в рекомендованных товарах и превратите эту важную гигиеническую процедуру в весёлую игру.'),
  ('9603c325-693c-472c-b02b-2c75bd255571', 'Вы — герой сегодняшнего дня! 🌟', 'Несмотря на все капризы и усталость, вы прекрасно справляетесь! Откройте Дневник настроения и оставьте запись, за которую сегодня сможете поаплодировать себе стоя.'),
  ('a3eb6f02-e9da-422e-a243-1f395cf4661e', 'Режим сна сдвигается? ⏱️', 'Вечером малыш стал дольше бодрствовать? Запустите таймер сна, проанализируйте график и заново рассчитайте окна сна.'),
  ('aac102d8-edd5-4708-bab2-8cf3fcc9802c', 'Пищеварение замедлилось? 🚽', 'Во время утренней смены подгузника обратите внимание на стул. Если у малыша запор, не забудьте отметить это в приложении и добавить в меню продукты, богатые клетчаткой (грушу, овсянку).'),
  ('5bf406ee-d6c9-4691-8b5e-2df617ed2939', 'Исследуем природу 🌳', 'Малышу стало тесно в стенах дома? Найдите среди Мест для мам безопасный парк с большой песочницей и качелями и отправляйтесь подышать свежим воздухом.'),
  ('ad873c49-3118-429c-a9cf-3328699e514f', 'Макаронная погоня! 🍝', 'Малыш не хочет сидеть за столом? Посмотрите в рецептах для малышей идеи ярких макарон с овощами, чтобы снова привлечь его внимание к тарелке.'),
  ('dca5184f-26ea-4b5e-b78d-2f4c36c6bf42', 'Сила монотонных звуков 🌬️', 'Тишина пугает малыша? Включите в комнате среди Белых шумов звук фена или вентилятора и посмотрите, как он помогает создать ощущение безопасности во время сна.'),
  ('04ea5cc7-5f44-4fc9-ad82-59f8e294f0a5', 'Похвалите себя! 🌟', 'Сегодня вам удалось одеть малыша без слёз? Запишите даже самый маленький успех в Дневнике настроения и от души поаплодируйте своим материнским навыкам.'),
  ('5d85dda7-f62e-4490-8b4e-2ca037fd60ac', 'Щит иммунитета 🛡️', 'Готовы к смене сезона? С помощью инструмента контроля питания проверьте, получил ли малыш сегодня достаточно витамина C, и обновите меню.'),
  ('680f971c-231a-40e8-a772-413975915698', 'Удары и толчки 🛑', 'Внезапно разозлившись, малыш замахивается или толкается? Спросите у Anacan AI, как справиться с таким непростым поведением в 21.5 месяца, превратив ситуацию в игру.'),
  ('4bdcd931-fb36-41ca-9759-7a92226d97f9', 'Как понять, что малыш наелся? ⏱️', 'Если малыш начал бросать или выплёвывать еду, значит, он сообщает, что наелся. Остановите таймер кормления, отметьте, что норма выполнена, и проанализируйте аппетит.'),
  ('be36c558-6f81-4ee5-9a59-f79497bbff2d', 'Битва за чистку зубов 🪥', 'Малыш убегает, как только видит щётку? Посмотрите в Рекомендованных товарах музыкальные щётки или щётки-напальчники и превратите эту важную гигиеническую процедуру в весёлую игру.'),
  ('cd9296b3-74e7-4229-8871-9f5ee4fe977a', 'Водный баланс мамы 💧', 'У вас болит голова? Возможно, в заботах о малыше вы забыли пить воду. Приготовьте детокс-воду по полезным рецептам для женщин, чтобы освежиться и восстановить силы.'),
  ('2fbfd933-5095-452a-808e-4209aab75b80', 'Вам тоже нужно общение 👯‍♀️', 'Устали разговаривать только с малышом? Найдите среди Мест для мам центры с игровыми группами и познакомьтесь с другими мамами.'),
  ('a7d068ee-6f98-437e-b7f3-f2284f8fbdbc', 'Маленький подражатель 📱', 'Малыш делает вид, что разговаривает по телефону, как вы, и повторяет ваши жесты? Дети — наше самое точное отражение!'),
  ('bf157f3f-185f-45b5-aae0-091b2cf00653', 'Вместе, но по отдельности 👶', 'В парке малыш не играет с другими детьми, а только наблюдает за ними? Это параллельная игра! Откройте интересные факты об этом этапе социализации в разделе Блоги.'),
  ('9faf82e4-78ff-4782-a4bb-0d745a808c97', 'Протест против зелёного 🥦', 'Малыш отказывается от овощей? Узнайте в Рецептах для малышей, начинающих прикорм, как спрятать овощи во вкусных блинчиках.'),
  ('c2142ff9-9553-4737-9602-95ee907b4599', 'Не сдавайтесь усталости 🛋️', 'Сегодня вам хотелось всё бросить? Это нормально! Откройте Дневник настроения, запишите всё, что вас тревожит, и посвятите этот вечер только себе.'),
  ('cc7b1b1f-1c7c-4424-996a-a223a00c890e', 'Подгузник остаётся сухим? 🧻', 'Утренняя проверка! Если подгузник долго остаётся сухим, значит, пора приучать малыша к горшку. Сделайте отметку в трекере подгузников и проверьте статистику.'),
  ('3e9ffaf8-f631-4e99-946e-651b683eab7f', 'Фразы «Мама, иди сюда!» 🗣️', 'Малыш уже пытается соединять два слова в предложения? Это большой скачок в развитии речи! Сохраните его первые короткие фразы на память в трекере развития.'),
  ('473def83-9d3b-4698-becd-a16f81aed11d', 'Истерики в магазине 🛒', 'Малыш упал на пол из-за того, что вы не купили желаемое? Не паникуйте. Не обращая внимания на взгляды окружающих, спокойно присядьте до уровня его глаз.'),
  ('fdbb311e-3b42-4723-986f-c65a632fb53e', 'Сбросьте эмоциональный груз 📝', 'День был трудным? Выплесните эмоции, записав сегодняшний стресс в дневник настроения. Все мамы сталкиваются с такими истериками на публике — вы не одиноки.'),
  ('6b045729-7aac-44f1-99aa-a2dbeb7985f2', 'Список спасает 🛒', 'Память снова вас подвела? Не пытайтесь держать в голове каждую мелочь, которая закончилась дома: сразу добавьте её в список покупок, а ваш партнёр разберётся.'),
  ('7abb85ab-0b3c-4464-a5f4-15bfe391f1ba', 'Удар по мячу ⚽', 'Малыш пытается пнуть лежащий на земле мяч? Его равновесие и координация ног совершенствуются. Сыграйте с ним в небольшую игру с передачами мяча.'),
  ('eec0d21f-e4e1-482b-ae4c-9c9f182e42a1', 'Волшебный фон для сна 🪄', 'Малышу трудно уснуть? Создайте оригинальную сказку в разделе умных сказок и прочитайте её.'),
  ('51155148-f9ec-40a7-99a1-3f09cffe59c1', 'Папина игровая площадка 👨‍👧', 'Ваше терпение на исходе? Закройте дверь комнаты и оставьте малыша наедине с папой. Пусть сегодня вечером он возглавит домашнюю игровую площадку.'),
  ('81f2ea67-6d6b-45a8-9d3f-bdbc71d94739', 'Упрямство при выборе одежды 👗', 'Малыш хочет надеть толстый свитер летом, а летнюю футболку — зимой? Так формируется его воля. Предложите два подходящих варианта и оставьте выбор за ним, спросив: «Что ты хочешь надеть?»'),
  ('c6ce4007-ba3b-4772-8fba-7c4797ad17dd', 'Свежий воздух — лучшее лекарство 🌳', 'Малыш сильно капризничает и не может усидеть дома? Проверьте погоду, подберите подходящую одежду и сразу отправляйтесь в парк. Природа успокоит его быстрее всего.'),
  ('02902252-366d-405a-a62b-9c6f129b4a84', 'Как развивается интеллект? 🧠', 'Обязательно прочитайте в разделе блогов статью о домашних играх, которые стимулируют мозг и развивают восприятие цветов и форм у детей в возрасте 21.5 месяца.'),
  ('08bbbba1-9e53-4379-a09e-82d1079f7df6', 'Проверка запасов железа 🥩', 'Для активной работы мышц важно не допускать анемии. Проверьте сегодняшнее потребление железа с помощью инструмента контроля питания и сразу восполните его нехватку.'),
  ('cd9b8bec-56d4-42a3-a245-f71b148a61ef', 'От шума к тишине 🎶', 'После шумных игр внезапная тишина может напугать малыша. Включите в комнате звук фена из раздела «Белый шум» и убедитесь, как монотонный звук помогает уснуть.'),
  ('54f26234-4c50-45b3-9088-6a5b0c08fcd2', 'Водный баланс мамы 💧', 'У вас болит голова? Возможно, бегая за малышом, вы забыли пить воду. Приготовьте детокс-воду по полезным рецептам, чтобы взбодриться и восстановить силы.'),
  ('a27861d3-4efc-4b58-bec5-f3117fe589e3', 'Игры на сортировку 🔴🔵', 'Малышу нравится складывать красные предметы в одну сторону, а синие — в другую? Попросите Anacan AI предложить идеи игр, чтобы сделать это логическое упражнение ещё увлекательнее.'),
  ('d5617275-bfe2-4829-8f3f-d3b94dc34cfe', 'Проанализируем режим ⏱️', 'Малыш слишком долго бодрствует вечером? Запустите таймер сна и проследите за графиком. Возможно, пришло время сократить дневной сон на 15 минут.'),
  ('53a89401-1ea0-43b5-9469-65a0d422f72c', 'Нескончаемое шоу за столом 🥣', 'Играет с едой, бросает её на пол, но не ест. Включите таймер кормления и точно проанализируйте динамику аппетита по графику в приложении.'),
  ('86da0f7a-f021-4c65-aed2-e8e15433a92d', 'Любовь к вращению 🌀', 'Постоянно крутит колёса или крышки? Почитайте в Блогах об этой особой двигательной потребности и её роли в когнитивном развитии.'),
  ('9ea6bc21-5003-4afe-8fca-e2eebb549250', 'Песочная терапия 🏖️', 'Не бойтесь испачкаться! Найдите в Местах для мам площадку с песочницей. Игры с песком прекрасно способствуют сенсорному развитию.'),
  ('081299bb-b5c9-4af5-8361-9fa39bbdf0bf', 'Проблемы с запором? 🚽', 'Меняя утром подгузник, обратите внимание на стул малыша. Если есть запор, отметьте это в приложении и выберите в Рецептах для малышей, начинающих прикорм, продукты, богатые клетчаткой (грушу, овсянку).'),
  ('a11b2562-1cd1-41dc-ac6f-d1a7d36b53bb', 'Художник за работой 🎨', 'Рисуя каракули, раскрашивает и себя? Посмотрите в Рекомендованных товарах самые популярные среди мам безопасные смываемые краски.'),
  ('f9d59314-c8fe-45fa-9d77-efb82ec57626', 'Вечерний смех 📸', 'Не упустите забавный момент перед сном!'),
  ('34d9fbb9-7747-4964-9067-399afa7f0a7c', 'Натуральное успокаивающее средство 🍃', 'Малыш уснул. Забудьте о домашних делах! Заварите чай с мелиссой по одному из полезных рецептов для женщин, прилягте на диван и просто насладитесь тишиной.'),
  ('e79393de-a250-4c25-b9a8-93a1bc3692aa', 'Щит из витамина C 🍊', 'Иммунитет должен быть крепким. С помощью инструмента контроля питания проверьте, получил ли малыш сегодня достаточно витамина C, и добавьте красок в его меню.'),
  ('f29d2f2b-6e38-44f2-9d6b-467c0c3431e7', 'Битва за одежду 👗', 'Началось упрямое «Не хочу эту кофту!»? Узнайте у Anacan AI, как избежать утренних капризов при одевании и дать малышу право самостоятельного выбора.'),
  ('2a640acf-5bf6-44d4-b56f-00e902c2ddd2', 'Стремление к самостоятельности 🥣', 'Не отдаёт вам ложку? Запустите таймер кормления и проанализируйте, сколько времени занимает эта проба самостоятельности. А на разбросанную еду просто смотрите с улыбкой.'),
  ('cb94164a-0ea2-471c-9c17-a09778ea707c', 'Страх разлуки? 🌌', 'Начинает плакать, как только вы выходите из комнаты? Включите среди Белых шумов звуки материнской утробы (биение сердца), чтобы вернуть малышу знакомое чувство тепла и безопасности.'),
  ('d3ae908a-552f-4504-a171-436173eaeceb', 'Битва за чистку зубов 🪥', 'При виде щётки сразу сжимает рот? Посмотрите музыкальные щётки или щётки-напальчники в Рекомендованных товарах и превратите эту гигиеническую процедуру в весёлую игру.'),
  ('4932b8a8-d024-498c-ba06-d790b59bc198', 'Будьте добрее к себе 🧘‍♀️', 'Сегодня всё пошло не так? Запишите свои мысли в Дневнике настроения, простите себя, глубоко вдохните и отдохните.'),
  ('ed014436-2469-48a6-b579-7bce93de1ae7', 'Словарный запас растёт 🗣️', 'Малыш всё чаще говорит фразами из двух слов? Прямо сейчас спросите у Anacan AI, как поддержать это замечательное речевое развитие и научиться вести с малышом диалог.'),
  ('ed579060-f78c-4890-b8e4-2bb0c7729792', 'Цвет стула 💩', 'Обращайте на него внимание при смене подгузника! Следите за балансом жидкости и клетчатки с помощью инструмента контроля питания, чтобы предотвратить запор.'),
  ('15f9bb81-a16f-4753-a3f5-a2b604b16a46', 'Сон на свежем воздухе 🌳', 'Не может уснуть дома? Найдите в Местах для мам тихий зелёный парк. Свежий воздух улучшит и аппетит, и сон малыша.'),
  ('e02612f3-415f-450d-9411-e60c3bd32d09', 'Звук тишины 🌧️', 'После слишком насыщенного дня мозгу нужно замедлиться. Включите звук дождя в разделе «Белые шумы», чтобы естественным образом создать спокойную атмосферу для сна.'),
  ('3dca59c4-0add-4ccb-919d-3806c0dfdbf4', 'Природное успокоительное 🍃', 'День был полон истерик и шума? Включите шелест листьев в разделе «Белые шумы» и подарите нервной системе малыша и своей нервной системе настоящий массаж.'),
  ('3f5ef83a-d114-41da-8dd2-6bd3c11c45e8', 'Энергия за 5 минут ⚡', 'Не спешите с утра заниматься домашними делами. Приготовьте овсянку с ягодами — кладезь антиоксидантов — из раздела полезных рецептов и зарядите организм энергией.'),
  ('e5117ef0-d242-45f1-b114-50b3bfca72d9', 'Вам тоже нужно общение ☕', 'Устали разговаривать только с малышом? Найдите в разделе «Места для мам» детские кафе, где часто собираются мамы, и пообщайтесь.'),
  ('622216cc-100d-4e85-95dc-7d70e41c5761', 'Хочет есть самостоятельно 🥣', 'Не отдаёт вам ложку? Запустите таймер кормления и проанализируйте, сколько времени занимает эта проба самостоятельности. А на разбросанную еду просто смотрите с улыбкой.'),
  ('9387504c-dde1-4fdb-977d-53c3dfbb83a2', 'Безопасные открытия ⚠️', 'Шкафы, ящики... Для маленького исследователя они могут быть опасны! Загляните в раздел рекомендуемых товаров и присмотритесь к защитным накладкам для мебели и блокираторам безопасности.'),
  ('bdef77ef-7476-4b14-a4a3-51d31635951f', 'Проанализируем режим ⏱️', 'Вечернее время бодрствования слишком затянулось? Запустите таймер сна. Возможно, пора сократить дневной сон на 15 минут.'),
  ('1221d1a0-4818-4be5-bd89-1e05d41e52f3', 'Боль в спине у мамы 🧘‍♀️', 'Спина болит из-за того, что вы часто поднимаете малыша? Позаботьтесь о себе: заварите восстанавливающий зелёный чай с имбирём, обладающий противовоспалительными свойствами, из раздела полезных рецептов.'),
  ('5e592d03-eefe-420f-a53e-496dd3dda1cc', 'Не тот стакан? 🥤', 'Началась настоящая буря из-за того, что вы налили воду в синий стакан, а не в красный? Сразу спросите у Anacan AI, как спокойно справляться с такими, на первый взгляд, нелепыми истериками.'),
  ('5fa9e0c4-2198-4898-832b-73dabf54c160', 'Выплесните эмоции 📝', 'Сегодня малыш без конца плакал, и вы очень устали. Не вините себя. Запишите всю свою усталость в Дневник настроения, освободите мысли и отдохните.'),
  ('17a5c3c0-5b0c-46d3-a055-3e4119a58d57', 'Пусть сам расскажет сказку 📖', 'Малыш смотрит на картинки в книге и что-то рассказывает на своём языке? Сразу добавьте этот чудесный момент воображения в Альбом малыша в виде видео со звуком и сохраните на память.'),
  ('200bc386-90fc-4565-9a45-00b11604777d', 'Вырвитесь из четырёх стен 🌳', 'Дома малыш не может выплеснуть энергию и всё разбрасывает? Откройте карту «Места для мам», найдите парк с безопасной площадкой для бега и отправляйтесь на свежий воздух.'),
  ('f2808bcb-7bbf-4422-8d7a-f49af045384f', 'Не хочет делиться? 🧸', 'В парке никому не даёт свои игрушки? Обязательно прочитайте в разделе блогов практическую статью о том, как научить ребёнка в 22 месяца играть по очереди.'),
  ('5ba12c84-c569-4cd8-9800-87090cc15d44', 'Кальциевый щит 🦴', 'Кальций необходим для костей и зубов. С помощью инструмента контроля питания проверьте, получил ли малыш сегодня достаточную норму йогурта и сыра.'),
  ('7ecc82ad-1a38-4c53-9465-dd5ae12ea103', 'Обувь стала тесной? 📏', 'В последнее время малыш часто спотыкается во время бега? Возможно, его стопа выросла! Внесите текущий рост и размеры в Трекер веса, чтобы отслеживать физическое развитие.'),
  ('d79dc60f-8bf8-4657-a15d-609886c6c332', 'Бросает еду на пол? 🥣', 'Если малыш начал сбрасывать ложку и еду со стола, возможно, он уже наелся или ему стало скучно. Остановите таймер кормления, проанализируйте динамику аппетита на графике и завершите приём пищи.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ru = v.t, body_ru = v.b
FROM (VALUES
  ('1e63b6e0-14e2-4999-89f7-2f0db3539031'::uuid, 'Ночные пробуждения ⏱️', 'Запустите таймер сна! По статистическому графику таймера вы сразу сможете понять, связаны ли пробуждения с ночными страхами или регрессом сна.'),
  ('8665ce13-4bbc-4643-86cd-402909af004b', 'Потребность в железе 🥩', 'Подкрепите маленького бегуна! С помощью трекера питания проверьте, получил ли он сегодня достаточно железа, и скорректируйте его меню.'),
  ('2097babe-f9a8-45d7-927c-24d3ef08f38a', 'Звонкий смех 📸', 'Он забавно хмурится или смотрит на вас и заливается смехом? Украсьте этот милый момент стикерами из фотосессии малыша и добавьте в альбом на долгую память.'),
  ('3d45eb72-a379-4b0c-95b5-43a9f90cd232', 'Сила монотонных звуков 🎶', 'После шумного дня внезапная тишина может его напугать. Включите звук фена в разделе «Белый шум», чтобы создать ощущение безопасности во время сна.'),
  ('af588f6b-bdb1-4b34-b380-81bc42d5db3f', 'Мамина батарейка 🔋', 'Сил совсем не осталось? Не спешите за сладким! Приготовьте питательный белковый смузи с арахисовой пастой по одному из полезных рецептов для женщин — он быстро зарядит вас энергией.'),
  ('3f0a8eb7-b5c5-4230-90cc-9ba54d5ff248', 'Одежда снова мала? 📏', 'Похоже, у малыша скачок роста! Внесите текущий рост и размер обуви в Трекер развития и с гордостью наблюдайте, как поднимается кривая роста.'),
  ('5bace5b1-8b66-491f-869e-157ff26e9bbf', 'В поисках логики 🧩', 'Ему наскучили привычные игрушки? Найдите в разделе рекомендованных товаров безопасные пазлы по возрасту, которые помогут развить мышление.'),
  ('e03c5d95-be6c-414b-b518-86431da64323', 'Внезапно бьёт и кусается 🦖', 'В гневе он становится агрессивным? Узнайте у Anacan AI, как с помощью игры мягко скорректировать такое поведение.'),
  ('53335520-c239-4dc6-bb98-8950aeac052d', 'Овощи играют в прятки 🥕', 'Отказывается от моркови и шпината? В рецептах для малышей узнайте, как искусно спрятать эти витаминные овощи во вкусных блинчиках.'),
  ('9cc1439a-0d58-4e5e-94b1-3125467bf825', 'Не мучайте себя чувством вины 💖', 'Сегодня вы повысили голос? Не вините себя. Запишите свои чувства в Дневнике настроения — вы всё равно самая лучшая мама для своего малыша.'),
  ('bd4e1f9a-2949-4f64-b861-47344e3cdbfc', 'Бесконечное шоу за столом ⏱️', 'Он играет с едой, но не ест? Включите таймер кормления, отслеживайте продолжительность приёма пищи и точно анализируйте изменения аппетита.'),
  ('31a9cc16-de41-4012-b357-b74232182120', 'Сегодняшняя героиня — вы 🌟', 'Каждый новый навык, который он осваивает, — результат вашего труда. Откройте Дневник настроения и оставьте запись, за которую сегодня вам захочется аплодировать себе стоя!'),
  ('39267d40-2480-48f4-9716-e425031ba3b3', 'Вместе, но по отдельности 👶', 'В парке он не играет с другими детьми, а только наблюдает за ними? Это параллельная игра! Почитайте в разделе блогов об этом естественном этапе социализации.'),
  ('7ae07c2d-565f-4b45-bebf-b9e3ab799a99', 'Перекус без сахара 🍪', 'Магазинное печенье не понадобится. Откройте в рецептах для малышей полезные сладости с финиками и яблоками, которые можно приготовить дома за 10 минут.'),
  ('4c3b97db-69e0-4349-8a8d-b599fed49f3d', 'Ночной подгузник переполнен? 🧻', 'Если утром подгузник очень тяжёлый, это может нарушать ночной сон. Отмечайте мочеиспускания в Трекере подгузников и анализируйте статистику, чтобы скорректировать употребление жидкости вечером.'),
  ('c15f640c-d99c-497d-be3f-c7f256e90fd8', 'Маленький исследователь на кухне 🥦', 'Он тоже хочет готовить вместе с вами? Найдите в разделе рецептов простые и вкусные овощные кексы, которые можно приготовить вместе с малышом, уже начавшим прикорм.'),
  ('685f831c-092e-4c6a-aaf1-8fc0973b0182', '5 минут для заряда энергии ⚡', 'Не спешите с утра заниматься домашними делами. Приготовьте овсянку с ягодами — кладезь антиоксидантов из раздела полезных рецептов для женщин — и наполните организм энергией.'),
  ('a2d43041-fecf-4b9c-87c8-b48f899e1810', 'Ночные пробуждения ⏱️', 'Запустите таймер сна! Статистический график таймера поможет точно определить, связаны ли пробуждения с ночным страхом или регрессом сна, и скорректировать режим.'),
  ('ca7d5385-3628-4318-a29d-52e41611d6dd', 'Интеллект продолжает развиваться 🧠', 'Малыш любит всё сортировать! Откройте раздел «Рекомендуемые товары» и найдите геометрические головоломки (пазлы), которые стимулируют работу мозга и развивают восприятие цветов и форм.'),
  ('2c09d1ae-89ad-4429-b136-e47270b6a957', 'Сегодня вы — герой 🌟', 'Каждый новый навык, который малыш осваивает, — результат ваших усилий. Откройте Дневник настроения и оставьте сегодня запись, за которую вам захочется поаплодировать себе стоя!'),
  ('61d69ed1-ecb9-44fd-ac6a-cb922359921f', 'Маленький художник весь в краске! 📸', 'Малыш разрисовал себя и стену? Вместо того чтобы сердиться, украсьте этот забавный момент весёлыми стикерами в разделе «Фотосессия малыша» и сохраните в альбоме как память на всю жизнь.'),
  ('f52268ca-f991-4824-88f4-73fcbe961356', 'У малыша запор? 💩', 'Меняя утром подгузник, обратите внимание на стул малыша. Если у него запор, отметьте это в приложении и обязательно добавьте в меню продукты, богатые клетчаткой, с помощью инструмента контроля питания.'),
  ('596bb7f3-6693-46d8-ab7c-2abd702c9a04', 'Чувство безопасности 🌌', 'Малыш боится, когда вы выключаете свет в комнате? Включите среди Белых шумов звуки материнской утробы (биение сердца), чтобы подарить ему знакомое тёплое чувство безопасности и настроить на сон.'),
  ('85644ffd-0693-4b98-8af6-f0210f7b50a9', 'Вам тоже нужно общение ☕', 'Устали разговаривать только с малышом? Найдите в разделе «Места для мам» детские кафе, где часто собираются мамы, и откройте для себя новый круг общения.'),
  ('bafa81ec-ed9b-4642-a5cd-3249a43a8c84', 'Удары и толчки 🛑', 'Малыш внезапно начинает драться, когда злится? Обратитесь к Anacan AI, чтобы узнать, как мягко скорректировать характерные для этого возраста вспышки агрессии, превратив обучение в игру.'),
  ('1b86b21d-6e02-4ac7-a965-21bdbcf95db5', 'Скачок в развитии логики 🧩', 'Малыш начинает понимать причинно-следственные связи. В разделе «Блоги» прочитайте о лучших домашних играх для ускорения познавательного развития детей в возрасте 22 месяцев и попробуйте их на практике.'),
  ('6351737e-949c-4fb6-a2b3-5af919c832cf', 'Проанализируем режим ⏱️', 'Вечерний период бодрствования стал слишком долгим? Запустите таймер сна и следите за графиком. Возможно, пришло время сократить дневной сон на 15 минут.'),
  ('f36fcaba-998e-48e4-a1c2-d085b47ccd2f', 'Проверим запасы железа 🥩', 'Чтобы мышцы оставались активными, важно не допускать анемии. Проверьте с помощью инструмента контроля питания, достаточно ли железа было получено сегодня, и сразу восполните недостаток.'),
  ('04a88ead-f1bb-44fb-a8ea-9c02adfcfb9b', 'Перекус без сахара 🍪', 'Покупное печенье не понадобится. Откройте рецепты для малышей и найдите полезные сладости с финиками и яблоками, которые можно приготовить дома за 10 минут и которые обязательно пробудят аппетит.'),
  ('7b343e4c-3369-4f05-b976-97c243e8ed13', 'Скачок роста! 📏', 'Рукава рубашек снова стали короткими? Физическое развитие ускоряется. Внесите текущие параметры в Трекер развития и с гордостью полюбуйтесь графиком роста.'),
  ('7c55b3cc-0f0f-47b0-8148-d026b3b7590e', 'Скоро появятся новые слова! 🗣️', 'Малыш произносит много звуков, но пока не говорит целых слов? Чтобы помочь пассивному словарному запасу перейти в активный, добавляйте эти забавные попытки произнести слоги в Аудиоальбом малыша и наблюдайте за прогрессом.'),
  ('614145be-ebb6-498c-9b3f-26a829cb6b6d', 'Маленький помощник 🧹', 'Малыш уже хочет участвовать в домашних делах. В разделе «Блоги» прочитайте, как в игровой форме привить ребёнку в возрасте 22.5 месяцев чувство ответственности, и примените советы на практике.'),
  ('e1d32a6a-e4ea-4c4f-8731-157813de9284', 'Знакомство с другими мамами 👯‍♀️', 'Пусть малыш играет, а вы общаетесь! Найдите на карте дружественных мамам мест центр с игровыми группами и выберитесь из дома.'),
  ('2e576d6b-3baa-4d91-b939-7173553eee26', 'Чистим зубки? 🪥', 'При виде щётки малыш сразу сжимает рот? Получите практические советы от Anacan AI и узнайте, как превратить эту гигиеническую процедуру в весёлую игру.'),
  ('8e98b7fa-b3a5-48a4-896a-9431c201a988', 'Природное успокоительное 🍃', 'День выдался слишком шумным? Таймер остановился. Забудьте о домашних делах, заварите чай с мелиссой из раздела полезных рецептов и просто насладитесь тишиной.'),
  ('e49913ea-33f5-4d6e-8204-24fdfbb6dfec', 'В поисках полезных сладостей 🍎', 'Пора отказаться от магазинного печенья! Откройте в рецептах для малышей полезное печенье с финиками и яблоками, которое можно приготовить дома за 10 минут, и порадуйте аппетит малыша.'),
  ('8566be64-ecf0-4dc1-8d90-20c831db74ad', 'Страх разлуки вернулся? 🌌', 'Малыш плачет, как только вы выходите из комнаты? Включите звук сердцебиения в разделе «Белый шум», чтобы подарить ему чувство безопасности и настроить на сон.'),
  ('942d7419-7926-47e6-b70e-db59dc58e301', 'Брюки снова стали коротки! 📏', 'Рукава рубашек стали малы? У малыша скачок физического развития. Внесите текущие параметры в трекер веса и с гордостью посмотрите на график роста.'),
  ('95ec49ae-492b-442d-be59-8db9c9f8c8e4', 'Забавное произношение 🗣️', 'Некоторые слова малыш произносит так мило и забавно! Не упустите эти драгоценные моменты. Загрузите видео со звуком в альбом малыша, чтобы в будущем посмеяться вместе.'),
  ('25439bfb-873c-4735-bc03-f5aa2d6b8ff2', 'Достаточно ли белка? 🍗', 'Для развития активных мышц необходим белок. Оцените ежедневный баланс питания малыша с помощью инструмента контроля питания и обогатите его меню.'),
  ('a458d5c8-d74f-4a15-a4a9-53e24632f8f7', 'Я сделаю это сам! 👕', 'Одевание по утрам превращается в настоящий кризис? Прямо сейчас спросите у Anacan AI, как справляться с упрямством и правильно предоставлять малышу выбор.'),
  ('f5dd0c22-b8ec-461e-a5b4-9045aa3ae282', 'Книги нужно читать, а не рвать 📖', 'Малыш рвёт страницы во время вечерней сказки? Прямо сейчас прочитайте в разделе блогов, как решить эту проблему, не отбив у него интерес к чтению.'),
  ('19a9511e-358f-41a2-bbf2-d966afa6ffa9', 'Проанализируем режим ⏱️', 'Вечером малыш бодрствует слишком долго? Запустите таймер сна и проследите за графиком. Возможно, пришло время сократить дневной сон на 15 минут.'),
  ('65db46df-45b6-4a1e-ae35-6797a38fafce', 'Терапия песком и грязью 🏖️', 'Не бойтесь испачкаться! Прямо сейчас откройте для себя лучшие средства для игр с кинетическим песком и сенсорных занятий в разделе рекомендованных товаров.'),
  ('dc3f8791-df91-4f2d-8dc5-44a0fff017da', 'Это ваша заслуга 🌟', 'Каждый новый навык, которому малыш учится, каждый уверенный шаг — результат ваших стараний. Откройте дневник настроения и сегодня напишите заметку о том, как вы собой гордитесь!'),
  ('2dafd9b8-26be-4b73-a1b1-cede334643cd', 'Сколько раз сегодня вы сказали «Нет»? 💆‍♀️', 'Вы очень устали, правда? Сделайте глубокий вдох. Выплесните все свои чувства в дневнике настроения, отбросьте чувство вины и просто отдохните.'),
  ('379a5991-8f1e-48b3-9f27-5e21468d8859', 'Малыш проснулся в сухом подгузнике? 🩲', 'Утром при смене подгузника вы заметили, что он сухой? Прямо сейчас спросите у Anacan AI, когда лучше всего начинать приучение к горшку и какие психологические методы использовать.'),
  ('9728ea76-627d-4390-8b60-df7f4a0dc917', 'Любовь к кексам 🧁', 'Малыш просит сладкого? Не спешите в магазин. Найдите в рецептах для малышей домашний кекс без сахара с бананом и овсянкой, который готовится за 10 минут, и сохраните высокий балл здоровья в инструменте контроля питания.'),
  ('6d017679-be1f-4b11-b8fd-36574013a33a', 'Воображение не знает границ 🧸', 'Кормит мишку или лечит вас? Снимите это проявление эмпатии на короткое видео, добавьте в Альбом малыша и сохраните воспоминание на всю жизнь.'),
  ('f542a783-2187-4790-b865-10366397c49d', 'Безопасные открытия ⚠️', 'Шкафы, ящики... Для маленького исследователя они могут быть опасны! Обязательно загляните в раздел «Рекомендуемые товары» и выберите защитные накладки для мебели и замки безопасности.'),
  ('8497fe17-ba82-4513-8de8-e30bada196eb', 'Сбросьте усталость за день 🛋️', 'Вы выбились из сил, бегая за малышом. Ребёнок уснул — теперь выпишите весь стресс в Дневник настроения и налейте себе чашку травяного чая.'),
  ('8fc02957-0717-4600-94a0-03ec95b3ecc9', 'Сигналы готовности к горшку? 🚽', 'Утром подгузник остаётся совершенно сухим? Возможно, это идеальное время для начала приучения к горшку. Отметьте это в Трекере подгузников и ознакомьтесь со статьями о подготовке в приложении.'),
  ('924176de-d987-4381-ba5c-3bdf618f72f9', 'Не хочет есть мясо? 🥩', 'Малышу нужен белок, но он отказывается от мяса? Найдите в рецептах для малышей вкусные куриные тефтели, которые легко жевать, и восполните норму в инструменте Контроля питания.'),
  ('75bd2c8f-8af9-437f-ac84-6c69bc76ea8c', 'План побега из кровати 🏃‍♂️', 'Убегает из комнаты, когда приходит время сна? Запустите Таймер сна, включите шум леса из раздела «Белые шумы» и превратите комнату в тихую уютную пещеру.'),
  ('bd146fb2-5002-4d8c-824b-58bbd81c0c9b', 'Утреннее упрямство 🛑', 'Капризы «Я это не надену!» и «Я это не буду есть!» осложняют ваше утро? Сразу напишите Anacan AI и узнайте, как реагировать на характерную для этого возраста проверку границ.'),
  ('fdf24d1a-f6c7-451f-974c-c9a5a3bf1aa7', 'Прыжки от стены к дивану! 🧗‍♂️', 'Он настоящий каскадёр! Найдите в разделе «Места для мам» центры с просторными игровыми залами и дайте малышу вволю выплеснуть энергию.'),
  ('1a8b991b-0214-44d5-b2fa-cca54722c709', 'Произведение искусства на стене 🎨', 'Взял карандаш и разрисовал стену? Не сердитесь! Добавьте эту милую шалость в альбом с забавными рамками из раздела «Фотосессия малыша» и просто улыбнитесь.'),
  ('5ded1b01-b65d-40da-8990-d4cd09688a69', 'Внезапные пробуждения вернулись? ⏱️', 'Просыпается среди ночи с плачем? Посмотрите график в Таймере сна. Если дневной сон заканчивается слишком поздно, вечером малышу будет сложнее перейти в глубокий сон.'),
  ('79c4c89f-ba17-4c97-96b0-f5dc444414e9', 'Мамина пауза на кофе ☕', 'Не забывайте о себе! Приготовьте заряжающий энергией овсяный перекус из раздела «Полезные рецепты для женщин» и насладитесь чашкой кофе.'),
  ('178de938-0734-4759-bd61-91671bd355ba', 'Правильный выбор горшка 🚽', 'Начните визуальную подготовку к приучению к туалету! Обязательно загляните в раздел «Рекомендуемые товары» и выберите самые удобные и привлекательные модели горшков, проверенные мамами.'),
  ('2f6cc31a-8b1b-415e-861a-b476799ab26e', 'Достаточно ли Омега-3? 🐟', 'Для быстрого развития мозга важны рыба или грецкие орехи! Проверьте потребление Омега-3 за эту неделю с помощью инструмента Контроля питания и сразу скорректируйте меню.'),
  ('f1e65e7a-efb2-4ee4-9b90-639511a93965', 'Вы не обязаны быть идеальной 💖', 'Сегодня дома беспорядок, а еда приготовлена с опозданием? Ничего страшного! Запишите свои мысли в Дневник настроения и помните: ваш ребёнок любит вас в любом состоянии.'),
  ('0ec68466-1a64-4bc2-ab11-6f19a539925d', 'Больше воды — легче пищеварение 💧', 'Как работает кишечник активного малыша? Вносите наблюдения при смене подгузника. Если есть риск запора, ознакомьтесь в приложении с рекомендациями по продуктам, богатым натуральной клетчаткой.'),
  ('60b3ac1d-dc8e-4802-b644-6bc09bfcea1f', 'Битва за еду окончена ⏱️', 'Отбрасывает ложку за столом? Остановите Таймер кормления — ребёнок уже сыт. Анализируйте график аппетита и избегайте кормления через силу.'),
  ('057bf87f-0bbd-415e-a240-9562e85f263d', 'Битва за одежду! 👗', 'Утреннее одевание превращается в настоящий кризис? Предложите малышу две разные футболки, чтобы дать ему свободу выбора.'),
  ('2ac666c9-f3bd-4794-a981-76652151d626', 'Трёт глазки? 🥱', 'Это сигнал ко сну! Запустите таймер сна, включите в разделе «Белый шум» шелест леса, чтобы мягко настроить малыша на сон, и следите за режимом.'),
  ('5ce76677-164d-4bc6-835d-9ba614b47d9b', 'Мамино время для кофе ☕', 'Пора сделать перерыв. Пока малыш играет самостоятельно, восстановите силы с помощью богатого антиоксидантами зелёного чая или лёгкого кофе из раздела полезных рецептов для женщин.'),
  ('35dcaff3-d09c-4c5a-87b5-8fa048fa86b8', 'Лезет на стены дома? 🧗', 'Малышу обязательно нужно выплеснуть энергию! Откройте карту мест для мам, найдите новый парк с безопасной площадкой для бега и горкой и дайте ему вдоволь порезвиться.'),
  ('3eefbe35-a241-4512-8320-0993efa296ef', 'Побег из-за стола! 🏃‍♂️', 'Бросает еду на полпути и убегает? Остановите таймер кормления. Вместо того чтобы заставлять малыша есть, прочитайте в разделе «Блоги», как естественным образом улучшить аппетит.'),
  ('ecf28bb2-147f-47c5-8e81-503885a13db6', 'Почему обувь стала тесной? 👟', 'Малыш часто спотыкается во время бега? Возможно, его стопа выросла! Внесите текущие параметры в трекер развития, сразу проверьте скачок роста и проанализируйте изменения.'),
  ('c795e5c9-7249-46e0-9227-8cae7b9774c9', 'Правильно подбирает фигуры? 🧩', 'Чтобы поддержать развитие логики, прямо сейчас найдите в рекомендованных товарах подходящие по возрасту геометрические пазлы и развивающие деревянные игрушки.'),
  ('ce8c0e6d-8b04-4829-9134-54da2f1cc621', 'Достаточно ли белка? 🥚', 'Белок необходим быстро растущим мышцам. Рассчитайте сегодняшнюю норму с помощью инструмента контроля питания и скорректируйте меню, если белка не хватает.'),
  ('d5a7dad1-9dd5-40f2-bc6d-27d7e6052c76', 'Первые серьёзные разговоры 🗣️', 'Малыш подолгу что-то обсуждает с вами на своём языке? Сохраните этот забавный и бесценный момент в Альбоме малыша в виде видео со звуком.'),
  ('6d0154ad-03f9-4392-b21e-d18f214374b2', 'Внезапные крики! 🛑', 'Малыш падает на пол, когда не получает желаемого? Спросите нашего экспертного помощника Anacan AI, как в игровой форме справляться с эмоциональными вспышками, которые учащаются ближе к 23-му месяцу.'),
  ('9e25f59c-eab1-44ee-ae76-e1b1ae42dc4c', 'Пусть не забывает пить воду 💧', 'Как работает кишечник у активного малыша? Отмечайте стул при смене подгузника. Если есть риск запора, обязательно ознакомьтесь в приложении с рекомендациями по продуктам, богатым натуральной клетчаткой.'),
  ('bc4d0552-0cde-4c7a-bca8-4b2551c95ad7', 'Боится темноты? 🌌', 'Плачет, когда вы выключаете свет в комнате? Включите в разделе «Белый шум» звуки материнской утробы (биение сердца), чтобы подарить малышу знакомое чувство полной безопасности.'),
  ('1ecb40c2-379b-4b51-a326-4d93bf0ac050', 'Берегите утреннюю энергию ⚡', 'Не начинайте день натощак! Позаботьтесь о себе: выберите в разделе полезных рецептов для женщин вкусный и сытный овсяный кекс, который готовится за 5 минут.'),
  ('69fe7fde-913c-4ff4-8fe2-fcbdad210e16', 'Вам тоже нужны друзья 👯‍♀️', 'Устали разговаривать только с малышом? Найдите среди мест для мам центры с игровыми группами, общайтесь с другими мамами и делитесь опытом.'),
  ('f7991ada-b885-400f-9f72-4df6d1f9477e', 'Дневной сон становится короче? ⏱️', 'Малыш долго засыпал вечером? Запустите таймер сна и следите за режимом. Возможно, настало время сократить дневной сон на 15-20 минут.'),
  ('0347ce08-669e-4477-9fbc-63c1580b9edb', 'Сегодняшний герой — вы 🌟', 'Каждый новый навык малыша и каждый его уверенный шаг — результат ваших усилий. Откройте Дневник настроения и напишите сегодня заметку о том, за что вы собой гордитесь!'),
  ('19e2869e-6998-4c65-b3a4-edbc6a06f435', 'Убегает при виде зелени? 🥦', 'Начал привередничать из-за цвета еды? Откройте рецепты для малышей и узнайте, как умело спрятать шпинат и морковь во вкусных панкейках, чтобы пробудить аппетит.'),
  ('b793a816-4035-4e2c-8e9a-647949d5fa3a', 'Маленький художник за работой 🎨', 'Не сердитесь, даже если малыш весь в краске! Украсьте этот творческий момент весёлыми стикерами из раздела «Фотосессия малыша», добавьте его в альбом и улыбнитесь.'),
  ('addb392c-deee-4dda-99c7-ed94d64cd987', 'Удары и толчки 🦖', 'Когда малыш злится, он внезапно начинает драться или толкает друзей? Узнайте у Anacan AI, как мягко направить в другое русло характерные для этого возраста бурные эмоции.'),
  ('ebc52a7e-1091-4bf2-89de-cc6e528ddbe1', 'Кости становятся крепче 🦴', 'Для быстрого развития необходим кальций. С помощью трекера питания проверьте, получил ли малыш сегодня норму сыра и йогурта, и восполните недостающее.'),
  ('ee59618a-2d83-4249-b1e6-0323265cd134', 'Природное успокоительное 🍃', 'День выдался слишком шумным? Таймер остановлен. Забудьте о домашних делах, включите в разделе «Белые шумы» журчание ручья и прилягте на диван отдохнуть.'),
  ('5557465c-fb11-48b9-90c2-fc336972f19c', 'Книги нужно читать, а не рвать 📖', 'Малыш рвёт страницы во время вечерней сказки? Прямо сейчас прочитайте в разделе «Блоги», как решить эту проблему, не отбив у него интерес к чтению.'),
  ('5b487ba9-a209-4653-a8fe-4315e87398df', 'Бесконечное шоу в кровати 🛌', 'Вместо сна малыш прыгает на кровати? Запустите таймер сна и следите за графиком. Проанализируйте, не успел ли он выплеснуть энергию или, наоборот, переутомился.'),
  ('9fb4af87-300a-4df0-8f02-48703cd4da3a', 'Битва за чистку зубов 🪥', 'При виде щётки малыш сразу крепко сжимает рот? Посмотрите музыкальные щётки или щётки-напальчники в разделе «Рекомендуемые товары» и узнайте, как превратить эту важную процедуру в весёлую игру.'),
  ('0b69ffc4-e10f-4228-a354-3609a2cf48bb', 'Укусы в гневе 🦖', 'Когда малыш злится, он кусает друзей или вас? Прямо сейчас спросите нашего помощника-эксперта Anacan AI, как с любовью справиться с этим непростым поведением.'),
  ('0bd19a92-8f32-4626-9053-67019de34d6b', 'Ест только хлеб? 🍞', 'Отодвигает белковую пищу и овощи, требуя только углеводы? С помощью трекера питания подсчитайте, сколько полезной пищи малыш получил сегодня, и скорректируйте рацион.'),
  ('3794ac2c-9f00-4406-8f93-da27c84ffed3', 'Так и тянет порвать страницы 📖', 'Во время вечерней сказки малыш пытается порвать страницы книги? Прочитайте в разделе «Блоги», как решить эту проблему, не отбив у него интерес к чтению.'),
  ('21c31221-548f-42a2-945f-424351b307be', 'Произведение искусства на стене 🎨', 'Малыш взял карандаш и разрисовал стену? Не сердитесь! Добавьте эту милую шалость в альбом, украсив её забавными рамками из раздела «Фотосессия малыша», и просто улыбнитесь.'),
  ('cb6101a7-dbfd-4d36-944e-5acbfd6bc964', 'Болит спина? 🧘‍♀️', 'Постоянно поднимать малыша весом 12+ кг непросто. Заварите по одному из полезных рецептов противовоспалительный имбирный чай, помогающий расслабить мышцы, и отдохните.'),
  ('e15645b0-86cf-412b-8fdc-f53e32110fb7', 'План побега из кроватки 🏃‍♂️', 'Когда приходит время сна, малыш вылезает из кроватки? Запустите таймер сна, включите монотонный стук поезда в разделе «Белые шумы» и мягко настройте его на сон.'),
  ('406278a2-debe-4851-9b00-479abeb4b13e', 'Сигналы готовности к горшку? 🚽', 'Утром подгузник остаётся совершенно сухим? Возможно, настало идеальное время для приучения к туалету. Отметьте это в трекере подгузников и выберите эргономичный горшок в разделе «Рекомендуемые товары».'),
  ('67af77d4-bcc0-42c9-9d93-190208cee7c5', 'Хочет играть один? 👶', 'В парке малыш не присоединяется к другим детям, а наблюдает со стороны? Узнайте самые интересные научные факты об этой здоровой форме параллельной игры в разделе «Блоги».'),
  ('789f31a5-225d-4210-8e89-eb69a6524d9d', 'В поисках идеальной мамы 💖', 'Сегодня вы немного повысили голос? Не мучайте себя чувством вины. Запишите свои чувства в Дневник настроения — для малыша вы всё равно самая лучшая.'),
  ('354016aa-fdff-494e-9db1-d11124a417c8', 'Проанализируем режим ⏱️', 'Вечернее бодрствование слишком затянулось? Запустите таймер сна и проследите за графиком. Возможно, пришло время сократить дневной сон на 15 минут.'),
  ('d03661d9-e587-4637-b9c4-cf2d9c6ce6c8', 'Терапия песком и грязью 🏖️', 'Не бойтесь испачкаться! Найдите в разделе «Места для мам» безопасный парк с песочницей для сенсорного развития и позвольте малышу побыть наедине с природой.'),
  ('dd733e39-eed2-478b-9a6a-adcec13e6fc1', 'Лучший друг железа 🥩', 'Для усвоения железа организму необходим витамин C! Проверьте сегодняшнее меню с помощью инструмента контроля питания и добавьте к мясу салат с большим количеством лимонного сока.'),
  ('97ab1430-c17a-4645-93d1-2d0b7261c822', 'Ест только хлеб? 🍞', 'Отодвигает белковые продукты и овощи и просит только углеводы? С помощью инструмента контроля питания подсчитайте, сколько полезной пищи малыш съел сегодня, и скорректируйте рацион.'),
  ('b991e93f-39a2-4eb7-afdb-453c13a1d55b', 'Так и хочется порвать страницы 📖', 'Во время вечерней сказки малыш пытается порвать страницы книги? В разделе «Блоги» прочитайте, как решить эту проблему, не отбив у него интерес к чтению.'),
  ('fa426bdb-bb7f-4a4f-9e93-d26f8fe4998a', 'Укусы в порыве злости 🦖', 'Когда малыш злится, он кусает друзей или вас? Прямо сейчас спросите у нашего ИИ-помощника Anacan, как с любовью справиться с таким непростым поведением.'),
  ('1c3f0685-89ab-4827-a123-f84fa8b82551', 'Болит спина? 🧘‍♀️', 'Постоянно поднимать малыша весом 12+ кг непросто. Приготовьте противовоспалительный имбирный чай для расслабления мышц по рецепту из раздела полезных рецептов для женщин и отдохните.'),
  ('71912e32-5753-4990-97c7-dcf5458c45d1', 'Произведение искусства на стене 🎨', 'Малыш взял карандаш и разрисовал стену? Не сердитесь! Добавьте эту милую шалость в альбом с забавными рамками из раздела «Фотосессия малыша» и просто улыбнитесь.'),
  ('aa4285be-2d37-4c2f-82d8-24587b052512', 'План побега из кроватки 🏃‍♂️', 'Когда приходит время спать, малыш перелезает через бортик кроватки? Запустите таймер сна, включите монотонный стук поезда в разделе «Белый шум» и спокойно настройте его на сон.'),
  ('7057ef80-4efd-430a-a44f-a695f7bd7b53', 'Прыжок на двух ногах 🦘', 'Стоя на месте, малыш пытается подпрыгнуть сразу на двух ногах? Выглядит очень забавно, правда? Обязательно запечатлейте этот момент.'),
  ('a5fa8450-6478-40eb-8c4a-42d08f636974', 'Музыкальное умиротворение 🎶', 'Самый простой способ справиться с вечерними капризами — включить любимую мелодию, обнять малыша и медленно потанцевать вместе.'),
  ('cea6f894-72c1-48a7-91fc-bc8637fa2cca', 'Отказывается спать? 🥱', 'Малыш сопротивляется и не хочет ложиться на дневной сон? Попросите у ИИ Anacan точную информацию об окнах сна ближе к 2 годам и подходящий распорядок дня.'),
  ('b7bcd4fe-cc33-4ea9-a97e-59e15168cb31', 'В поисках полезных сладостей 🍎', 'Пора отказаться от магазинного печенья! Откройте в разделе рецептов для малышей полезные сладости с финиками и яблоками, которые можно приготовить дома за 10 минут, и порадуйте малыша.'),
  ('ed519633-a8d9-4eaa-a80a-911f5bc80cd1', 'Битва за чистку зубов 🪥', 'При виде щётки малыш сразу сжимает рот? Получите практические советы от ИИ Anacan и узнайте, как превратить эту важную гигиеническую процедуру в весёлую игру.'),
  ('fc53997b-db7d-4e51-803e-f6bd3797e9e3', 'Забавное произношение 🗣️', 'Некоторые слова малыш произносит так мило и неправильно! Не упустите эти драгоценные моменты. Загрузите видео со звуком в Альбом малыша, чтобы в будущем посмеяться над ними вместе.'),
  ('41e1758f-79bb-43e3-8304-d4d74fa983b0', 'Остались дома из-за странной погоды?', 'Инструмент «Погода и одежда» мгновенно подскажет вам скорость ветра и подходящий комплект одежды — смело отправляйтесь в парк.'),
  ('bcfad7da-e488-4ced-aa83-11c72d34ebec', 'Последние коренные зубы? 🦷', 'Малыш без причины всё грызёт и стал раздражительным? Возможно, скоро появятся самые дальние коренные зубы. Отметьте процесс в трекере прорезывания зубов и подготовьте охлаждённые прорезыватели.'),
  ('c57b31e1-ab4c-412f-95b1-bcfc05812865', 'Герой сказки 🪄', 'Сегодня вечером создайте в «Умных сказках» особенную историю, главным героем которой станет ваш ребёнок: отважный малыш, который любит чистить зубы.'),
  ('3dd0cee4-66f4-4904-9285-5b0b7b0dfa7b', 'Уделите время себе 🛋️', 'Вы выбились из сил, бегая за малышом. Ребёнок уснул — теперь запишите все переживания в «Дневник настроения» и налейте себе чашку чая с мелиссой.'),
  ('6721af60-2c7e-45f7-a60e-e27511cbb049', 'Голод или жажда? 💧', 'Иногда жажду принимают за отсутствие аппетита. Проверьте записи о выделениях в трекере подгузников, чтобы сразу убедиться, что малыш получает достаточно жидкости.'),
  ('be975b82-781b-4e9e-b454-14728754957f', 'Маленький певец 🎤', 'Малыш без конца поёт одну и ту же песню? Это развивает чувство ритма и способствует развитию речи.'),
  ('12f1dbe9-33ce-4aad-aead-7be2d360eb1e', 'Воображение не знает границ 🧸', 'Малыш кормит своего мишку или лечит вас? Загляните в «Рекомендуемые товары», чтобы выбрать набор врача или кухонный набор — такие игры прекрасно развивают эмпатию.'),
  ('813a036f-96ee-4802-8c36-c3d573f602c0', 'Страх разлуки возвращается? 🌌', 'Малыш начинает плакать, как только вы выходите из комнаты? Включите звук сердцебиения в разделе «Белый шум», чтобы подарить ему чувство безопасности и настроить на сон.'),
  ('8c8e48b0-6f8d-4855-bb6b-3ff2edd9fbb3', 'Брюки снова стали короткими! 📏', 'Рукава рубашек стали коротки? У ребёнка скачок физического развития. Внесите текущие параметры в «Трекер развития» и с гордостью посмотрите на график роста.'),
  ('24f24fa2-f109-4ee8-b9c0-2fe64e74bf4d', 'Белковый заряд для мамы ⚡', 'Бегать за активным малышом непросто. Приготовьте энергетический смузи с белком и фруктами по одному из полезных рецептов для женщин и зарядитесь энергией.'),
  ('5e6168f7-641f-4f35-ba96-328826769e77', 'Я сделаю это сам! 👕', 'Утреннее одевание превращается в настоящий кризис? Прямо сейчас узнайте у Anacan AI, как справляться с упрямством и предоставлять малышу право выбора.'),
  ('a40e092a-696e-4da1-98b1-5b56a4f49122', 'Как понять, что малыш наелся? ⏱️', 'Если малыш начал бросать или выплёвывать еду, он показывает, что наелся. Остановите таймер кормления, отметьте, что порция съедена, и проанализируйте аппетит.'),
  ('5266953d-d239-48ef-aac1-e6e5bcca5cbf', 'Любовь к книгам 📖', 'Малыш приносит любимую книгу сказок и садится к вам на колени? Он уже дольше удерживает внимание. Читайте вместе и называйте то, что изображено на картинках.'),
  ('b3334b05-05eb-4d1a-9a1b-b94086c6493b', 'Появились страхи? 👻', 'Малыш вдруг стал бояться пылесоса, хотя раньше не боялся? По мере развития воображения могут возникать необоснованные страхи. Обнимите его и скажите, что он в безопасности.'),
  ('c2a4b3f4-3db4-4b1d-a807-2effcd0ace08', 'Пора на свежий воздух 🌳', 'Ребёнок сильно капризничает и не может усидеть дома? Проверьте погоду и рекомендации по одежде и сразу отправляйтесь в парк. Природа поможет ему успокоиться быстрее всего.'),
  ('387df56f-151e-4857-83aa-f757db180cee', 'Вам тоже нужны друзья 👯‍♀️', 'Устали разговаривать только с ребёнком? Найдите в разделе «Места для мам» центры с игровыми группами, общайтесь с другими мамами и делитесь опытом.'),
  ('c13703f6-090d-418f-ba78-30e2aa25d678', 'Маленький помощник по уборке 🧹', 'Малыш уже хочет участвовать в домашних делах. В разделе «Блоги» прочитайте, как в игровой форме привить ребёнку примерно 2 лет чувство ответственности, и применяйте эти советы на практике.'),
  ('c6d0e6b3-90f7-4c66-9fd0-1f47e6d714c9', 'Гордитесь собой! 🌟', 'Каждый новый навык, который малыш осваивает, каждый его уверенный шаг — результат ваших усилий. Откройте Дневник настроения и сегодня напишите заметку о том, за что вы собой гордитесь!'),
  ('85abdfc2-20eb-4a57-a2bc-cb822114eada', 'Операция «Спрятать овощи» 🥦', 'Малыш отодвигает тарелку, как только видит брокколи? В рецептах для малышей узнайте, как умело спрятать эти витамины во вкусных блинчиках и пробудить его аппетит.'),
  ('8a4be0f9-7229-4996-baf5-618ca78de14d', 'Игра никак не заканчивается ⏱️', 'Вместо того чтобы идти спать, малыш убегает и прячется? Запустите таймер сна и включите шум океанских волн в разделе «Белый шум», превратив комнату в тихую пещеру для сна.'),
  ('b333371b-bfc0-429c-bd23-a3e9996c1c00', 'Слишком ранние пробуждения? 🌅', 'Малыш просыпается ещё до восхода солнца и полон энергии? Прямо сейчас спросите нашего эксперта Anacan AI, как сдвинуть его режим сна на более подходящее время.'),
  ('3c7a1c30-6e81-411e-a8e2-8748214141cf', 'Игры на логику 🧩', 'Малыш складывает игрушки в коробку, а затем высыпает их обратно? Так у него формируется понимание понятий «внутри» и «снаружи». Отметьте этот когнитивный навык в Трекере развития.'),
  ('b06ec056-54a0-4363-b389-839031267542', 'Обувное упрямство 👟', 'Выходя на улицу, малыш непременно хочет надеть зимой летнюю обувь? Иногда позволяйте ему выбирать самостоятельно — это укрепляет его волю.'),
  ('ff08789a-eee1-4756-9d40-5ac5e65f75a9', 'Есть вопрос? 🤖', 'Вас пугает то, что вы читаете о кризисе 2 лет? Не теряйтесь в интернете — напишите напрямую Anacan AI и узнайте, как легче пройти этот период.'),
  ('4ee32e6d-768e-4628-8838-47e0599752e7', 'Диванный альпинист! 🧗', 'Лазание по мебели стало его любимым занятием? Украсьте это смелое и забавное моторное шоу весёлыми стикерами в разделе «Фотосессия малыша» и добавьте снимки в альбом.'),
  ('74a21e11-19bb-4326-af8e-197831260dd5', 'Мамина энергия на исходе? 🔋', 'Днём вы засыпаете на ходу? В разделе полезных рецептов для женщин найдите белковый смузи с арахисовой пастой, который мгновенно придаст сил без кофеина.'),
  ('842a46f0-f832-4901-8e08-572103acff74', 'Сегодня всё давалось с трудом? 💆‍♀️', 'Весь день вы слышали крики и плач? Сделайте глубокий вдох, перестаньте себя осуждать — вы прекрасная мама!'),
  ('25dc715a-32c8-4d74-92d1-69586eb52b13', 'Все кастрюли из кухни оказались на полу?', 'Игры с безопасными предметами развивают логическое мышление малыша. Позвольте ему свободно исследовать свои сокровища.'),
  ('43609cdd-bc75-4be9-80ac-98506e0aba38', 'Нужна тишина 🤫', 'Первые полчаса после засыпания — самое чувствительное время. Проверьте уровень шума в помещении с помощью шумомера и избегайте внезапных громких звуков.'),
  ('8b59959d-35b3-4803-a8d5-668ef810ded0', 'Иллюзия совершенства 🛋️', 'Не вините себя, глядя на всегда весёлых мам в социальных сетях. И ваша усталость, и беспорядок в комнате — совершенно естественная реальность.'),
  ('17e385d1-c634-49cd-9d0d-e1c98c9b0fd8', 'От слов к предложениям 🗣️', 'Малыш уже начал составлять забавные предложения из 3 слов? Запишите этот удивительный речевой скачок и его милое произношение на видео со звуком, чтобы сохранить на память.'),
  ('3fe4d415-9d24-4577-93ed-654921e52b2c', 'Страницы оживают 📖', 'Во время чтения сказки малыш изображает голоса животных из книги? Обязательно прочитайте в разделе «Блоги» об интерактивных техниках чтения, которые помогают развивать воображение.'),
  ('bad958b0-7da3-4a62-ae7d-c35289ff6f57', 'Взрыв энергии 💥', 'Четыре стены дома уже не выдерживают этой беготни. Откройте карту «Места для мам», найдите безопасный парк с мягким покрытием и большой горкой и дайте малышу вдоволь порезвиться.'),
  ('6dabe6f9-b86b-4347-9d8c-8d189d8a1224', 'Я сам почищу! 🪥', 'Малыш забирает у вас зубную щётку и хочет всё делать сам, но на деле почти не чистит зубы? Найдите в разделе «Рекомендуемые товары» музыкальные и эргономичные модели, которые облегчат этот процесс.'),
  ('a9e849fb-b58a-4614-9ca7-0396de5c5865', 'Питьевой режим и запор 💧', 'Малыш много бегает, но мало пьёт? При смене подгузника следите за выделениями. Если есть риск запора, внесите это в приложение и добавьте в рацион продукты, богатые клетчаткой, с помощью инструмента контроля питания.'),
  ('d816b4dc-5206-4a90-9e61-8c02ef8f5c68', 'Испытание терпения за столом 🥣', 'Малыш играет с едой и пачкает всё вокруг? Включите таймер питания, проанализируйте динамику аппетита на графике и точно отслеживайте продолжительность приёма пищи.'),
  ('5f435409-af45-4f28-ad39-0362ac580462', 'Желание всё бросать на пол 🛑', 'Когда малыш злится или скучает, он размахивает тем, что держит в руках, и бросает это? Спросите Anacan AI, как мягко направлять такие эмоциональные реакции.'),
  ('cf7b282d-cfc2-4ce1-9f7c-e71f0a8529ba', 'Рубашки становятся малы! 📏', 'Во время одевания вы заметили, что рукава стали тесными? Ближе к 2 годам происходит скачок физического развития! Введите текущий рост в «Трекер развития» и с гордостью взгляните на кривую роста.'),
  ('d1b0bfba-8ace-4234-8eb6-40647f25ce47', 'Горячий чай и тишина 🍵', 'Таймер остановился, малыш уснул. Не спешите заниматься домашними делами! Заварите чай с мелиссой по одному из полезных рецептов для женщин и отметьте свои маленькие сегодняшние победы в «Дневнике настроения».'),
  ('1c764980-a64f-44cc-b47e-9bb7c39ae099', 'Сила железа 🥩', 'Чтобы активный малыш не столкнулся с анемией и оставался энергичным, проверьте сегодняшнее потребление железа в инструменте контроля питания и при его нехватке скорректируйте меню.'),
  ('2754ee28-07df-42f6-ba7d-9d86b1edf758', 'Магия монотонных звуков 🌬️', 'Внезапная тишина после выключения телевизора беспокоит малыша. Включите в комнате звук вентилятора или фена из раздела «Белый шум» и посмотрите, как он создаёт ощущение безопасности во время сна.'),
  ('301a1109-2563-49a6-a096-aa057de78fa7', 'Искусство в разноцветных ладошках 🎨', 'Играя с красками, малыш перепачкал всё лицо? Вместо того чтобы сердиться, сразу сфотографируйте этот забавный творческий момент и добавьте его в альбом как самое яркое воспоминание.'),
  ('3112ae5c-eae2-4dc5-ae42-0bb7f83e1fdb', 'Вечерние ритуалы 🧸', 'Каждый вечер малыш засыпает, обнимая одну и ту же игрушку? Сохраните этот трогательный момент спокойствия и доверия: без фотографии, просто опишите его в разделе заметок «Альбома малыша».'),
  ('363e202f-bc22-4752-9313-7e506d91cf84', 'Первые попытки подружиться 👶', 'В парке малыш интересуется игрушкой другого ребёнка и пытается привлечь его внимание звуками? Узнайте, как поддержать этот этап социализации, общаясь с другими мамами в разделе «Места для мам».'),
  ('a11c68a5-ec27-4659-9acb-bdcc422f80f8', 'Маленький доктор за работой 🩺', 'Малыш делает укол плюшевому мишке или слушает его животик? Игры воображения в самом разгаре! В разделе «Блоги» прочитайте о поразительном влиянии ролевых игр на развитие интеллекта.'),
  ('053139e2-7d9f-4a00-9462-2ddb17d7e133', 'Проснулся с совершенно сухим подгузником? 🩲', 'Утром при смене подгузника вы заметили, что он сухой? Это один из главных признаков физической готовности малыша к горшку! Отметьте это в трекере подгузников и внимательно следите за статистикой.'),
  ('d7110781-b463-4661-96ac-270a072de535', 'Без сахара, но сладко 🍪', 'Малыш просит перекусить после обеда? Магазинное печенье не понадобится. Откройте в рецептах для малышей полезные сладости с финиками и овсяными хлопьями, которые готовятся за 10 минут.'),
  ('f9924ca2-641b-4911-b60a-55193623479d', 'Полностью проанализируем режим ⏱️', 'Вечером малышу потребовалось 40 минут, чтобы уснуть? Посмотрите на график таймера сна. Возможно, пора сократить дневной сон на 20 минут и укладывать малыша вечером пораньше.'),
  ('94201b9a-86d5-4505-89c9-5202248a32f0', 'Утренние капризы 👗', '«Не хочу эти туфли!» — упрямство малыша усложняет ваше утро? Узнайте у Anacan AI о самых эффективных психологических приёмах, которые помогут предоставить ему свободу выбора, предлагая альтернативы.'),
  ('c7ffac8f-2df5-4b9d-8171-edd5730bbcb9', 'Запас белка для мамы ⚡', 'Бегать за активным малышом непросто. Не доводите себя до изнеможения! В разделе полезных рецептов найдите энергетический смузи, богатый белком и фруктами, чтобы восстановить силы.'),
  ('fdd42343-56c5-47a1-8eaa-9e8b57c16e15', 'Природное успокоительное 🍃', 'День выдался слишком шумным и суматошным? Таймер остановлен. Приглушите свет, включите в разделе «Белый шум» журчание ручья и подарите расслабление и малышу, и себе.'),
  ('06ba8468-2412-484c-9b4b-12b5ce2a132b', 'Борьба за самостоятельность! 👕', 'Малыш хочет одеваться сам и отказывается от вашей помощи? Прямо сейчас спросите у нашего экспертного помощника Anacan AI, как направить это упрямство в русло здорового развития.'),
  ('10c5438d-d27e-4125-a092-12fa2afc9118', 'Проверка запасов железа 🥩', 'Чтобы у активного малыша не развилась анемия, проверьте в инструменте «Контроль питания», сколько железа он получил сегодня (мясо, бобовые), и скорректируйте меню.'),
  ('f5441f5e-36e8-4685-812e-3b947ba2fe54', 'Время замедлиться перед сном 🎶', 'Малыш не устаёт бегать и не хочет ложиться спать? Запустите таймер сна, включите в разделе «Белый шум» шум океанских волн и создайте в комнате спокойную атмосферу для сна.'),
  ('194c05a1-f79c-496c-b1f4-f1316b804846', 'Пусть малыш расскажет сказку 📖', 'Малыш рассматривает картинки в книге и что-то рассказывает на своём языке? Снимите этот чудесный момент проявления фантазии на видео со звуком, добавьте в «Альбом малыша» и сохраните на память.'),
  ('81278832-aa98-446b-b9de-87731d74c2b6', 'Безопасное место для пробежки 🏃‍♀️', 'Малыш не может выплеснуть энергию дома и всё разбрасывает? Откройте карту «Места для мам», найдите парк с безопасной зоной для бега и отправляйтесь на свежий воздух.'),
  ('fe937f54-e4d9-4674-821c-ae81d7c0c2cc', 'Скандал из-за не того стакана? 🥤', 'Малыш устроил настоящий скандал, потому что вы налили воду не в синий, а в красный стакан? Узнайте у Anacan AI, как сохранять спокойствие и справляться с такими капризами, даже если они кажутся абсурдными.'),
  ('4582098e-0228-4efe-b173-11bb966a75f4', 'Ночные пробуждения ⏱️', 'Запустите таймер сна! По статистическому графику таймера вы сможете точно определить, связаны ли пробуждения с ночными страхами или регрессом сна, и скорректировать режим.'),
  ('91af8067-4bf1-4cab-af7f-58a96c7e04b3', 'Вам тоже нужен перерыв ☕', 'Выйдите из дома и немного передохните! В разделе «Места для мам» найдите ближайшее кафе с детским уголком и спокойно насладитесь горячим кофе.'),
  ('e6513be5-cd7d-41ca-afb7-bc1d9cfbc0d8', 'У малыша запор? 🚽', 'При утренней смене подгузника обратите внимание на стул малыша. Если у него запор, отметьте это в приложении и сразу добавьте богатые клетчаткой продукты с помощью инструмента «Контроль питания», чтобы восстановить баланс.'),
  ('442e022d-5a7b-4ad3-bb7f-6aecb9da6631', 'Истерика из-за экрана 📱', 'Малыш падает на пол и устраивает истерику, когда вы забираете телефон? Узнайте у Anacan AI, как ограничить экранное время без лишнего стресса и установить здоровые границы.'),
  ('70c5aa02-8fdb-44ad-8a7f-cb5e6e2076a9', 'Сегодняшний герой — вы 🌟', 'Каждый новый навык, которому малыш учится день за днём, — результат ваших усилий. Откройте «Дневник настроения» и напишите сегодня заметку, за которую вам захочется поаплодировать себе стоя!'),
  ('d0802019-8ab1-4450-b744-1d4846aeaf76', 'Споры из-за чистки зубов 🪥', 'Малыш убегает, как только видит зубную щётку? Посмотрите в разделе «Рекомендуемые товары» музыкальные или вращающиеся детские щётки и превратите эту важную гигиеническую процедуру в весёлую игру.'),
  ('134f77a6-22c5-4894-83a4-bbdf2a3551b0', 'Природное успокоительное 🍃', 'День выдался слишком шумным и суматошным? Таймер остановлен. Приглушите свет, включите в разделе «Белый шум» журчание ручья и подарите расслабление и малышу, и себе.'),
  ('c38c019f-d84f-4e70-a98d-688ae4d3f657', 'Скачок в развитии логики 🧩', 'Малыш начинает понимать причинно-следственные связи. В разделе «Блоги» прочитайте о лучших домашних играх для ускорения познавательного развития детей примерно 2 лет и попробуйте поиграть в них.'),
  ('e1d2d8e1-5d2b-4afe-b927-cf13cedf3cda', 'Кальциевая защита 🦴', 'Кальций необходим для зубов и костей. С помощью инструмента контроля питания проверьте, получил ли малыш сегодня норму йогурта и сыра.'),
  ('20e07ee8-1ee8-4d24-9dc9-8aeafced1a45', 'Монстр панкейков 🥞', 'Отказывается от завтрака? В разделе рецептов для малышей найдите рецепт банановых панкейков без сахара. Малыш сможет брать их руками и есть самостоятельно, а заодно у него разыграется аппетит.'),
  ('98f28b6b-3cea-495d-a58b-704216aa3a0d', 'Испытание терпения за столом 🥣', 'Играет с едой и пачкает всё вокруг? Включите таймер питания, проанализируйте динамику аппетита на графике и точно отследите, сколько времени занимает приём пищи.'),
  ('a8ac0c29-0fa0-4dec-a0ed-2411236fabc2', 'Терапия песком и грязью 🏖️', 'Не бойтесь испачкаться! Откройте для себя лучшие товары для игр с кинетическим песком и других сенсорных занятий в разделе «Рекомендуемые товары».'),
  ('5c1b9d9c-ddd2-4dad-b93e-0902ebeb2417', 'Искусство выплеснуть энергию 🧗', 'Домашних стен малышу уже мало. Откройте карту мест для мам и найдите место с безопасной игровой зоной и мягким покрытием, где он сможет вдоволь бегать и прыгать.'),
  ('7c5f1c11-9db4-4f7a-913f-8ca7bf583cb6', 'Избирательный аппетит 🥦', 'Малыш просит только макароны или хлеб? Проанализируйте меню с помощью инструмента контроля питания и восполните недостающие витамины интересными блюдами из раздела рецептов для малышей.'),
  ('ea466226-d28d-4765-94f7-982ef3a85a8e', 'Приглушите свет 🌙', 'За 1 час до сна выключите дома весь яркий свет и экраны. Мелатонин вырабатывается только в спокойной обстановке при приглушённом освещении.'),
  ('247c6eba-b9c7-406d-95d9-27a9c74871bf', 'Умные игрушки 🧩', 'Для развития интеллекта в 2 года нужны не просто игрушки со звуками, а обучающие игрушки. Откройте для себя деревянные пазлы для развития логики в разделе «Рекомендуемые товары».'),
  ('50a05ffc-5382-423e-b256-bdeac07c78eb', 'Готовим торт без сахара 🎂', 'Для завтрашнего особенного дня нужен полезный торт! В разделе рецептов для малышей найдите рецепты фруктовых тортов без рафинированного сахара, полностью подходящих детям.'),
  ('9c2176f9-4583-459e-b4a3-631c624068de', 'Источник маминой энергии 🥗', 'Не забывайте заряжать собственные батарейки! Приготовьте по одному из полезных рецептов питательный протеиновый смузи с арахисовой пастой, который быстро придаст сил.'),
  ('19814a91-cb64-4bf7-bdcb-7655e0d384a4', 'Официально 2 года! 🎈', '2 года непрерывных усилий, любви и бессонных ночей. Запишите в дневнике настроения, как вы гордитесь всеми этими 730 днями. Вы действительно потрясающая мама!'),
  ('6a49b5e2-afea-42a7-8643-310e7b5b7642', 'Вы справились 🥂', 'Два года самоотдачи! Если малыш уснул, отложите домашние дела. Откройте дневник настроения, напишите слова благодарности самой себе и просто отдохните.'),
  ('e00156cd-d1b9-4727-b3d4-e86b004b8681', 'Кризис 2 лет? 🌪️', 'Малыш всё чаще говорит «нет» и кричит? Чтобы легче пройти этот известный этап, прямо сейчас узнайте у Anacan AI о тактиках управления эмоциональными вспышками.'),
  ('17c8a3a6-67b0-49ab-a185-9e25f788bb11', 'Не хочет сидеть за столом 🥣', 'Малышу быстро надоедает есть, и он убегает? Включите таймер питания, зафиксируйте продолжительность приёма пищи и полностью откажитесь от кормления через силу.'),
  ('32abe85c-b2ef-4ebb-aa71-2ad4fbb4e416', 'Потребность в тишине 🤫', 'После вчерашнего шума поддерживайте тишину в комнате с помощью шумомера. Прерывистый ночной сон портит настроение и малышу, и вам.'),
  ('8796a078-f4e3-4ea5-9258-919333a4b718', 'Хаос после дня рождения 🌪️', 'После вчерашней вечеринки дома всё вверх дном? Не спешите убираться. Посвятите этот день отдыху вместе с вашим новоиспечённым 2-летним малышом.'),
  ('07c79611-988f-4228-b928-f34af1a7425a', 'Творчество из природных материалов 🍂', 'Выходите из дома! Листья и камешки в парке — лучшие материалы для сенсорных игр. Найдите среди Мест для мам локацию с просторной зелёной зоной.'),
  ('14d525a3-b7d6-43c1-9919-132c8691cf60', 'Больше воды — легче пищеварение 💧', 'За играми и беготнёй малыш забывает пить воду? Внесите утреннюю запись в трекер подгузников и сразу оцените баланс жидкости и клетчатки, чтобы снизить риск запора.'),
  ('8a2ef907-aa42-42a0-b57d-125e83745fe9', 'Вечерняя сказка как привычка 📖', 'Малыш пересказывает прочитанную вами сказку своими словами? Снимите на видео со звуком этот удивительный скачок в развитии речи, добавьте в Альбом малыша и сохраните на память.'),
  ('031b0761-047d-4d63-84ce-fd41ce83245b', 'Период «Это моё!» 🧸', 'Малыш не делится игрушкой в парке и кричит? Узнайте у Anacan AI, как правильно реагировать на эгоцентризм в 2 года, не допуская проявлений агрессии.'),
  ('16c2ca9a-7971-49b0-9210-b9dd3baea775', 'Противовоспалительная сила 🍵', 'Из-за частого ношения малыша у вас болят спина и руки? Восстановите силы, заварив чай с имбирём и лимоном по одному из полезных рецептов для женщин.'),
  ('4645899a-65b7-4ec6-9619-57e71d7569de', 'Проанализируем режим ⏱️', 'Период бодрствования перед ночным сном слишком затянулся? Запустите таймер сна и проследите за графиком. Возможно, пора сократить дневной сон на 20 минут!'),
  ('5bc99c8b-11ed-40cb-90ff-db30ccb7cbdb', 'Малыш продолжает подражать вам 🦜', 'Когда вы разговариваете по телефону, малыш тоже берёт пульт и прикладывает его к уху? Он копирует вас на 100%! Старайтесь подавать ему хороший пример.'),
  ('bfbd5b7b-bf9b-48f6-a1a2-f194c1a573f8', 'Сила слова «нет» 🛑', 'На любое предложение малыш качает головой и говорит «нет»! Это не упрямство, а способ выразить своё мнение. Предлагайте ему выбор, чтобы помочь успокоиться.'),
  ('e590043b-d98d-4bab-915d-caf59d5351e3', 'Папины забавные выходки 🤡', 'Лучший способ рассмешить малыша — это папины смешные звуки. Насладитесь вместе с ребёнком весёлыми моментами этого вечера.'),
  ('72f63b03-217f-4966-9286-177869cd7d59', 'Без сахара, но вкусно 🥞', 'Малыш просит сладкого? Не спешите в магазин. Найдите в рецептах для малышей бананово-яблочные панкейки, которые готовятся всего за 10 минут, и порадуйте его вкусным перекусом.'),
  ('c2a3a287-3762-4751-aa0e-2e7d2c1d038c', 'Битва за зубную щётку 🪥', 'Чистка зубов каждый раз превращается в настоящее сражение? Посмотрите в Рекомендуемых товарах музыкальные щётки или щётки с любимыми героями мультфильмов и превратите чистку в игру.'),
  ('d3ffa760-4dfc-4872-9709-1f13cf644f4a', 'Естественное успокоение 🍃', 'День выдался шумным и активным? Таймер остановился. Приглушите свет, включите звук журчащего ручья в Белом шуме и позвольте отдохнуть не только малышу, но и себе.'),
  ('3b32f5ba-4db0-47e2-ab4a-893183710c64', 'Железная защита 🥩', 'У малыша стало меньше энергии или он просто устал? Проверьте с помощью инструмента контроля питания, достаточно ли сегодня было железа (мясо, бобовые), и сразу восполните нехватку.'),
  ('a743db36-b967-433a-8695-0780f7195e63', 'Игра в доктора началась 🩺', 'Малыш делает укол своему мишке? Воображение сейчас развивается особенно активно. Устройте фотосессию малыша, запечатлейте этот милый момент и сохраните как одно из самых тёплых воспоминаний.'),
  ('d6af2d07-9e24-449e-843c-4a4fbcab142b', 'Вам тоже нужна передышка ☕', 'Ненадолго передайте заботу о ребёнке близким и переведите дух! Найдите среди Мест для мам кафе с детским уголком и спокойно насладитесь горячим кофе.'),
  ('10e42611-20e5-4efa-b449-859dcdf79439', 'План побега из кровати 🏃‍♂️', 'Убегает и прячется, когда приходит время спать? Запустите таймер сна, включите шум леса в разделе «Белый шум» и превратите комнату в тихую уютную пещеру.'),
  ('a00ab8a1-2a6c-4ace-a218-64e35136c179', 'От параллельной игры к совместной 👶', 'Малыш всё чаще проявляет интерес к играм рядом с другими детьми. Откройте для себя секреты социализации двухлетних детей и психологию игр на детской площадке в разделе «Блоги».'),
  ('ab2766ea-1937-4401-b3fe-78b7aa14f747', 'Упрямство при одевании 👗', 'Плачет и кричит: «Не хочу эти брюки!»? Узнайте у Anacan AI, как сократить утренние кризисы при одевании и предоставить малышу право самостоятельного выбора.'),
  ('3743e0d0-daf8-4b16-9966-a5c865827254', 'Маленький повар за работой 👨‍🍳', 'Помогает вам на кухне и месит тесто? Запишите этот забавный момент, когда малыш весь в муке, на видео со звуком и сохраните воспоминание на всю жизнь.'),
  ('8b9210f4-74fc-4c2d-b35a-90728df0c189', 'Крики в магазине 🛒', 'Малыш бросился на пол в общественном месте, потому что не получил желаемого? Не обращайте внимания на взгляды окружающих и поделитесь своими переживаниями с Anacan AI, чтобы научиться спокойно справляться с кризисом двухлетнего возраста.'),
  ('d5d9b1e2-d062-4d67-8535-5d3b9126d7d2', 'Не спали ночью? ☕', 'Ночные пробуждения лишили вас сил? Приготовьте белковый смузи с арахисовой пастой из раздела полезных рецептов для женщин — он мгновенно зарядит энергией без кофеина и поможет взбодриться.'),
  ('02f4d85d-ea15-4227-a58f-b7dba39b78d0', 'Внезапные пробуждения 🌌', 'Малыш просыпается среди ночи с плачем и не может успокоиться? Напишите эксперту Anacan AI, чтобы понять разницу между ночным ужасом и кошмаром и узнать, как правильно действовать.'),
  ('3a940a2c-0062-4cd0-9553-c25d5aadd4ea', 'Больше никаких сражений с зубной щёткой 🪥', 'При виде зубной щётки малыш сразу сжимает рот? Найдите в разделе «Рекомендуемые товары» музыкальные и эргономичные модели, которые облегчат процесс, и превратите ежедневную процедуру в игру.'),
  ('78846b79-c47d-4a00-947e-59f644b0393d', 'Железная защита 🥩', 'Чтобы у активного малыша не развилась анемия и он оставался энергичным, найдите в разделе рецептов для малышей вкусные овощные тефтели с мясом, которые легко жевать и которые помогут улучшить аппетит.'),
  ('14cb8a25-67e3-4a93-92e7-813bc9ea34c1', 'Любитель рвать страницы 📖', 'Вместо чтения малыш рвёт страницы книги? Прямо сейчас спросите у Anacan AI, как решить эту проблему, не отбив интереса к чтению.'),
  ('ce2cdb1e-e1d2-4e44-a336-1708ff489505', 'Энергия за 5 минут ⚡', 'Днём засыпаете на ходу? Приготовьте ягодную овсянку из раздела полезных рецептов для женщин — этот кладезь антиоксидантов мгновенно придаст сил и поможет организму восстановиться.'),
  ('d83ebff1-21e6-4964-94da-2347551c7e01', 'От слов к предложениям 🗣️', 'Малыш уже начал составлять забавные предложения из 3-4 слов? Прочитайте в разделе «Блоги» о лучших домашних играх и упражнениях со слогами, которые поддержат этот удивительный скачок в развитии речи.'),
  ('25c00809-7707-4080-969f-0093aea099c2', 'Время массажа 💆‍♂️', 'Когда ребёнок уснёт, сделайте друг другу массаж плеч вместе с партнёром, чтобы снять накопившийся за день стресс. Вы — одна команда!'),
  ('3708efde-5f63-47e0-b30e-19b8bf533ad8', 'Воображаемая поездка 🚗', 'Берёт пустую коробку или игрушку, крутит её как руль и издаёт звуки? Символическая игра (pretend play) активно развивается!'),
  ('c1efd894-6c8f-4d33-9cdd-4d863998e9be', 'Мамы делятся переживаниями 💬', 'Мысль «Почему мой ребёнок так делает?» не даёт вам покоя? Присоединяйтесь к сообществу Anacan и прочитайте похожие истории других мам.'),
  ('71d54817-9c7d-4b6a-a083-cfc9af5ca532', 'Кладезь кальция 🦴', 'Кальций необходим для здоровья зубов и костей. С помощью инструмента контроля питания проверьте, получил ли малыш сегодня норму йогурта и сыра, и восполните недостающее.'),
  ('86c19953-fc54-4688-b5d9-b4feaed16fa5', 'Анализ режима сна ⏱️', 'Малыш долго ворочается перед сном? Посмотрите график таймера сна. Возможно, самое время сократить дневной сон на 20 минут и укладывать малыша вечером пораньше.'),
  ('69468bd3-2ce5-4731-b30e-3685775a4a1a', 'Волшебный фон тишины 🌊', 'День выдался беспокойным и шумным? Включите шум океанских волн в разделе «Белый шум», чтобы успокоить нервную систему малыша и свою собственную.'),
  ('86704e7d-f300-4ac8-a2e1-2a5068e8a7e2', 'Игра с овощами 🥦', 'Малыш отказывается от шпината? Узнайте в рецептах для малышей, как умело спрятать эти витамины во вкусных блинчиках и пробудить аппетит.'),
  ('c422d14a-eccf-4f6a-bcbb-1ec2a5bdfc3a', 'Скачок роста! 📏', 'Штанишки снова стали коротки? К 25-му месяцу физическое развитие ускоряется. Внесите текущие показатели в Трекер развития и с гордостью взгляните на график роста.'),
  ('2f36e03e-8050-4c96-a7d2-3231c5e8bf3f', 'Исследуем свежий воздух 🌳', 'Малышу уже тесно в четырёх стенах. Найдите просторный и безопасный парк в разделе «Места для мам» и позвольте ему вдоволь побегать и выплеснуть всю энергию.'),
  ('484ef066-dacc-4b23-98a9-ef3409b6f055', 'Испытание терпения за столом ⏱️', 'Малыш играет с едой, но не ест? Включите таймер кормления, следите за продолжительностью процесса и анализируйте изменения аппетита по графику в приложении.'),
  ('d99bde2e-2ab1-43d0-b2d0-95122a7f44ce', 'Почему он вдруг дерётся? 🛑', 'Малыш замахивается, когда злится? Узнайте у ИИ-эксперта Anacan, как мягко скорректировать характерное для этого возраста агрессивное поведение, превратив эмоции в игру.'),
  ('1a858fa5-276f-440e-972b-2b83e93db467', 'Перерыв на кофе ☕', 'Домашние дела, забота о малыше... Пора сделать перерыв! Найдите кафе с детским уголком в разделе «Места для мам» и спокойно насладитесь горячим кофе.'),
  ('40782485-009f-459f-b399-6e2d09a90f95', 'Сегодняшний герой — вы 🌟', 'Каждый новый навык, который малыш осваивает каждый день, — результат ваших усилий.'),
  ('9fcf0a97-e2c0-4a40-994a-17bcfcd07b1b', 'Баланс витамина C 🍊', 'Иммунитет должен быть крепким. С помощью инструмента контроля питания проверьте, получил ли малыш сегодня достаточно витамина C, и скорректируйте меню.'),
  ('0ef06d2c-90d7-4377-9290-8bde591b5f45', 'Бесконечный период «Почему?» 🤔', '«Что это?», «Почему так?»... Малыш уже активно познаёт мир! Отвечайте терпеливо, ведь в такие моменты нейроны в его мозге устраивают настоящий праздник.'),
  ('23204200-aac5-4b32-bb1b-c194a2fa62c8', 'Разорвите цепь перфекционизма 🛑', 'Малыш сегодня не спал днём, а дома полный беспорядок? Ничего страшного! Сделайте глубокий вдох: невозможно контролировать всё одновременно. Просто отпустите ситуацию.'),
  ('c615cbe9-985e-4212-bc61-219d1808967f', 'Терпение на исходе?', 'Закройте дверь комнаты и оставьте малыша наедине с папой. Пусть сегодня вечером он станет главным по домашним играм.'),
  ('5d64edd3-2a7c-4881-81d2-2b0ca3685e08', 'Устали сидеть в четырёх стенах?', 'Найдите кафе с детским игровым уголком в разделе «Места для мам». Пусть малыш играет, а вы наслаждаетесь кофе.'),
  ('752be34d-ef64-4eb5-9d4c-e6d82cd2a840', 'Я оденусь сам 👕', 'Даже если малыш пытается надеть штанишки на голову, не мешайте ему учиться одеваться. Стремление к самостоятельности сейчас на пике! Отметьте эту маленькую победу в Трекере развития.'),
  ('84770b0a-8d36-4d8c-9fce-09146969d787', 'Музыкальное умиротворение 🎶', 'Самый простой способ справиться с вечерними капризами — включить любимую мелодию, обнять малыша и медленно потанцевать вместе с ним.'),
  ('725e419e-e208-48ec-ad13-bc8e5886eebb', '«Я сам буду есть!» 🥦', 'Малыш хочет забрать у вас ложку? Позвольте ему. Он испачкается, но это ощущение самостоятельности очень важно для него.'),
  ('b6c449a4-eac7-47b9-9e9b-4c3b2deebe5b', 'Сегодняшний герой — вы 🌟', 'Каждый новый навык, который малыш осваивает, и каждый его самостоятельный шаг — результат ваших усилий.'),
  ('2a9eaf13-aaf9-41fd-baa3-5fdcb48e56ca', 'Развивающие игрушки 🧩', 'В 2 года малышу нужны не просто звучащие, а развивающие игрушки. Откройте для себя деревянные пазлы и сортеры для развития логики в разделе «Рекомендуемые товары».'),
  ('5592a39d-90a2-449d-9f20-3a71ba9dddad', 'У малыша запор? 🚽', 'За играми и беготнёй малыш забывает пить воду? Следите за стулом во время смены подгузника. Если есть риск запора, отметьте это в приложении и сразу добавьте в рацион продукты с клетчаткой с помощью инструмента контроля питания.'),
  ('a589907e-1ec5-4668-9a51-f72995d314f0', 'Проанализируем режим ⏱️', 'Вечером укладывание заняло 40 минут? Посмотрите график таймера сна. Возможно, пора сократить дневной сон на 20 минут и начать вечернее укладывание раньше.'),
  ('1966178b-773a-4205-ab76-e8693f0abf72', 'Без сахара, но сладко 🍪', 'Малыш просит перекус после обеда? Магазинное печенье не понадобится. Приготовьте по детским рецептам полезные сладости с финиками и овсянкой всего за 10 минут.'),
  ('6f0ae293-593e-4249-828e-c2ec4c4fce2b', 'Забавные гримасы 🤪', 'Малыш корчит рожицы перед зеркалом? Не упустите этот весёлый момент! Сразу украсьте снимок забавными рамками из раздела «Фотосессия малыша» и добавьте его в альбом.'),
  ('853c16b5-ec48-42df-a039-bc81b5a0ae1e', 'Вам тоже нужен перерыв ☕', 'Выйдите из дома и немного передохните! Найдите в разделе «Места для мам» ближайшее кафе с детским уголком, насладитесь горячим кофе и познакомьтесь с другими мамами.'),
  ('7f7e8cbd-f54d-475a-9880-5e509bceab0e', 'Тарелка не того цвета! 🎨', 'У малыша случилась истерика, потому что вы подали еду на красной, а не на зелёной тарелке? Прочитайте советы в разделе «Блоги», чтобы научиться справляться с нелогичным упрямством, характерным для этого возраста.'),
  ('967e4cff-99ce-432e-991e-40e75469ba59', 'Боль в спине у мамы 🧘‍♀️', 'Ноет спина из-за того, что вы поднимаете малыша весом 13+ kq? Заварите расслабляющий мышцы имбирный чай по одному из полезных рецептов для женщин и позаботьтесь о себе.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ru = v.t, body_ru = v.b
FROM (VALUES
  ('a1d9ccbc-d633-4cf7-8231-4a3a870b0696'::uuid, 'Маленький подражатель 📸', 'Малыш разговаривает по телефону, как вы, или повторяет ваши движения? Украсьте этот забавный момент весёлыми стикерами из раздела «Фотосессия малыша» и добавьте снимок в альбом.'),
  ('43a58d7e-e492-4b05-8142-e4389027f185', 'Любит всё бросать на пол 🛑', 'Когда малыш злится или скучает, он швыряет то, что держит в руках? В статьях раздела «Блоги» вы узнаете, как мягко перенаправлять такие эмоциональные реакции.'),
  ('cec4b4c4-52ab-4e49-adea-d05ca6bfff30', 'Искусство раскрашенных ладошек 🎨', 'Играя с красками, малыш перепачкал всё лицо? Вместо того чтобы сердиться, сразу сфотографируйте этот забавный творческий момент и добавьте его в Альбом малыша как самое яркое воспоминание.'),
  ('deb2e459-e0cf-41a4-8379-c85e410b286a', 'Натуральное успокоительное 🍃', 'Таймер остановился. Малыш уснул. Пора позаботиться о себе! Заварите чай с мелиссой по одному из полезных рецептов для женщин, прилягте на диван и насладитесь тишиной после этого утомительного дня.'),
  ('6653e097-de4e-4ae0-8162-9b9f5ea59388', '«Я сам помою!» 🧽', 'Малыш забирает у вас щётку или мочалку в ванной? Поищите в разделе «Рекомендуемые товары» безопасные детские принадлежности для купания, которые поддержат его стремление к самостоятельности.'),
  ('74cf7a22-e38a-436b-abf9-30e1ae8f9815', 'Энергия за 5 минут ⚡', 'Вы выбились из сил от постоянной беготни? Приготовьте по одному из полезных рецептов для женщин белковый смузи с арахисовой пастой, который быстро придаст сил, и восстановите энергию.'),
  ('04f27cd2-d5c6-4a88-a758-f59dfedfac03', 'Сигналы пищеварения 💩', 'Вносите данные при смене подгузника. Если есть риск запора, обязательно ознакомьтесь в приложении с рекомендациями по продуктам, богатым натуральной клетчаткой, и рецептами фруктовой воды.'),
  ('2312b09a-1559-4ed0-aada-ff2063057e72', 'Страх разлуки? 🌌', 'Малыш плачет, как только вы выходите из комнаты? Включите звук материнской утробы в разделе «Белый шум», чтобы вернуть ему знакомое тёплое чувство безопасности и настроить на сон.'),
  ('a2bb6939-4631-4be2-a871-cb519c3fdacb', 'Без сахара, но сладко 🍪', 'Пора отказаться от магазинного печенья! Откройте для себя полезные сладости с финиками и овсянкой, которые можно приготовить дома всего за 10 минут, в разделе рецептов для малышей.'),
  ('5e9c412f-bcfb-4d5e-a447-66eebbf03e51', 'Искусство говорить «Нет!» 🛑', 'На всё отвечает «нет»? Это не попытка вам перечить, а способ познать свою индивидуальность. Предлагайте малышу выбор из двух вариантов вместо закрытых вопросов — так вам будет легче справиться с его упрямством.'),
  ('64707418-d2a0-43f8-b7ef-86936fa426fe', 'Память снова подвела?', 'Не держите в голове все мелочи, которые закончились дома. Сразу добавляйте их в список покупок — пусть ваш партнёр обо всём позаботится.'),
  ('d3a41958-709d-460d-ae40-910c3a69b580', 'Просыпается среди ночи с криком и не успокаивается?', 'Кризис двух лет влияет и на сон. Дайте функции «Анализ плача» прослушать звук, чтобы точнее определить причину.'),
  ('07a0b7ef-0c8f-405e-aede-5d8c497ab1df', 'Спокойствие пещеры 🌌', 'Малыш не устаёт бегать и не хочет ложиться? Запустите таймер сна и включите шум леса в разделе «Белый шум», чтобы превратить комнату в тихую и уютную пещеру для сна.'),
  ('9849f311-0e6e-4965-b1a2-164cf002508c', 'Время прыгать 🦘', 'Малыш прыгает по диванам дома? Найдите в разделе «Места для мам» развлекательный центр с батутом и мягким покрытием, где он сможет безопасно выплеснуть энергию.'),
  ('e6b6723c-fd0e-4884-94df-d412f5e903e7', 'Слишком ранние пробуждения! 🌅', 'Малыш встаёт ещё до восхода солнца? Прямо сейчас получите практические советы от нашего ИИ-помощника Anacan, чтобы узнать, как наладить его режим сна.'),
  ('498eede0-22c9-4d0a-b512-067c46777cb9', 'Новые забавные слова 🗣️', 'Какое смешное слово малыш придумал сегодня? Сохраните этот чудесный этап развития речи в «Альбоме малыша» в виде видео со звуком — спустя годы вы будете пересматривать его и смеяться от души.'),
  ('710fba45-03e1-4e84-9d81-f9c99d7d2c40', 'Засыпаете на ходу среди дня?', 'Приготовьте смузи с арахисовой пастой из раздела полезных рецептов — он мгновенно придаст сил без кофеина.'),
  ('78d6a4b5-d4db-4754-8341-cf2bcc10342a', 'Бесконечное шоу в кровати 🛌', 'Прыгает на кровати вместо того, чтобы спать? Проследите за графиком таймера сна и сразу определите, не успел ли малыш выплеснуть энергию или, наоборот, слишком устал.'),
  ('4622294e-c362-48ed-b4bf-63c35923b3ce', 'Горячий чай и тишина 🍵', 'Таймер остановился, малыш уснул. Не спешите заниматься домашними делами! Заварите чай с мелиссой и просто насладитесь тишиной.'),
  ('53c02e98-c468-40ac-9f02-6cb3c5e5158c', 'Кальциевый щит 🦴', 'Кальций необходим для зубов и костей. С помощью инструмента контроля питания проверьте, получил ли малыш сегодня норму йогурта и сыра, и восполните недостающее.'),
  ('f10247de-df8b-47ef-a539-e87f8db55ae2', 'Маленький доктор за работой 🩺', 'Делает мишке укол или слушает его животик? Воображение сейчас на пике! Сразу запечатлейте этот милый момент с помощью «Фотосессии малыша» и превратите его в незабываемое воспоминание.'),
  ('1a31af42-99cc-4ebb-8d30-72e007760f62', 'Потребность в тишине 🤫', 'Поддерживайте тишину в комнате с помощью шумомера. Прерванный ночью сон вредит и развитию малыша, и вашему утреннему настроению.'),
  ('bcb1a85f-15a5-4fe9-bbeb-6c1ae564f15a', 'Последние моляры? 🦷', 'Без причины всё грызёт и постоянно тянет руки в рот? Возможно, скоро прорежутся самые дальние моляры (вторые моляры). Обязательно проверьте трекер прорезывания зубов.'),
  ('e490e4c7-7ef7-4eec-a03a-11da14534526', 'Домашние дела могут подождать 🛑', 'Не успели помыть пол? Пусть подождёт. Беспорядок можно убрать, а вот восстановление истощённой мамы требует времени. Прилягте на диван и просто насладитесь тишиной.'),
  ('753bfaff-7926-4516-b6b5-e78d2b60a270', 'Вражда с фруктами 🍎', 'Сегодня бросает на пол фрукт, который любил ещё вчера? Избирательность в еде — классическая проблема этого возраста. Посмотрите в разделе полезных рецептов варианты весёлой и необычной подачи.'),
  ('8b287134-38e5-4f28-8d41-3ba7f9bcd5b7', 'Воображаемые игры становятся сложнее 🧸', 'Кормит игрушки и укладывает их спать? Воображение сейчас развивается особенно активно! Отмечайте эти проявления эмпатии в трекере развития.'),
  ('b884ea59-629f-4f5c-a2db-ce8f7aee5def', 'Вместе вы — сила🥂', 'Когда ребёнок уснёт, заварите чай вместе с партнёром, чтобы снять накопившееся за день напряжение, и похвалите друг друга, сказав: «Мы отличная команда».'),
  ('26ecdf90-afa5-4aeb-a939-0e9c19c4397d', 'Проанализируем режим ⏱️', 'Вечером укладывание заняло 40 минут? Посмотрите график таймера сна. Возможно, самое время сократить дневной сон на 20 минут и начать вечерний ритуал пораньше.'),
  ('4efacff1-8d44-47f9-9c4b-52dbb8de0f37', 'Истерика в общественном месте 🛒', 'В магазине малыш упал на пол из-за того, что ему не купили желаемое? Не обращайте внимания на взгляды окружающих и поделитесь переживаниями с Anacan AI, чтобы научиться спокойно справляться с такими кризисами.'),
  ('6e38a4cd-2c0a-4585-9a87-c6dd4f83a0a6', 'Не бойтесь испачкаться!', 'Откройте для себя лучшие товары для игр с кинетическим песком и других сенсорных занятий в разделе «Рекомендуемые товары» и сразу закажите их на дом.'),
  ('3c1dc66a-c7fe-45c2-99c5-908555ae99a9', 'Энергетическая бомба для мамы ⚡', 'Глаза уже закрываются от постоянной беготни? Спешите не за сладостями, а за белком! Зарядитесь энергией с помощью смузи с арахисовой пастой, который можно приготовить за 5 минут по рецепту из раздела полезных рецептов для женщин.'),
  ('83cfece3-b100-41d8-bb8e-0c02263c9e3e', 'Боится теней? 🌌', 'Когда вы затемняете комнату, его пугают тени на стене? Развитие воображения может порождать страхи. Включите звук материнской утробы из раздела «Белый шум», чтобы создать в комнате ощущение безопасности.'),
  ('a23bc347-ea83-491e-af00-0e80deaecf0f', 'Первый шаг к горшку? 🧻', 'Утром подгузник остаётся совершенно сухим, а малышу в нём некомфортно? Это отличный сигнал. Сделайте отметку в трекере подгузников и начните читать об этапах подготовки к приучению к горшку в разделе «Блоги».'),
  ('46824a50-cc48-4a9c-ad3e-91d5073cd55e', 'Буря «Нет!» 🛑', 'На каждое ваше предложение отвечает криком и протестом? Узнайте у нашего эксперта Anacan AI, как сохранять спокойствие в сложные моменты кризиса 2 лет и превращать капризы в игру.'),
  ('51c7f01a-f92a-4f7e-97c1-5893c5304d42', 'В поисках логики 🧩', 'Простые игрушки ему уже быстро надоедают. Откройте для себя в разделе «Рекомендуемые товары» деревянные пазлы и геометрические игры, которые развивают интеллект и концентрацию внимания.'),
  ('a1d0bf30-60c8-4128-8527-423ff92dd8f8', 'Бесконечные догонялки 🏃‍♂️', 'Вместо того чтобы ложиться спать, прыгает по диванам? Запустите таймер сна, отметьте продолжительность укладывания и, ориентируясь на график, попробуйте начинать вечерний ритуал пораньше.'),
  ('1e0042aa-0b2b-4948-aaf5-3b9cec37c61f', 'Забавные фразы 🗣️', 'Эти фразы из 3-4 слов с милыми ошибками бесценны! Не упустите этот замечательный этап развития: сразу добавьте видео со звуком в Альбом малыша и сохраните воспоминание навсегда.'),
  ('4d28b1d1-1b59-430b-a6d9-3d3ad8b1e671', 'Не может выплеснуть энергию и всё разносит?', 'Откройте карту «Места для мам», найдите безопасную площадку с мягким покрытием и горкой и дайте малышу вволю побегать.'),
  ('031a9c48-32b8-49a9-a9d1-55eb165785a3', 'Проверка запасов белка 🥚', 'Для быстро растущих мышц необходим белок. С помощью инструмента контроля питания рассчитайте сегодняшнюю норму (яйца, мясо, бобовые) и скорректируйте меню, если белка не хватает.'),
  ('9a014c54-2569-48f1-8b59-1e18b3b2e5b1', 'Искусство рисования пальчиками! 🎨', 'Играя с красками, малыш испачкался с ног до головы? Вместо того чтобы сердиться, украсьте этот забавный творческий момент весёлыми стикерами в разделе «Фотосессия малыша» и добавьте фото в альбом.'),
  ('9b9b6d7f-8fb9-448e-ba10-0598457b94a6', 'Ночные пробуждения вернулись? ⏱️', 'Малыш просыпается среди ночи с плачем и с трудом засыпает? Проанализируйте статистику таймера сна. Возможно, дневной сон стал слишком долгим и нарушает вечерний режим?'),
  ('87f68482-c94a-42ff-b3af-66083c5353fb', 'Не читать, а рассказывать 📖', 'Во время вечерней сказки малыш сам рассказывает вам, что изображено на картинках? Запишите на аудио этот удивительный момент проявления воображения.'),
  ('9bde240a-b972-41fa-8294-7b553545ae04', 'Кости становятся крепче 🦴', 'Для быстрого развития необходим кальций. С помощью инструмента контроля питания проверьте, получил ли малыш сегодня норму сыра и йогурта, и восполните недостающее.'),
  ('ffa8de8b-2edf-4c8a-82b0-fb8a5415ce7b', 'Не хочет делиться? 🧸', 'В парке малыш бежит к игрушкам других детей, но не отдаёт свои? В разделе блогов узнайте, как научить двухлетнего ребёнка играть по очереди.'),
  ('0fca32b2-cafe-4f95-9933-261c2771f460', 'Давайте подробно проанализируем режим ⏱️', 'Вечером малышу потребовалось 40 минут, чтобы заснуть? Посмотрите график таймера сна. Возможно, пора сократить дневной сон на 20 минут и укладывать малыша вечером пораньше.'),
  ('63d48088-e9cb-43c1-afc1-9e4bb32ff340', 'Ваша маленькая копия 📸', 'Когда вы подметаете комнату, малыш тоже начинает вытирать всё тряпочкой или ходит как вы? Способность к подражанию сейчас на пике!'),
  ('669259fd-a22a-4d24-b932-9eedd58dff3f', 'Без сахара, но сладко 🍪', 'Пора отказаться от магазинного печенья! Откройте в рецептах для малышей полезные сладости с финиками и яблоками, которые можно приготовить дома за 10 минут, и порадуйте малыша.'),
  ('14d92f0a-2caa-441a-b66e-e4531b0f2c30', 'Внезапная агрессия 🛑', 'Когда малыш злится, он толкает друзей или замахивается на вас? Спросите у Anacan AI прямо сейчас, как мягко направить в нужное русло усилившиеся в этом возрасте эмоции.'),
  ('a1ab1785-3fde-4782-bfe0-d24e5fc6ec72', 'Болит спина? 🧘‍♀️', 'Спина ноет из-за того, что вы поднимаете малыша весом 13+ кг? Позаботьтесь о себе: найдите среди полезных рецептов противовоспалительный имбирный чай, который помогает расслабить мышцы, и заварите его.'),
  ('e3fde63e-bd7b-46c0-8b54-9e79a9f6fb65', 'Тишина пугает малыша?', 'Включите в комнате звук вентилятора или фена из раздела «Белый шум» и посмотрите, как он помогает создать идеальное ощущение безопасности во время сна.'),
  ('7ac3c96c-42b7-4566-aa71-c52f9eb0b4eb', 'Туман в голове 🌫️', 'Вы очень устали и всё забываете? Приготовьте богатый Омега-3 перекус с грецкими орехами из раздела полезных рецептов для женщин и разгрузите мысли в Дневнике настроения.'),
  ('8144388a-1733-475c-83c3-62e4fa74eb05', 'Протест против горшка? 🚽', 'Малыш не хочет идти в туалет и плачет? Спросите прямо сейчас у нашего экспертного помощника Anacan AI, стоит ли сделать перерыв в приучении к горшку или попробовать другой метод.'),
  ('aff8f3ff-854b-4c58-ae45-b01d9a3d3fdb', 'Ест только фрукты? 🍎', 'Малыш отказывается от белковой пищи или овощей? С помощью инструмента контроля питания рассчитайте, сколько полезных продуктов он получил сегодня, и придумайте вкусные сочетания, например йогурт с фруктами.'),
  ('53d8ad5e-ba3b-4f31-a266-650eb5f83382', 'Помощник по уборке 🧹', 'Когда вы подметаете комнату, малыш тоже протирает всё тряпочкой или атакует пылесос? Украсьте этот забавный момент подражания стикерами из раздела «Фотосессия малыша» и сразу добавьте его в альбом.'),
  ('9d0ac1c5-216f-4fa0-95d2-f983474b4839', 'Проверяем запасы железа 🥩', 'Чтобы у активного малыша не развилась анемия, проверьте в инструменте контроля питания, сколько железа он получил сегодня (мясо, бобовые), и скорректируйте меню.'),
  ('8f01b040-4aa3-4a5f-a127-4287f88b0ef1', 'Искусство прыжков 🦘', 'Дивана ему уже недостаточно! Найдите безопасный крытый развлекательный центр с батутом, чтобы малыш мог выплеснуть энергию.'),
  ('cf348bab-0260-4da9-bc53-4069f0a6ddf3', 'Маленький художник за работой 🎨', 'Играя с красками, малыш перепачкал всё лицо? Вместо того чтобы сердиться, насладитесь этим забавным творческим моментом.'),
  ('d6dd1818-c4fb-46af-be6f-20980791db71', 'Ночные пробуждения вернулись? ⏱️', 'Малыш просыпается среди ночи с плачем и с трудом засыпает? Проанализируйте статистику таймера сна. Причиной может быть регресс сна в 2 года или прорезывание зубов.'),
  ('1d5cbb75-8a18-4083-a6e5-10d5b00dd31c', 'Естественное успокоение 🍃', 'День выдался очень шумным и активным? Затемните комнату, включите журчание ручья в разделе «Белый шум» и подарите отдых и малышу, и себе.'),
  ('947b2874-60ed-46dc-82cb-4ddf972a50b1', 'Достаточно ли белка? 🍗', 'Для развития активных мышц необходим белок. Оцените баланс ежедневного рациона малыша с помощью инструмента контроля питания и сделайте его меню более разнообразным.'),
  ('f56b8fb7-fe66-42a7-afb0-9342dd02a543', 'Любимые песни 🎤', 'Малыш без конца поёт или напевает одну и ту же песню? Сохраните свидетельство развития чувства ритма и речи в альбоме, добавив музыкальные стикеры из раздела «Фотосессия малыша».'),
  ('0963259b-f909-4657-ae5e-475b63d595ec', 'Бунт против дневного сна! 🛌', 'Малыш не хочет спать днём и убегает? Спросите у Anacan AI о потребностях двухлетних детей во сне и секретах организации спокойного времени (quiet time).'),
  ('0bba2ea7-ff2c-40db-9921-cae50208c766', 'Мастер раздевания! 🧦', 'Малыш пытается самостоятельно снять носки или штанишки? Это отличный признак развития моторики.'),
  ('160a2dee-dfe4-4a75-b257-c4a10c478741', 'Сила имбиря 🫖', 'После целого дня на ногах у вас болят спина и ноги? Найдите в разделе полезных рецептов чай, который помогает расслабить мышцы, заварите его и отдохните.'),
  ('20369d8a-500f-4d0c-8f13-a85f623e07d2', 'Наблюдаем за птицами 🕊️', 'Малышу стало скучно дома? Найдите зелёный парк и покормите вместе птиц, чтобы развивать его любовь и бережное отношение к природе.'),
  ('69fc5add-e558-46f8-bee8-37acee27a9c1', 'Время придумывать истории 📖', 'Устали читать книги? Выключите свет, включите шум дождя в разделе «Белый шум», вместе придумывайте в темноте волшебные сказки и постепенно засыпайте.'),
  ('d25adde2-a568-4bad-bacf-b25822698f2a', 'Снова вернуться к пюре? 🥣', 'Малыш ленится жевать твёрдую пищу и снова просит пюре? Загляните в раздел рецептов для малышей и найдите интересные рецепты мягких котлет, которые легко жевать, но это уже не пюре.'),
  ('181e78e0-6fdf-4595-ab68-0d67492cb40c', 'Я сам налью! 🥛', 'Малыш хочет сам наливать воду в стакан и разливает её повсюду? Чтобы помочь ему освоить практические бытовые навыки, обратите внимание на умные стаканы-непроливайки в разделе «Рекомендуемые товары».'),
  ('68364d15-562a-4922-a1dc-902274f2d63c', 'Хлопает дверями? 🚪', 'Когда малыш злится, он хлопает дверями и плачет? Чтобы научиться справляться с такими сильными эмоциональными вспышками, прямо сейчас обратитесь к нашему эксперту Anacan AI и узнайте подходящие стратегии.'),
  ('0e790195-f407-4908-a021-252afa265e2e', 'Водный баланс мамы 💧', 'Забыли выпить воды, пока бегали за малышом? Возможно, именно поэтому у вас болит голова. Приготовьте освежающую детокс-воду с мятой и лимоном из раздела полезных рецептов.'),
  ('704cb940-aadd-424e-94f9-6bfecacafa6d', 'Утренняя проверка пищеварения 💩', 'При смене подгузника обращайте внимание на стул малыша. По мере увеличения количества твёрдой пищи повышается риск запора. Отметьте это в приложении и добавьте продукты, богатые клетчаткой (грушу, овсянку), с помощью инструмента контроля питания.'),
  ('94804bde-ee95-44e1-87c0-8fe6a051dfb6', 'Страх внезапных звуков 🌪️', 'Малыш боится шума пылесоса или блендера? Включите звук фена в разделе «Белый шум», чтобы уменьшить его страх и постепенно подготовить ко сну.'),
  ('0c2ed459-b6ef-4583-9c57-19766bfe4257', 'Сортируем цвета 🔴🔵', 'Чтобы поддержать развитие логического мышления, найдите в разделе рекомендованных товаров подходящие по возрасту геометрические пазлы и разноцветные деревянные игрушки, которые помогут малышу развивать интеллект.'),
  ('1d490bb4-d589-47e3-911a-0660496e1c17', 'Кусается и дерётся 🦖', 'Когда малыш сердится, он внезапно замахивается или кусается? Читайте психологические статьи в разделе «Блоги», чтобы узнать, как мягко скорректировать характерные для этого возраста проявления агрессии.'),
  ('f82f821d-7bd9-4cb7-9d17-c92628dde594', 'Обувь внезапно стала тесной? 👟', 'Малыш часто спотыкается во время бега? Возможно, его стопа выросла! Внесите текущий рост и размер обуви в трекер веса, чтобы отслеживать физическое развитие.'),
  ('ca3c13b4-94b6-44d7-a1be-1829a1d0e718', 'Кости становятся крепче 🦴', 'Быстрый рост требует кальция. С помощью инструмента контроля питания проверьте, получил ли малыш сегодня необходимое количество сыра и йогурта, и сразу восполните недостающее.'),
  ('cbda41ad-a761-4c07-b60f-6e77f3dd54cc', 'Вы и так замечательная мама 🌟', 'Сегодня вы без остановки бегали за малышом и устали. Откройте дневник настроения, запишите даже самый маленький добрый поступок, который вы сегодня совершили для него, и устройте себе овацию!'),
  ('dc8f916f-27ea-45e1-9c5f-84435b0902fd', 'Упрямо хочет есть сам 🥄', 'Малыш забирает у вас ложку и пачкает всё вокруг? Запустите таймер питания и проанализируйте, сколько времени занимает эта проба самостоятельности. А на разбросанную еду просто смотрите с улыбкой.'),
  ('1d9a17fb-3ed7-4382-9eaf-1517914b5b98', 'Не хочу эти брюки! 👗', 'Началось упрямое «Я сам оденусь!»? Узнайте у Anacan AI, как избежать утренних споров из-за одежды и предоставить малышу право самостоятельного выбора.'),
  ('98d988ed-7e7f-4eb3-8b84-734112bb1929', 'Вам тоже нужны друзья 👯‍♀️', 'Устали разговаривать только с малышом? Найдите в разделе дружественных к мамам мест центры с игровыми группами, чтобы общаться с другими мамами и обмениваться опытом.'),
  ('f6ae40aa-d27d-4aed-a0d9-bd51bad467d7', 'Книги нужно читать, а не рвать 📖', 'Во время вечерней сказки малыш рвёт страницы или не даёт вам читать? Спросите у Anacan AI, как решить эту проблему, не мешая формированию привычки к чтению.'),
  ('27d6b395-9576-4f2d-9566-57d41e7c6f41', 'Полностью проанализируем режим ⏱️', 'Вечером малышу потребовалось 40 минут, чтобы уснуть? Посмотрите график таймера сна. Возможно, пора сократить дневной сон на 20 минут и раньше укладывать малыша вечером.'),
  ('dec1d9f5-52bc-4c79-9c9c-281f44046beb', 'Нескончаемые вопросы «Почему?» 🤔', 'Малыш не устаёт задавать вопросы? Этап «Что это?» и «Почему?» официально начался! Узнайте из блогов, как терпеливо отвечать на вопросы маленького исследователя.'),
  ('e68bbf03-3f37-41e8-a1d9-32feba8b86d7', 'Без сахара, но сладко 🍪', 'Больше никакого магазинного печенья! Откройте для себя в рецептах для малышей полезные сладости, которые можно приготовить дома за 10 минут, и порадуйте своего малыша.'),
  ('32443a45-bb1d-40cd-8cbf-77a3eda300d7', 'Горячий кофе и тишина 🍵', 'Таймер остановился, малыш уснул. Не спешите заниматься домашними делами! Приготовьте особенный кофе по рецепту из раздела полезных рецептов, прилягте на диван и просто наслаждайтесь тишиной.'),
  ('de0f5d4f-9f96-42d7-a940-e7558af5d045', 'Не перекусывайте на ходу 🍎', 'Позаботьтесь о себе! Приготовьте по нашим полезным рецептам ягодный салат — настоящий кладезь антиоксидантов.'),
  ('7a5b3c40-a866-426b-8ed4-dd68302d6513', 'Любовь к туалетной бумаге 🧻', 'Малыш разматывает рулоны туалетной бумаги в ванной и играет с ними? Используйте этот интерес с пользой: прямо сейчас прочитайте в разделе «Блоги» статью о том, как в игровой форме приучить малыша к горшку.'),
  ('d2a5512c-c089-47a6-aba1-367f406306e5', 'Раз, два, три... 🔢', 'Малыш пытается что-нибудь считать, поднимаясь по лестнице? Это первые проблески математического мышления.'),
  ('f4ef4af2-bbdc-456f-a980-4eeb315c77b8', 'Все ли зубки на месте? 🦷', 'Прорезываются последние коренные зубы? Чтобы обеспечить повышенную потребность в кальции, обязательно проверьте в инструменте контроля питания, сколько йогурта и сыра малыш съел сегодня.'),
  ('0480de3f-fc2e-475f-9c9a-7f062b43912d', 'В спальне слишком жарко? 🌡️', 'Малыш часто ворочается в постели и потеет? Проверьте температуру в комнате, включите таймер сна и создайте ощущение прохлады с помощью звука вентилятора из раздела «Белый шум».'),
  ('2b885719-7eb3-49f2-a501-3fdceb08a1dc', 'Плачет вслед за вами? 🚪', 'Малыш кричит вам вслед, даже когда вы просто выходите из комнаты? Спросите у Anacan AI, как мягко справиться с этой новой волной тревоги разлуки.'),
  ('4ef212ee-e501-41a3-bd1b-0f62028addbd', 'Логика в действии 🧩', 'Малыш уже мастерски подбирает геометрические фигуры? Загляните в раздел «Рекомендуемые товары», чтобы найти более сложные игры, которые бросят вызов его интеллекту.'),
  ('132f97c4-bee0-471c-ad8b-a7fc3585b9d6', 'Выбираем зубную пасту 🪥', 'Малыш уже учится сплёвывать воду? Обязательно прочитайте в разделе «Блоги» нашу научную статью о том, какую пасту выбрать — с фтором или без него.'),
  ('c85cd72a-3a99-42a3-86ab-1fa1d9a4f422', 'Пирожки из грязи! 🧁', 'Малыш хочет играть с землёй во дворе? Позвольте ему испачкаться! Сохраните эти чудесные моменты, поддерживающие сенсорное развитие, с помощью фотосессии малыша.'),
  ('da905da7-70f6-46f4-b372-c620f421daf8', 'Перезагрузите мозг 🧘‍♀️', 'Кажется, что всё навалилось разом? Откройте дневник настроения и в течение 3 минут без остановки записывайте всё, что чувствуете. Письмо помогает быстро снизить стресс.'),
  ('929b30f1-695d-4f66-a22b-9182b15561c4', 'Проверка гравитации! 🍎', 'Малыш обожает бросать еду или игрушки сверху вниз? Спросите у Anacan AI, как не запрещать эти физические эксперименты, а направить их в другое русло.'),
  ('a100b8dd-35f6-4549-ae5f-d60352e46cb5', 'Не хватает клетчатки? 💩', 'Стул стал твёрдым и малыша беспокоит запор? Сделайте запись в трекере подгузников и сразу добавьте чернослив или овсянку в меню с помощью инструмента контроля питания.'),
  ('f0258928-f8cb-46a1-adb3-9d7138af115d', 'Первый товарищ по играм 👯‍♂️', 'Малыш постоянно пытается играть с другим ребёнком в парке? Найдите в разделе «Места для мам» детские кафе, которые помогут поддержать этот новый этап социализации.'),
  ('0b94a795-dee1-49c6-a4fb-e07d6174147f', 'Анализ таймера сна ⏱️', 'Малыш слишком поздно засыпает по вечерам? Посмотрите график таймера сна. Возможно, скоро придётся заметно сократить дневной сон и укладывать малыша вечером раньше.'),
  ('225bd8fb-b294-42ab-8941-6c8eee154c5f', 'Обувь внезапно стала мала? 👟', 'Малыш часто спотыкается во время бега? Возможно, его стопа выросла! Внесите текущие показатели роста и размера обуви в трекер развития, чтобы следить за физическим развитием.'),
  ('f7cd700a-6bea-4a3e-a6b4-0018529f2ea2', 'Кофе или вода? 💧', 'Не пытайтесь заглушить усталость кофеином! Откройте для себя в разделе полезных рецептов для женщин энергетические детокс-напитки с белком и фруктами.'),
  ('51803c0a-8b62-474c-8ecd-e45188efdf2a', 'Игра в складывание одежды 🧺', 'Малыш тоже хочет помогать, пока вы складываете одежду? Поручите ему находить пары носков! Читайте в блогах, как в игровой форме привить ребёнку чувство ответственности.'),
  ('ede1e4a9-4d71-4eca-bacd-697cb6454edc', 'Страх тёмной комнаты 🌌', 'Малыш плачет, когда вы выключаете свет? По мере развития воображения страхов становится больше. Включите в разделе «Белый шум» звуки материнской утробы, чтобы вернуть ему знакомое чувство безопасности.'),
  ('13aac5b4-c714-41fb-8e2e-16c1c92d8390', 'Как пробудить интерес к книгам? 📖', 'Вместо чтения малыш хочет рвать страницы? Спросите у Anacan AI, как привлечь его внимание к сказке, не отбив интереса к чтению.'),
  ('542e3a59-e25b-4803-a553-c3183744d2dc', 'Секрет усвоения железа: витамин C 🍋', 'Чтобы железо лучше усваивалось организмом, загляните в сегодняшнее меню в инструменте контроля питания. Обязательно дополните мясное блюдо салатом с большим количеством лимонного сока или помидоров.'),
  ('bb3d49d9-8e03-48af-9a82-d11c505ca32b', 'Мамино время для кофе ☕', 'Отложите домашние дела и передохните! Найдите среди мест, дружественных к мамам, кафе с детским игровым уголком, спокойно насладитесь горячим кофе и познакомьтесь с другими мамами.'),
  ('0d828df8-79e8-40c6-a759-0255d981435d', 'Звук ночи: поезд 🚂', 'После дневного шума внезапная тишина тревожит малыша? Включите монотонный стук поезда в разделе «Белый шум», чтобы заглушить остальные домашние звуки и настроить его на сон.'),
  ('8776b932-7a29-4e58-81cd-88646f84a4c7', 'Обувь внезапно стала тесной? 👟', 'Малыш спотыкается во время бега или пытается снять обувь? Возможно, его стопа выросла! Внесите актуальные параметры в Трекер развития и сразу оцените динамику физического развития.'),
  ('e742c56f-494a-46b7-82c7-113a5d4f0287', 'Энергетические шарики без сахара 🍪', 'Пора отказаться от магазинных сладостей! Откройте в рецептах для малышей полезные и вкусные шарики из фиников и овсяных хлопьев, которые готовятся всего за 10 минут, и порадуйте ребёнка.'),
  ('81b85e80-d265-4f32-8c47-4b14aa23d8e1', 'Внезапная агрессия 🦖', 'В порыве гнева малыш толкает друзей или замахивается на вас? Прямо сейчас спросите у Anacan AI, как мягко направлять его сильные эмоции, характерные для этого возраста.'),
  ('bf03a99b-eae8-47d0-a5c6-eb2e17e62b7d', 'Не забывайте о себе ⚡', 'К середине дня у вас совсем не остаётся сил? Не налегайте на сладкое! Приготовьте по одному из полезных рецептов для женщин питательный белковый смузи с арахисовой пастой и зарядитесь энергией.'),
  ('fdde906c-a398-4012-a073-4015f9852301', 'Анализ сна с помощью таймера ⏱️', 'Вечером малыш слишком долго засыпал? Запустите таймер сна и следите за графиком. Проанализируйте, не успел ли он потратить накопившуюся энергию или, наоборот, переутомился.'),
  ('63af320f-f496-491d-b573-f5b6663a91e4', 'Горячий чай и тишина 🍵', 'Таймер остановился, ребёнок уснул. Не беритесь сейчас за домашние дела! Заварите чай с мелиссой по одному из полезных рецептов для женщин и позвольте усталости прошедшего дня раствориться в тёплом пару.'),
  ('86e064b7-8da1-4aa9-b551-ca85b1a25e7c', 'Достаточно ли белка? 🍗', 'Мышцам малыша, который постоянно бегает и прыгает, необходим белок. Оцените сбалансированность его ежедневного рациона с помощью инструмента контроля питания и разнообразьте меню.'),
  ('947ec858-749d-4a0f-bf72-73a1503e2c5f', 'Бесконечные вопросы «Почему?» 🤔', '«Что это? Почему так?» — этот этап официально начался! Узнайте в блогах, как терпеливо отвечать на бесконечные вопросы любознательного ребёнка, помогая ему развиваться.'),
  ('5d69eb5c-8ed9-4c1d-9b48-d1c46bb4e1fb', 'Старые аудиозаписи 🎤', 'Когда ребёнок уснёт, откройте Альбом малыша и послушайте милые звуки, которые он издавал несколько месяцев назад. Порадуйтесь и почувствуйте гордость за то, как быстро он растёт!'),
  ('c3ea09ec-b61b-40ca-8245-a6b47232b78f', 'Этап «Это моё!» 🧸', 'В парке малыш никому не даёт свои игрушки? Спросите у Anacan AI, как научить приближающегося к 2.5 годам ребёнка играть по очереди.'),
  ('0ba368ce-9746-48c2-a3e5-a973ee982121', 'Любовь к макаронам 🍝', 'Ребёнок уже несколько дней просит одно и то же блюдо? Пищевая избирательность сейчас на пике. Поищите среди полезных рецептов интересные соусы, в которых можно незаметно спрятать овощи.'),
  ('92abce30-d667-4f40-9371-ee7642e09a28', 'Наслаждение тишиной 🤫', 'В комнате наконец-то воцарилась тишина. Забудьте о делах и посидите в полумраке. Включите шумомер, измерьте уровень этой тишины и дайте мозгу отдохнуть.'),
  ('e50a9ce1-a01a-4462-9bc9-e410e94685ff', 'Нам исполнилось 800!🚀', 'Теперь наступает время ещё большего количества вопросов, движений и проявлений индивидуальности. Сделайте глубокий вдох и шагните в этот новый увлекательный этап.'),
  ('0ea063ed-fd41-47e6-9ae7-1268a3f1138f', 'Мифы об идеальной маме 🛑', 'Вините себя за то, что сегодня ребёнок провёл слишком много времени перед экраном? Забудьте об идеальных мамах из интернета. Вы прекрасны в своей реальной жизни.'),
  ('6e5882b6-b1b9-4876-8253-b97551d73f12', 'Папина игровая площадка 👨‍👧', 'Терпение на исходе? Закройте дверь в комнату и оставьте ребёнка наедине с папой. Пусть сегодня вечером он руководит домашними играми.'),
  ('c72b4558-e629-4a4b-bb39-ef072b6603b3', 'Период «Почему?» 🤔', 'На всё спрашивает: «Почему это так?» Его мозг впитывает информацию как губка. Наберитесь терпения и давайте короткие, понятные ответы.'),
  ('015a0c8f-c960-422b-8198-6bdb85909e68', 'День был трудным? 📝', 'Запишите сегодняшний стресс в дневник настроения и выговоритесь. Все мамы переживают такие кризисы — вы не одиноки.'),
  ('5229a519-68a8-4340-8bba-d14464123530', 'Игры воображения 🧸', 'Оживляет машинки и кормит игрушечного мишку? Его воображение стремительно развивается. Отметьте этот когнитивный скачок в трекере развития и присоединяйтесь к игре.'),
  ('f0d11fbf-f594-485d-b316-f567d5c6731d', 'Заскучали дома?', 'Найдите среди мест, дружественных мамам, кафе с детским игровым уголком. Пусть ребёнок играет, а вы спокойно выпьете горячий кофе.'),
  ('b9ab0ee4-3e32-4c6f-9669-cbb581181150', 'Музыкальное спокойствие 🎶', 'Самый простой способ справиться с вечерними капризами — включить любимую мелодию, обнять ребёнка и медленно потанцевать вместе.'),
  ('c4cbfe42-b7f8-4e4c-ad6a-198774caa2d6', 'Остались дома из-за странной погоды?', 'Пусть инструмент «Погода и одежда» мгновенно покажет температуру, которую не определишь по виду из окна, — и отправляйтесь в парк.'),
  ('ce87972f-2f28-45fe-80b3-aa0ec4116930', 'Я сам оденусь 👕', 'Даже если ребёнок надевает брюки на голову, не мешайте его попыткам одеться самостоятельно. Стремление к независимости сейчас на пике! Дайте ему время и возможность попробовать.'),
  ('43a750e7-aff2-4c1a-baec-6890bc56e642', 'Я сам налью! 🥛', 'Хочет сам налить воду в стакан и всё вокруг становится мокрым? Поищите в Рекомендованных товарах умные непроливайки, которые помогают развивать практические навыки и облегчают вам жизнь.'),
  ('8d131ccb-5e19-4d42-b8a6-86bf255b1f23', 'Повар на кухне 👩‍🍳', 'Вместе замесите тесто для бананового печенья без сахара из рецептов для малышей. Пусть ребёнок развивает моторику, весело проводит время и с аппетитом ест то, что приготовил сам.'),
  ('bd7400ff-b3f7-4318-9c68-166242aa98f9', 'Горячий чай и тишина 🍵', 'Таймер остановился, ребёнок уснул. Не спешите заниматься домашними делами! Заварите чай с мелиссой или ромашкой из полезных рецептов, прилягте на диван и просто насладитесь тишиной.'),
  ('65e69d4e-9f8b-4e23-8934-10178d918f6b', 'Твоё? Моё! 🧸', 'Не хочет отдавать в парке чужую игрушку? Это период эгоцентризма. Учите делиться не силой, а соблюдая очерёдность.'),
  ('250e2ef0-defa-4388-a9c2-8574f1be0fed', 'Маленький повар на кухне 👩‍🍳', 'Вместе замесите тесто для печенья без сахара по одному из рецептов для малышей. Пусть малыш развивает моторику и с аппетитом ест то, что приготовил сам.'),
  ('2ee3ac65-4c9f-4558-a181-e43a5be6a221', 'Маленький альпинист 🧗', 'Лазание по мебели уже превратилось в хобби? Загляните в раздел «Рекомендуемые товары» и выберите специальные защитные приспособления, чтобы сделать дом максимально безопасным.'),
  ('e1c7d8a6-1882-42b5-8d1e-5420a73cc054', 'Журчание воды 🌊', 'День выдался слишком бурным и полным беготни? Приглушите свет, включите в разделе «Белый шум» журчание реки и просто вместе погрузитесь в атмосферу спокойствия.'),
  ('09840996-6ece-429b-8105-2969a0ec7d4b', 'Похвалите себя 🌟', 'Удалось прожить день без истерик? Без вас малыш не смог бы так развиваться. Откройте «Дневник настроения» и напишите себе большую благодарность за все ваши старания!'),
  ('152dc6e1-3207-4818-a59d-35cf71d6d914', 'Забота об игрушках 🧸', 'Малыш поёт мишке колыбельную или укрывает его? Это признак активно развивающейся эмпатии. Добавьте этот момент в «Альбом малыша» в виде видео со звуком и сохраните проявление его заботы.'),
  ('cb411136-f146-4918-b034-820fe50cfd21', 'Словарный взрыв 🗣️', 'Как развивается словарный запас малыша? В разделе «Блоги» узнайте нормы речевого развития для этого возраста и найдите домашние игры, которые помогут поддержать этот процесс.'),
  ('047ed43c-bb7c-4206-afa0-67d1dc0f765d', 'Еда превращается в фигурки ⭐️', 'Малыш не ест обычные нарезанные фрукты? В рецептах для малышей найдите забавные варианты подачи в форме звёздочек или животных и превратите приём пищи в увлекательную визуальную игру.'),
  ('5f17b1b2-9554-4ba7-b535-5f0af1522385', 'Прячется, чтобы покакать? 🙈', 'Малыш уходит за занавеску или в угол, чтобы покакать? Это один из главных психологических признаков готовности к горшку! Отметьте это в трекере подгузников и прочитайте обучающие статьи в разделе «Блоги».'),
  ('c569bc01-3134-4ece-a6d6-d600fb0bf88b', 'Ноет поясница? 🧘‍♀️', 'Из-за того, что вы часто поднимаете подросшего малыша, мышцы перенапряглись. Заварите противовоспалительный имбирный чай по одному из полезных рецептов для женщин, прилягте и уделите немного времени себе.'),
  ('504aaa66-e4f6-4eca-bd17-eead2d69deec', 'Искусство одеваться самостоятельно 👕', 'Малыш пытается надеть брюки на голову, а футболку — на ноги? Не упустите эту забавную попытку проявить самостоятельность! Сразу украсьте фото весёлыми стикерами в разделе «Фотосессия малыша» и загрузите его в альбом.'),
  ('c0ee7f2f-8895-4772-8368-647fe5fed56e', 'Исследование луж 🌧️', 'После дождя нельзя сидеть дома! Найдите ближайший парк в разделе «Места для мам», наденьте малышу резиновые сапоги и позвольте ему попрыгать по лужам и грязи.'),
  ('e70f443c-46d9-4882-ab14-fad93c425a0f', 'Окно сна смещается ⏱️', 'Малыш отказался от дневного сна? Чтобы к вечеру он не переутомился и не устроил истерику, запустите таймер сна и начните вечерний ритуал на 30 минут раньше.'),
  ('65eaf451-e5ab-4c54-9b0f-1a6331bd0312', 'Мелкая моторика развивается 🧩', 'Малыш уже запомнил, как собирать простые пазлы. В разделе «Рекомендуемые товары» найдите более сложные деревянные пазлы из множества деталей, которые дадут его уму новую нагрузку.'),
  ('c2a5ae09-9d8c-4ef8-afa7-4f35fb948c6f', 'Истерика на полу 🛑', 'Малыш падает на пол и кричит в общественном месте? Не обращайте внимания на взгляды окружающих! Обсудите ситуацию с Anacan AI и узнайте, как сохранять спокойствие и справляться с такими сильными эмоциональными вспышками.'),
  ('f9afcff7-9182-4728-9ed2-135f5b97e440', 'Книги нужно читать, а не рвать 📖', 'Малыш рвёт страницы во время вечерней сказки? В разделе «Блоги» прочитайте, как привлечь его внимание к сказке, не отбив интереса к чтению.'),
  ('11eb0bc9-4158-4fbc-8d65-97be316f8b92', 'Кальций содержится не только в молоке 🧀', 'Малыш отказывается пить молоко? Кальций необходим для здоровья костей. С помощью инструмента контроля питания подсчитайте, сколько сыра, йогурта или брокколи малыш съел сегодня, и восполните недостающее количество.'),
  ('d4efd00f-6d87-4868-a912-9b76b79425d0', 'Шоу перед зеркалом 🤪', 'Корчит рожицы своему отражению и заливается смехом? Снимите этот забавный момент знакомства с собой на видео, сразу добавьте его в Альбом малыша и забудьте о дневном стрессе.'),
  ('3f2f1108-7831-4796-88a8-5de7f4f81912', 'Вам тоже нужен перерыв ☕', 'Выйдите из дома и немного развейтесь! Найдите в разделе «Места для мам» ближайшее кафе с детским уголком, насладитесь горячим кофе и познакомьтесь с другими мамами.'),
  ('875b72c1-d353-4eb2-8649-bca828613387', 'Гордитесь собой 🌟', 'Каждый новый навык малыша, каждый его уверенный шаг — результат вашей самоотдачи. Откройте Дневник настроения и напишите сегодня о том, за что вы готовы аплодировать себе стоя!'),
  ('9ccd2cce-af67-4d8c-b8c4-0ddfa25c77b1', 'Разбрасывает еду? 🥣', 'Ему надоедает сидеть за столом, и он бросает ложку? Включите таймер кормления, проанализируйте продолжительность процесса на графике и полностью откажитесь от кормления через силу.'),
  ('4bafd57a-0f5f-4a7d-8215-cfd63b08cad2', 'Еда только одного цвета? 🟡', 'Хочет есть только жёлтые продукты (картофель, макароны, бананы)? Проанализируйте его меню с помощью инструмента контроля питания и найдите в Рецептах для малыша яркие альтернативы со спрятанными овощами.'),
  ('accea8e1-cb5f-4833-9081-056b6237ac04', 'Разница между «я» и «ты» 🗣️', 'Малыш уже говорит о себе не в 3-м лице, а использует слово «я»? Чтобы поддержать этот важный скачок в развитии мышления, прямо сейчас спросите у Anacan AI, как правильно выстраивать диалог.'),
  ('f9e8a36b-3135-4421-adad-49b6ce187cf2', 'Ещё одну сказку! 📚', 'Постоянно придумывает новые поводы не ложиться спать? Запустите таймер сна, придерживайтесь установленных границ и включите шум океанских волн в разделе «Белый шум», чтобы создать в комнате спокойную атмосферу.'),
  ('52ee49fe-425d-44ef-9429-5ef1f4410d82', 'Искусство прыгать 🦘', 'Пытается прыгать с лестницы или дивана? Для развития моторики малышу нужно безопасное пространство. Найдите в разделе «Места для мам» крытый развлекательный центр с батутами и направьте его энергию в нужное русло.'),
  ('f8fbff5d-2a79-4ebc-90f5-c58d315a80ab', 'У вас тоже есть заряд энергии 🔋', 'Устали весь день говорить «нет» и бегать за малышом? Выплесните свои переживания в Дневнике настроения. Помните: время для себя — не роскошь, а необходимость.'),
  ('fb79060e-f7c1-4e3e-983a-bf84e747b66e', 'Ботинки надеты не на те ноги! 👟', 'Надел правый ботинок на левую ногу, левый — на правую и не хочет переобуваться? Украсьте эту забавную попытку проявить самостоятельность весёлыми стикерами из Фотосессии малыша и превратите снимок в самый смешной кадр альбома.'),
  ('10f0ddfb-06ae-4780-9b39-ba433d0edc10', 'Банан или телефон? 🍌', 'Прикладывает банан или пульт к уху и ведёт воображаемые разговоры? Вот она, вершина игры воображения! Снимите этот драгоценный момент на видео со звуком, сразу добавьте его в Альбом малыша и сохраните в памяти навсегда.'),
  ('24cc9d6f-2286-4f7a-a81a-633ab5dd91df', 'Страх тёмной комнаты 🌌', 'Когда вы выключаете свет, предметы в комнате кажутся малышу чудовищами? С развитием воображения появляются и страхи. Включите звуки материнской утробы в разделе «Белый шум», чтобы вернуть ему знакомое ощущение полной безопасности.'),
  ('3c29abba-6cf4-47d2-a227-99611ccf0101', 'Секрет железа и энергии 🥩', 'Чтобы у активного малыша не развилась анемия, проверьте в инструменте контроля питания, достаточно ли железа он получил сегодня (мясо, чечевица, шпинат), и дополните меню продуктами с витамином C.'),
  ('074c97a3-66b5-4499-b8dd-c6ca41189da1', 'Потребление жидкости и запор 💧', 'Много бегает, но мало пьёт? Следите за выделениями при смене подгузника. Если есть риск запора, отметьте это в приложении и сразу добавьте богатые клетчаткой продукты (груши, овсянку) с помощью инструмента контроля питания.'),
  ('33f7b16f-fd6e-4686-be50-8b9aabfa4a20', 'Мастер цветов и форм 🔴🟩', 'Группирует предметы, пуговицы или игрушки по цвету? Найдите в разделе «Рекомендуемые товары» деревянные пазлы, которые бросят вызов его интеллекту и помогут развить логическое мышление.'),
  ('912d3d15-f8b0-4ade-8219-5e9c81b99f0a', 'Ночной ужас или кошмар? 🤖', 'Малыш просыпается среди ночи с плачем и не может успокоиться? Чтобы понять разницу между этими состояниями и правильно оказать психологическую поддержку, ознакомьтесь с нашими научными статьями в разделе «Блоги».'),
  ('71700719-be0c-45bf-8d93-6cb51d48ed2d', 'Книжный червь 📖', 'Приносит любимую книгу сказок и просит снова и снова читать одну и ту же страницу? Повторение — это его способ учиться. Терпеливо прочитайте ещё раз.'),
  ('d6aaa644-5d8a-47cd-b998-227fc0b6f04b', 'Домашние дела могут подождать 🛑', 'Пол не вымыт? Пусть подождёт. Беспорядок в доме можно устранить, а восстановление выгоревшей мамы занимает много времени. Прилягте на диван и насладитесь тишиной.'),
  ('04312503-34be-494a-8896-38312d406a86', 'Воображаемое чаепитие 🫖', 'Заставляет вас или свои игрушки пить чай из воображаемых чашек? Ролевые игры — вершина интеллектуального развития!'),
  ('149beadc-5c37-404b-8b3e-f6ce437629da', 'Боль в шее у мамы 🧘‍♀️', 'После игр на полу и ношения малыша у вас затекли шея и спина? Отдохните, заварив по одному из полезных рецептов зелёный чай с имбирём, который помогает расслабить мышцы и уменьшить воспаление.'),
  ('2daba5bf-3da2-43ab-bc87-fdc726c1aabb', 'Монстр под кроватью? 👾', 'По мере развития воображения страхи тоже начинают казаться реальными. Если малыш боится теней, приглушите свет и включите в разделе «Белые шумы» звук материнской утробы (биение сердца), чтобы вернуть ему знакомое чувство полной безопасности.'),
  ('d0a47f18-7e98-462c-be4f-167fcf918411', 'Ссора из-за очереди на горку 🛑', 'Не хочет ждать других детей в парке? Обязательно прочитайте в разделе «Блоги» статьи о социализации и узнайте, как ближе к 2.5 годам научить малыша соблюдать очередь и проявлять терпение.'),
  ('dc66703c-31b3-4677-a6cd-dc09bb5b60cf', 'Не вините себя 💖', 'Сегодня капризы вывели вас из себя и вы повысили голос? Выплесните свои переживания в Дневнике настроения. Вы не робот и не обязаны быть идеальной!'),
  ('f9ec5212-0b50-47f7-b50f-84f41a8701a2', 'Мода носить всё задом наперёд! 👕', 'Малыш надел брюки задом наперёд, перепутал обувь и не хочет переодеваться? Не мешайте этой забавной попытке проявить самостоятельность!'),
  ('36818534-e1f7-451b-9f88-51bf852bc139', 'Бунт против дневного сна! ⏱️', 'Малыш отказался спать днём и теперь сильно переутомлён? Посмотрите график в таймере сна и начните вечерний ритуал как минимум на 40 минут раньше, чтобы предотвратить ночные страхи.'),
  ('54668cb8-852a-467f-9492-c88f3b1ba329', 'Сдерживает стул? 💩', 'Во время приучения к горшку малыш встаёт и сдерживает стул? Это может привести к психологическому запору. Отметьте это в Трекере подгузников и сразу добавьте в меню абрикосы или овсянку.'),
  ('d3a86832-34ed-43f4-90d5-a80f77b22f80', 'Ему тесно в четырёх стенах 🌳', 'Не может выплеснуть энергию дома и разбрасывает всё вокруг? Откройте карту Мест для мам, найдите безопасный парк с мягким покрытием и горкой и дайте малышу вдоволь порезвиться на свежем воздухе.'),
  ('24023d7c-2bc9-4102-89e5-fd869c13910d', 'Скачок роста и веса! 📏', 'Во время одевания вы заметили, что футболки стали тесными или обувь жмёт? Внесите текущие рост и параметры в Трекер веса и с гордостью наблюдайте, как поднимается кривая развития.'),
  ('af6b0980-8f3e-49f7-8539-9fc05967e656', 'Проверьте запасы железа 🥩', 'Малыш бледен или быстро устаёт? Проверьте в инструменте контроля питания, сколько железа он получил сегодня, и вместе с мясом обязательно давайте витамин C (лимон, помидор), чтобы улучшить его усвоение.'),
  ('f5e0ef2c-4838-48df-b45d-d158a473879a', 'Вам тоже нужны друзья 👯‍♀️', 'Устали весь день разговаривать только на детском языке? Найдите в разделе «Места для мам» детские кафе, где собирается много мам, и создайте для себя возможность пообщаться.'),
  ('3046868d-cc9d-4ca4-8350-b813468ec4dd', 'Срочные покупки 🛒', 'Закончились шампунь, подгузники или овсянка? Не держите это в голове — добавьте всё в список покупок и синхронизируйте его с партнёром.'),
  ('437a3027-38a4-47b2-a62c-a24094b2e7eb', 'Падает на пол и кричит, когда не получает желаемого?', 'Истерики малыша продолжаются. Спокойно оставайтесь рядом, а когда он успокоится — обнимите.'),
  ('46ca17b0-646f-46ee-9f74-a67a0f778d4f', 'Герой сказки 🪄', 'Сегодня вечером создайте в «Умных сказках» особенную историю, главным героем которой станет ваш малыш: «Храбрый малыш, который любит ночь».'),
  ('44efc816-fa09-4bf6-a073-38bbffbb2693', 'Объятие «Я тебя люблю» 🫂', 'Внезапно подбегает, обнимает вас за шею или гладит по лицу? Малыш уже выражает свою любовь прикосновениями. Насладитесь этим моментом.'),
  ('764398f1-2f82-4a41-a767-bcf8004dd068', 'Раскладываем вещи по местам 🧸', 'Кладёт игрушку в коробку, а затем снова достаёт? Так формируется понимание понятий «внутри» и «снаружи». Обязательно отметьте этот когнитивный навык в трекере развития.'),
  ('850a613f-ecbc-4d9b-ab63-9701c3f268f9', 'Есть вопрос? 🤖', 'Как должна развиваться речь ребёнка после 2 лет? Не теряйтесь в интернете — напишите напрямую Anacan AI и получите научно обоснованный ответ.'),
  ('4fcc8b4e-e106-490a-a901-8c89be671af5', 'Скоро появятся длинные предложения! 🗣️', 'Уже объединяет 4-5 слов и рассказывает забавную историю? Происходит настоящий словарный взрыв! Не упустите этот драгоценный момент: сразу сохраните голосовую запись в Альбоме малыша и отметьте новый этап развития.'),
  ('569d530d-d6b9-4460-be46-292c62f656dd', 'В поисках логики 🧩', 'Малыш уже запомнил, как собирать простые пазлы из двух-трёх деталей. В разделе «Рекомендуемые товары» найдите более сложные деревянные игрушки, которые развивают интеллект и понимание причинно-следственных связей.'),
  ('ce1a09c7-d2c5-485b-a920-bc02df41fb58', 'Буря в ванной 🛁', 'Не хочет выходить из воды и плачет? Сразу спросите у Anacan AI об отвлекающих игрушках и практичных способах спокойно завершить купание без стресса.'),
  ('32be8503-ee3d-483e-baae-9b3b130b80cc', 'Спор из-за очереди на горку 🛑', 'Не хочет ждать других детей в парке? Обязательно прочитайте в разделе «Блоги» статьи о социализации и узнайте, как ближе к 2.5 годам научить малыша соблюдать очередь и делиться.'),
  ('bbf3c14f-5832-4554-88a9-fc0b10c25324', 'Страницы оживают 📖', 'Во время чтения сказки малыш сам придумывает финал? Узнайте с помощью Anacan AI об интерактивных техниках чтения, поддерживающих этот удивительный полёт воображения.'),
  ('c3d03381-340f-4ce1-b075-de3e6584aed7', 'Потребление жидкости и запор 💩', 'Много бегает, но мало пьёт? Следите за стулом во время смены подгузника (или при посещении горшка). Если есть риск запора, отметьте это в приложении и сразу добавьте чернослив или овсянку в меню с помощью инструмента контроля питания.'),
  ('275e7b7b-377b-40f0-9e43-ab5886fc93b4', 'Играет с едой 🥦', 'Вместо того чтобы есть макароны, разминает и разбрасывает их? В этом возрасте еда — ещё и игрушка. Отмечайте объём съеденного в плане питания, чтобы следить за недельным балансом.'),
  ('7af19435-be8e-48dc-a066-aab689899f04', 'Утренний философ 🧦', 'Сегодня утром малыш решил надеть носок на руку? Не сердитесь из-за таких моментов исследования мира, сопровождающихся упрямством. Позвольте ему немного так походить — это его способ проверить свою самостоятельность.'),
  ('f13502d3-76f4-47c6-bfef-ed2cb1d9fcf7', 'Волшебная сила воды 🛀', 'После целого дня беготни устали и малыш, и вы. Тёплая ванна — это не просто гигиена, а один из лучших способов успокоить его нервную систему.'),
  ('1b2a22e9-6d73-4469-8535-2d773936acd1', 'Эгоизм в парке 🧸', 'Во время игры в песке никому не отдаёт свою формочку? К 27 месяцам представление о том, что нужно делиться, всё ещё развито слабо. Не обвиняйте малыша в эгоизме, а просто объясните правило очереди.'),
  ('57e50587-fc65-4605-a4e9-bbde134adfea', 'Папин голос 📖', 'Давайте сегодня вечером создадим в комнате особую атмосферу. Поручите чтение книги или рассказывание сказки папе с его низким, внушающим доверие голосом, а сами немного отдохните.'),
  ('64f0ac54-c21f-4a4c-bcce-53662284a4f5', 'Превосходная память 🧠', 'Сегодня утром малыш безошибочно нашёл игрушку, которую вы спрятали вчера? Его долговременная память развилась удивительно хорошо.'),
  ('99e86be1-9932-47a0-b9a8-f6b98dc7dfcf', 'Отказ от сна 🥱', 'Не хочет ложиться спать днём и сопротивляется? Некоторые дети в этом возрасте отказываются от дневного сна. Вместо споров объявите тихий час и полистайте вместе книжку в кровати.'),
  ('f80a3604-81aa-4362-9508-4aa4c845b4bc', 'Акустика комнаты 🤫', 'Малыш вздрагивает от малейшего стука, как только засыпает? Проверьте уровень шума в комнате с помощью шумомера и включите белый шум, чтобы заглушить звуки, доносящиеся из окна.'),
  ('25092d10-5861-4eec-8fa9-86857d835418', 'Маленький помощник 🧹', 'Пытается забрать у вас одежду, когда вы её складываете, или тряпку, когда моете пол? Малыш чувствует себя взрослым. Дайте ему небольшую тряпочку и позвольте помочь вам.'),
  ('739e50cd-5199-4e7e-9448-99a52d59a069', 'Крепость из подушек 🏰', 'Сегодня вечером превратите комнату в игровую площадку. Постройте небольшую крепость из диванных подушек и заберитесь внутрь вместе. Будет немного беспорядка, но этот смех того стоит.'),
  ('a9e6d37d-aa66-4119-abcb-6619dfc78256', 'Проверка внимания 🧩', 'Малыш уже может играть с одной игрушкой 10-15 минут? Значит, продолжительность концентрации внимания увеличивается.'),
  ('1a9b02d2-5d73-4e72-a7df-f4672edf0835', 'Вечерний ритуал с папой 👨‍🍼', 'Сегодня вечером поручите папе подготовить малыша ко сну, почистить ему зубы и надеть пижаму, а сами спокойно выпейте чашку чая.'),
  ('6c74968c-8cc0-4bee-8ae3-eae708b5b244', 'Что приготовить? 🍲', 'Совсем не знаете, что приготовить сегодня? Не тратьте время на бесконечные поиски в интернете — найдите новые и простые рецепты в статьях о детском питании в разделе «Блоги» приложения.'),
  ('855cedcf-292a-4a61-b049-6fd355b3a599', 'Изучение причин и следствий 🤔', '«Что будет, если это бросить?», «Для чего эта кнопка?» Малыш постоянно ставит физические эксперименты. Ещё раз проверьте безопасность дома.'),
  ('3e22553e-b182-4faa-9fc2-459fc9a92590', 'Сильные истерики 🛑', 'Вас смущают истерики малыша в магазине или парке? Помните: важно не то, что подумают окружающие, а эмоции, которые ребёнок испытывает в этот момент. Установите зрительный контакт и помогите ему успокоиться.'),
  ('e37f9999-21b9-4b48-be42-d9cbbc3d9c55', 'Попытки прыгать 🤸‍♂️', 'Малыш пытается спрыгнуть с дивана на пол или подпрыгнуть на месте? Крупная моторика совершенствуется! Подбадривайте его.'),
  ('ebbeae36-6d1a-428b-bb72-2ef8bd324080', 'Полный анализ режима ⏱️', 'Вечером малышу понадобилось 40 минут, чтобы заснуть? Посмотрите график таймера сна. Возможно, уже пора значительно сократить дневной сон и укладывать малыша вечером раньше.'),
  ('1240eee6-bdc5-4609-ba23-b9d212dcb809', 'Исследование природы ⛅', 'В четырёх стенах становится тесно. Откройте инструмент прогноза погоды и подбора одежды, оденьте малыша по погоде и сразу отправляйтесь в парк. Пусть он исследует листья и камешки.'),
  ('1e908b82-2f19-4ebe-b79e-40246a88bab7', 'Насладитесь тишиной 🤫', 'Малыш наконец уснул. Теперь даже малейший звук в доме раздражает вас. Наденьте наушники, ничего не включайте и просто насладитесь тишиной.'),
  ('488aec04-c9ee-4eb7-9fb1-11c9a4093d08', 'Знакомство с цветами 🎨', 'Когда вы просите показать красный мяч, малыш указывает именно на красный? Он уже начинает различать цвета. Отметьте этот новый этап восприятия в трекере развития.'),
  ('3be3de73-5fca-4eff-b43e-5882d476d692', '«Я уже наелся» 🥣', 'Съедает две ложки, говорит, что наелся, и убегает? Не заставляйте его есть. Попробуйте предлагать небольшие порции, но чаще.'),
  ('9e9231eb-622b-4591-8fb2-b2c0bedcc252', 'Знакомство с частями тела 👀', 'Когда вы спрашиваете: «Где у тебя плечи?», малыш касается их пальцем и показывает? Познавательные способности сейчас активно развиваются! Продолжайте игру с более сложными названиями частей тела.'),
  ('1fe350a6-fb9b-4b57-8832-dec2f74e4b97', 'Беговой марафон 🏃‍♂️', 'Ходить ему уже скучно — теперь он только бегает! Уберите мелкие препятствия в центре комнаты и с улыбкой наблюдайте за этой неиссякаемой энергией.'),
  ('a661f7cf-1a9f-46de-b66d-252b9874aa1c', 'Игры в темноте 🐰', 'Не хочет засыпать и боится темноты? Полностью затемните комнату и устройте на стене театр теней с помощью рук. Превратите страх в весёлую игру.'),
  ('a8a8e76c-4244-41ff-a34c-127f03070b5f', 'Офлайн-час для мамы ☕', 'Когда малыш погружён в свой мир и разговаривает с куклами, не спешите сразу к посудомоечной машине. Налейте себе кофе, отложите телефон и побудьте полностью офлайн 15 минут.'),
  ('41bea9aa-47ca-48e8-8cd4-15b1a0a181a6', 'Первые длинные предложения 🗣️', 'Мама, машина поехала туда! Малыш уже соединяет слова и строит осмысленные предложения. Прислушивайтесь к этим историческим моментам и обязательно сохраняйте их на память в трекере развития.'),
  ('69b61ce4-2f0a-419f-8ea0-47c763ae7f20', 'Время заглянуть в блог 📱', 'Пора ли начинать приучение к горшку? Если вы сомневаетесь, откройте раздел блогов в приложении Anacan и прочитайте одобренные педиатрами статьи, написанные специалистами.'),
  ('8ba7811e-fc92-4ddc-b1e8-28de83aa7843', 'Анализ дня 📝', 'День был трудным? Выплесните эмоции, записав весь сегодняшний стресс в дневнике настроения. Все мамы переживают такие тяжёлые кризисы — вы не одиноки.'),
  ('3932254a-4956-424d-86dc-117f82815e3f', 'Отказ от воды 💧', 'Постоянно просит сладкие соки вместо воды? Рассчитайте суточную потребность малыша в воде и предлагайте её в ярких, интересных стаканчиках.'),
  ('7f344552-48d5-4a0e-95d3-b9aa7199f33a', 'Выдуманные истории 🎭', 'Малыш озвучивает игрушечного мишку и рассказывает ему выдуманные истории? Воображение разыгралось вовсю! Наблюдайте со стороны и не вмешивайтесь.'),
  ('eda9b33e-46f7-44ed-b1db-b9ad146b53a3', 'Без сказки не уснём 🪄', 'Классические сказки больше не привлекают его внимания? Создайте в умных сказках особенную историю, главным героем которой станет сам малыш.'),
  ('67860791-a8d9-49e2-af36-c3429ea56929', 'Беспорядок — это нормально 🌪️', 'Устали каждый день складывать одни и те же игрушки в коробку? Сегодня не убирайте! Беспорядок в доме — не конец света, ваше душевное спокойствие важнее.'),
  ('a0432486-9631-45f3-ac61-64c5dc937b54', '10 минут наедине с собой 🛀', 'В комнате воцарилась тишина. Попросите партнёра взять на себя все домашние дела. А сами примите тёплый душ и побудьте наедине с собой 10 минут.'),
  ('fc396394-677d-4b99-a945-20af7aec5056', 'Кальций — это не только молоко 🧀', 'Малыш отказывается пить молоко? Кальций необходим для костей. С помощью инструмента контроля питания подсчитайте, сколько сыра, йогурта или брокколи он съел сегодня, и восполните недостаток.'),
  ('40c67b1f-86cb-4258-ae34-ac9f630e9bcd', 'Клуб взаимной поддержки 💬', 'Вы очень устали и чувствуете, что никто вас не понимает? Напишите прямо сейчас в Сообщество Anacan. Там вас поддержат тысячи мам, которые тоже страдают от недосыпа.'),
  ('5fa2d1b1-040b-4c74-81f7-5aaa581e81fc', 'Нелогичное упрямство 🛑', 'Сегодня утром малыш устроил бурю из-за того, что вы налили воду не в красный, а в синий стакан? Это не каприз — он просто проверяет, может ли управлять окружающим миром. Будьте терпеливы.'),
  ('6555b02b-e564-49b7-b5ae-a0b3594560b0', 'Кладезь витаминов 🥗', 'Вы делаете всё, чтобы малыш был сыт. А как же вы сами? Выберите среди полезных рецептов богатый железом и кальцием обед, который готовится за 10 минут, и восстановите силы.'),
  ('74e20827-e129-489b-a3ba-b3145efc42b3', 'Перед зеркалом 👀', 'Малыш стоит перед зеркалом, строит разные гримасы и смеётся сам с собой? Он прекрасно осознаёт себя как отдельную личность. Понаблюдайте за ним незаметно и насладитесь этими забавными моментами.'),
  ('dfbc5f7d-d4f2-4480-8272-664e257700f7', 'Битва из-за пижамы 👕', 'Каждый вечер переодевание превращается в настоящую битву? Предоставьте малышу выбор: «Ты хочешь белую пижаму или синюю?» Этот приём часто срабатывает.'),
  ('437d195c-2ce7-46eb-a38c-e5ab8476f991', 'Чужая игрушка 🧸', 'Ваш малыш не даёт свою игрушку ребёнку, пришедшему в гости? Это не эгоизм, а защита личных границ. Учите делиться не принуждением, а собственным примером.'),
  ('49a7a4ab-0bbe-4e7b-ab8f-16aac2b2f875', 'Произношение слов 🗣️', 'Малыш произносит некоторые слова не полностью или очень забавно? Не смейтесь, а просто повторите слово правильно и с верным ударением, чтобы его мозг запомнил нужный вариант.'),
  ('d03e0dcf-56bb-436b-bb3e-19d3231b91eb', 'Подозрение на ночной страх 😭', 'Малыш среди ночи плачет с закрытыми глазами и не успокаивается? Сразу дайте функции «Анализ плача» послушать этот звук. Иногда причина не просто в газах, а в ночном страхе.'),
  ('42301ed7-ed5e-4c5a-a79b-59b5256decae', 'Утренние капризы ☁️', 'Едва открыв глаза, малыш плачет по любому поводу и всем недоволен? Возможно, он как раз переживает скачок роста. Просто чаще обнимайте его и дайте почувствовать себя в безопасности.'),
  ('4611486b-3235-40ef-8f07-a9ac44bd4de8', 'Разрешите испачкаться 🏖️', 'Малыш хочет играть в парке с грязью или песком? Разрешите ему испачкаться! Лучшие места для таких занятий, поддерживающих сенсорное развитие, ищите в приложении в разделе «Места для мам».'),
  ('b8751eb5-8b11-4040-9350-f54539cfefa1', 'Командный дух 🥂', 'Вы пережили ещё один непростой день. Когда малыш уснёт, налейте себе и партнёру по чашке чая и поддержите друг друга словами: «Мы действительно отлично справляемся».'),
  ('dc029c20-8f5d-4aa9-a173-be7d3be13a69', 'Как вы себя чувствуете? 🩸', 'У вас внезапно упал уровень энергии или резко меняется настроение? Загляните в «Трекер менструации» в приложении. Отслеживайте цикл, чтобы лучше понимать потребности своего организма.'),
  ('df6798e4-19ad-45ba-b5f8-d0bab8fc0951', 'Придуманные сказки 📖', 'Устали читать книги? Выключите свет, включите звук дождя в разделе «Белый шум» и вместе придумывайте в темноте сказки, пока не уснёте.'),
  ('ebf1eb36-04dc-42ad-9b92-cfc852cf267d', 'Фруктовые открытия 🍏', 'Малыш отказывается от белковой пищи или овощей? Рассчитайте сегодняшнюю норму с помощью инструмента контроля питания и создавайте вкусные сочетания, например фруктовый йогурт, используя рецепты для малышей.'),
  ('14a13bdc-ca07-4dfa-9231-806da316a5bd', 'Считаем на пальцах 🔢', 'Малыш пытается говорить «один, два, три», поднимаясь по лестнице или расставляя машинки? Так закладываются основы математического мышления. Считайте всё вместе с ним вслух.'),
  ('8bf6a243-dbba-488e-976d-ab76ac22fdef', 'Глубокий вдох 🧘‍♀️', 'За целый день ответов на вопросы у вас пересохло в горле. Как только в комнате воцарится тишина, отложите все экраны и отдохните, просто делая глубокие вдохи и выдохи.'),
  ('c86b2cf3-2c86-4802-abd7-eac1fbe8e326', 'Горячий чай и тишина 🍵', 'Таймер остановился, малыш уснул. Не спешите заниматься домашними делами! Заварите чай с мелиссой или ромашкой по одному из полезных рецептов, прилягте на диван и просто насладитесь тишиной.'),
  ('37bdad79-de07-4752-a75a-2761546b1523', 'Делиться непросто 🧸', 'Малыш грубо ведёт себя с братом или другим ребёнком в парке? Умение делиться для него пока остаётся абстрактным понятием. Не наказывайте его, а покажите, что понимаете его чувства.'),
  ('966fb5ae-0b22-47d8-b524-7d0d8e3e8e61', 'Воображаемое чаепитие 🍵', 'Малыш приглашает вас в свои воображаемые игры и просит выпить чай из пустой чашки? Станьте частью его фантазии. Такие игры развивают его социальный интеллект.'),
  ('cab52685-d8da-4cce-a78e-b76068863ea1', 'Папина сказка 📖', 'Сегодня вечером дайте своим голосовым связкам отдохнуть. Пусть папа возьмёт на себя задачу забавно прочитать любимые книги малыша, меняя интонации и голоса.'),
  ('380a71ea-f755-4ca8-a25d-c156eefcd118', 'Не плакать при падении 🧗‍♂️', 'Слегка упав, малыш не сразу плачет, а смотрит на вашу реакцию и только потом решает, как реагировать? Не паникуйте: улыбнитесь и скажите, что ничего страшного не произошло и он сильный.'),
  ('77a38e1b-ddf2-4519-806e-48198f93ac3a', 'Боится темноты?  🌙', 'Поставьте рядом с кроватью небольшой ночник тёплого цвета. Остальную комнату оставьте полностью тёмной, чтобы не мешать выработке мелатонина.'),
  ('b3b925ae-8f35-4c41-918e-ce24c80daa1b', 'Вражда с овощами 🥦', 'Малыш откладывает в сторону все овощи из супа? Поищите в плане питания другие варианты. Спрятать овощи в котлетах — старейшая мамина хитрость.'),
  ('16c277b4-79fe-460a-b9a5-72a7e8683280', 'Идеальных мам не бывает 💬', 'Вам кажется, что вы плохая мама, потому что не успеваете делать всё одновременно? Скорее присоединяйтесь к Сообществу Anacan. Искренние признания других мам придадут вам сил.'),
  ('2e1e3e82-a2d5-4c25-a5ab-d3b0a7f4df86', 'Увлечение каракулями 🖍️', 'Малыш начинает иначе держать карандаш и осознанно рисует линии на бумаге. Обязательно отметьте этот замечательный прогресс мелкой моторики в трекере развития.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ru = v.t, body_ru = v.b
FROM (VALUES
  ('72b641f0-637f-48cd-8a37-fcd8fc3414bf'::uuid, 'Кофейная подзарядка ☕', 'Дневная суета лишила вас сил. Займите малыша на 15 минут безопасным делом (например, раскрашиванием) и обязательно устройте себе кофейную подзарядку.'),
  ('35817a20-39d6-4243-8610-08e856df9e52', 'Точные броски ⚾', 'Малыш уже пытается поймать руками большой мяч, который вы ему бросаете, и даже кинуть его обратно? Зрительно-моторная координация стремительно развивается. Поиграйте вместе в мяч в коридоре.'),
  ('801c2145-44f5-4f5c-b680-cdaa0cf58a86', 'Музыкальный переход 🛀', 'Вечерний ритуал стал сложнее? Включите на фоне спокойную классическую музыку во время тёплой ванны. Гармония воды и музыки успокоит даже самого упрямого малыша.'),
  ('e1b2a066-88e9-4a4f-9df5-3af6a5d26b79', 'Отказ от дневного сна 🥱', 'Малыш снова не уснул? Не боритесь со сном, утомляя и его, и себя. Даже тихое рассматривание книги в комнате — это один из видов отдыха для мозга.'),
  ('17487e3f-403d-4b65-ab45-c514d335d8cb', 'Выражение чувств 📝', 'Сегодня вы безумно устали или малыш сказал что-то очень милое? В любом случае откройте дневник настроения и сохраните этот момент для будущего.'),
  ('343623a3-2f2a-4afd-99aa-b377f0610f4c', 'Битва за чистку зубов 🦷', 'Малыш не позволяет поднести щётку ко рту? Превратите обязанность в игру. Позвольте ему почистить ваши зубы, а затем поменяйтесь ролями.'),
  ('7022b1d9-81c4-428f-be96-d38885bd2971', 'Самостоятельная игра 🧸', 'Вы не обязаны развлекать малыша каждую минуту. Скука пробуждает в детях творческое начало. Позвольте ему самостоятельно исследовать что-нибудь в комнате.'),
  ('561010fd-17de-4698-b582-1c91bc73389a', 'Просто обнимите 🫂', 'Не нужны ни специальные приспособления, ни книги, ни сказки. Сегодня вечером просто прижмите малыша к груди, вдохните его запах и в темноте прошепчите ему о своей любви.'),
  ('927b3990-20b2-4f48-94c1-3ea0663bfcd4', 'Твёрдое «нет» 🛑', 'Малыш отстраняется и говорит «нет», когда кто-то хочет его поцеловать? Уважайте его телесные границы и требуйте того же от окружающих. Именно с этого начинается уверенность в себе.'),
  ('f73f1d7d-92d7-412b-a0e4-c0f949786729', 'Загляните в блоги 📱', 'Не справляетесь с истериками двухлетнего малыша? Почитайте психологические блоги в приложении Anacan. Понимание того, что происходит в мозге ребёнка во время кризиса, поможет вам справиться с ситуацией.'),
  ('7281bfed-2cc1-421c-942f-77684085a8cf', 'Время умной сказки 🪄', 'Сегодня вечером создайте для малыша в разделе умных сказок особое приключение: историю о бесстрашном храбром кролике. Помогайте справляться со страхами с помощью сказок.'),
  ('e96ff0af-1a62-4cbe-8543-0ed5c9498c20', 'Хаос дома 🌪️', 'Комната, которую вы убираете каждый день, снова превращается в беспорядок за 5 минут? Не переживайте! Дом — не музей, а место, где кипит жизнь. Сосредоточьтесь не на беспорядке, а на радости вашего ребёнка.'),
  ('fa5b66d9-39b4-43f8-b655-5b6b176b299f', 'Пробуждение страхов 👻', 'Раньше ребёнок совсем не боялся шумного пылесоса, а теперь прячется за вами? По мере развития воображения могут появляться необоснованные страхи. Приласкайте его и помогите почувствовать себя в безопасности.'),
  ('7b50e55a-c023-4d17-aacb-ffa1852fdee2', 'Сонные глазки 🥱', 'Даже если ребёнок хочет спать, он ни за что не желает идти в кровать. Сегодня немного измените вечерний ритуал. Вместо чтения книги прилягте рядом и напомните ему о приятных событиях этого дня.'),
  ('a4e24e0d-5f22-40d2-b64c-109e7cec356e', 'Всплеск энергии ⛅', 'Ребёнок дома буквально лезет на стены? Ему обязательно нужно выплеснуть энергию. Учитывая погоду, оденьте его подходящим образом, сходите в парк и позвольте побегать, пока он не устанет.'),
  ('a628c2a6-552d-4e1a-a37b-9ed947ed297d', 'Копирует ваш голос 🗣️', 'Поучает игрушки, в точности повторяя ваш тон и ваши фразы? Ребёнок — ваше лучшее зеркало. Увидеть себя со стороны будет забавно.'),
  ('a5f509e7-b242-4ca9-b7c5-aa083ba7699a', 'Скачок роста и веса! 📏', 'Вы заметили, что рубашки стали тесными или обувь начала жать? Внесите текущие показатели роста и веса в Трекер развития и с гордостью наблюдайте, как поднимается кривая развития.'),
  ('a9ef3c95-4b55-4dd2-abe5-e4a54e6509df', 'Когда мама устала 🛑', 'Вы не робот. Если сегодня у вас нет сил готовить, закажите еду. Быть идеальной мамой — не значит делать всё в одиночку.'),
  ('ce9a0c9c-c1ca-4fbc-ad47-53a33a6c199f', 'Тост за победу 🥂', 'Вы благополучно пережили трудный день, полный капризов и упрямства. Сядьте напротив партнёра и чокнитесь чашками чая. Вы справляетесь с этой огромной ответственностью.'),
  ('7cad0a21-48df-4f84-89c3-bca4ef4e2b8a', 'Думаете, что ребёнок пьёт мало воды?💧', 'Купите ему яркие стаканчики разных форм и превратите питьё воды в весёлую привычку.'),
  ('d2d72f62-94bd-4b00-9bc2-090ee3d937fa', 'Разговоры шёпотом 🌙', 'Полностью выключите свет в комнате. Прилягте рядом и очень тихо, шёпотом расскажите ему о событиях дня. Шёпот — один из лучших способов подготовить мозг ко сну.'),
  ('df67b2d6-67a7-45d0-8784-314cb9888630', 'Свобода выбора 👗', 'Ребёнок хочет сам выбирать одежду, но цвета совсем не сочетаются? Ничего страшного. Чтобы не подавлять его волю, просто предложите 2 варианта: этот или другой?'),
  ('308209fb-08e0-4807-8fb4-5bc201b75466', 'Забавные звуки папы 🤡', 'Самый быстрый способ рассмешить малыша — забавные звуки и гримасы папы. Сегодня вечером послушайте его звонкий смех и тоже улыбнитесь.'),
  ('591ee14c-695d-499c-8f9b-1192b3fd9c23', 'Время поделиться переживаниями 💬', 'Сегодня ребёнок плакал по любому поводу, и вы выбились из сил. Сразу зайдите в Сообщество Anacan и напишите: Сегодня было очень тяжело. Вы увидите, что сотни женщин сейчас переживают то же самое.'),
  ('7b870bcd-23ba-4647-a5da-35a4bde7db6f', 'Мастер конструктора 🧱', 'Ребёнок соединяет крупные детали лего и пытается что-то построить? Так он открывает для себя геометрию. Добавьте эти первые инженерные эксперименты в Трекер развития.'),
  ('3cc5c04e-9600-46b6-86d4-dfe7f6d1b82d', 'Повторение слов 🗣️', 'Ребёнок тут же повторяет за вами каждое новое слово, словно попугай? Его словарный запас растёт. Обращайте особое внимание на слова и эмоции, которые вы выражаете в его присутствии.'),
  ('b4771ddf-ae8c-44a0-b4dd-2f61938d3c93', 'Мелодия ночи 🛀', 'После целого дня в движении и ребёнок, и вы выбились из сил. Тёплая ванна и лёгкая, нежная мелодия на фоне помогут его нервной системе полностью успокоиться.'),
  ('0f4c51cd-27d9-4064-9aec-69b37d8e0a6f', 'Утренний танец 🎶', 'Малыш полон энергии, как только откроет глаза? Чтобы смягчить утренний хаос, включите весёлую детскую песенку и несколько минут потанцуйте вместе по комнате — начните день с улыбки.'),
  ('3f35178a-8193-420a-abc5-0ec312dd4ef0', 'Список необходимого 🛒', 'Закончились подгузники, шампунь или фруктовое пюре? Не держите всё в голове: сразу добавляйте нужное в список покупок и синхронизируйте его с партнёром одним нажатием.'),
  ('4ec6bcf9-c49a-4e82-9a6f-0ae618212221', 'Глубокая тишина 🤫', 'Первые полчаса после засыпания — самое чуткое время. Проверьте уровень шума в децибелах с помощью шумомера, убавьте громкость телевизора и насладитесь глубокой тишиной, воцарившейся дома.'),
  ('79665648-b787-4a1e-b120-da8384605658', 'Секрет железа: витамин C 🍋', 'Малыш выглядит бледным или у него нет аппетита? Проверьте сегодняшнее потребление железа в трекере питания и обязательно подавайте к мясу салат с большим количеством лимонного сока, чтобы улучшить усвоение железа.'),
  ('a55553fe-9a49-45fa-b5bb-ccf86cdd6fc8', 'Ночные пробуждения 🌌', 'Малыш просыпается среди ночи с плачем и не успокаивается? Загляните в раздел «Блоги», чтобы узнать, чем ночной ужас отличается от кошмара и как правильно помочь малышу психологически.'),
  ('f582b213-b9d3-463a-9b65-bba1181ecabf', 'Искусство рисовать круги! 🎨', 'Малыш пытается рисовать карандашом замкнутые круги на бумаге (или на стене!)? Это впечатляющий скачок в развитии моторики.'),
  ('41c18ba7-5f94-4cf4-bbb5-a65eaf5e3cf9', 'Зелёный детокс 🌿', 'Чувствуете вздутие? Проверьте свой цикл в Трекере менструации и восстановите энергию с помощью зелёного смузи из раздела полезных рецептов для женщин.'),
  ('99409d74-b463-47c8-b5a8-30d9e195253d', 'Питьевой режим и запор 💩', 'Малыш много бегает, но мало пьёт? Следите за стулом при смене подгузника (или на горшке). Если есть риск запора, добавьте в меню овсянку.'),
  ('ee2ef852-cac1-4c22-a029-d59cd40dbe5f', 'Охота на монстров! 👾', 'Малыш ищет монстра под кроватью? В этом возрасте усиливаются страхи, вызванные воображением. Включите звук вентилятора в разделе «Белые шумы», чтобы создать в комнате спокойную, безопасную и монотонную звуковую обстановку.'),
  ('3389c70e-b510-475b-87c1-4f01743277cd', 'План побега из кроватки 🛌', 'Малыш пытается выбраться из своей кроватки? Возможно, приближается время перехода на детскую кровать. Ещё раз проверьте безопасность комнаты с высоты малыша.'),
  ('92afc025-d2fe-4c60-9ebd-9366e19b0175', 'Перерыв для мамы ☕', 'Когда малыш играет самостоятельно, не спешите сразу заниматься домашними делами. Беспорядок никуда не убежит, а вот ваши силы могут закончиться. Присядьте и выпейте горячий кофе.'),
  ('c522fcae-04de-4086-b6e1-764904ead448', 'Пик возраста «Почему?» 🤔', '«Почему это там?», «Почему я сплю?»... Его мозг словно губка! Давайте на эти бесконечные вопросы короткие, но логичные ответы. Малыш познаёт мир через ваши слова.'),
  ('3a442f56-c411-4f3c-a16a-32453afe5f33', 'Общение в парке 🌳', 'Малыш чаще играет рядом с другими детьми, чем вместе с ними? Параллельная игра совершенно естественна для этого возраста. Учитывая погоду и подходящую одежду, старайтесь чаще гулять там, где он сможет находиться среди сверстников.'),
  ('5d66b2e6-45ec-4c26-ae59-9d0d0eba4b4d', 'Воображаемые друзья 🧸', 'Малыш рассказывает сказку плюшевому мишке или пьёт чай из пустой чашки? Символические игры — настоящий шедевр развития. С гордостью отметьте этот когнитивный скачок в трекере развития.'),
  ('d4544a8c-8615-4a88-b7e6-c7dc2d3b805a', 'Потребность в тишине 🤫', 'Первые полчаса после засыпания — самое чуткое время. Проверьте уровень шума в децибелах с помощью шумомера и отрегулируйте громкость телевизора в соседней комнате.'),
  ('32813c49-da9b-4dca-8d61-b20de94b9fae', 'Хочет, чтобы всё принадлежало ему? 🛑', 'Понятие совместного использования вещей ещё не сформировалось. Не заставляйте малыша делиться, а вместо этого постепенно вводите правило «Давайте играть по очереди».'),
  ('fb38f47e-3f88-41bf-87e7-fb7f9b1c8e65', 'Кризисный момент 🛒', 'Малыш кричит, потому что вы не купили ему понравившуюся игрушку в магазине. Не обращайте внимания на взгляды окружающих «идеальных» родителей. Спокойно установите зрительный контакт и всё объясните.'),
  ('3a862b3f-38a2-4cda-8a77-17c531d3e5f5', 'Домашние дела подождут 🛑', 'Пол не вымыт, бельё не сложено? Пусть подождёт. Беспорядок в доме можно устранить, а психологически истощённой маме потребуется гораздо больше времени на восстановление. Прилягте на диван.'),
  ('52c32776-811a-4d66-a0c4-6b1c34cdfc69', 'Примите бессонные ночи 😭', 'Малыш проснулся посреди ночи и не хочет спать. Не сердитесь на него. Дайте функции «Анализ плача» прослушать его голос, чтобы определить причину (боль, газы, страх), и терпеливо обнимите малыша.'),
  ('bc7db5e2-0eb7-4adc-85cd-1181aac8b268', 'В поисках новых друзей 👫', 'Малыш пытается бегать со сверстниками в парке и подходить к ним? Социализация официально началась! Наблюдайте за этим с гордостью на расстоянии, оставаясь рядом для подстраховки.'),
  ('100554ba-e336-4148-9dd0-9a0ceeecb04b', 'Учитесь по блогам 📱', 'Вас утомляет то, что ребёнок на всё отвечает «нет»? Это классический признак кризиса 2 лет. Читайте психологические блоги в приложении, чтобы понять, что происходит в его голове.'),
  ('19cce24b-ae51-482e-8dc7-6812a220483b', 'Не вините себя 📝', 'Сегодня вам не хватило терпения и вы повысили голос? Когда ребёнок уснёт, запишите свои чувства в Дневник настроения и простите себя. Вы просто устали, вы живой человек.'),
  ('1bc0b4db-b3a8-4a70-bfa5-eaa18f5fe1f5', 'Самостоятельно по лестнице 🧗‍♂️', 'Малыш стремится подниматься по лестнице, держась за вашу руку, или даже пытается делать это самостоятельно? Он проверяет возможности своего тела. Обязательно предоставьте ему эту свободу, оставаясь рядом для подстраховки.'),
  ('380af2db-ede8-491b-ab1a-6f695da10f42', 'Страх разлуки 🥺', 'Даже когда вы идёте в туалет, малыш ждёт вас за дверью и плачет. Тревога разлуки иногда усиливается. Каждый раз отзывайтесь и говорите ему, что вы рядом и обязательно вернётесь.'),
  ('805c93f2-e2d3-43ec-9e6f-4782049680cd', 'Темнота в комнате 🌙', 'Чтобы малыш быстрее уснул, выключите в комнате все дополнительные источники света, особенно экраны планшетов. Мелатонин вырабатывается только в темноте.'),
  ('ba544f24-4325-4cce-9fad-539f5e144287', 'Капризы за столом 🥣', 'Малыш съел две ложки и говорит, что наелся? Не заставляйте его. Здоровые отношения с едой важнее кормления через силу. Предлагайте еду чаще, но уменьшите порции.'),
  ('0b8f75a4-5ddd-4527-a07d-f3a8b79df578', 'Радостные аплодисменты 👏', 'Когда у малыша что-то получается (например, построить башню), он сам себе аплодирует и гордится? Ему нужно одобрение! Вместе с ним бурно порадуйтесь этому маленькому достижению.'),
  ('2ac10424-b1ee-4b11-b087-e5d8e74e2722', 'Час тишины ☕', 'Если малыш не спит днём, установите хотя бы 1 час тишины (quiet time). Пусть он листает книги в своей кровати, а вы тем временем выпейте чай и посмотрите телефон.'),
  ('2eea19a8-6377-4aff-9f02-8b899ec1a730', 'Время для пары 🥂', 'Ребёнок уснул. Теперь отложите телефоны и домашние дела. Хотя бы 20 минут поговорите с партнёром на любую тему, кроме ребёнка. Ведь вы ещё и пара.'),
  ('2102feb2-22f3-4c41-8de6-6f3e115e2d56', 'Концовка сказки 🪄', 'Классические сказки утомляют. В «Умных сказках» на этот раз предложите ребёнку самому выбрать концовку истории. Спросите: «Как ты думаешь, кто помог медвежонку?» — и дайте волю его воображению.'),
  ('8df55e5c-cbbb-49b9-bd1a-b655d228f1d5', 'Проверка границ ⚠️', 'Вы просите малыша не делать этого, а он смотрит вам прямо в глаза и всё равно продолжает? Он не пытается вас разозлить, а проверяет, насколько устойчивы установленные вами границы. Будьте последовательны.'),
  ('aa89536f-3d4b-4a1e-9088-0384b755894e', 'Реакция на картинки 📖', 'Увидев в книге животных или детей, малыш прикасается к изображениям и издаёт звуки? Его зрительное восприятие развивается удивительно. Отметьте эту деталь в Трекере развития.'),
  ('493d7552-4aa4-42f1-ab76-65529b782f6d', 'Маленький инженер 🏗️', 'Обожает строить и разрушать башни? Откройте раздел «Рекомендуемые товары» и найдите магнитные или деревянные блоки, которые помогут ещё лучше развить интеллект и моторику малыша.'),
  ('96969038-76a5-48c3-b60c-aafe8839c46c', 'Сделайте глубокий вдох 🌬️', 'Сегодня вы выбились из сил, бегая за малышом? Откройте Дневник настроения и напишите о своей усталости. Не стремитесь быть идеальной мамой — ваши чувства тоже важны!'),
  ('3cbc904d-0d48-46fa-a264-4d48559d6b46', 'День был тяжёлым?', 'Расскажите о сегодняшнем стрессе в Дневнике настроения, чтобы облегчить душу. Все мамы сталкиваются с такими кризисами — вы не одиноки.'),
  ('aabf621d-766b-4fe7-b19d-2316986fdc64', 'Пир для мамы 🥑', 'Вы делаете всё, чтобы накормить малыша. А как же вы? Выберите среди полезных рецептов богатый железом обед, который придаст вам сил, и спокойно поешьте.'),
  ('c60bf17d-5d16-4967-881d-d808bb5c5b6e', 'Фразы из двух слов 🗣️', '«Мама, иди», «Брось мяч» — словарный запас малыша растёт день ото дня. Поддерживайте развитие его речи, повторяя произнесённые им неполные слова правильно и чётко.'),
  ('274e44c7-f2f2-4e14-a2db-692e3ab50d92', 'Истерики в магазине 🛒', 'Малыш бросился на пол из-за того, что вы не купили желаемое? Не обращайте внимания на взгляды окружающих. Опуститесь до уровня его глаз и скажите, что понимаете его чувства.'),
  ('7ffa24e8-d5c5-47fa-bd56-46791566e3ed', 'Одежда наизнанку 👗', 'Малыш надевает обувь не на ту ногу, а футболку — наизнанку и ни за что не хочет переодеваться? Пусть остаётся так! Это самый безобидный способ заявить о своей индивидуальности.'),
  ('90cdd9aa-f5c9-402b-8ee4-af9073e319ae', 'Музыкальное умиротворение 🎶', 'Самый простой способ справиться с вечерними капризами — включить любимую мелодию малыша, обнять его и медленно потанцевать вместе.'),
  ('c19b60f5-cbba-4300-8903-9c5cb8625ba7', 'Гордитесь собой 🌟', 'Каждый новый навык, который малыш осваивает, и каждый его уверенный шаг — результат усилий, которые приложили вы и ваш партнёр.'),
  ('e47a41a7-8601-4ce3-8c27-0c69ab445dad', 'Декларация независимости 📜', 'На всё отвечает: «Я сам!» — и из-за этого дела затягиваются? Спросите Anacan AI, как направить это безграничное упрямство в русло развития.'),
  ('e4b29fb1-70d1-4a56-b112-96966513c6eb', 'Детали в книгах 📖', 'Малыш листает книгу и показывает пальцем на мельчайшие детали рисунка? Его зрительная память прекрасно работает. Обсуждайте с ним то, что изображено на картинках.'),
  ('14b9dba6-d0f2-4f3d-a4e8-f737b507b018', 'Мастер каракулей 🖍️', 'Стоит малышу взять в руки карандаш, как он начинает рисовать каракули на стенах или бумаге. Так с помощью красок развивается его мелкая моторика.'),
  ('48cc1013-ae1c-4b86-9e80-78bd05d5745a', 'Ночная тишина 🛀', 'Тёплая ванна, лёгкий массаж и тёмная комната. Старайтесь не нарушать ритуал отхода ко сну, ведь он даёт мозгу малыша сигнал, что наступило лучшее время для сна.'),
  ('a8d24ffb-d035-4c11-983e-8c2c2a9ad274', 'Разговоры мам по душам 💬', 'Вас изматывает мысль: «Почему мой ребёнок такой упрямый?» Присоединяйтесь к Сообществу Anacan, и вы увидите, что каждый ребёнок проходит через разные возрастные кризисы.'),
  ('5ae62f81-7331-472c-9b48-c967d0615a5b', 'Герой вечера: папа 🦸‍♂️', 'Сегодня вечером доверьте ритуал отхода ко сну своему партнёру с помощью функции «Партнёр». Пусть он прочитает сказку, а вы тем временем примите тёплую ванну и снимите накопившийся за день стресс.'),
  ('88d95f7d-2e98-41b0-8554-4115adfb31c5', 'Избирательность в еде 🥦', 'Сегодня малыш отказывается от блюда, которое вчера ел с аппетитом? Проанализируйте меню с помощью инструмента контроля питания и найдите необычные и весёлые варианты подачи в Рецептах для малышей.'),
  ('b1d18fda-3875-4aca-b436-4ecb52ef49a6', 'Дни без боли 🩸', 'Приближается менструация и уже начались спазмы? Прежде чем принимать лекарства, позаботьтесь о себе: приготовьте богатые магнием финиково-ореховые шарики по рецепту из раздела «Полезные рецепты для женщин».'),
  ('55fa43db-2800-421e-b0f2-748c40c7ef07', 'Одежда становится мала! 📏', 'Рукава рубашек снова стали короткими? Внесите текущие показатели в Трекер веса и взгляните на растущий график, чтобы наглядно увидеть скачок развития к 29-му месяцу.'),
  ('8a1a47bc-2d1d-4804-abb1-5b5294f326db', 'Книжный герой 📖', 'Малыш просит прочитать одну и ту же сказку в 100-й раз? Узнайте из Блогов, какую невероятную роль это кажущееся утомительным повторение играет в развитии интеллекта, и запаситесь терпением.'),
  ('c88c6893-fe11-4ce0-bf2d-ed7f94e0770d', 'Первые логические предположения 🤔', 'Малыш строит фразы вроде «Если я сделаю это, получится так»? Не упустите этот удивительный скачок в развитии мышления: запишите видео со звуком, добавьте его в Альбом малыша и гордитесь этим достижением.'),
  ('3469bb77-d2d2-406c-8c90-287cb3502fb6', 'Семейное совещание 🥂', 'Когда малыш уснёт, заварите чай вместе с партнёром, похвалите друг друга и скажите: «Мы отличная команда». Это поможет снять накопившееся за день напряжение.'),
  ('69a15994-f6a2-4e74-92d0-633dfea33b45', 'Новое место для мамы ☕', 'Вам надоело постоянно смотреть на одни и те же стены дома. Найдите среди Мест для мам кафе с детским игровым уголком. Пусть малыш играет, а вы наслаждайтесь кофе.'),
  ('71af31e1-67cd-4bc6-a54d-505d0d3ed0af', 'Звуки животных 🐶', 'При виде кошки малыш пытается сказать «мяу», а при виде собаки — «гав-гав»? Звуки животных отлично помогают развивать словарный запас. Поиграйте с малышом в эту игру.'),
  ('1fe665ee-e68e-4e2a-b81e-f697b1100d0d', 'Педиатр на связи 🤖', 'Каким должен быть размер порции ближе к 2.5 годам? Если сомневаетесь, сразу попросите Anacan AI составить точную, научно обоснованную таблицу.'),
  ('8139ee6f-daa0-4072-ad02-2be67ee8488d', 'Герой сказки 🪄', 'Сегодня вечером создайте в Умных сказках особенную историю, главным героем которой станет ваш малыш: отважный малыш, который любит чистить зубы.'),
  ('9d6f4449-54d1-4585-9f63-6d19afec1bda', 'Объятия «Я тебя люблю» 🫂', 'Малыш неожиданно подходит, обнимает вас за шею или гладит по лицу? Теперь он выражает свою любовь прикосновениями. Насладитесь ни с чем не сравнимым умиротворением этого момента.'),
  ('c32b736c-41b6-4e37-ad3d-7f15cea8084a', 'Протест против сна 🥱', 'Малыш не хочет ложиться спать днём и плачет? Не настаивайте. Вместо этого объявите 30-минутный Час тишины, во время которого он сможет спокойно полистать книги в комнате.'),
  ('c762e9b7-a5b4-4810-a642-39d1f9c28936', 'Смена караула 👨‍👧', 'За целый день ваш мозг устал отвечать на вопросы «Почему?». Сегодня вечером поручите партнёру надеть на малыша пижаму и уложить его спать, а сами отдохните.'),
  ('dc54ef63-6d88-4c2f-9c5d-c431db5caf8b', 'Необычная мода 👗', 'Малыш хочет надеть летние шорты посреди зимы, а брюки — на голову? Не мешайте ему экспериментировать. Эти забавные пробы помогают ему утверждать свою индивидуальность.'),
  ('37bfacdd-d6ce-4a16-96d7-85b70834ca41', 'Исследование тарелки 🥦', 'Сегодня малыш бросает на пол еду, которую любил ещё вчера? Откройте инструмент «План питания» и воспользуйтесь разнообразными и яркими идеями меню для 2.5 лет, подготовленными специалистами.'),
  ('6b5d8f34-e3e9-4e8b-8382-9b0f64e3f018', 'Неожиданные страхи 👻', 'Малыш начал бояться темноты в комнате или воображаемых теней? По мере развития воображения могут появляться необоснованные страхи. Поддержите малыша и дайте ему почувствовать, что вы рядом.'),
  ('b459387d-d414-446b-ac06-391ffb5af36c', 'Неиссякаемая батарейка 🔋', 'Вы ещё не успели открыть глаза, а малыш уже устроил марафон по ковру. Налейте себе большую чашку кофе — день будет очень активным.'),
  ('98be6947-c839-4cba-807a-2d0a7d2db4bd', 'Смешная гримаса папы 🤡', 'Самый быстрый способ рассмешить малыша — это странные звуки и гримасы папы. Сегодня вечером слушайте весёлый смех и тоже улыбайтесь неподалёку.'),
  ('9c1b9283-eb25-42f4-8927-c54192637c35', 'Утренняя энергия мамы ⚡', 'Проснулись утром уставшей? Не налегайте на сладкое. Найдите среди полезных рецептов овсянку с белком и фруктами, которую можно приготовить за 5 минут, и начните день с новыми силами.'),
  ('1868bb46-a550-4249-8524-2b40ecd9cad3', 'Нужна поддержка папы 🫂', 'Согласно Трекеру менструации, у вас дни ПМС и вы особенно чувствительны? С помощью функции для партнёра сообщите ему, что сегодня вам нужно немного больше поддержки.'),
  ('5efae0dc-5ddd-4ac1-9526-ddfa449ec612', 'Крепость из подушек 🏰', 'Сегодня вечером превратите комнату в игровую площадку. Постройте небольшую крепость из диванных подушек и заберитесь внутрь. Будет немного беспорядка, но весёлый смех определённо того стоит.'),
  ('e40e4ab0-cd42-4ed7-b968-edc0adab6461', 'Переговоры как у адвоката 🗣️', 'Говорит, что ещё немного поиграет, а потом оденется? Он уже пытается вести с вами профессиональные переговоры. Развитие речи идёт отлично, но не забывайте с любовью отстаивать свои границы.'),
  ('f9854a88-373e-4d4d-91e8-4e24a9ea9cba', 'Исследование природы 🌳', 'В четырёх стенах становится тесно. Даже если на улице прохладно, оденьте малыша потеплее и сходите в парк на 20 минут. Пусть исследует листья и камни — свежий воздух пойдёт на пользу вам обоим.'),
  ('fb90f3c3-fde8-496d-b59b-6ba1236abd46', 'Восторг «Я тебя нашёл!» 🙈', 'Прятки уже стали любимой игрой. Малыш прячется за занавеской и ждёт, когда вы его найдёте. Сделайте эту игру самой весёлой частью вашего распорядка дня.'),
  ('fce8d709-58cb-464d-bc50-7c2b9036555e', 'Привыкаем к темноте 🌙', 'Чтобы малыш быстрее заснул, выключите все экраны в комнате. Синий свет от телевизора замедляет выработку гормона сна.'),
  ('1dc3a9e4-8c1a-46c9-b53c-b30058a99bb3', 'Смелые восхождения 🧗‍♂️', 'Пытается взобраться повыше, держась за диван или кресло? Равновесие и мышечная сила развиваются. Страхуйте малыша, но не мешайте этим попыткам юного альпиниста.'),
  ('a7098097-ad7b-4ef2-ac70-151dc53814b4', 'Упрямство за столом 🥣', 'Съедает две ложки, говорит, что наелся, и убегает? Не заставляйте его. Здоровые отношения с едой важнее, чем кормление через силу.'),
  ('f8b30c93-8e49-4cb9-8db0-9b3082221d0d', 'Анализ дня 📝', 'Сегодня вы безумно устали или малыш сказал что-то очень милое? В любом случае откройте Дневник настроения, сохраните этот момент на память и излейте душу.'),
  ('18e35d56-8285-420a-adac-121643743cd2', 'Проверка внимания 🧩', 'Малыш уже может играть с одной игрушкой, например с пазлом, в течение 10-15 минут? Это означает, что он способен дольше удерживать внимание. Тихо постойте в стороне и понаблюдайте за ним.'),
  ('87548d0a-d1fb-4a91-8d0e-f51d5f31d60e', 'Исследуем причины и следствия 🤔', '«Что будет, если я это брошу?», «Для чего нужна эта кнопка?» Малыш постоянно экспериментирует с окружающими предметами. Ещё раз оцените безопасность дома с высоты его роста.'),
  ('f1a78ec7-6b62-43e2-8747-e4f8c033a5e7', 'Без сказки не уснём 🪄', 'Классические сказки уже не привлекают его внимание? Придумайте особенную историю, главным героем которой станет сам малыш, добавьте звуки природы и погрузитесь в мир его фантазий.'),
  ('becd06f2-3767-4d60-98af-e6ee50a40e21', 'Танцы под музыку 🎶', 'Малыш сразу начинает двигаться в ритме, когда слышит весёлую музыку? Связь между слухом и моторикой развивается превосходно! Включите весёлую песню и потанцуйте вместе с ним в комнате.'),
  ('befcea5e-21fe-4c91-b025-35c7c94f17a1', 'Папина сказка 📖', 'Сегодня вечером дайте своим голосовым связкам отдохнуть. Пусть папа возьмёт на себя чтение любимых книг малыша — разными голосами и в забавной манере.'),
  ('5b291f89-d920-4ebd-a4e6-3d982c3f7c31', 'По следам художника 🖍️', 'Бумага закончилась, и теперь на очереди стены и двери? Мелкая моторика малыша развивается благодаря рисованию. Расстелите в комнате большой лист картона и объясните, что рисовать можно только здесь.'),
  ('a9576738-56a5-42cd-a95f-6e85e5fb1189', 'Нелогичное упрямство 🛑', 'Малыш устроил бурю из-за того, что вы налили воду не в синий, а в красный стакан? Это не каприз — он просто проверяет ваши границы и то, насколько способен управлять окружающим миром. Будьте терпеливы.'),
  ('e5ef4a95-198d-48b4-a37a-8ba378115031', 'Целительная сила воды 🛀', 'После целого дня в беготне вы оба выбились из сил. Тёплая ванна — это не просто гигиена, а один из лучших естественных способов успокоить перевозбуждённую нервную систему малыша.'),
  ('891847ab-5f43-4ba4-a99f-cf7faceb076c', 'Примиритесь с беспорядком 🌪️', 'Устали каждый день собирать одни и те же игрушки? Сегодня не собирайте! Беспорядок дома — не конец света, а ваше душевное спокойствие важнее всего.'),
  ('9de03e77-6cb6-4585-9646-e7347bac18d6', 'Заглушите чувство вины 💬', 'Вините себя за то, что сегодня малыш слишком долго сидел перед экраном? Зайдите в Сообщество Anacan, почитайте о том, что другие мамы тоже порой испытывают такие чувства, и успокойтесь. Вы не одни.'),
  ('f7d0d8f9-fd4d-4b19-b40e-907cdb2d4aea', 'Личность в зеркале 👀', 'Малыш строит перед зеркалом разные гримасы, разговаривает сам с собой и смеётся? Это прекрасный признак осознания себя как личности. Незаметно понаблюдайте за ним и с гордостью наслаждайтесь этими забавными моментами.'),
  ('765fd3c5-2a1b-4659-aa42-b76314ae48dc', 'Эгоизм в парке 🧸', 'Во время игры в песочнице малыш никому не отдаёт свою формочку? Это не эгоизм, а защита личных границ. Не заставляйте его делиться, а мягко научите правилу «Давайте играть по очереди».'),
  ('8329858a-b5aa-4e88-a094-94baf4b4dff4', 'Игры воображения 🧸', 'Малыш пытается напоить игрушечного мишку или куклу и разговаривает с ними? Символическая игра — настоящий шедевр развития. С интересом наблюдайте со стороны за этим милым режиссёром.'),
  ('fc8def68-9f4f-421f-a543-941a3d40a533', 'Новые слова 🧠', 'Сегодня малыш произнёс необычную сложную фразу, совсем как взрослый? Сразу откройте Трекер развития и сохраните этот когнитивный скачок как воспоминание, к которому сможете вернуться в будущем.'),
  ('115c548f-9326-4a38-a159-3195407d360e', 'Время для двоих 🥂', 'Ребёнок уснул. Теперь отложите домашние дела. Хотя бы 20 минут поговорите с партнёром о чём угодно, кроме ребёнка. Вы не только родители, но и пара.'),
  ('91f7fb7e-2bab-481e-816b-6e91267f93ae', 'Целенаправленное ползание 🐢', 'Малыш уже ходит, но иногда ради забавы быстро уползает от вас? Уберите из комнаты опасные препятствия и тоже присоединитесь к этой игре в догонялки.'),
  ('ca59c65d-2643-4f9a-b7e1-efbf69908275', 'Офлайн-час для мамы ☕', 'Когда малыш погружён в игру, не спешите сразу загружать посудомоечную машину. Налейте себе горячего чая, отложите телефон и проведите 15 минут офлайн, ни о чём не думая.'),
  ('53f1873b-90e8-4dcd-884c-7bbec73835df', 'Разговоры шёпотом 🌙', 'Полностью выключите свет в комнате. Лягте рядом с малышом и очень тихо, шёпотом расскажите о том, что произошло за день. Шёпот — один из самых успокаивающих способов подготовить мозг ко сну.'),
  ('67fb000b-9452-4ae5-aa28-3a36f345f54a', 'Дни без боли 🩸', 'Приближается менструация и уже начались спазмы? Прежде чем принимать лекарства, позаботьтесь о себе: приготовьте по рецепту из раздела «Полезные рецепты» богатый магнием перекус из фиников и орехов.'),
  ('f0ddb044-981f-4758-9737-12aa24392d50', 'Счёт на пальцах 🔢', 'Поднимаясь по лестнице или расставляя игрушки, малыш пытается говорить «один, два, три»? У него пробуждается математическое мышление. Вместе громко посчитайте предметы в комнате.'),
  ('841fa22f-136a-48a1-b594-4a69eafbc030', 'Восстановите силы 🍲', 'Постоянная беготня лишила вас сил. Вместо перекуса на ходу приготовьте себе особую сытную тарелку с продуктами, богатыми кальцием, и поешьте с удовольствием.'),
  ('d245b047-0d4a-45c3-956c-817469ecd147', '«Почему?» закончилось, «Как?» началось 🤔', 'Скачок воображения и логики! Теперь малыш спрашивает, как устроены разные вещи. Узнайте у нашего AI-эксперта Anacan, как отвечать на эти вопросы понятно, интересно и с учётом возраста ребёнка.'),
  ('0d9edca6-9e16-4f20-b482-5f21d8925331', 'Смиритесь с бессонными ночами 😭', 'Малыш проснулся среди ночи и не хочет спать. Не сердитесь на него. Постарайтесь выяснить причину (боль, газы, страх), терпеливо обнимите и дайте ему почувствовать себя в безопасности.'),
  ('6fbdbe3b-91f8-4e0a-9823-628cb1856a3a', 'Стойкие пятна 👗', 'Вас утомляет то, что одежда постоянно пачкается? Не раздражайтесь: малыш знакомится с едой. Используйте силиконовые нагрудники и наслаждайтесь этими яркими и неопрятными моментами.'),
  ('9f08baf7-46d6-4ac6-b651-94901e800f6b', 'Давай я помогу! 🧹', 'Малыш пытается забрать у вас швабру или тряпку, когда вы моете пол или вытираете пыль? Он уже чувствует себя взрослым. Дайте ему маленькую тряпочку и позвольте присоединиться к вашей команде.'),
  ('40197a85-31e6-4141-9d38-df9b89843274', 'Прислушивайтесь к своему телу 🩸', 'Внезапно нестерпимо хочется сладкого или появилась усталость? Загляните в календарь Трекера менструации. Если приближается менструация, выберите в разделе полезных рецептов перекус, богатый магнием.'),
  ('4ca62724-362e-47af-b9dc-e138d57c7cbd', 'Тени в комнате 🌌', 'Малыш боится темноты и воображаемых чудовищ? Не оставляйте комнату в полной темноте и включите в разделе «Белые шумы» звуки материнской утробы, чтобы подарить ему знакомое ощущение полной безопасности.'),
  ('f8e208a6-e2c2-4a88-b04c-adaeb10974b8', 'Тревога разлуки 🥺', 'Малыш плачет вслед за вами, когда вы выходите из комнаты или даже идёте в туалет? Он думает, что вы не вернётесь. Успокойте его словами: «Я всегда рядом, ты слышишь мой голос?»'),
  ('216f95a1-f03e-48c4-8e9d-615f08aa0853', 'Маленький болтун 🗣️', 'Малыш уже объединяет 4-5 слов и рассказывает забавные истории? У него настоящий лексический взрыв! Не упустите этот золотой момент.'),
  ('41e28dbe-e3fb-4744-b4f1-9927a3802b24', 'Приглушите посторонние звуки 🤫', 'Во время засыпания малыш особенно чувствителен к звукам. Чтобы заглушить шум с улицы, включите в комнате негромкий белый шум (white noise) или спокойную музыку.'),
  ('745737c8-7329-40d3-90c9-336ff2e4a2ae', 'Готовим вместе 🧑‍🍳', 'Малыш хочет помогать вам на кухне? Позвольте ему насыпать муку или налить воду. Даже если всё вокруг испачкается, его радость и желание учиться того стоят.'),
  ('1938c0bd-ea98-478e-8da7-ef024a27ce71', 'Список — не пожелание, а необходимость 🛒', 'Из-за недосыпа ухудшилась память, и в магазине вы забываете, что нужно купить? Не перегружайте себя. Записывайте всё в «Список покупок» в приложении.'),
  ('30a1934e-958b-40a0-9b32-c4894a70a798', 'Просто обнимите 🫂', 'Сегодня не нужны ни игры, ни книги. Просто прижмите малыша к груди, вдохните его запах и прошепчите в темноте, как сильно вы им дорожите.'),
  ('e00d8cce-8b3a-4ac6-ad35-5a22b01bd325', 'Мастер конструктора 🧱', 'Малыш соединяет крупные детали LEGO и пытается что-то построить? Он знакомится с пространством и геометрией. Отметьте эту особенную инженерную попытку в Трекере развития.'),
  ('1a4b3925-7885-40fb-a56f-488e3358cee1', '10 минут наедине с собой 🛀', 'В комнате воцарилась тишина. Попросите партнёра взять на себя все домашние дела, а сами примите тёплый душ и побудьте наедине с собой.'),
  ('505c8d78-0b81-4cb5-96f5-e5571e1fc049', 'Синдром 2 лет 📱', 'Вас утомляет, что ребёнок на всё отвечает «нет»? Прочитайте статьи в разделе «Блоги», чтобы понять причины этой бури развития, происходящей в его мозге.'),
  ('5e96bc6a-ca0b-4e3c-9cde-441c31566ab3', 'Операция «Спрятанные овощи» 🥦', 'Малыш выбрасывает из тарелки зелень или брокколи? Найдите среди рецептов для малышей красочный домашний кекс с овощами и легко отметьте норму витаминов в инструменте контроля питания.'),
  ('91db0bda-d980-4153-bb7d-0ed55ffcd626', 'Глубокий вдох 🧘‍♀️', 'Отвечая на вопросы весь день, вы наверняка почувствовали сухость в горле. Как только в комнате воцарится тишина, отложите все экраны и немного отдохните, просто делая глубокие вдохи и выдохи.'),
  ('de182c61-510f-445a-9f50-8ed2459f90cf', 'Произношение слов 🗣️', 'Малыш произносит некоторые слова не полностью или очень забавно? Не смейтесь, а повторите слово правильно и с верным ударением, чтобы его мозг запомнил правильный вариант.'),
  ('f4bf03e5-dc33-4bfa-a875-42962b014227', 'Самостоятельная игра 🧸', 'Вы не обязаны развлекать малыша каждую минуту. Скука для детей — начало творческого процесса. Позвольте ему самостоятельно исследовать что-нибудь в комнате.'),
  ('3ead07a7-4417-4744-9277-6bedf5fa245b', 'Мгновение, останавливающее время 📸', 'Когда малыш уснёт, посмотрите на его невинное личико. Даже если весь день он сводил вас с ума, как только он засыпает, вы уже скучаете по нему, правда? В этом и заключается парадокс материнства.'),
  ('5f09ad8f-0fde-4f65-8032-dfe56e435a81', 'Привычка пить воду 💧', 'Малыш постоянно просит сладкие соки вместо воды? Проверьте питьевой режим в плане питания. Предлагайте воду в ярких стаканчиках с необычными трубочками, чтобы заинтересовать его.'),
  ('e8fd5bc0-a904-4768-8c61-d9259b243761', 'Команда «Аплодисменты» 👏', 'Малыш хлопает себе, радуясь, когда у него что-то получается? Как только увидите этот чудесный момент, устройте дома небольшой победный танец и разделите его радость!'),
  ('2a429f3f-0b1b-49c6-befd-28bf5cd2cf98', 'Когда мама устала 🛑', 'Вы не робот. Если сегодня у вас нет сил готовить, закажите еду. Быть идеальной мамой — не значит делать всё самостоятельно.'),
  ('5c059ccd-12dd-4a31-9da6-6e33ef79b1be', 'Твёрдое «нет» 🛑', 'Малыш отстраняется и твёрдо говорит «нет», когда кто-то хочет его поцеловать? Уважайте его телесные границы. Очень важно, чтобы он умел возражать против прикосновений без разрешения.'),
  ('79a825c4-e46e-4e7d-81f2-4387a7318ef2', 'Делимся сокровенным 💬', 'Очень устали? Присоединяйтесь к Сообществу Anacan. Читайте реальные истории тысяч мам и черпайте силы в ощущении, что вы не одиноки.'),
  ('0048f15c-3ab2-4568-b3e6-cf763bd916d3', 'Спрячьте овощи 🥦', 'Малыш откладывает в сторону все овощи из супа? Не боритесь с ним. Измельчить овощи в пюре и спрятать их в соусе или котлетах — одна из самых старых маминых хитростей.'),
  ('4d0d3015-35d0-4444-b757-3789d14e8ec4', 'Реакция на картинки 📖', 'Увидев в книге животных или различные предметы, малыш трогает их и издаёт звуки? Его зрительное восприятие восхищает. Поговорите с ним о персонажах книги.'),
  ('cfe51929-b2af-45a2-b23e-e670a8d3ebd8', 'Погоня перед сном 🏃‍♂️', 'Малыш бесконечно придумывает отговорки, чтобы не ложиться спать? Запустите таймер сна, придерживайтесь установленных границ и включите звук дождя в разделе «Белый шум», чтобы создать в комнате спокойную атмосферу.'),
  ('0727c4e7-7433-410a-9da5-27fff69d9877', 'Питьевой режим и запор 💩', 'Малыш много бегает, но пьёт мало воды? Следите за его стулом в горшке или подгузнике. Если есть риск запора, отметьте это в приложении и сразу добавьте в меню овсянку или грушу с помощью инструмента контроля питания.'),
  ('5730e69b-8e67-40bb-94c5-56cb9dd41a75', 'В поисках новых друзей 👫', 'Малыш пытается бегать со сверстниками в парке и подходить к ним? Социализация официально началась! Наблюдайте за этими попытками с гордостью, оставаясь неподалёку для подстраховки.'),
  ('a11a0d3a-a9c4-402b-9b3c-bc6d874fc9a7', 'Ночная мелодия 🛀', 'После целого дня в движении и малыш, и вы выбились из сил. Тёплая ванна и тихая, нежная мелодия на фоне помогут полностью успокоить его нервную систему.'),
  ('100fc6ed-66a7-4e9e-939c-15af0683652e', 'Отказ от дневного сна 🥱', 'Малыш снова не уснул? Не боритесь с ним, утомляя и его, и себя. Тихая игра с игрушками в комнате — тоже один из видов отдыха для мозга.'),
  ('ca5c9545-5eb9-432c-acea-7e6fe2c5ab98', 'Тишина и кофе 🤫', 'Он уснул! Вместо того чтобы разгружать посудомоечную машину, посидите в полумраке комнаты. Насладитесь 15 минутами тишины и отдохните.'),
  ('cc9ba302-22d8-43e5-a70d-2bed916f8d33', 'Посмотрите вниз! 👣', 'Он уже хватается за пальцы ног и изучает их или даже любит ходить босиком? Исследование нервных окончаний на стопах очень важно для развития чувства равновесия.'),
  ('0bcb845e-25a8-4c8a-b05c-67b7a3788c4a', 'Сюрпризы погоды ⛅', 'Собираясь на прогулку, не дайте погоде себя обмануть, чтобы малыш не замёрз. Не судите о ней только по виду из окна — заранее проверьте скорость ветра и фактическую температуру на улице.'),
  ('1566736d-5f6a-420b-9aaa-9e37909efa16', 'Открывает своё «Я» 👑', '«Я сам!» и «Моё!» не сходят с его языка. Сейчас период эгоцентризма проявляется особенно ярко. Отнеситесь с уважением к его индивидуальности — это один из этапов развития.'),
  ('7aba0d06-67c9-4fba-811b-47eacf1ff2d7', 'Папина ответственность 👨‍🍼', 'Дневной усталости вам и так хватает. Вечером поручите папе подготовить малыша ко сну и надеть на него пижаму, а сами просто понаблюдайте со стороны.'),
  ('2876fc5f-fac3-4af5-b718-9c2f0d9b5314', 'Нужно пополнить запас энергии 🍲', 'Усталость пробирает до костей? Побалуйте себя особенным салатом, который готовится за 10 минут, надолго насыщает и придаёт бодрости.'),
  ('2b82cde7-2302-4ad2-96b7-ca1beedb8f4f', 'Битва за щётку окончена 🪥', 'При виде зубной щётки он сразу крепко сжимает рот? Поищите в Рекомендуемых товарах музыкальные или вращающиеся детские щётки, которые упростят процесс и превратят гигиену в развлечение.'),
  ('c3b0f127-530e-4b11-9687-7c0bcb24de5f', 'Ночная буря 😭', 'Он без видимой причины проснулся среди ночи и плачет? Это газы или просто ночной страх? Спокойно обнимите малыша и, не повышая голоса, помогите ему успокоиться.'),
  ('127ac6bb-4f6e-424f-91fb-e2d406c68c2a', 'За пределы четырёх стен ☕', 'Домашняя рутина начинает вас угнетать. Внесите сегодня немного разнообразия. Сходите в тихое кафе неподалёку: малыш сменит обстановку, а вы сможете насладиться чашечкой кофе.'),
  ('1e376436-3f0d-4a14-a96b-e1c16c40c937', 'Чуткий сон 🤫', 'Он вздрагивает от малейшего шороха, как только засыпает? Оцените акустику комнаты и включите белый шум, чтобы заглушить звуки, доносящиеся из окна.'),
  ('e0d7037f-df25-46a9-8fd2-5b2b39c1432d', 'Покорение мебели 🧗‍♂️', 'Он пытается забраться наверх, держась за диван или стул? Так мышцы ног осваивают разные высоты. Обеспечьте безопасность малыша, но не препятствуйте этим попыткам маленького альпиниста.'),
  ('458c2efd-1859-4a36-bc6c-218987ce42a4', 'Произведение искусства на тарелке 🥦', 'Он отказывается от еды? Иногда дело не во вкусе, а во внешнем виде. Попробуйте пробудить его аппетит, выложив забавные рожицы из разноцветных овощей.'),
  ('6007d88c-cdbb-46d0-9b99-4e7bdd857418', 'Колыбельная на ночь 🎶', 'Ни одно приложение и ни одна запись не заменят мамину колыбельную. Сегодня вечером просто прижмите малыша к груди и тихо спойте его любимую колыбельную, которая дарит ему чувство безопасности.'),
  ('ade78fe2-3290-467b-9d4f-4aa0e7d81802', 'Первая победа на горшке! 🚽', 'Он хочет сам ходить на горшок? Это одна из главных побед в 2.5 года! Отметьте этот успех в трекере Подгузник/Горшок и прочитайте в Блогах, как сделать переход ещё легче.'),
  ('6c9cc94d-8363-4a16-b062-eb3e2640d824', 'Провалы в памяти 🛒', 'Из-за недосыпа ухудшилась память, и вы забываете, что нужно купить в магазине? Не перегружайте мозг. Запишите всё в список, и пусть ваш партнёр купит необходимое по пути домой.'),
  ('8f8c331b-379e-4898-a071-076982bfc0c2', 'Дипломатические переговоры 🤝', 'Не хочет отдавать свою игрушку в парке? Обязательно прочитайте в разделе «Блоги», как после 2.5 лет научить малыша не делиться, а играть по очереди.'),
  ('e1ad3771-efd0-4fef-8fce-2cfe9cc2174f', 'Ночные пробуждения 🌌', 'Просыпается посреди ночи с плачем и не успокаивается? Посмотрите график таймера сна. Чтобы понять разницу между ночным ужасом и кошмаром, прямо сейчас загляните в раздел «Блоги».'),
  ('d3fd3ce0-fc06-4bdf-8472-041feda78c86', 'Кризисы упрямства 🛑', 'На каждое ваше «нет» отвечает криком? Поговорите с Anacan AI, чтобы научиться спокойно справляться с этими неконтролируемыми эмоциональными вспышками и освоить тактики переключения внимания.'),
  ('de972116-bddf-48f9-bc08-9f55438a9ed7', 'Папин час сказок 📚', 'Сегодня вечером доверьте ритуал отхода ко сну своему партнёру! Включите в приложении режим «Партнёр»: пусть он читает сказку, а вы спокойно выпейте чаю.'),
  ('fd7112b4-d166-4f5f-ab2b-5f43c5c75632', 'Обмен опытом 💬', 'Новое движение малыша вас напугало? Не ищите страшные статьи в интернете. Воспользуйтесь советами опытных мам в сообществе Anacan.'),
  ('0b033378-5688-4baf-b5a5-b23c33fde967', 'Секрет усвоения железа: витамин C 🍋', 'Малыш выглядит бледным или у него нет аппетита? Проверьте сегодняшнее потребление железа в инструменте контроля питания и обязательно подавайте к мясу салат с большим количеством лимонного сока, чтобы улучшить усвоение железа.'),
  ('69b9bded-4194-4499-ad7b-42407cdd5970', 'Только сухая пища? 🍞', 'Отказывается от пюре и жидких блюд, просит только хлеб и печенье? Это избирательность в отношении текстуры пищи. Проанализируйте меню с помощью инструмента контроля питания и найдите полезные альтернативы в разделе «Рецепты для малышей».'),
  ('a97ba33c-1ca8-42a6-b9a0-1eac5f5ba6a9', 'Прислушайтесь к своему телу 🩸', 'Внезапно непреодолимо хочется сладкого и всё раздражает? Загляните в календарь в «Трекере менструации». Если приближается менструация, приготовьте перекус из фиников и орехов, богатый магнием, по рецепту из раздела «Полезные рецепты для женщин».'),
  ('16180139-d7b3-4c7d-9723-1b1d28274883', 'Исследователь природы 🔍', 'Устраивает дома настоящий погром? Берите лупу и отправляйтесь на улицу! Найдите зелёный парк в разделе «Места, дружественные мамам», вместе исследуйте насекомых и листья и направьте энергию малыша на изучение природы.'),
  ('1e0561d7-2e98-4811-8aaf-2ee6c5e76ef8', 'Вечерний ритуал стал сложнее?🛀', 'Во время тёплой ванны включите спокойную музыку. Гармония воды и мелодии успокоит даже самого упрямого малыша.'),
  ('39972a4c-ff8f-4f23-abf0-aefe71b44bb9', 'Хаос в доме 🌪️', 'Вся комната завалена игрушками? 10 весёлых минут, проведённых с малышом, важнее уборки. Игрушки и завтра будут на месте — не изнуряйте себя.'),
  ('15d607dd-13ee-4b91-b920-e762edd4acd3', 'В поисках полной тишины 🛋️', 'Как только малыш уснёт, не спешите разгружать посудомоечную машину! Прилягте на диван, закройте глаза и на 15 минут растворитесь в этой редкой, полной тишине дома.'),
  ('6417fc2a-8680-4b6d-9b78-5b97074e6a4c', 'Привыкаем к темноте 🌙', 'Чтобы малыш быстрее уснул, выключите в комнате все лишние источники света и экраны. Выработка гормона мелатонина ускоряется только в спокойной и тёмной обстановке.'),
  ('986722e4-1562-4f18-a164-dd6f65efe855', 'Я вас слышу 🗣️', 'Малыш внимательно вас слушает и пытается строить похожие фразы? Он разговаривает с вами! Чаще отвечайте ему улыбкой и поощряйте это общение.'),
  ('2eb3f64d-4f32-4bfb-81ca-c75ffc798fd6', 'Пора на прогулку 🌳', 'В четырёх стенах становится душно. Посадите малыша в коляску и выйдите на свежий воздух хотя бы на 20 минут. Спокойствие природы благотворно повлияет и на малыша, и на ваше эмоциональное состояние.'),
  ('48fd17bd-f8c5-4be3-9778-ec599f5cc5b0', 'Посмотрите под ноги! 👣', 'Малышу уже нравится ходить босиком и исследовать ногами разные поверхности? Стимуляция нервных окончаний на стопах очень важна для развития равновесия.'),
  ('e607fc1e-dfa8-4735-b945-f39209fa5d8a', 'Волшебный мир сказки 🪄', 'Сегодня вечером попробуйте что-нибудь совсем новое: расскажите историю о маленьком облачке, которое исследует небо. Меняйте интонацию в соответствии с ритмом сказки.'),
  ('4434b892-1b9a-48ea-bd05-6295b7705bc1', 'Тишина в вечернем ритуале 🌬️', 'Малыш весь день бегал и теперь никак не может остановиться? Запустите таймер сна, включите шум океанских волн в разделе «Белые шумы» и превратите комнату в тихую пещеру для сна, чтобы помочь ему успокоиться и восстановить силы.'),
  ('a8561422-a7d3-4164-876d-1471ce35f23d', 'Папин день на кухне 👨‍🍳', 'Активируйте режим партнёра. Сегодня приготовление обеда и кормление — обязанность папы! А вы посвятите это время себе: почитайте книгу или просто отдохните.'),
  ('f2202a7a-5edc-4209-b790-4083df0975d2', 'Ползание с целью 🐢', 'Малыш уже ходит, но иногда ради забавы быстро уползает от вас? Уберите из комнаты опасные препятствия и присоединяйтесь к этой весёлой игре в догонялки.'),
  ('9f77c4af-512a-49b9-8cbf-0c7c57609122', 'Витамин D для костей ☀️', 'Витамин D необходим для усвоения кальция! Проверьте сегодняшний рацион с помощью инструмента контроля питания и загляните в раздел «Рекомендуемые товары», чтобы ознакомиться с каплями, которые рекомендуют врачи.'),
  ('a85116cf-7f79-486c-8e28-8b90c93cfb63', 'Кризис перед выходом 🛑', 'Вам нужно выйти из дома, но малыш всё делает медленно и не спешит? В этом возрасте у детей ещё нет чувства времени! Вместо того чтобы торопить его, узнайте у нашего эксперта Anacan AI, как облегчить переход от одного занятия к другому.'),
  ('b222d604-2c4a-4c8d-9eda-efff14884581', 'В поисках идеальной мамы 💖', 'Сегодня ваше терпение лопнуло и вы повысили голос? Не мучайте себя чувством вины. Когда малыш уснёт, запишите свои переживания в Дневник настроения, чтобы снять эмоциональное напряжение.'),
  ('259a4698-04af-4cc3-93e9-91599ab8a275', 'Дневной сон уходит в прошлое? ⏱️', 'Малыш категорически отказывается спать днём, а вечером сильно переутомляется? Проанализируйте статистику таймера сна и попробуйте полностью перейти на режим тихого часа (quiet time).'),
  ('278f2f23-c655-4241-807c-401148d291e5', 'Мамины приступы ПМС 🍫', 'Перед менструацией у вас стало меньше энергии? Прежде чем принимать лекарства, приготовьте ягодный смузи с натуральным сахаром по рецепту из раздела полезных рецептов для женщин — он быстро придаст сил и поможет организму восстановиться.'),
  ('af74ff56-7d79-46b1-8bf0-e27bd2c06fed', 'Я сам порежу! ✂️', 'Малыш хочет сам нарезать банан или пластилин на кухне? Это замечательное стремление, которое развивает мелкую моторику! Прямо сейчас загляните в раздел «Рекомендуемые товары», чтобы выбрать безопасные детские ножи и ножницы, которыми нельзя порезаться.'),
  ('04970a72-c396-466c-9613-3a82e661e79f', 'Малыш сам не знает, почему плачет 😭', 'У малыша сильная истерика из-за того, что стакан красный, а не синий? На самом деле причиной может быть усталость или эмоциональная перегрузка. Поделитесь своими переживаниями с Anacan AI и узнайте, как сохранять спокойствие во время таких неконтролируемых эмоциональных вспышек.'),
  ('c150e539-1698-44fc-be7c-18e8beb9b566', 'Посторонние звуки в комнате 🌌', 'Малыша будит полная тишина в комнате или тихий стук из соседней квартиры? Включите шум вентилятора в разделе «Белые шумы» и убедитесь, как хорошо он маскирует посторонние звуки во время сна.'),
  ('f0684802-cf6d-4a4b-96a5-44c5cabd2832', 'Убираем дом вместе 🧹', 'Нужно убрать дом? Активируйте режим партнёра! Узнайте, как вам, папе и малышу, которому можно дать небольшую тряпочку, превратить уборку в весёлую семейную игру.'),
  ('20745776-36d1-4511-abf0-1fafb63ced1d', 'Игра вместо экрана 📱', 'Вечером малыш просит включить мультфильм и плачет? Узнайте у Anacan AI, как без стресса ограничить экранное время и сразу переключить внимание малыша на другую игру.'),
  ('956585f5-6347-4c88-b6a3-3638bd223889', 'Время для вашего кофе ☕', 'Устали постоянно сидеть дома? Найдите в разделе «Места для мам» детские кафе, где часто собираются мамы, и откройте для себя новое пространство для общения.'),
  ('96e63d94-22cd-4a99-8350-f721e6ade562', 'Искусство ждать своей очереди 🧸', 'Не хочет ждать, пока другой ребёнок скатится с горки в парке? Обязательно прочитайте в разделе «Блоги», как после 2.5 лет привить малышу терпение и научить играть по очереди.'),
  ('1cf87075-900c-4f1c-a89d-b12b8314ac9b', 'Проверка запасов железа 🥩', 'Малыш выглядит бледным или у него нет аппетита? Проверьте сегодняшнее потребление железа в инструменте контроля питания и для лучшего усвоения обязательно подайте к мясу салат с большим количеством лимонного сока.'),
  ('9c0be1cd-f5f7-43c2-bf11-199a917727ea', 'Массаж от папы 💆‍♀️', 'У вас затекла спина оттого, что весь день бегаете за малышом? С помощью функции для партнёра сообщите ему, что сегодня вечером после укладывания малыша пришло время сделать вам короткий массаж плеч.'),
  ('fcd8e598-c584-4111-a575-0192c20a2ba3', 'Превратите питьё воды в игру 💧', 'Много бегает, но мало пьёт? Риск запора повышается. Отметьте стул в приложении, сразу добавьте овсянку в меню с помощью инструмента контроля питания и закажите цветную детскую бутылочку для воды в разделе «Рекомендуемые товары».'),
  ('819da396-26ce-4c11-baf2-c21f3a1ad406', 'Избирательный аппетит 🍝', 'Хочет только макароны? Проверьте недельный баланс с помощью инструмента контроля питания. Не изводите себя переживаниями из-за одного дня.'),
  ('f0c36b67-8799-4202-8ab4-a072283a2c59', 'Слёзы от усталости 💧', 'Вам тоже хочется плакать? Это совершенно нормально. Запишите свои чувства в Дневнике настроения и отбросьте чувство вины.'),
  ('f35164ca-a4af-42c5-8f5c-d2b4e2de79f4', 'Узнаёт цифры? 🔢', 'Пытается что-нибудь считать, поднимаясь по лестнице или собирая игрушки? Сразу добавьте эти первые искорки математического развития в Альбом малыша в виде видео со звуком и превратите их в воспоминание на всю жизнь.'),
  ('02944013-1945-43f5-a622-bb7657b42970', 'Спрячьте овощи 🥦', 'Выбрасывает из тарелки зелень или брокколи? Найдите среди рецептов для малышей красочный домашний кекс с овощами и без труда выполните норму витаминов в инструменте контроля питания.'),
  ('45019ac4-08ed-4d8b-8186-060ceb70601a', 'Вы — идеальная команда 🌟', 'Каждый новый навык, который малыш осваивает, каждый его уверенный шаг — результат усилий вас и вашего партнёра. Откройте Дневник настроения и сегодня стоя поаплодируйте себе как команде!'),
  ('5613e3d7-d67b-4e9a-b92f-7ce15054b42e', 'Скачок роста и веса! 📏', 'Во время одевания вы заметили, что рубашки стали тесны или обувь жмёт? Внесите текущий рост и параметры в Трекер веса и с гордостью посмотрите, как поднимается кривая развития.'),
  ('3a871deb-8d4f-4409-84bd-a7fdcb6e8f4e', 'Время папиной сказки 📚', 'Сегодня вечером укладывание малыша берёт на себя ваш партнёр. Пусть он читает сказку, а вы насладитесь этой небольшой передышкой.'),
  ('751db3a1-bc4d-4599-b35d-5aadaed3cfca', 'Вопросы «Почему?» 🤔', 'Малыш хочет понять мир. Узнайте из Блогов, как терпеливо отвечать на его бесконечные вопросы. Ваше терпение — вклад в его развитие.'),
  ('ce6fd7ba-57bf-4c85-bfa6-c9b4b3713d0c', 'В четырёх стенах тесно 🌳', 'Дома всё летит вверх дном? Найдите ближайший парк в разделе «Места для мам». Свежий воздух — лучшее лекарство и для малыша, и для вас.'),
  ('034073b2-a550-46ff-9473-8411c49fc4ec', 'Железо и сила 🥩', 'Малыш выглядит бледным? Проверьте потребление железа в инструменте контроля питания. Для лучшего усвоения подайте к мясу салат с лимонным соком.'),
  ('3e853511-fee0-4626-9f71-c751f4b255ca', 'Битва с зубной щёткой 🪥', 'Убегает при виде щётки? Посмотрите музыкальные щётки в разделе «Рекомендуемые товары». Превратите гигиену не в обязанность, а в игру.'),
  ('d32651ed-78b7-4090-bd14-46fc6e60d9a7', 'Истерики из-за экрана 📱', 'Когда вы забираете телефон, начинается настоящая буря? Спросите у Anacan AI о действенных психологических приёмах, которые помогут спокойно установить ограничения на экранное время.'),
  ('49972eb0-ce9d-4cba-ad0b-3cc84b80e743', 'Ночные страхи 🤖', 'Малыш просыпается среди ночи с криком и не узнаёт вас? Узнайте из статей в разделе «Блоги», что делать в такой ситуации и как сразу отличить ночной страх от кошмара.'),
  ('4efefe1c-c867-4006-9142-0718a80c34db', 'У вас тоже есть друзья ☕', 'Разговаривать только с малышом утомительно. Найдите детские кафе в разделе «Места для мам», выпейте чашечку кофе и пообщайтесь с другими мамами.'),
  ('a185d77d-1385-43cb-bec6-87f42c458382', 'Утренние истерики 🛑', 'Плачет в ответ на каждое ваше «нет»? Поделитесь своими переживаниями с Anacan AI и узнайте, как спокойно справляться с эмоциональными вспышками и переключать внимание малыша.'),
  ('1d63f653-1008-4746-a730-0e985e6ca79c', 'Разрешите испачкаться 🏖️', 'Хочет играть с грязью? Пусть испачкается! Найдите в разделе «Рекомендуемые товары» лучшие материалы для игр, способствующих сенсорному развитию.'),
  ('ab5b74cd-5dbb-4df0-aad8-f7ce58bb43e4', 'Скачок роста 📏', 'Рубашки стали коротки? Малыш растёт! Внесите текущие параметры в Трекер веса и с гордостью наблюдайте, как поднимается кривая развития.'),
  ('cd4b46fb-6caf-421b-9a9e-22b85cfd2d73', 'Горячий чай и тишина 🍵', 'Таймер остановился, малыш уснул. Забудьте о домашних делах! Заварите чай с мелиссой по одному из полезных рецептов и просто насладитесь тишиной.'),
  ('3e08f834-ae99-412b-94f4-fcb284f337ca', 'Анализ режима ⏱️', 'Укладывание вечером занимает слишком много времени? Посмотрите график таймера сна. Возможно, пора значительно сократить дневной сон.'),
  ('6c779bea-dc2a-41ad-8ebb-96d5620eee3b', 'Кальциевый щит 🦴', 'Не пьёт молоко? Кальций необходим для костей. С помощью инструмента контроля питания подсчитайте количество йогурта или брокколи в рационе и восполните дефицит.'),
  ('9550715f-5ff1-4a49-8dae-33944b52477f', 'Длинные предложения 🗣️', 'Уже рассказывает забавные истории? Наступил настоящий словарный взрыв! Сохраните голосовую запись этого драгоценного момента в Альбоме малыша.'),
  ('2d4c6405-93aa-4a22-9aae-af7a8dcd04fc', 'Ранние пробуждения 🌅', 'Просыпается до восхода солнца и полон энергии? А вы уже без сил. Спросите у Anacan AI, как наладить такой режим. Недосып не будет длиться вечно.'),
  ('49091c89-e2f8-4ecf-a7b6-b705116efa46', 'Папина сказка 📚', 'Включите партнёрский режим. Сегодня вечером главный герой сказки — папа! Пусть он читает, а вы налейте себе кофе и насладитесь тишиной в другой комнате.'),
  ('865b1ef2-1722-47cc-bf4d-3108a098404b', 'Не хочет делиться 🧸', 'Никому не даёт свою игрушку? Это не эгоизм, а особенность возрастного развития. Узнайте в Блогах, как научить малыша играть по очереди.'),
  ('983d85d9-b1dc-40ec-a012-9c7aba93c4d9', 'Слёзы — это нормально 💧', 'Вы устали и хотите просто поплакать? Быть сильной мамой — значит иногда уметь признавать свою слабость.'),
  ('ee623f8b-a47a-4ef6-96d3-5754f3e3cd43', 'Упадок сил ⚡', 'Днём засыпаете на ходу? Выбирайте не кофеин, а белок! Восстановите силы с помощью смузи с арахисовой пастой, который мгновенно заряжает энергией, из раздела полезных рецептов.'),
  ('fe3bdaaa-fafd-445d-b4e7-84a8026c6168', 'Внезапные истерики 🛑', 'Без видимой причины падает на пол и бьётся в истерике? Поделитесь своими переживаниями с Anacan AI и узнайте, как спокойно справляться с такими кризисами и не обращать внимания на взгляды окружающих.'),
  ('59dde031-61d1-4132-874a-bbebe2bc223a', 'Трагедия сломанного печенья 🍪', 'Печенье разломилось пополам — и наступил конец света? Добро пожаловать в мир классических кризисов 2.5 лет. Не ищите логики, просто скажите малышу, что понимаете, насколько велико его горе.'),
  ('5e26eff6-747b-42a4-909a-13e90be41e9d', 'Реальность без фильтров 🛑', 'Смотрите в социальных сетях видео со спокойными и опрятными детьми и вините себя? Это всего лишь 15-секундные иллюзии. Ваша суматошная и шумная реальность прекраснее всего.'),
  ('db6eccad-9548-4b17-8f6b-0466160ee8dc', 'Пижамный протест 👕', 'Не хочет одеваться и бегает по дому? Превратите борьбу в игру. Посмотрим, кто оденется быстрее? Соревнование часто становится лучшим способом преодолеть упрямство.'),
  ('118d8e02-86c1-4716-8dfd-287849e960b7', 'Маленький диктофон включён 🎙️', 'Малыш тут же повторяет даже самое случайное слово, которое вы произнесли? Он — ваше живое зеркало. В этом возрасте словарный запас стремительно растёт — отмечайте новые слова в Трекере развития.'),
  ('4ffb5f4c-fcb6-4d97-8d29-5662777e74bb', 'Быстрые закупки 🛒', 'Из-за недосыпа вам трудно сосредоточиться? Вы постоянно забываете, что нужно купить. Сразу добавляйте всё в Список покупок, а ответственность за поход в магазин полностью передайте партнёру.'),
  ('8658617d-87c3-40a0-a148-d3af3d34503e', 'Папин театр сказок 📖', 'Ваши голосовые связки устали весь день повторять «нет». Сегодня вечером передайте чтение сказки папе. Пусть он меняет голоса и рассказывает забавные истории, а вы отдохните.'),
  ('5d60ba67-a127-4fbd-bd24-40125cd3bcc8', 'Новый холст художника 🖍️', 'Бумага закончилась, и теперь малыш хочет рисовать на стене или двери? Это не просто каракули — так он исследует мир и развивает мелкую моторику. Дайте ему большой лист картона и обозначьте границы для рисования.'),
  ('b27a302e-b37e-4606-900b-22135e770f9b', 'Прикоснуться к тишине 🤫', 'Домашний хаос наконец утих, и малыш уснул. Откройте Шумомер, проверьте уровень тишины в комнате и на 15 минут растворитесь в ней, не глядя ни на один экран.'),
  ('d7ebaa5c-a836-4c14-8fc7-8ddab08162c6', 'Овощная маскировка 🥦', 'Малыш отодвигает в сторону всё зелёное на тарелке? Избирательность в еде достигла пика. В разделе «План питания» найдите хитрые рецепты, в которых овощи можно превратить в пюре и спрятать в котлетах.'),
  ('2461cdb3-c847-4528-8c72-5b1258b6ff1d', 'Границы на детской площадке 🧸', 'Малыш никому не даёт своё ведёрко в песочнице? Это не эгоизм, а формирование понятия собственности. Учите делиться не принуждением, а соблюдением очереди: «Сейчас его очередь».'),
  ('b0edd680-c98e-4626-b7fa-18383befe832', 'Пришли воображаемые гости ☕', 'Малыш разговаривает в комнате с невидимыми друзьями и наливает им чай? Это расцвет воображения! С гордостью наблюдайте со стороны за этим замечательным маленьким сценаристом.'),
  ('dea0086a-894a-4d43-a110-0948ee956740', 'Волшебство в руках малыша 🪄', 'Классические сказки ему наскучили? В «Умных сказках» на этот раз позвольте ему самому выбрать героя. Летающая собака или Говорящее дерево — дайте волю воображению.'),
  ('0a08658d-8354-4bb5-9ba8-b4c528e517fc', 'Устанавливает свои правила 🛑', 'На всё отвечает: «Я сам!» Надевает обувь не на ту ногу, а футболку — задом наперёд, но всё равно настаивает на своём. Ничего страшного: стремление к самостоятельности важнее внешнего вида, поэтому позвольте ему попробовать.'),
  ('411275c3-b6bc-4218-a886-bbf3ee4ba697', 'Водная терапия 🛀', 'После целого дня беготни нервы напряжены и у малыша, и у вас. Тёплая ванна нужна не только для гигиены — воспользуйтесь удивительной способностью воды снимать напряжение.'),
  ('d5a4b327-9717-431f-8c67-ec44df34af85', 'Чувство выгорания 🔋', 'Хочется на всех кричать? Это выгорание. Прямо сейчас зайдите в Сообщество Anacan, прочитайте откровения мам, которые переживают тот же период, и получите поддержку.'),
  ('38c563a6-395b-403a-8ffd-c4d46a16b207', 'Кухонная диверсия 🧑‍🍳', 'Пока вы готовите, малыш устраивает концерт на кастрюлях? Он тоже хочет быть частью команды. Дайте ему небольшой кусочек теста — пусть тоже готовит.'),
  ('65dda26f-c428-4285-904a-5e44f932685c', 'Справляемся вместе 🥂', 'Когда ребёнок уснёт, сядьте с партнёром лицом друг к другу. Вместо разговоров о ребёнке улыбнитесь друг другу со словами: «Мы и сегодня выжили» — и почувствуйте, что вы одна команда.'),
  ('68aff420-6957-4fb3-8fd3-172910f79641', 'Пора выйти на улицу ⛅', 'В четырёх стенах становится невыносимо. Проверьте фактическую температуру с помощью инструмента погоды и подбора одежды и, не раздумывая, отправляйтесь в парк. Свежий воздух помогает быстро справиться даже с самыми сильными истериками.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ru = v.t, body_ru = v.b
FROM (VALUES
  ('70cc8a60-04a1-4e4e-b5c3-986f74563498'::uuid, 'Обувь за 20 минут 👟', 'Малыш хочет сам надеть обувь, и выход из дома затягивается? Не теряйте терпения.'),
  ('e2414d34-11c4-4990-9c63-38d30534a147', 'Предложения становятся длиннее 🗣️', 'Малыш уже соединяет слова и составляет интересные предложения, полностью соответствующие его собственной логике. Не упускайте эти моменты: снимайте его милые диалоги на видео с помощью «Фотосессии малыша».'),
  ('ef8a1fe8-6bb2-49b8-bcbe-cb005f42d12f', 'Игры в темноте 🐰', 'Малыш боится, когда гаснет свет? Полностью затемните комнату и устройте на стене театр теней с помощью фонарика. Превратите страх в весёлую игру и помогите ему подружиться с темнотой.'),
  ('005f91e2-a696-4de0-bf24-bb840b614746', 'Скачок роста и веса 📏', 'Брюки снова стали коротки? Малыш быстро растёт! Внесите актуальные показатели в «Трекер развития» и с гордостью посмотрите на растущую кривую развития — результат ваших бессонных ночей.'),
  ('4d0ac53a-0a7d-40d8-a958-4dd99382d977', 'Пробуждения без причины 😭', 'Малыш проснулся посреди ночи с криком? Не паникуйте. С помощью инструмента анализа плача проверьте, связано ли это с болью роста или ночным страхом, а затем спокойно обнимите его.'),
  ('7a36ad44-2dba-4854-82a6-8b3c27a56c6f', 'Ледяной кофе ☕', 'Заварить кофе и выпить его через 3 часа — официальный неписаный закон материнства. Сегодня сделайте исключение. Оставьте малыша ненадолго играть самостоятельно и выпейте этот кофе горячим за 10 минут!'),
  ('1e03f3e4-2305-4ae5-883c-39581f248697', 'Знакомство с цифрами 🔢', 'Поднимаясь по лестнице или расставляя игрушки, малыш пытается считать: один, два, три. Поддержите этот математический этап когнитивного развития, считая вместе с ним.'),
  ('2e1f0716-93b5-4be3-9000-fdb28349534d', 'Секретное оружие папы 🤡', 'Когда ваши приёмы уже не работают, странные звуки и смешные гримасы папы мгновенно спасают ситуацию. Во время вечерних истерик сразу передавайте ему эстафету.'),
  ('b24ba903-09d2-4243-a80b-995524b45caf', 'Капризы перед дневным сном 🥱', 'Малыш категорически не хочет ложиться? В 2.5 года некоторые дети начинают отказываться от дневного сна. Не заставляйте его спать, а устройте вместо этого 30 минут тихого чтения книг.'),
  ('54501d8f-f370-4895-a96c-448bca275b4e', 'Посмотри под ноги — что там? 👣', 'Малышу особенно нравится ходить босиком и ощущать разные поверхности — песок, ковёр, камни. Стимуляция нервных окончаний на стопах очень важна для его неврологического развития.'),
  ('7212233e-c5da-4c83-bd8d-a74e469e3fcc', 'Приглушите свет 🌙', 'За 1 час до сна выключите дома весь яркий свет и экраны с синим свечением. Создайте спокойную сумеречную атмосферу, способствующую выработке мелатонина.'),
  ('efc5b454-d92c-49c6-a2a5-9e995c6d9a84', 'Тревоги из-за здоровья 🤖', 'Сомневаетесь, какие прививки или витамины необходимы в 2.5 года? Не теряйтесь среди пугающих форумов в интернете — сразу получите точный ответ от Anacan AI.'),
  ('235bf352-67d4-4056-94d7-5429271d340f', 'Маленькие споры 🗣️', '«Нет, я уже большой, я сам знаю!» Малыш уже приводит доводы и пытается с вами не соглашаться. Отвечайте ему на равных, не повышая голоса, но твёрдо.'),
  ('ae99921f-bf29-40ac-a251-a633a4741d07', 'Уделять время себе — не преступление 💆‍♀️', 'Чувство, что вы проводите с ребёнком слишком мало времени, знакомо каждой маме. Но не забывайте: у истощённой мамы не остаётся сил, чтобы что-то дать ребёнку. Устройте себе днём 20-минутную передышку.'),
  ('ead40251-f5fc-4b01-b344-4b041fbbf0eb', 'Самая прекрасная ноша 🫂', 'Весь день малыш сводил вас с ума и плакал по любому поводу. Но вечером, засыпая, он прижался к вашей груди — этот запах тёплого маленького тельца... Вот оно, самое прекрасное чувство на свете.'),
  ('41765791-323c-438b-b416-30b7105b9c01', 'Место для мамы ☕', 'Устали каждый день ходить в один и тот же парк? Найдите среди мест, дружелюбных к мамам, новое тихое кафе, где дети смогут спокойно поиграть, и сегодня немного побалуйте себя.'),
  ('dc90d262-2720-4f19-9f2a-dcf90cd5da80', 'Понимание форм и пространства 🧩', 'Малыш упорно пытается собирать пазлы и вставлять разные фигурки в подходящие отверстия. Не вмешивайтесь, даже если он ошибается. Именно методом проб и ошибок он учится решать задачи.'),
  ('e0925ec9-2283-4167-888a-ee7948c21d0f', 'Естественный белый шум 🤫', 'В первые полчаса после засыпания мозг наиболее активен. Отрегулируйте уровень шума в комнате с помощью шумомера. Иногда один лишь тихий шум дождя способен погрузить малыша в глубокий сон.'),
  ('28ff0d8a-2265-4669-8253-5aac2bfb80da', 'Поблагодарите себя 🎈', 'Бессонные ночи, дневная суета... Но вы справились. Сегодня похвалите себя за то, что растите малыша, не повышая голоса!'),
  ('95ffd69a-c8c2-4b14-b98e-76c322f02229', 'В магазин без списка? Ни за что! 🛒', 'Вы полагаетесь на память, идёте в магазин и возвращаетесь домой без самого необходимого. Пора менять эту привычку. Приучите себя сразу вносить в список покупок всё, что заканчивается дома.'),
  ('ec24c154-30dc-40d8-8aed-20579933d8fb', 'Дайте волю чувствам 📝', 'Вас никто не понимает? Не замечает вашей усталости? Дневник настроения — лучший хранитель тайн. Запишите в него весь свой стресс, боль и одиночество — и вы почувствуете, как на душе становится легче.'),
  ('093d545f-b52d-4160-be2f-88e5e1b53427', 'Война с овощами продолжается 🥦', 'Малыш снова заметил в супе крошечный кусочек моркови и отказался есть? Уменьшите порции, поэкспериментируйте с формой продуктов. Творческий подход — главное оружие мамы.'),
  ('0e43d226-9cd6-4c62-b9a7-e0206f0830ca', 'Сюрприз «Я тебя нашёл!» 🙈', 'Правила игры в прятки изменились. Теперь малыш прячется, а потом сам выбегает с криком: «Я здесь!» Позвольте ему придумывать свои правила и смейтесь вместе от души.'),
  ('39e6032f-d2bf-40b5-98db-1f2ab3a5a379', 'Вечернее умиротворение 🛀', 'Если вечером малыш особенно упрям и раздражён, устройте ему тёплую ванну. Пусть он просто поиграет с водой — её терапевтическая сила поможет смыть весь накопившийся негатив.'),
  ('2c4fbb59-42cd-4340-ba93-aee620d9df26', 'Напевает песенки 🎶', 'Во время игры малыш напевает песенки с непонятными словами. Это признак развития как речи, так и слуха. Обязательно отметьте этот новый этап в трекере развития.'),
  ('491d12b8-51d5-4984-8dda-d40fbb4e95c8', 'Время папиного чтения 📖', 'Давайте сегодня создадим в комнате особую атмосферу. Доверьте чтение книги глубокому, внушающему спокойствие голосу папы, а сами отдохните в стороне, наслаждаясь полной тишиной.'),
  ('c32299af-eeac-42f3-ab67-01688b0d4551', 'Группа поддержки для мам 💬', 'Вам предстоит принять непростое решение? (Детский сад, горшок, сон). Советы опытных мам в сообществе Anacan — это самые практичные решения, о которых не прочитаешь ни в одной книге.'),
  ('1c02ca47-65ab-4daa-8468-3f801795414a', 'Пусть дома останется беспорядок 🌪️', 'Устали каждый вечер складывать одни и те же игрушки в коробку? Сегодня не убирайте! Дом — не музей, а место, где кипит жизнь и растёт маленький исследователь.'),
  ('890c1216-15b7-4852-b1cb-42e4a141e897', 'Меткие броски и ловля мяча ⚾', 'Теперь малыш не просто упускает большой мяч, который вы ему бросаете, а пытается его поймать. Зрительно-моторная координация стремительно развивается. Устройте в коридоре небольшую совместную тренировку.'),
  ('a764d770-048d-4a17-b477-fc4f761c3c2d', 'Без сказки не засыпаем 🪄', 'Полностью выключите свет в комнате. В разделе умных сказок выберите спокойный фон без слов, только со звуками природы (ветра, леса), чтобы помочь малышу быстрее уснуть.'),
  ('1c8d40ed-ce45-4ab5-a646-af121febdc6b', 'Гордость за вашу команду 🥂', 'Вы справились с непростым днём. Когда малыш уснёт, налейте себе чаю вместе с партнёром и поддержите друг друга словами: «Мы и правда отлично справляемся».'),
  ('b19556d6-123c-4633-b806-8552c2789139', 'Погода переменчива ⛅', 'Собираясь на прогулку, не дайте погоде себя обмануть, чтобы малыш не замёрз. Не судите о погоде только по виду из окна — воспользуйтесь помощником по погоде и одежде, чтобы подобрать наиболее подходящий комплект для прогулки.'),
  ('d7f16071-fb32-41c6-bf73-3b61867ff844', 'Смелые прыжки 🧗‍♂️', 'Малыш прыгает с дивана на подушки. Так он проверяет силу притяжения и собственную смелость. Вместо того чтобы запрещать, организуйте в комнате безопасную зону для прыжков.'),
  ('3c7fed9f-b2da-420c-b7cb-afa7c5dc9f37', 'Примите бессонную ночь 😭', 'Малыш проснулся посреди ночи и не хочет спать. Не сердитесь на него. Постарайтесь выяснить причину, приласкайте его и дайте почувствовать, что вы рядом.'),
  ('904ee771-1822-4dbc-a79d-be6697d8f129', 'Терпение во время истерики 🛒', 'Малыш кричит в магазине, потому что вы не купили желанную игрушку. Не обращайте внимания на взгляды окружающих «идеальных» родителей. Спокойно установите зрительный контакт, всё объясните и не отступайте от своего решения.'),
  ('c5b71abf-d92a-46da-8996-4282a02052e4', 'Малышу 31 месяц!  🎉', 'Он уже вступил в самый интеллектуально насыщенный и одновременно самый непростой период детства. Каждая его фраза и каждый вопрос становятся для вас большим открытием.'),
  ('0f2d9f90-69e8-4777-adab-24eab59b69a5', 'Капризы за столом 🥣', 'Съедает две ложки, говорит, что наелся, и убегает? Не заставляйте его есть. Здоровые отношения с едой важнее, чем пустая тарелка.'),
  ('1b92930f-874b-4bdc-b9d4-44b2ec744469', 'Кадр, останавливающий время 📸', 'Когда малыш мило играет в комнате, сразу откройте «Фотосессию малыша» и без всяких фильтров запечатлейте на память его изменившееся, повзрослевшее личико и сияющие глаза.'),
  ('1beec453-866b-4504-9a19-59d21f2305e4', 'Снова тревога разлуки? 🥺', 'Малыш ждёт вас за дверью и плачет, даже когда вы идёте в туалет. Тревога разлуки иногда возвращается. Каждый раз откликайтесь и даже из другой комнаты говорите ему, что вы рядом и обязательно вернётесь.'),
  ('01e5d997-771c-4149-81ec-cf5e1b89ede9', 'Энергию нужно выплёскивать 🌳', 'В четырёх стенах малыш становится раздражительным. Посадите его в коляску или возьмите за руку и выйдите на свежий воздух. Спокойствие природы благотворно повлияет и на малыша, и на ваше эмоциональное состояние.'),
  ('149c401f-2cba-4bc8-b3fb-54e3507ca6f5', 'Привыкаем к темноте 🌙', 'Чтобы малыш быстрее заснул, выключите в комнате все дополнительные источники света и экраны планшетов. Мелатонин быстро вырабатывается только в спокойной и тёмной обстановке.'),
  ('1d84618d-c436-422f-bb3e-95d3ae0487d6', 'Поток вопросов «Что это?» ☝️', 'Малыш показывает пальцем на всё вокруг и спрашивает, как это называется? Он хочет, чтобы вы назвали ему окружающий мир. Это огромный скачок в развитии речи! Терпеливо повторяйте название каждого предмета, на который он показывает.'),
  ('0d2ab4f6-8a9d-4fb2-978b-635299c5c2d2', 'Радостные аплодисменты 👏', 'Получилось что-то сделать, и малыш с гордостью аплодирует себе? Ему важно ваше одобрение! Порадуйтесь его маленькому достижению, поддержите громкими аплодисментами и вдохновите на новые успехи.'),
  ('25c7776c-5416-4926-9ebf-f1fff97f3809', 'Есть вопрос? 🤖', 'После 2.5 лет вас беспокоит график роста и веса ребёнка? Вместо того чтобы читать пугающие статьи в интернете, получите точную и научно обоснованную информацию у Anacan AI.'),
  ('8ca38ffe-27aa-42ae-a1e8-03b42c6c25c2', 'Папины забавные звуки 🤡', 'Когда ваши приёмы не помогают, ситуацию спасают забавные звуки, которые издаёт папа. Во время вечерних капризов сразу передайте эстафету ему и с улыбкой наблюдайте со стороны.'),
  ('186e8c82-10c6-4dcc-8ae8-517e2888e663', 'Ночная мелодия 🛀', 'После целого дня в движении и малыш, и вы выбились из сил. Тёплая ванна и тихая, нежная мелодия на фоне помогут его нервной системе полностью успокоиться.'),
  ('34a5aff2-1b83-44f1-acd3-59c942a78f84', 'Наполняет картинки смыслом 📖', 'Увидев в книге животных или детей, малыш прикасается к ним и спрашивает: «Что он делает?». Его зрительное восприятие развивается удивительно быстро. Рассказывайте ему подробные истории о персонажах.'),
  ('638fb01b-1266-441c-a6a2-ad8bcb0172d8', 'Время для мамы 🥑', 'В ежедневной суете не обедайте на ходу. Выберите полезный и питательный перекус из здоровых рецептов и хотя бы 10 минут спокойно полежите на диване, уделив внимание собственному питанию.'),
  ('543664cd-6c89-4ffd-ac7b-d08edd1101b7', 'Разговоры шёпотом 🌙', 'Полностью выключите свет в комнате. Лягте рядом и очень тихо, шёпотом расскажите малышу о том, что произошло за день. Шёпот — один из лучших способов подготовить мозг ко сну.'),
  ('93186474-3eab-43ed-a284-f876b4f1b709', 'Железо и сила 🥩', 'Малыш выглядит бледным или быстро устаёт? Подавайте к мясу салат с лимоном или помидорами, чтобы улучшить усвоение железа.'),
  ('fd977b6d-8463-4d3e-998c-e4dea887a555', 'Сила списков 🛒', 'Постоянно забываете что-нибудь купить в магазине? В приложении вас ждёт список покупок. Записывайте туда всё необходимое, чтобы ваш супруг мог купить нужные продукты по дороге с работы.'),
  ('b5b01983-be53-446e-a05f-8de98770b472', 'Это моё 🧸', 'Малыш не даёт свои игрушки пришедшему в гости ребёнку? Это не эгоизм, а защита личных границ. Учите его делиться не принуждением, а собственным примером.'),
  ('b791e063-932d-483a-b56e-e710cf0815c9', 'Свободная игра 🧸', 'Вы не обязаны развлекать малыша каждую минуту и постоянно придумывать для него игры. Скука для детей — начало творчества. Позвольте ему самостоятельно исследовать что-нибудь в комнате.'),
  ('78cdd6a4-a9f3-4cd8-8b42-3de0066371e3', 'Разрешите испачкаться 🏖️', 'Малыш хочет играть с грязью или водой? Пусть испачкается! Всё необходимое для этих занятий, поддерживающих сенсорное развитие и несложных в уборке, вы найдёте в разделе «Рекомендованные товары».'),
  ('a54926e2-dcf2-4ae7-b48f-de76a56a8b5a', 'Отфильтруйте звуки 🤫', 'Во время засыпания чувствительность малыша повышается. Чтобы заглушить звуки с улицы, включите в комнате негромкий белый шум (white noise) или звуки природы.'),
  ('b1b0d666-c61e-4108-b645-d26f43bbe56c', 'Посмотрите вниз: что он исследует? 👣', 'Малышу уже нравится ходить босиком, ощущать ковёр или камешки в комнате. Стимуляция нервных окончаний на стопах очень важна для развития равновесия и двигательных навыков.'),
  ('07396f85-0dfe-4998-a9ea-d36af8bc97dd', 'Просто обнимите 🫂', 'Не нужны ни игры, ни книги, ни сказки. Сегодня вечером просто прижмите малыша к груди, вдохните его запах и прошепчите в темноте, как сильно вы им дорожите.'),
  ('0c781594-9b76-4258-9f91-7171c6608a1a', 'Обмен опытом 💬', 'Вас пугает, что ребёнок всё отрицает и упрямится? Не ищите страшные статьи в интернете. Обратитесь к реальному опыту мам из сообщества Anacan.'),
  ('598525b6-1a5f-4877-944f-c79292ee0167', 'Целенаправленные забеги 🐢', 'Малышу уже недостаточно просто ходить: он быстро убегает и прячется от вас. Уберите из комнаты опасные препятствия и с большим энтузиазмом присоединяйтесь к игре в догонялки.'),
  ('01e01b8e-03c9-4797-b794-5c6f68c813f6', 'Папина сказка 📖', 'Сегодня вечером дайте своему голосу отдохнуть. Пусть папа возьмёт на себя чтение любимых книг малыша, забавно меняя интонации и голоса.'),
  ('687bbb3b-79db-41d1-81e9-02d82200fd25', 'Начинается твёрдое «нет» 🛑', 'Малыш отстраняется и твёрдо говорит «нет», когда кто-то хочет его поцеловать? Уважайте его телесные границы. Умение протестовать против прикосновений без разрешения — важное условие для будущей уверенности в себе.'),
  ('cb9d6b16-c52e-4770-b96a-4ab41dd866dc', 'Когда мама устала 🛑', 'Вы не железная. Если сегодня у вас нет сил готовить, сварите макароны или закажите еду. Быть идеальной мамой — не значит делать всё в одиночку.'),
  ('438805fb-6787-4d0d-b1d5-b2a1a747c30c', 'Сигнал о запоре 💩', 'Малыш много бегает, но забывает пить воду? Следите за его стулом в горшке. Обязательно добавьте в меню богатые клетчаткой овсянку и чернослив.'),
  ('6e0e2948-0156-4f7e-a4e9-342d621f5670', 'Бесконечное шоу в кровати 🛌', 'Вместо сна малыш прыгает и бегает по кровати? Запустите таймер сна и с любовью соблюдайте установленные границы. Включите в разделе «Белый шум» звуки леса и превратите комнату в спокойное пространство для сна.'),
  ('c7ebe08f-c601-4b91-b115-456e094665de', 'Кальциевый щит 🦴', 'Малыш не пьёт молоко? Кальций необходим для костей. С помощью инструмента контроля питания подсчитайте, сколько сыра, йогурта или брокколи он съел сегодня, и восполните нехватку.'),
  ('54448f6d-1a3b-4d93-a54d-a52f199ed706', 'Крепость из подушек 🏰', 'Сегодня вечером превратите комнату в игровую площадку. Постройте небольшую крепость из диванных подушек и заберитесь внутрь. Будет немного беспорядка, но весёлый смех того определённо стоит.'),
  ('71cd2e71-d81c-477a-9842-72269b236716', 'Хочу есть самостоятельно 🥄', 'Малыш отбирает ложку и пачкает всё вокруг? Запустите таймер питания. Не смотрите на разбросанную еду — гордитесь его самостоятельностью и растущей уверенностью в себе.'),
  ('a40edf39-5245-44c1-a544-58bd483fee61', 'Утренние капризы ☁️', 'Едва открыв глаза, малыш плачет из-за всего и ничем не доволен? Возможно, он находится в самом разгаре скачка роста. Просто чаще обнимайте его и дарите чувство безопасности — это поможет спасти день.'),
  ('08e4a521-2f7a-4298-b56b-2d48b11d0ee9', 'Ночная смена папы 👨‍🍼', 'Дневной усталости вам и так хватает. Вечером поручите папе подготовить малыша ко сну и надеть на него пижаму, а сами просто наблюдайте со стороны.'),
  ('352c5750-18d9-48a8-a40c-2d51006fd988', 'Повторение слов 🗣️', 'Малыш тут же, словно попугай, повторяет каждое новое слово, которое слышит от вас? Его словарный запас растёт. Обращайте особое внимание на слова и эмоции при нём — он всё копирует.'),
  ('3f0547e8-7e6b-4c78-bdaf-b78aab3ce2fa', 'Спрячьте овощи 🥦', 'Малыш снова заметил в супе крошечный кусочек моркови и отказался есть? Превратить овощи в пюре и спрятать их в котлетах с помощью плана питания — старая добрая и полезная мамина хитрость.'),
  ('b0e5435a-23a4-401e-a5a2-1b672694e080', 'Сюрпризы погоды ⛅', 'Не позволяйте переменчивой погоде застать вас врасплох и не дайте малышу замёрзнуть на прогулке. Не оценивайте погоду только по виду из окна: воспользуйтесь помощником «Погода и одежда», подберите наиболее подходящий для улицы комплект и смело выходите из дома.'),
  ('c7c50614-edd2-448c-a9f6-e76579ba2f11', 'Ночная буря 😭', 'Малыш без видимой причины проснулся среди ночи и плачет? Это газы или просто ночной страх? Спокойно обнимите его и, не повышая голоса, помогите успокоиться и снова уснуть.'),
  ('ccc01a90-d6a0-43fa-b96b-7ed5976f5309', 'Страх разлуки 🥺', 'Даже когда вы идёте в туалет, малыш ждёт вас за дверью и плачет. Иногда тревога из-за разлуки усиливается. Каждый раз подавайте ему голос и говорите, что вы рядом и скоро вернётесь.'),
  ('1f77c97d-063c-457e-9c51-eaecc473dae1', 'В поисках новых друзей 👫', 'Малыш пытается бегать со сверстниками в парке и подходить к ним? Социализация официально началась! Наблюдайте за этими первыми попытками с гордостью, оставаясь неподалёку для подстраховки.'),
  ('3eccfd90-7490-4750-87b2-6db63c387fc8', 'Пижамная борьба 👕', 'Вечернее переодевание превращается в настоящую битву? Предоставьте выбор малышу: «Ты хочешь красную пижаму или синюю?» Эта маленькая хитрость поможет ему почувствовать, что решение принимает он.'),
  ('a9a77950-254b-44a6-a42a-1aaac4de986d', 'Час тишины ☕', 'Если малыш не спит днём, установите хотя бы 1 час тишины (quiet time). Пусть он листает книгу в своей кровати, а вы выпейте чаю и немного перезагрузитесь.'),
  ('193d109c-1b4e-4ffc-b28d-b0ef379e189f', 'Монстр в темноте 🌌', 'Малыш боится теней, когда вы выключаете свет? По мере развития воображения страхи кажутся всё более реальными. Включите в разделе «Белый шум» звуки материнской утробы, чтобы подарить ему то знакомое чувство безопасности, в котором он нуждается.'),
  ('52e4f8ee-826b-476b-b87c-2f51c60ddd09', 'Внезапные слёзы 😭', 'Малыш начинает плакать без видимой причины, едва открыв глаза? Поговорите с нашим AI-экспертом Anacan и узнайте, как спокойно помочь малышу справиться с эмоциональной перегрузкой.'),
  ('9a65afbd-9f9f-42c0-ae08-4e58e8bf0c14', 'Пора на свежий воздух 🌳', 'Вам обоим тесно в четырёх стенах? Пока терпение не лопнуло, найдите ближайший парк в разделе «Места для мам». Свежий воздух — лучшее лекарство для вас обоих.'),
  ('51ad8bab-02f3-44e2-b4ec-e672c59c18fa', 'Давай я помогу! 🧹', 'Малыш пытается забрать у вас тряпку, когда вы моете пол или вытираете пыль? Он уже чувствует себя большим. Дайте ему маленькую тряпочку и позвольте присоединиться к вашей команде — это поможет ему развиваться.'),
  ('aa639fbc-fe83-44f4-b9ac-8b3bd199a951', 'Энергию нужно выплеснуть 🌳', 'В четырёх стенах малыш становится раздражительным. Посадите его в коляску или возьмите за руку и отправляйтесь на свежий воздух. Спокойствие природы прекрасно повлияет и на малыша, и на ваше эмоциональное состояние.'),
  ('d88a96c2-0998-4bcd-a181-952127acf518', 'Привыкаем к темноте 🌙', 'Чтобы малыш быстрее заснул, выключите в комнате все дополнительные источники света, особенно экраны планшетов. Мелатонин вырабатывается только в темноте.'),
  ('5d05da29-b0e2-435e-9e14-f523b38e966b', 'Смиритесь с бессонной ночью 😭', 'Малыш проснулся посреди ночи и не хочет спать. Не сердитесь на него. Постарайтесь выяснить причину — боль, газы или страх — обнимите его и терпеливо подождите, пока он снова уснёт.'),
  ('7d1bf85e-e587-4da1-8ee8-b719514d8f71', 'Стойкие пятна 👗', 'Вы устали от постоянных пятен на одежде? Не раздражайтесь: малыш знакомится с едой. Используйте силиконовые нагрудники и просто наслаждайтесь этими яркими и немного неряшливыми моментами.'),
  ('f3bd302c-47f2-4428-b12d-4062c2445dfe', 'Друг в зеркале 👀', 'Поднесите малыша к зеркалу. Понаблюдайте, как удивлённо он рассматривает своё отражение и строит разные рожицы. Это прекрасное занятие для развития самосознания.'),
  ('30560050-23fa-4905-9bfc-f3082838579d', 'Засыпаем под музыку 🛀', 'Вечерний ритуал стал непростым? Включите спокойную музыку во время тёплой ванны. Гармония воды и мелодии поможет расслабиться даже самому упрямому малышу.'),
  ('a805f1c5-c4c1-4bb3-8f2d-828f16d9efaf', 'Битва за чистку зубов 🦷', 'Малыш не позволяет поднести щётку ко рту? Превратите обязанность в игру. Разрешите ему почистить ваши зубы, а затем поменяйтесь ролями.'),
  ('c0129df7-df96-4659-882d-c3fd4d3c25e7', 'Отказ от еды 🥣', 'Малыш съедает две ложки, говорит, что наелся, и убегает? Не заставляйте его. Здоровые отношения с едой важнее, чем кормление через силу. Предлагайте еду чаще, но меньшими порциями.'),
  ('2f4c11d8-739d-4bb0-9942-69a623d77f66', 'Гормональная буря 🩸', 'Внезапно захотелось сладкого и всё раздражает? Загляните в Трекер менструации. Возможно, это ПМС. Не вините себя: поддержите организм перекусом с магнием и финиками из раздела «Полезные рецепты».'),
  ('b69b6089-ef94-4c8e-8537-ca4464897520', 'Утренние капризы без причины 🛑', 'Малыш кричит и плачет из-за всего, едва открыв глаза? Прямо сейчас поговорите с нашим AI-экспертом Anacan и узнайте, как спокойно помочь малышу справиться с эмоциональной перегрузкой.'),
  ('c01d73b8-c3b9-41a9-ae94-2f63ced9cfc4', 'Пусть малыш закончит сказку 📖', 'Сегодня вечером, читая сказку, не договаривайте предложения до конца — пусть малыш продолжит их сам! Спросите у Anacan AI о диалоговых приёмах, которые помогают поддерживать его удивительное речевое развитие.'),
  ('0b9c3636-088f-48ec-88e8-94ea05f16477', 'Разрешите испачкаться 🏖️', 'Малыш хочет играть с грязью или водой? Пусть испачкается! Найдите в разделе «Рекомендованные товары» легко моющиеся принадлежности для таких занятий, поддерживающих сенсорное развитие.'),
  ('28f1c509-c643-44be-b37c-9bbbdb368b42', 'Анализ режима ⏱️', 'На засыпание вечером уходит целый час? Посмотрите на график таймера сна. Возможно, уже давно пора сократить дневной сон и укладывать малыша вечером пораньше.'),
  ('e4b4940d-8946-4ebd-8a09-0e41f12848e2', 'Уборка вместе 🧹', 'Нужно прибраться дома? Пока вы подметаете комнату, дайте малышу тряпочку — пусть тоже помогает. О том, как превратить совместную уборку в весёлую игру, читайте в Блогах.'),
  ('08a08f0f-d89f-412b-a0e0-06835ec16be6', 'Ночной крик 🤖', 'Малыш просыпается среди ночи с криком и не узнаёт вас? Это может быть ночной страх. Сразу спросите у Anacan AI, как правильно действовать и почему малыша не следует будить.'),
  ('0b568eaa-4297-4b84-983b-14d42c18fb06', '«Почему?» не заканчиваются 🤔', 'Малыш хочет понять мир и найти всему логичное объяснение. Узнайте у Anacan AI, как терпеливо и без раздражения отвечать на его бесконечные вопросы. Ваше терпение — вклад в его будущее.'),
  ('e029b1ab-4432-4819-9a9e-c44e5506a20c', 'Право выпить кофе горячим ☕', 'В комнате беспорядок? Пусть пока остаётся. Выделите себе 10 минут и наконец выпейте этот кофе горячим. Вы не обязаны быть идеальной.'),
  ('7d7930a8-9ab0-45ba-bbf4-3a10238d3d72', 'Шоколад, съеденный тайком 🍫', 'Зашли на кухню и тайком от малыша на ходу перекусили чем-нибудь сладким? Не ругайте себя. Чтобы выдержать дневную суету, мама имеет полное право немного поднять уровень сахара в крови.'),
  ('946cf6ed-b93e-4326-a1b8-4af737be38ff', 'Сцена для папы 🎭', 'Ваша фраза «Доедай» больше не действует. Передайте эстафету папе. Когда он превращает ложку в летящий самолёт, упрямство каким-то чудесным образом исчезает. Отдыхайте и наблюдайте.'),
  ('c17a59df-f595-4941-acce-8426080226bf', 'Кризис из-за ложки не того цвета 🥄', 'Случился конец света, потому что вы дали еду не зелёной, а жёлтой ложкой? Глубоко вдохните. Не ищите в этом логики: малыш просто проверяет, может ли он управлять окружающим миром. Просто поменяйте ложку и улыбнитесь.'),
  ('202cf19c-e94a-473d-b9ba-56a3c22509c2', '«Давай я помогу» 🧽', 'Малыш выхватывает у вас тряпку, пока вы вытираете пыль? Он хочет почувствовать себя большим. Дайте ему небольшую влажную тряпочку. Грязи после такой уборки может стать больше, зато малыш будет горд собой.'),
  ('4f32f07a-4c87-40d2-83db-3d4785cda04f', 'Акустика дома 🤫', 'Малыш с трудом уснул днём. Теперь даже малейший шорох в доме может свести вас с ума. Сразу включите Шумомер, закройте окна и наслаждайтесь этой абсолютной тишиной.'),
  ('f750ae50-4664-4363-8c07-389c3fa0e9cb', 'Война из-за обуви 👟', 'Малыш надел правый ботинок на левую ногу и категорически не хочет его снимать? Пусть так и остаётся. Сейчас эстетика и правильность не важнее его ощущения свободы.'),
  ('bcbba6df-cc6d-45d3-b424-d121d2ee2ecb', 'Подружиться с темнотой 🌙', 'Полностью выключите свет в комнате. Лягте рядом и очень тихо, шёпотом расскажите малышу о том, что произошло за день. Шёпот — один из самых естественных способов подготовить мозг ко сну.'),
  ('db4f7065-c5e8-4316-a750-ff341f726db5', 'Маленький художник 🎨', 'Малыш рисует круги карандашом на стене или на бумаге? Это большой скачок в развитии моторики.'),
  ('eacddbb3-0cac-4a07-a3b8-0e2751f215e2', 'Начинаете искать детский сад? 🏫', 'Ближе к 3 годам вы всё чаще задумываетесь о детском саде? Если вы устали размышлять в одиночку, присоединяйтесь к Сообществу Anacan и спросите других мам об их опыте и рекомендациях.'),
  ('37d0e7fb-1a1f-4126-b2cd-6303007be080', 'Воображаемое чаепитие ☕', 'Малыш протягивает вам пустую чашку и говорит: «Пей чай»? Символические игры — настоящее достижение в развитии. С большим удовольствием выпейте воображаемый чай комнатной температуры из этой чашки.'),
  ('aaf79d19-89d8-4b33-8891-ceb716e86559', 'Вся одежда в пятнах 🎨', 'Пижама в пятнах от еды, а вся одежда — от краски? Дети не должны расти без единого пятнышка: они исследуют мир и пачкаются. Пользуйтесь силиконовыми нагрудниками, а об остальном позаботится стиральная машина.'),
  ('d6cb9a79-b32c-4069-9d3c-ac4297c600b6', '15-минутный побег 🛀', 'Зашли в туалет, закрыли дверь и просто смотрите в телефон? Да, это самый популярный у мам способ ненадолго сбежать от суеты и отдохнуть. Побудьте в тишине, ни перед кем не отчитываясь.'),
  ('0db2d13e-0a0c-45f3-a6f3-c4bf73384a78', 'Твёрдое «Не целуй меня!» 🛑', 'Когда кто-то из родственников хочет его поцеловать, он отворачивается и отталкивает? Не нарушайте его телесные границы! Умение протестовать против прикосновений без разрешения — важное условие его здорового будущего.'),
  ('aaaf42f2-3e96-489f-b1d3-e331bf487627', 'Ночные страхи — это реально 😭', 'Среди ночи малыш просыпается с плачем, не открывая глаз, и никого не слышит. Это ночной страх. Не трясите и не пытайтесь его разбудить. Просто будьте рядом и дайте ему почувствовать себя в безопасности.'),
  ('be944652-2efc-45de-a928-8d34a23e4645', 'Детокс на природе необходим 🌳', 'Сегодня домашний хаос стал невыносимым? Сразу загляните в раздел «Погода и одежда», оденьтесь по погоде и отправляйтесь в ближайший парк. Свежий воздух — лучшее успокоительное для ребёнка.'),
  ('09900d01-e715-436d-95eb-cb7b3165dfb1', 'Новая версия слов 🗣️', 'Вместо «вода» говорит «вава», а вместо «большой» — «басой»? Это звучит так мило, что трудно не рассмеяться. Но каждый раз доброжелательно повторяйте правильный вариант слова, чтобы мозг малыша запоминал верное произношение.'),
  ('9853e360-5dcb-4105-84a8-77759e13bdcd', 'Пусть малыш придумает конец сказки 🪄', 'Вам обоим уже надоели классические книги. В этот раз предложите ребёнку самому выбрать концовку истории в «Умных сказках». Спросите: «Как ты думаешь, кто помог герою?» — и дайте волю его воображению.'),
  ('d5f06496-2705-48a5-8325-2f0c28ac0a0f', 'Когда энергия на нуле 🔋', 'Сегодня совсем ни на что нет сил? Выберите среди полезных рецептов смузи, который можно приготовить за 5 минут: взбейте в блендере напиток, богатый железом и витаминами, и выпейте его прямо на ходу. Позаботьтесь о себе.'),
  ('42bb5c65-e45f-45b5-8da0-322b9acd1ab4', 'Список покупок спасает 🛒', 'Понадеялись на память, сходили в магазин и вернулись без подгузников? Такое бывает. Возьмите за привычку записывать всё необходимое в «Список покупок» — пусть приложение напоминает вместо вас.'),
  ('8f5ba264-bfbc-4e71-b81e-4cbb2fe23c54', 'Неожиданный вечер вдвоём 🥂', 'Ребёнок неожиданно рано уснул! Не тратьте этот редкий момент на уборку дома. Сядьте напротив партнёра, выключите телевизор и просто спросите друг друга, как прошёл день.'),
  ('92ad5bcb-5fa6-44a6-8e27-05fc8347c1e3', 'Инженерия с пазлами 🧩', 'Малыш упорно пытается вставить фигурки в подходящие отверстия. Даже если он ошибается и сердится, не спешите помогать. Именно методом проб и ошибок он учится решать задачи.'),
  ('2fb64a2b-9948-4425-9837-80add71d4e54', 'Папина экспедиция в парк 👨‍👧', 'Материнство — не круглосуточное дежурство 24/7! Поручите сегодняшнюю прогулку папе. Пусть они вместе испачкаются в грязи, а вы прилягте на диван и насладитесь тишиной.'),
  ('9928c8dc-9b21-49a6-b0c4-fd4704041409', 'Скачок роста и веса 📏', 'Штанины опять стали короткими? Малыш растёт прямо у вас на глазах! Внесите текущие показатели в «Трекер развития» и с гордостью посмотрите на кривую роста — результат ваших бессонных ночей.'),
  ('ed4eff7e-2e68-4d65-af30-186f1086a150', 'Чудо классической музыки 🎶', 'Под вечер малыш без видимой причины стал раздражительным. Выключите телевизор, приглушите свет и включите в комнате очень тихую классическую музыку. Гармония воды и музыки изменит атмосферу.'),
  ('331370dc-1940-499c-abdb-15eb6fc3307a', 'Тайные агенты в супе 🥦', 'Малыш объявил бойкот всему зелёному? Не переживайте. Измельчать овощи в пюре и прятать их в котлетах и соусах с помощью плана питания — один из самых старых и полезных маминых приёмов.'),
  ('a9d400f1-6a44-4584-a532-eeed75cc3207', 'Придуманные песенки 🎤', 'Расставляя игрушки, малыш напевает себе под нос слова, которых нет ни в одном языке. Одновременно развиваются его словарный запас и чувство ритма. Обязательно добавьте этот новый музыкальный этап в «Трекер развития».'),
  ('e7308375-84bd-4b4e-9322-163dcd46ff8e', 'Упрямая пижама 👕', 'Одевание превратилось в настоящую битву? Предоставьте выбор ребёнку: «Ты хочешь красную пижаму или синюю?» Эта маленькая хитрость даст ему почувствовать, что решение принимает он, и поможет прекратить борьбу.'),
  ('346ca24f-e8f9-47c9-9cc2-dc1b86281214', 'Тревога разлуки 🥺', 'Даже когда вы выходите из комнаты всего на секунду, малыш плачет вслед за вами. Тревога разлуки иногда возвращается. Каждый раз отзывайтесь и успокаивайте его издалека: «Я здесь, я на кухне, скоро приду».'),
  ('afa94b0b-8399-4813-8b1a-8a243185fcf4', 'Давление идеала 🛑', 'Другие дети уже называют цвета, а ваш ребёнок не хочет? Немедленно перестаньте сравнивать! Каждый ребёнок развивается в своём темпе. Ваш малыш идёт своим путём, и это совершенно нормально.'),
  ('d5610b5c-f92a-4668-b551-ccf2ba5bd9e4', 'Секретная тактика папы 👨‍🍼', 'Дневной усталости с вас уже достаточно. Вечером доверьте папиным играм подготовку ребёнка ко сну и чистку зубов, а сами спокойно посидите в стороне с чашкой чая.'),
  ('47b60c96-b788-4cad-9b79-643917c1b944', 'Вопросы о здоровье ребёнка 🤖', 'График роста и веса ребёнка в 32 месяца внезапно вас встревожил? Не ищите на интернет-форумах страшные заболевания — узнайте точные, научно обоснованные факты у Anacan AI.'),
  ('7f82c861-b627-4e20-b2ed-f2fb9f45756b', 'Естественная атмосфера для сна 🤫', 'Первые полчаса после засыпания — время, когда мозг наиболее чувствителен. Чтобы заглушить звуки с улицы, включите в комнате негромкий белый шум, например шум дождя.'),
  ('9bea836b-e06e-49f0-af98-259fe4009523', 'Я вам покажу! ☝️', 'Малыш показывает на всё пальцем и задаёт вопрос за вопросом. Он хочет, чтобы вы называли ему окружающий мир. Это большой скачок в развитии речи! Даже если вы устали, терпеливо повторяйте названия предметов.'),
  ('68ebc7a3-cb63-4696-9089-9b8d5bd20d47', 'Просто обнимите 🫂', 'Не нужны ни игры, ни книги, ни сказки. Сегодня вечером просто прижмите малыша к груди, вдохните его чудесный запах и прошепчите в темноте, как сильно вы им дорожите.'),
  ('e7127e7f-2c80-4b8e-aba6-2bcc0bbe7513', 'Уборка вместе 🧹', 'Нужно прибраться дома? Пока вы подметаете комнату, позвольте малышу помогать вам, протирая поверхности тряпочкой. О том, как превратить уборку в весёлую командную работу, читайте в блогах.'),
  ('f0084bbf-ef12-44c3-80b2-42b0bd99f526', 'Я очень устала 🔋', 'Все ждут от вас энергии, но ваша батарейка разрядилась. Сегодня ничего не готовьте — закажите еду. Быть идеальной мамой не означает делать всё в одиночку. Разрешите себе отдохнуть.'),
  ('001946c3-28e7-4dd7-a8dd-6edeeb1c5013', 'От круга к фигурам 🎨', 'Рисует карандашом круги на стене или бумаге? Эта шалость на самом деле говорит о большом скачке в развитии мелкой моторики.'),
  ('447f446e-b226-43bb-8269-02d7d4965189', 'Гармония воды 🛀', 'После целого дня в беготне устали и малыш, и вы. Во время тёплой ванны включите на фоне успокаивающие звуки природы. Гармония воды поможет подготовиться ко сну даже самому упрямому ребёнку.'),
  ('706c71ad-a073-4d24-bc8e-9dc899c5ba4e', 'Истерика в магазине 🛒', 'Малыш кричит у кассы, требуя сладости? Совершенно не обращайте внимания на осуждающие взгляды окружающих. Спокойно установите зрительный контакт, объясните правило и твёрдо придерживайтесь своего решения.'),
  ('4144a3ff-720b-4a72-a2d5-5866dd12fa04', 'Режим сбился? ⏱️', 'Вечером засыпание занимает больше 1 часа? Посмотрите график таймера сна. Возможно, уже давно пора значительно сократить дневной сон и укладывать малыша вечером пораньше.'),
  ('556e8775-c182-4e9f-b2c6-f0cf109ff616', 'Подражание животным 🐶', 'Малыш не только издаёт звуки, но и ползает как собака и крадётся как кошка? Язык тела соединяется с воображением. С энтузиазмом присоединяйтесь к этой игре вместе с ним на ковре.'),
  ('b521243e-fc9e-4c87-849b-f17e742b8529', 'Кризис дневного сна 🥱', 'Не хочет ложиться и плачет? Ближе к 3 годам некоторые дети начинают отказываться от дневного сна. Вместо борьбы объявите «тихий час» и предложите малышу просто спокойно поиграть в кровати с игрушками.'),
  ('9d29683b-c9aa-4b14-81df-782b8e1da8f5', 'Не хочет засыпать и боится темноты?', 'Полностью затемните комнату и покажите на стене сделанные руками тени птицы и собаки. Превратите страх в весёлую игру и помогите малышу подружиться с темнотой.'),
  ('a452ae82-775c-477d-b99f-ddd24ddd54fa', 'Сигналы во время еды 🥣', 'Съедает две ложки, говорит, что наелся, и убегает со стула? Не заставляйте его. Здоровые отношения с едой гораздо важнее, чем необходимость доесть всё на тарелке. Когда проголодается, сам попросит.'),
  ('aa995666-2118-43a4-9171-858348f38b54', 'Истории в картинках 📖', 'Увидев в книге животных или детей, малыш трогает их и спрашивает: «Что он делает?» Зрительное восприятие развивается удивительно быстро. Вместе придумывайте подробные и забавные истории о персонажах.'),
  ('076945c8-0a00-4e34-b0d0-2a0bb6a70d19', 'Режим сна меняется? 😭', 'Малыш просыпается посреди ночи и не хочет спать. Не сердитесь на него. Постарайтесь выяснить причину, а затем мягко поглаживайте, давая почувствовать, что вы рядом, и подождите, пока он снова уснёт.'),
  ('3d9ffa52-2fa2-4130-82de-58bdbc77e7b6', 'Сюрпризы погоды ⛅', 'Собираясь на прогулку, не дайте погоде обмануть вас, чтобы малыш не замёрз. Не судите о ней только по виду из окна: с помощником по погоде и одежде подберите комплект, который лучше всего подходит для ветра на улице, и спокойно выходите из дома.'),
  ('50a3f6bc-f0a4-4606-972d-9c8a2cc70695', 'Польза самостоятельной игры 🧸', 'Вы не обязаны развлекать малыша каждую минуту и постоянно придумывать для него игры. Скука — первая ступень к развитию детского творчества. Позвольте ему самостоятельно исследовать что-нибудь в комнате.'),
  ('0e8938b3-51a2-479f-a598-94b98e255136', 'Забытые покупки 🛒', 'Каждый раз в магазине забываете купить самое важное? Список покупок уже ждёт вас в приложении. Запишите туда всё необходимое, чтобы ваш партнёр мог купить нужные продукты по пути с работы.'),
  ('2b8de8fb-82bc-4b54-a795-1fffd716ddd5', 'Общение с помощью языка тела 🗣️', 'Когда вы спрашиваете: «Пойдём?», малыш поднимает руки, а если чего-то не хочет — решительно качает головой. Его способность понимать речь невероятно выросла! Чаще отвечайте ему подтверждающими фразами.'),
  ('db645804-58ab-429b-bd1f-cae1d65c9e1e', 'Засыпание под музыку 🎶', 'Попробуйте успокоить беспричинные вечерние капризы с помощью лёгкой классической музыки. Часто этот простой, но действенный приём творит дома чудеса и наполняет комнату умиротворением.'),
  ('295a4c1e-3bba-40c5-820d-04095aefe60e', 'Кто займётся домашними делами? 🌪️', 'Домашние дела не сделаны? Пусть подождут. Попросите партнёра сегодня взять их на себя. А вы отдохните: вы — самый важный человек в этом доме, и вам необходимо восстановить силы.'),
  ('546e217e-8060-4a89-877d-29e71165dae1', 'Командная поддержка 🥂', 'Вы справились с ещё одним трудным днём. Когда малыш уснёт, налейте себе и партнёру чаю и поддержите друг друга словами: «Мы действительно отлично справляемся!»'),
  ('f23e5345-9d7c-4e2d-871d-a259a849da6f', 'Понимает смысл картинок 📖', 'Увидев персонажей в книге, малыш трогает их и спрашивает: «Что он делает?» Зрительное восприятие развивается удивительно быстро. Вместе придумайте для прочитанной книги новую, совершенно вымышленную концовку.'),
  ('3edbcdb0-49d0-4dd6-973b-d76b6099a642', 'Синдром уборки 🌪️', 'Вы убрали весь дом, но уже через 10 минут он снова напоминает место взрыва? Сегодня просто примите этот беспорядок. Сядьте на диван и не вставайте, пока не допьёте кофе.'),
  ('3eea40c1-536e-46c3-bd20-2051d2e3ccae', 'Дипломатическое решение папы 👨‍👧', 'Ваша фраза «Доешь всё» больше не действует? Передайте эстафету папе. Когда он превращает ложку в летящий космический корабль, упрямство каким-то чудом исчезает. Отдохните и понаблюдайте за представлением.'),
  ('ac669cdb-bbf4-4741-8460-56b46118bbec', 'Утренний адвокат приступает к работе 💼', '«Я надену не эту рубашку, а другую!» Теперь перед вами не просто ребёнок, а маленький адвокат, который ведёт профессиональные переговоры. Не спорьте — просто предложите 2 варианта, создав ощущение, что решение принимает он.'),
  ('8805c85d-beba-4d76-905f-2991bc6002f2', 'Победа над горшком 🚽', 'Малыш чувствует, что ему нужно в туалет, и сам бежит к горшку? Это большая победа!'),
  ('9a0661d6-3164-4575-bc05-58b2efdd3f26', 'Пусть сам придумает сказку 📖', 'Сегодня вечером отложите книгу в сторону. Пусть малыш сам расскажет историю! Спросите у Anacan AI, как с помощью диалога поддержать это удивительное развитие воображения.'),
  ('32681963-7779-41a7-9090-772ca76143b7', 'Разрешите беспорядок 🌪️', 'Устали каждый день складывать одни и те же игрушки в коробку? Сегодня не убирайте! Дом — не музей, а место, где кипит жизнь. Сосредоточьтесь не на беспорядке, а на радости вашего ребёнка от новых открытий.'),
  ('500b7216-41e0-45a9-a2b9-20687055dfdc', 'Теперь очередь папы 👨‍🍼', 'Дневной усталости с вас достаточно. Вечером поручите папе подготовить ребёнка ко сну, почистить ему зубы и надеть пижаму, а сами спокойно выпейте чаю в тишине.'),
  ('be6a944e-f3ba-401c-9b99-70457d5df68b', 'Мама, посмотри на меня! 👀', 'Когда вы смотрите в телефон или заняты другим делом, ребёнок подходит и поворачивает ваше лицо к себе? Ему нужно ваше полное внимание. Установите зрительный контакт и покажите, что вы слушаете его и что он важен для вас.'),
  ('e95e1a48-e2fe-47ab-898a-2c6c20ef5f3c', 'Предложения превращаются в сказки 🗣️', 'Ребёнок уже соединяет слова и рассказывает забавные выдуманные истории? Это настоящий лексический взрыв!'),
  ('13a8c002-9f52-4112-970b-14cac50a9b5c', 'Акустика комнаты 🤫', 'В момент засыпания чувствительность к звукам повышается. Проверьте Шумомер, чтобы оценить звуки с улицы, и включите в комнате негромкий белый шум (white noise).'),
  ('4892459c-b0fb-4a8c-89d7-1bb93e680c5b', 'Маленький инженер 🤔', 'Что будет, если это бросить? Для чего нужна эта кнопка? Ребёнок постоянно проводит физические эксперименты. Он учится! Ещё раз оцените безопасность дома с высоты его роста.'),
  ('a57ba6d4-a9da-4163-8ddf-e60b3ee296c5', 'Тайное сообщество мам 💬', 'Вам нужно принять непростое решение? (Например, выбрать детский сад). Советы опытных мам в Сообществе Anacan — это проверенные на практике решения из реальной жизни, о которых не прочитаешь ни в одной книге.'),
  ('dc8c6058-0791-46ab-b5d1-2637ff0b924e', 'Не доверяйте виду из окна ⛅', 'Собираясь на прогулку, не дайте виду из окна ввести вас в заблуждение. С помощью помощника по погоде и одежде подберите комплект, который лучше всего подходит для реальной температуры и ветра на улице, и спокойно выходите из дома.'),
  ('7325d8d6-eeac-417b-abca-d32163dd16b4', 'Спасение в супермаркете 🛒', 'Во время похода в магазин вы обязательно забываете купить что-то самое важное? Список покупок уже ждёт вас в приложении. Записывайте туда всё необходимое, чтобы ваш партнёр точно ничего не забыл купить по дороге с работы.'),
  ('d7e75209-c901-4086-8f01-b71b4374f127', 'Терапия водой 🛀', 'После целого дня в движении вы оба выбились из сил. Во время тёплой ванны включите на фоне успокаивающие звуки природы. Гармония воды подготовит ко сну даже самого упрямого ребёнка.'),
  ('f55edde1-4803-4d20-96d6-d40197fda19c', 'Решительное «Нет»! 🛑', 'Ребёнок отстраняется и твёрдо говорит «нет», когда кто-то хочет его поцеловать? Уважайте границы его тела. Умение возражать против прикосновений без разрешения необходимо для его здорового психологического развития.'),
  ('a279684f-8916-4183-8bdf-0b058193de01', 'Папины интонации 📖', 'Сегодня вечером дайте своим голосовым связкам отдохнуть. Пусть папа возьмёт на себя чтение любимых книг ребёнка — разными голосами, с выдумкой и юмором.'),
  ('acb821ae-037d-451e-905f-fae976b254b3', 'Личная собственность 🧸', 'Ребёнок не хочет давать свою игрушку пришедшему в гости малышу? Это не эгоизм, а защита личных границ. Учите его делиться не принуждением, а собственным примером.'),
  ('7794de7c-0d82-4deb-b825-a11099a42226', 'Бойкот дневного сна 🥱', 'Не хочет ложиться и сопротивляется? Некоторые дети в этом возрасте отказываются от дневного сна. Вместо борьбы объявите тихий час и предложите малышу просто спокойно поиграть с игрушками в кровати.'),
  ('a2143b10-3a17-415c-a09b-d16e4c9ace11', 'Разгадка ночного страха 😭', 'Малыш среди ночи просыпается с плачем, не открывает глаза и никого не слышит. Дайте функции «Анализ плача» послушать этот звук: если это ночной страх, не пытайтесь разбудить малыша. Просто будьте рядом и помогите ему почувствовать себя в безопасности.'),
  ('df260082-4554-4a41-9637-0bed22c395ae', 'Кризисы избирательного аппетита 🍝', 'Сегодня малыш отказывается от блюда, которое любил ещё вчера? Не превращайте приём пищи в поле боя. Проверьте недельный баланс с помощью инструмента контроля питания, а в разделе «Полезные рецепты» найдите необычные и забавные варианты подачи.'),
  ('181acf25-f33b-4b1f-a3df-4084c1837a73', 'Доктор для раненого мишки 🩺', 'Когда игрушка падает, малыш гладит её и говорит, что она плачет? У него развивается удивительное чувство эмпатии! Сразу отметьте этот важный этап становления личности в «Трекере развития».'),
  ('41b6bff2-f792-4d2c-a887-2fbdd7ee533a', 'Приглашение мелатонина 🌙', 'Чтобы малыш быстрее заснул, выключите в комнате все лишние источники света и экраны с синим свечением. Гормон сна (мелатонин) активно вырабатывается только в тёмной обстановке без электронных устройств.'),
  ('afdd5971-fffc-43af-9956-3bc9d2687359', 'Дипломатия в песочнице 🧸', 'Не хочет никому отдавать своё ведёрко в парке? Это не эгоизм, а лишь знакомство с понятием личной собственности. Не стыдите малыша, а предложите играть по очереди — и дипломатический кризис будет разрешён.'),
  ('0574f644-1505-478c-8228-ceb707400249', 'Зрительный контакт обязателен 🥂', 'Малыш неожиданно рано заснул! Не тратьте этот редкий момент на уборку дома. Сядьте напротив партнёра, выключите телевизор и, просто глядя друг другу в глаза, спросите, как прошёл день.'),
  ('091c7303-14ec-4220-83cd-0ec1c91a3ce2', 'Живой диктофон 🎙️', 'Малыш тут же, словно попугай, повторяет даже случайно сказанное вами слово? Он — ваше живое отражение. Вдвойне внимательно следите за словами и эмоциями в его присутствии: он всё копирует.'),
  ('e60389be-4932-49bf-9ebd-d4caa963b145', 'Реальность остывшего кофе ☕', 'Налить кофе, а через 3 часа выпить его ледяным — неписаный закон материнства. Сегодня измените правила! Оставьте малыша ненадолго самостоятельно поиграть с игрушками и выпейте этот кофе горячим за 10 минут. Вы это заслужили.'),
  ('28610640-860d-43af-8a5a-381f751b562e', 'Тайная буря мамы 🩸', 'Внезапная усталость, беспричинное желание плакать? Откройте «Трекер менструации». Возможно, у вас ПМС. Не вините себя: приготовьте перекус с магнием из раздела «Полезные рецепты» и прислушайтесь к своему телу.'),
  ('51272fb1-4e13-49cf-9f74-cdaa0749b5ed', 'Цифровой педиатр 🤖', 'График роста и веса 33-месячного малыша внезапно вас обеспокоил? Не ищите страшные заболевания на интернет-форумах — узнайте у Anacan AI точные, мгновенные и научно обоснованные факты.'),
  ('b5429001-8d63-464c-9e9d-56aab19950f8', 'Эффект Моцарта 🎶', 'Под вечер малыш вдруг стал агрессивным без видимой причины. Выключите телевизор, приглушите свет и включите в комнате очень тихую классическую музыку. Гармония воды и музыки волшебным образом изменит атмосферу.'),
  ('8510671a-e1a9-4df3-abde-5ad11cb9aee4', 'Лётные испытания 🧗‍♂️', 'Малыш бросается с дивана на подушки. Так он проверяет силу притяжения и собственную смелость. Вместо запретов создайте в комнате безопасную зону для прыжков и позвольте ему выплеснуть энергию.'),
  ('8f7f72ec-9698-4ef9-a7b6-a44bc3f231c0', 'Разгадка ночного плача 😭', 'Приступы плача, причину которых не удаётся понять, очень изматывают. Перестаньте гадать: воспользуйтесь инструментом «Анализ плача», чтобы распознать скрытое за звуком послание (боль, усталость) и успокоить малыша.'),
  ('a4f7c95b-7fff-41b8-a6d4-80ab1d481977', 'Мастер маскировки 🥦', 'Малыш откладывает овощи из супа в сторону, словно рассматривает их под микроскопом? Найдите в разделе «Полезные рецепты» рецепты соусов, в которых овощи станут незаметными. Изобретательность — главное тайное оружие мамы.'),
  ('30d43616-cc93-4cce-b2c3-cdd876b6c9e5', 'Война с зубной щёткой 🦷', 'Малыш не позволяет поднести зубную щётку ко рту и хочет всё делать сам? Превратите обязанность в игру. Пусть сначала он почистит зубы вам, а затем наступит ваша очередь.'),
  ('f865873b-dd5e-4259-93bf-a8d4ef0dc1b0', 'Протест против зелёного 🥦', 'Выбрасывает зелень из тарелки? Не превращайте трапезу в поле боя. Откройте в разделе полезных рецептов домашние кексы со спрятанными овощами и незаметно восполните запас витаминов.'),
  ('00bb1bab-f1b2-408a-929e-869ffd6367c6', 'Магия шёпота 🌙', 'Полностью выключите свет в комнате. Лягте рядом и очень тихо, на ушко, расскажите о том, что произошло за день. Шёпот — один из самых естественных и успокаивающих способов подготовить мозг ко сну.'),
  ('6948f738-9261-43c8-87d9-90b884505db8', 'Детектив по брокколи 🥦', 'Находит зелёные овощи в тарелке и отодвигает их в сторону? Переходите к искусству маскировки. В разделе полезных рецептов найдите хитрые блюда, в которых овощи можно превратить в пюре и спрятать во вкусных котлетках.'),
  ('c7ff87eb-a94f-4bb4-85c6-085ae172efe9', 'Первый концерт композитора 🎤', 'Расставляя игрушки, малыш напевает с особым ритмом слова, которых нет ни в одном словаре? Не прерывайте этот интеллектуальный прорыв — отметьте его первую композицию в Трекере развития.'),
  ('331b6c40-0fb5-4851-9134-928632566339', 'План побега на природу ⛅', 'Четыре стены уже действуют на нервы и малышу, и вам. Проверьте погоду и рекомендации по одежде, быстро соберитесь и отправляйтесь в парк. Свежий воздух помогает быстро остановить даже самые сильные истерики малыша.'),
  ('56824801-bf77-4597-b1ce-5aa469fe1db9', 'Золотая тишина 🤫', 'Домашний хаос наконец закончился, и малыш крепко уснул. Откройте шумомер, проверьте уровень тишины в комнате в децибелах и 15 минут наслаждайтесь этой золотой тишиной, не глядя ни на один экран.'),
  ('7614704a-6622-4005-bcc5-442f422f2e2c', 'Авангардная мода 👗', 'Натянул брюки на голову и гордо расхаживает по комнате? Не вмешивайтесь. Эти забавные эксперименты — проявление его стремления к свободе и индивидуальности. Да, выглядит нелепо, но такие моменты бесценны.'),
  ('45e0f5b4-5219-47b6-9a9e-bcadb9ed774d', 'Потеря памяти в магазине 🛒', 'Понадеялись на память, пошли в магазин и вернулись, забыв самое важное? Возьмите за привычку записывать всё необходимое в Список покупок в приложении — пусть вас выручает цифровая память.'),
  ('8cab638c-2941-4e59-9d14-fa8e3dd46600', 'Невидимые гости 👻', 'Смотрит на пустое место на диване, что-то говорит и даже наливает чай невидимому другу? Период воображаемых друзей в самом разгаре! Теперь малыш сам пишет сценарии своего мира. Наблюдайте за этим представлением с улыбкой.'),
  ('d368c6ed-7184-4b38-b97e-6f9c7890966b', 'Как вода смывает воспоминания 🛀', 'От беготни за весь день нервы на пределе и у малыша, и у вас. Тёплая ванна нужна не только для гигиены: воспользуйтесь волшебной силой воды, которая снимает напряжение и смывает весь накопившийся за день негатив.'),
  ('37a646c6-efce-4c74-8923-488fc7f72713', 'Папина смена на кухне 👨‍🍳', 'Материнство — не одиночный марафон. Пусть в выходной папа приготовит обед и накормит малыша, а вы прилягте на диван и насладитесь драгоценной передышкой.'),
  ('38899b21-6787-484d-901a-76cdc0b3deb6', 'Неужели только у меня так? 💬', 'Вы очень устали и думаете, что никто вас не понимает? Сразу напишите в Сообщество Anacan. Там тысячи мам, которые тоже не высыпаются, поддержат вас сообщениями «У меня так же» и придадут сил.'),
  ('c34613c3-022a-46ef-a284-68eea41b09f7', 'Пусть малыш напишет сценарий 🪄', 'Классические книги надоели вам обоим. В этот раз предложите малышу самому выбрать концовку в умных сказках. Перед сном разбудите его воображение вопросом: «Как ты думаешь, кто помог герою?»'),
  ('29d7734b-e03c-4396-8939-93b0dfe516dc', 'Запас питательных веществ для мамы 🥗', 'Чтобы накормить малыша, вы придумали 3 разных меню, а сами лишь перекусили на ходу? Выберите в разделе полезных рецептов витаминный салат, который готовится за 10 минут, и проявите заботу о себе.'),
  ('bdf82e6a-e184-465d-ab37-a709d395d1d4', 'Папин театр мимики 🤡', 'Когда ваши приёмы уже не помогают, странные звуки, которые издаёт папа, мгновенно спасают ситуацию. Во время вечерних капризов передайте инициативу ему, а сами наблюдайте со стороны за весёлым смехом.'),
  ('f6962d3f-b694-40e4-9faf-0cd32b36de3d', 'Маленький помощник 🧽', 'Вытираете пыль, а малыш выхватывает тряпку у вас из рук? Он хочет почувствовать себя взрослым и частью команды. Дайте ему влажную тряпочку. Скорее всего, он больше испачкает, чем уберёт, зато будет очень горд собой.'),
  ('ee52c904-b97d-4a34-b7fb-b60ab86aadcd', 'Энергетический батончик для мамы 🥑', 'В ежедневной суете не обедайте на ходу. Выберите питательный перекус из полезных рецептов и хотя бы 10 минут полежите на диване, поставив заботу о собственном питании на первое место.'),
  ('51decf20-cf70-4c72-beb9-3712b300a999', 'Марафон по игре в догонялки 🏃‍♂️', 'Теперь малыш не ограничивается ходьбой: когда вы его зовёте, он быстро убегает и прячется. Уберите из комнаты опасные препятствия и тоже присоединитесь к этой весёлой игре в догонялки.'),
  ('aff77c93-ed92-44bc-9afd-e64eb6ce5292', 'Откройте для себя психологию 📱', 'Вас утомляет, что ребёнок на всё отвечает «нет»? Читайте психологические блоги в приложении, чтобы понять глубинные причины этой бури развития, происходящей в его мозге.'),
  ('e18b761a-6fd6-438d-896c-ec7bd458b9c2', 'Сила темноты 🌙', 'Чтобы малыш быстрее заснул, выключите в комнате все лишние источники света и экраны планшетов. Мелатонин быстрее вырабатывается в тёмной обстановке без гаджетов.'),
  ('0953ad75-dec1-4dc2-9d50-5eb074aad008', 'Просто обнимите 🫂', 'Не нужны ни игры, ни книги, ни сказки. Сегодня вечером просто прижмите малыша к груди, вдохните его чудесный запах и прошепчите в темноте, как сильно вы им дорожите.'),
  ('4df5b42c-f87e-4fa7-b1d2-b3aa6d779c67', 'Машина «Что это?» ☝️', 'Он показывает на всё пальцем и спрашивает, как это называется? Малыш просит вас дать названия окружающему миру. Это огромный скачок в развитии речи! Даже если вы устали, терпеливо повторяйте названия предметов.'),
  ('fb8b7427-667b-4244-909c-df4ca467d79e', 'Вы тоже человек 🛑', 'Сегодня всё пошло не по плану? Не вините себя. Вы настоящая мама, а не отфильтрованная иллюзия из социальных сетей. Вашему ребёнку нужны просто вы.'),
  ('5a4437a7-7519-4a4e-9c66-e797d5e763f5', 'Режиссёр за работой 🎭', 'Глядя на персонажей в книге с картинками, малыш рассказывает полностью выдуманные им события? Его воображение сейчас на пике развития! С гордостью слушайте эти необычные истории, не перебивая.'),
  ('932de885-b10a-4cc0-af8a-8db540c3d060', 'Горячий чай и тишина 🍵', 'Забудьте о домашних делах — всё может подождать. Заварите чай с мелиссой по одному из полезных рецептов и насладитесь временем наедине с собой.'),
  ('ba3e9de9-b98f-4d3a-93a0-ef5b3f06f424', 'Терапия парком 🌳', 'В четырёх стенах вам становится тесно. Даже если на улице прохладно, тепло оденьте малыша и выйдите с ним в парк на 20 минут. Пусть он изучает листья и камни, а свежий воздух насытит его мозг кислородом.'),
  ('12d65ca5-dc2d-4959-8af5-51ab64abb6bf', 'Искусство на тарелке 🥦', 'Малыш отказывается от еды? Иногда дело не во вкусе, а во внешнем виде. Попробуйте сделать забавные рожицы из разноцветных овощей, чтобы пробудить его аппетит и превратить приём пищи в игру.'),
  ('27428d92-902e-4e8b-a566-975a32a7bf6a', 'Весёлый хохот 🤡', 'Когда ваши попытки не помогают, ситуацию спасают странные звуки, которые издаёт папа. Во время вечерних капризов сразу передайте инициативу ему, а сами наблюдайте со стороны с улыбкой.'),
  ('71ce1c15-b947-45d9-8c0e-c8a77ece4ef7', 'Дикая природа дома 🐶', 'Малыш не только издаёт звуки, но и ползает как собака и ластится как кошка? Язык тела и воображение удивительным образом объединяются. Присоединитесь к нему и поиграйте вместе на ковре.'),
  ('c0f3d36a-8d02-476e-a6a5-3dfb6c2aa133', 'Босые ножки 👣', 'Малыш получает особое удовольствие, когда ходит босиком и касается разных поверхностей. Стимуляция нервных окончаний на стопах незаменима для его неврологического развития, поэтому разрешайте ему ходить без носков.'),
  ('c3c4fb6d-e99b-442f-b18d-4a0a69488a0a', 'Цифровая память 🛒', 'Отправляясь в магазин, вы обязательно что-нибудь забываете? Список покупок уже ждёт вас в приложении. Запишите туда всё необходимое, чтобы ваш партнёр по дороге с работы купил именно то, что нужно.'),
  ('cb069764-7f58-461b-a159-7d553277ecda', 'Звуковое воображение 🪄', 'Сегодня вечером создайте для малыша особое приключение в умных сказках — историю о храбром кролике, который не боится пылесоса. Преодолевать страхи с помощью сказок гораздо легче.'),
  ('62149695-6298-4aba-847f-c8ce0b1eb19a', 'Не заденьте самолюбие 🛑', '«Я сам!» — заявляет малыш и отказывается от любой помощи. Даже если он надел обувь не на ту ногу, не вмешивайтесь. Сохранить его уверенность в себе важнее, чем правильно надеть обувь.'),
  ('86650154-88a4-4c7d-ab75-32f1a232aa9d', 'Конец сомнениям 🤖', 'Вас обеспокоили внезапные изменения в поведении ребёнка? Не ищите на интернет-форумах страшные заболевания — узнайте у Anacan AI точную, мгновенную и научно обоснованную информацию.'),
  ('d8fdf53e-3f50-42fc-a36a-84c2b2cbfbee', 'Страж сна 🤫', 'Первые полчаса после засыпания — время наиболее активной работы мозга. Создайте комфортную обстановку в комнате с помощью шумомера. Иногда даже тихий звук дождя помогает малышу погрузиться в глубокий сон.'),
  ('5820d5b6-2a79-44ac-a012-46235cfe81f4', 'Всего 5 дней до 1000! 🎈', 'Обратный отсчёт почти завершён! Вы вот-вот преодолеете большой и поистине легендарный путь длиной ровно в 1000 дней. Улыбнитесь и уже сейчас начинайте готовиться к юбилею и придумывать весёлые идеи для праздника!'),
  ('7ac49f38-01ad-4503-8e74-f0a0bf7621d8', 'Тихий час с книгой 🥱', 'Малыш не хочет ложиться и упорно сопротивляется? В этом возрасте некоторые дети отказываются от дневного сна. Вместо борьбы объявите тихий час и предложите ему просто полистать книгу в кровати.'),
  ('d50eb553-5709-43ce-81ea-ce5014437b1a', 'Письмо гордости 📝', 'На всём этом долгом пути со взлётами и падениями ваша главная сила — любовь к малышу. Откройте дневник настроения и напишите ему небольшое трогательное письмо, которое он прочитает в будущем и которым вы сможете гордиться.'),
  ('20a1ef6d-4573-433a-a2b7-db48ed6c1114', 'Маленький помощник 🧸', 'Просите малыша принести обувь — и он действительно идёт и приносит её? Его словарный запас и способность понимать речь сейчас на пике! Привлекайте его к небольшим домашним делам, чтобы укрепить уверенность в себе.'),
  ('9b33bb20-6873-451a-abe7-084cc34eff93', 'Вы — настоящая команда 🌟', 'Каждый уверенный шаг малыша — результат общих усилий вас и вашего партнёра.'),
  ('9d370453-5ab2-46ed-b11b-b4f3648ebe3e', 'Беспорядок дома, счастливая мама 🌪', 'Одежда скопилась горой, а посудомоечная машина переполнена? Пусть всё пока останется как есть. Попросите партнёра сегодня взять домашние дела на себя. Отдохните — вы главная опора этого дома.'),
  ('32252794-61c5-419d-b7e8-539bc9987fc9', 'Урок анатомии 👀', 'Когда вы спрашиваете: «Где плечи?», малыш показывает на них пальцем? Его способность понимать сейчас на пике! Продолжайте игру с более сложными частями тела, чтобы обогатить его словарный запас.'),
  ('520e2a70-086b-4229-864f-4de7f51683ae', 'Сила воды 🛀', 'После целого дня в движении устали и малыш, и вы. Во время тёплой ванны включите на фоне успокаивающие звуки природы. Гармония воды подготовит ко сну даже самого упрямого малыша.'),
  ('8083b651-9df8-40f8-a78a-23401da54600', 'У мамы вкуснее 🥣', 'Малыш отодвигает свою тарелку и тянется к вашей еде? Дети всегда больше доверяют выбору родителей. В разделе полезных рецептов выбирайте блюда, которые подойдут вам обоим.'),
  ('23868e91-8f1b-41db-955e-cd3d4e20a70a', 'Тактика прогулки ⛅', 'Собираясь на прогулку, не дайте обманчивой погоде застать вас врасплох и не допустите, чтобы малыш замёрз. Не судите о погоде только по виду из окна: с помощником по погоде и одежде подберите комплект, подходящий для ветра на улице, и спокойно выходите из дома.'),
  ('418dbea1-2468-4df0-ad94-f76ab3c14a42', 'Фабрика мелатонина 🌙', 'Чтобы малыш быстрее заснул, выключите в комнате все дополнительные источники света и экраны планшетов. Мелатонин быстро вырабатывается только в темноте и без гаджетов.'),
  ('dcb96656-d377-4147-b075-f440d05b3b54', 'Правила вежливости 👋', 'Когда кто-то выходит за дверь, малыш сам машет рукой на прощание! Так формируются социальный интеллект и эмпатия. Почаще поддерживайте эти проявления вежливости.'),
  ('32e0ad68-9613-493b-b8b0-dc5729e770dd', 'Убираемся вместе 🧹', 'Нужно прибраться дома? Пока вы подметаете комнату, позвольте малышу тоже помочь вам, протирая поверхности тряпочкой. О том, как превратить уборку в командную работу и весёлую игру, читайте в Блогах.'),
  ('a3a1222f-3b9a-40aa-a53c-50cc656ba7c7', 'Режим сбивается? ⏱️', 'Вечером малыш долго не может заснуть? Посмотрите график таймера сна. Возможно, уже пора значительно сократить дневной сон и укладывать малыша вечером пораньше.'),
  ('ee3cf122-8fc4-43ea-906b-ef2165dd428d', 'Упрямое «Я уже большой!» 🛑', 'Малыш хочет вмешиваться во всё и замедляет дела? В этой забавной борьбе за самостоятельность предлагайте ему выбор из нескольких простых вариантов.'),
  ('98562e83-4876-4c00-8dbc-2ad2897e54b5', 'Чудо длиной в 1000 дней! 👑', 'ПОЗДРАВЛЯЕМ! Ровно 1000 дней вы идёте по этому бурному и утомительному, но самому ценному пути в мире! Непременно отпразднуйте этот особенный день вашей победы и с гордостью поделитесь ею в Сообществе Anacan!'),
  ('c186b66b-55e3-4f3f-9de6-a20601b6d88b', 'Победный танец вашей команды 🥂', 'Сегодня вечером отпразднуйте вместе с партнёром усталость, слёзы и радость этих 1000 дней. Поставьте на стол свечу и с огромной радостью отметьте победу вашей нерушимой команды!'),
  ('f26096f7-035d-44ff-ad7c-b1f1eaade001', 'Вы справились! 📈', 'Какой огромный путь прошёл ваш малыш! Хрупкий страх первых дней теперь сменился невероятной уверенностью. Вы с гордостью прошли эти 1000 дней! Вы действительно великолепны!'),
  ('5cf4179d-ca05-4825-ae51-8ae8bda4be3e', 'Запись в дневнике 📝', 'Когда малыш уснёт, откройте Дневник настроения. Что сегодня утомило вас больше всего, а что рассмешило? Дайте своим чувствам полную свободу и облегчите душу.'),
  ('f9781f63-e578-4e40-8665-b3d4fa014824', 'Реальность после победы 🚀', 'После вчерашнего юбилея сегодня утром вас снова встретили разбросанные игрушки и крики «Не хочу!» Жизнь продолжается. Сделайте глубокий вдох: вы лучше всех управляете этим хаосом.'),
  ('fde949fd-c8a2-4b0b-a364-0d008da67880', 'Кризис дневного сна 🥱', 'Малыш не хочет ложиться и плачет? Ближе к 3 годам некоторые дети начинают отказываться от дневного сна. Вместо борьбы объявите Час тишины и предложите малышу просто полистать книгу в кровати.'),
  ('092fe7ca-f54f-4986-9a3f-884d05ff6c27', 'План побега из кроватки 🛌', 'Малыш пытается перелезть через бортик кроватки? Ещё раз проверьте безопасность комнаты. Возможно, приближается время перехода на кровать для детей постарше.'),
  ('9fdf76d2-ea34-465e-99e8-537978d670c9', 'Начинаются вопросы «Как?» 🤔', 'На смену вопросам «Почему?» приходят вопросы «Как это работает?». Малыш пытается разобраться в устройстве вещей. Запаситесь терпением и давайте ему короткие, логичные объяснения.'),
  ('c9428152-a130-431b-ac89-26275023d613', 'Перерыв для мамы ☕', 'Когда малыш играет самостоятельно, не спешите сразу заниматься домашними делами. Беспорядок в комнате никуда не денется, а ваша энергия может закончиться. Присядьте и выпейте горячий кофе.'),
  ('b69e774e-9d7b-4da5-9fb4-5b192b81f712', 'Воображаемые сюжеты 🧸', 'Малыш рассказывает сказку плюшевому мишке или пьёт чай из пустой чашки? Символические игры — настоящий шедевр развития. Не мешайте ему, а понаблюдайте со стороны за этим маленьким режиссёром.'),
  ('c131d97d-34fe-4f0d-ab19-20860829451c', 'Потребность в тишине 🤫', 'Первые полчаса после засыпания — самое чувствительное время. Проверьте уровень шума в децибелах с помощью шумомера и отрегулируйте громкость телевизора в соседней комнате.'),
  ('3af3aa71-d08b-4f87-af96-9527f5f91ec1', 'Утренняя зарядка 🤸‍♂️', 'Вы ещё не проснулись, а он уже прыгает на вас в кровати. Самый шумный, но самый любимый будильник в мире! Начните день с улыбки и зарядитесь его неуёмной энергией.'),
  ('8c84402b-2c57-4668-ad1d-96d138e6ba29', 'В магазин без списка — то ещё испытание 🛒', 'Сходили в магазин и вернулись без самого нужного? Такова материнская память. Не полагайтесь на неё: заведите привычку сразу записывать каждую мелочь в список покупок.'),
  ('90c41ad8-7de7-4c6d-ba3d-cf1aad328939', 'Чай при свечах 🕯️', 'Малыш уснул. Выключите свет и зажгите на столе свечу. Не ради романтики, а просто чтобы успокоить нервы и дать отдых глазам после насыщенного дня.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ru = v.t, body_ru = v.b
FROM (VALUES
  ('4390f43b-f533-4c56-8aa2-5901fd06c8f5'::uuid, 'Искусственный интеллект, реальная помощь 🤖', 'Что с психологической точки зрения стоит за упрямством малыша по любому поводу? Не ищите в интернете пугающие статьи. Попросите Anacan AI дать краткое научное объяснение кризиса у детей в 33 месяца.'),
  ('70560836-1d71-42c8-8235-1ad990694b3b', 'Сбившийся режим ⏱️', 'Вечером укладывание занимает больше 1 часа? Посмотрите график в таймере сна. Возможно, дневной сон уже давно пора сократить, а вечернее укладывание перенести на более раннее время.'),
  ('dfed41fd-982b-4955-b70f-6d43247a4468', 'Катастрофа с расчёсыванием волос 🪮', 'Малыш кричит так, будто расчёсывание и прикосновения к волосам — самая страшная пытка в мире? Прекратите борьбу. Сначала дайте расчёску ему и позвольте расчесать вас, а потом поменяйтесь ролями.'),
  ('5b72c8ce-753e-4283-9bd2-18995d662a91', 'Запасы железа 🥩', 'Малыш бледный или у него нет аппетита? Проверьте потребление железа в инструменте контроля питания. Вместе с мясом обязательно предложите салат с лимонным соком: витамин C помогает лучше усваивать железо.'),
  ('b0a26358-dcc7-4a57-8694-6e91e9d4baaa', 'Учимся делиться игрушками 🧸', 'Перед походом в парк поговорите с малышом: Сегодня мы будем играть игрушками по очереди. Да, он всё равно может не поделиться, но это абстрактное правило важно повторять снова и снова.'),
  ('c1d1533f-3d3f-4fb5-a549-d74668c72b3d', 'Папина тактика укладывания 👨‍🍼', 'Вечером малыш не хочет надевать пижаму и убегает? Передайте эстафету папе. Когда он превращает одевание в борьбу или забавную игру, малыш сам не замечает, как оказывается в пижаме.'),
  ('3aee856b-a30f-48de-84ad-3c91f83ed092', 'Загадка от природы 🍁', 'Превратите прогулку по парку в игру: Давай найдём самый большой жёлтый лист! Природа — самая большая интерактивная школа для малыша.'),
  ('746f5afe-3705-4073-a3c0-ff69e92f5a25', 'Интерес к стиральной машине 🧺', 'Малыш сидит перед стиральной машиной и сосредоточенно смотрит на вращающееся бельё? Это совершенно бесплатное и успокаивающее занятие. Не мешайте ему, а сами воспользуйтесь моментом и отдохните.'),
  ('8da8a36e-5d67-4dd0-ac14-245b62a8846a', 'Признание в дневнике настроения 📝', 'Возьмите телефон. Вместо того чтобы листать социальные сети, откройте дневник настроения и подробно запишите всё, что сегодня выводило вас из себя. Цифровая терапия действительно помогает.'),
  ('71f7d0fb-698f-4308-ad55-a95583a3469b', 'Время мелатонина 🌙', 'Чтобы начал вырабатываться гормон сна, как минимум за 1 час до укладывания исключите телевизор, планшет и другие источники синего света. Темнота и тишина — лучшие помощники для сна.'),
  ('9d1de334-e45a-491d-8075-45ce379df7ad', 'Игра «Я — мама!» 🎭', 'Малыш грозит кукле пальцем и сердится с вашей интонацией? По комнате ходит ваша маленькая копия. Увидеть себя со стороны забавно, но это также повод обратить внимание на своё поведение.'),
  ('fc7921b2-eab6-4a37-aad0-63611df47ad7', 'Отказ от дневного сна 🥱', 'Малыш не хочет ложиться, хотя глаза уже слипаются? Ближе к 3 годам такое сопротивление вполне типично. Не заставляйте его: приглушите свет в комнате и объявите тихий час с рассматриванием книг.'),
  ('2a74e43d-d2e3-45ad-8762-627a59c365b2', 'Утренний каприз из-за цвета 🔴', 'Малыш просил еду на зелёной тарелке, но, когда вы её принесли, расплакался: Я же говорил, на красной! Не ищите логики. Просто переложите еду на красную тарелку и поберегите свои нервные клетки.'),
  ('e0133a48-f7ee-4d9e-9e82-8b0c0ba8095b', 'Общение в парке 🌳', 'Малыш не столько играет с другими детьми, сколько занимается своей игрой рядом с ними? Параллельная игра совершенно естественна для этого возраста. Учитывая погоду, оденьте его и отправляйтесь в парк.'),
  ('88b776b7-0d43-49f1-b31c-da27294feb6f', 'Быстрый педиатр 🤖', 'Столкнулись с откатом в приучении к горшку (potty training)? Не изматывайте себя — спросите у Anacan AI, как справиться с этим психологическим процессом.'),
  ('92aa3f00-711e-43bd-a2d7-1f3bfbc7744d', 'Упрямое «Моё!» 🛑', 'Малыш хочет, чтобы всё принадлежало только ему? Представление о том, что нужно делиться, ещё не сформировалось до конца. Не заставляйте его, а вместо этого постепенно вводите правило «Давай играть по очереди».'),
  ('adf1cd9b-1322-48c3-a05b-72b8aa90f9cc', 'Волшебный фон для сна 🪄', 'Малышу трудно заснуть? Создайте особую сказку в «Умных сказках» и превратите освоение новых привычек в увлекательную историю.'),
  ('269b7d14-00d0-4c42-84b9-6759e61b0baa', 'Эстетический пищевой кризис 🥦', 'Малыш не ест корочку хлеба или ломтик огурца, потому что они некрасивые? Избирательность в еде порой принимает причудливые формы. Узнайте в плане питания самые искусные способы измельчать овощи в пюре и незаметно добавлять их в блюда.'),
  ('3619cb9e-e29f-4149-9f97-e65685c72f61', 'Утренний концерт начался 🎤', 'Проснувшись, малыш сразу включает максимальную громкость и что-то напевает? В 7 утра его батарейка уже полностью заряжена. Протрите глаза и с улыбкой наслаждайтесь шоу этой маленькой поп-звезды.'),
  ('4e5a485c-972c-4f14-b15e-6d0c1f1b8961', 'Потоп в ванной 🛀', 'Игры с водой нужны малышу не столько для чистоты, сколько для превращения комнаты в аквапарк. Пусть вода брызжет во все стороны. Тёплая вода и веселье смоют всё упрямство, накопившееся за день.'),
  ('22cad895-d987-4916-ac97-672fe0a05ac0', 'Ловушка «Ещё одну» 📖', 'Малыш не хочет ложиться спать и тянет время, прося ещё одну сказку. Отложите классические книги. Создайте в «Умных сказках» короткую историю для сна с придуманными им персонажами и завершите вечерний ритуал.'),
  ('4aedb3f8-6caf-4ec5-a8d3-5b5f77908beb', 'Тайный шоколадный перерыв 🍫', 'Мама, которая тайком перекусывает чем-нибудь сладким стоя за кухонным шкафом, мы вас видим! Не вините себя. Вы имеете полное право на этот скачок глюкозы, чтобы выдержать весь шум.'),
  ('c5c0175d-de40-45a7-97f9-43392b324696', 'Маленький домашний диктатор 👑', '«Садись не туда, а сюда!», «Это сделаешь не ты, а я!» Малыш хочет управлять всем домом. Не подавляя резко его волю, сохраняйте равновесие, говоря: «Ты сядешь сюда, а я — туда».'),
  ('2f5f6f47-30c9-4601-933d-5baa445585db', 'Сеанс массажа от папы 💆‍♂️', 'Сегодня вы долго были на ногах, и от постоянной беготни за малышом у вас отваливается спина. Как только ребёнок уснёт, попросите партнёра сделать вам 10-минутный массаж плеч. Вы — опора дома, а опоре тоже нужно отдыхать.'),
  ('e70841e8-9af5-471e-9ff6-b28774448a7f', 'Не вмешивайтесь 🧦', 'Пятка носка оказалась сверху, но малыш надел его сам и ходит с видом самого гордого человека на свете. Ни в коем случае не вмешивайтесь. Ощущение самостоятельности важнее правильно надетого носка.'),
  ('f3fc49f1-990c-4271-ab6c-21a94434e4c2', 'Глоток воздуха в сообществе 💬', 'Вы очень устали и чувствуете себя самой нетерпеливой мамой на свете? Сразу открывайте сообщество Anacan. Осознание того, что другие мамы переживают такие же кризисы, — мощная психологическая поддержка.'),
  ('3bcabb18-ba8e-4729-bb3a-959b28fdcaeb', 'Загадки облаков ⛅', 'Устали сидеть в четырёх стенах? Учитывая погоду, оденьтесь и отправляйтесь в парк. Просто сядьте и угадывайте, на что похожи облака в небе. Эта спокойная игра одновременно помогает мозгу отдохнуть и развивает его.'),
  ('8fab2e02-e35e-45f0-a10f-554adfe7c2c6', 'Домашний хаос наконец закончился.', 'Включите lofi-музыку, чтобы заглушить звуки с улицы и дать душе отдохнуть.'),
  ('9de02d84-1ac6-4478-a817-67045fcd6af5', 'Первая милая ложь? 🤥', '«Это не я разлил воду, это мишка». Внимание! Воображение малыша развилось настолько, что он уже может придумывать свою версию событий в собственных интересах. Не обвиняйте его во лжи, а улыбнитесь и скажите: «Передай мишке, чтобы он больше так не делал».'),
  ('541b84ef-a3ed-43ff-8a33-aa153668c840', 'Ночная буря 😭', 'Малыш без видимой причины проснулся среди ночи и плачет? Это газы или ночной ужас? Не гадайте: определите причину с помощью Анализа плача и успокойте малыша нежными объятиями.'),
  ('60323c41-a0d6-4029-8b71-994315dcb0cf', 'Горшочные промахи 🚽', 'Во время приучения к горшку малыш снова пописал на ковёр? Сделайте глубокий вдох. Если вы рассердитесь, это может привести к откату. Не тратьте нервы из-за того, что можно убрать: это всего лишь часть процесса обучения.'),
  ('1a8259f8-8cae-4f18-b5c2-ee44aa10346d', 'Маленький переговорщик в парке 🗣️', '«Можно я ещё немного поиграю, всего 5 минут!» — говорит малыш, пытаясь потянуть время. Понятия о времени у него пока нет, зато умение торговаться превосходное. Установите таймер и напомните о правилах мягко, в игровой форме.'),
  ('bf1a9cee-65ab-4eac-ad90-70c1631bbc46', 'Скачок роста 📏', 'Брюки стали короткими? Малыш быстро растёт! Внесите актуальные параметры в Трекер развития и с гордостью полюбуйтесь результатом своих бессонных ночей.'),
  ('cff0599d-3a80-4d02-94df-22f42e5f09f2', 'Пауза для двоих 🥂', 'Ребёнок уснул. Теперь отложите телефоны и домашние дела. Хотя бы 20 минут поговорите с партнёром о чём угодно, кроме ребёнка и счетов.'),
  ('5130988b-06fa-4ca0-8477-7c4e5105998f', 'Волшебный мир сказок 🪄', 'Сегодня вечером попробуйте в Умных сказках что-нибудь совсем новое: историю о маленьком облачке, которое исследовало небо. Подстройте голос под ритм сказки и мягко проводите малыша в сон.'),
  ('632fc2f4-f865-49e5-8a30-eef5c63d0d4a', 'Требование «Посмотри на меня!» 👀', 'Когда вы смотрите в телефон, малыш подходит, бьёт вас по руке или забирает устройство. И он совершенно прав. Ему нужны ваше внимание здесь и сейчас и полная вовлечённость. Установите зрительный контакт и дайте понять, что вы его слушаете.'),
  ('df191a16-4b37-4a90-bbd4-c8972ecc1670', 'Стойкие пятна, свободные открытия 🎨', 'Пижама в еде, а одежда — в краске? Дети не должны расти идеально чистыми: исследуя мир, они неизбежно пачкаются. Беспорядок — это подпись его творчества, поэтому не переживайте.'),
  ('43d613a7-90fe-4d48-880a-a0dadfb94dab', 'Операция «Спрятать овощи» 🥦', 'Малыш откладывает овощи из супа в сторону, будто рассматривает их под микроскопом? Найдите в Здоровых рецептах варианты соусов, в которых овощи станут незаметными. Креативность — главное оружие мамы.'),
  ('6fd78011-ad7d-48f0-9941-25d07912808e', 'Посмотрите вниз: что он исследует? 👣', 'Малыш особенно любит ходить босиком и касаться разных поверхностей. Стимуляция нервных окончаний на стопах важна для развития равновесия, поэтому разрешайте ему ходить без носков.'),
  ('dcc98b1b-6e09-41d3-9be6-78333aecdab4', 'Ночные защитники 🧸', 'Малыш боится темноты? Расставьте его любимых мишек и другие игрушки вокруг кровати и скажите: «Они будут защищать тебя до самого утра». Такая наглядная поддержка отлично помогает почувствовать себя в безопасности.'),
  ('3d8d4230-c58c-4f55-bb5e-c5c92f713201', 'Подтверждение тишины 🤫', 'После шумного дня, когда ребёнок уснёт, измерьте тишину в комнате с помощью Шумомера. Даже вид цифр, приближающихся к нулю, действует на мамин мозг как терапия.'),
  ('53046b7a-695e-4d17-9dda-231255060141', 'Утреннее «Нет!» 🛑', 'Малыш ещё не успел открыть глаза, а на любое предложение уже отвечает: «Нет!» На пороге 3 лет лучше не задавать вопросы, а сразу переходить к делу. Вместо «Давай умоемся?» скажите: «Пора умываться!».'),
  ('e5f27372-8ce2-40d6-acbc-12281fab28bb', 'Найдите время и для себя 🥑', 'Бесконечная суета лишила вас сил. Вместо перекуса на ходу приготовьте по Здоровым рецептам сытную витаминную тарелку и поешьте с удовольствием. Энергия вам точно понадобится.'),
  ('096e15b3-74ca-4180-ab20-07ce9b214b2a', 'Разговор шёпотом 🌙', 'Полностью выключите свет в комнате. Лягте рядом с малышом и очень тихо, шёпотом расскажите ему о том, что произошло за день. Шёпот — один из лучших способов подготовить мозг ко сну.'),
  ('41df7f7d-e272-4737-8498-6c866ab9545a', 'Обмен опытом 💬', 'Вас пугает, что ребёнок упрямится по любому поводу? Не ищите в интернете страшные статьи. Познакомьтесь с реальным опытом бывалых мам в Сообществе Anacan — и улыбнитесь.'),
  ('8ac94a1b-a693-498b-9e54-d59e3331d567', 'Профессиональный танцор 🎶', 'Услышав любой ритм — будь то музыка из рекламы или автомобильный сигнал, — малыш сразу начинает танцевать. Смотрите на жизнь так же весело! Присоединитесь к нему и устройте в комнате несколько минут безумных танцев.'),
  ('540ed6cc-ab45-42f3-bbdf-f7d1a37e6094', 'Секретная тактика папы 👨‍🍼', 'Дневной усталости вам и так хватает. Вечером поручите папе в игровой форме подготовить ребёнка ко сну и почистить ему зубы, а сами спокойно отдохните в стороне.'),
  ('75bb1e03-07ff-448a-b132-6eec4abf1a2d', 'Сложенная и разбросанная одежда 👗', 'Вы с большим трудом складываете одежду, а малыш приходит и в одно мгновение всё разбрасывает. Вместо того чтобы сердиться, превратите это в игру: посмотрим, кто дальше бросит эту футболку?'),
  ('ca77a3ff-10f8-4690-8926-270fe161b3d5', 'Хочу есть сам! 🥄', 'Берёт ложку и пачкает всё вокруг? Запустите таймер кормления. Не переживайте из-за разбросанной еды, а порадуйтесь самостоятельности, которую приобретает малыш.'),
  ('25c4de30-89c3-4f45-952f-3b21fb85b41e', 'Босоногий исследователь 👣', 'Не хочет надевать носки, убегает и прячется? Позвольте малышу немного походить босиком и почувствовать пол, ковёр и прохладную плитку. Развитие нервных окончаний на стопах очень важно для чувства равновесия.'),
  ('a0e0a012-48a8-4169-b4f6-62857311b266', 'Выключите свет — пора спать 🌙', 'Чтобы малыш быстрее уснул, выключите все дополнительные источники света и экраны планшетов в комнате. Мелатонин вырабатывается только в тёмной обстановке без электронных устройств.'),
  ('ac0003df-1b37-4e86-98c2-561682149d03', 'Поиски на природе 🍁', 'Оденьтесь по погоде и отправляйтесь на прогулку. Поиграйте в парке в поиск необычных камней и разноцветных листьев. В этом возрасте природа — самая большая интерактивная игрушка для малыша.'),
  ('85540a77-8c0c-40d1-bec5-6ddc93f07354', 'Забывчивость в магазине 🛒', 'Положились на память, отправились в магазин и вернулись, забыв самое важное? Возьмите за привычку сразу добавлять всё необходимое в список покупок — пусть приложение напоминает вам.'),
  ('bd0902bb-9be1-40b5-8e41-73f85b835f0e', 'Утренний помощник 🧑‍🍳', 'Малыш хочет помогать вам готовить завтрак. Просыплет муку, разольёт воду, испачкает кухню... Но благодаря таким упражнениям развивается его мелкая моторика. Будьте терпеливы.'),
  ('c929f83e-5e59-4728-8c79-df0502607758', 'Шоу папы-волшебника 🤡', 'Когда ваши приёмы уже не помогают, странные звуки, которые издаёт папа, мгновенно спасают ситуацию. Во время вечерних капризов передайте эстафету ему и со стороны наблюдайте за весёлым смехом.'),
  ('61f1a424-1da9-48ab-b336-92c9137ef39e', 'Терапия тёплой ванной 🛀', 'После целого дня в движении устали и малыш, и вы. Во время тёплой ванны включите на фоне успокаивающие звуки природы. Гармония воды поможет подготовиться ко сну даже самому упрямому ребёнку.'),
  ('8ae2c146-2d4a-4919-80fe-7f15c41cdc0e', 'Хочу налить сам! 💧', 'Малыш непременно хочет сам налить воду в стакан. Приготовьте салфетки и не подавляйте его самостоятельность. Сначала он будет разливать воду, но уже через несколько попыток вы удивитесь, как аккуратно он наполняет стакан.'),
  ('c8458955-5810-4609-a23d-82b155bf6112', 'Чувство эмоционального истощения 🔋', 'Чувствуете, что недостаточно хороши? Думаете, что не со всем справляетесь? Загляните в публикации Сообщества: вы не одиноки, и с вами всё в порядке. Вы — целый мир для своего ребёнка.'),
  ('87267db7-ab44-41b2-82ed-1d12fea90f71', 'Странная грамматика 🗣️', 'Малыш придумывает совершенно новые грамматические конструкции вроде «Я проголодался был» или «Он шёл и пришёл». Не поправляйте его строго — просто ответьте, повторив фразу правильно.'),
  ('9a6f7d87-06ae-42b3-a4d0-b7eff2923976', 'Совет Anacan AI 🤖', 'Хотите узнать, как помочь ребёнку общаться с другими детьми в парке? Не тратьте часы на поиски в интернете — задайте вопрос Anacan AI и мгновенно получите соответствующий этапу развития совет, одобренный педиатрами.'),
  ('a3b7ecf2-9668-46df-b331-9c7487819a32', 'Признаки ночного ужаса 😭', 'Если малыш внезапно плачет или кричит с закрытыми глазами, проверьте это с помощью Анализа плача. Если это ночной ужас, не пытайтесь его разбудить — просто оставайтесь рядом и молча дайте ему почувствовать себя в безопасности.'),
  ('181a440f-5684-4f29-a861-16adef184628', 'Время летит!', 'Оглянитесь назад и посмотрите, как многому вы научились. Этот маленький переговорщик уже умеет торговаться с вами по любому поводу. Гордитесь им и собой.'),
  ('31d8e844-a068-4aa5-8b2c-23a9d11616c4', 'Герой сказки 🪄', 'Классические книги уже наскучили вам обоим. В умных сказках сделайте малыша космонавтом и отправьте к звёздам или погрузите в морские глубины. Дайте волю воображению перед сном.'),
  ('4280853d-50c1-4092-8d31-3279f5e3d68a', 'Тихий час обязателен ☕', 'Если малыш категорически отказывается от дневного сна, не заставляйте его. Но установите 30-минутный Тихий час (quiet time). Пусть он побудет один в кровати с книгами, а вы сможете перевести дух.'),
  ('10fd3d36-ea93-4f52-8bc2-486b88206869', 'Дневник настроения 📝', 'Возьмите телефон. Вместо того чтобы листать социальные сети, откройте Дневник настроения и запишите на память самый забавный момент сегодняшнего дня, когда малыш рассмешил вас больше всего.'),
  ('502d3376-0322-4c07-aee1-71c209315c6b', 'Операция «Спрятанные овощи» 🥦', 'Малыш вылавливает овощи из супа и откладывает их в сторону? Не боритесь с ним. В плане питания вы найдёте самые необычные и хитрые способы превратить овощи в пюре и спрятать их в соусах.'),
  ('ad687f75-6bde-4ad1-8992-78906bd61fd5', 'Настойчивое «Мама, посмотри на меня!» 👀', 'Когда вы смотрите в телефон или занимаетесь делами, малыш подходит и выбивает его у вас из рук? Он хочет вашего безраздельного внимания, и это вполне естественно. 5 минут качественно проведённого времени с зрительным контактом помогут ему успокоиться.'),
  ('22e7c65d-25fb-4bbe-aa34-29a2d5e5e3ea', 'Игра «Побег из комнаты» 🏃‍♂️', 'Когда вы хотите надеть на малыша пижаму или футболку, он со смехом убегает из комнаты. Не сердитесь, а превратите это занятие в игру. Одеть его будет легче, если поиграть с ним в догонялки.'),
  ('322a385d-8940-4d2a-9d21-4777e2660139', 'Сводка погоды ⛅', 'Собираясь на прогулку, не позволяйте виду из окна ввести вас в заблуждение. С помощью помощника по погоде и одежде подберите комплект, который лучше всего соответствует реальной температуре и ветру на улице, и смело выходите из дома.'),
  ('9c87f5af-e2e2-4310-ab2c-98ff6d5521d4', 'Переход в беззвучный режим 🤫', 'Когда малыш засыпает, его чувствительность повышается. Соблюдайте тишину.'),
  ('af1711a8-2ca3-45c1-ae35-556b3b0e2d67', 'Папин дуэт перед сном 📖', 'Давайте сегодня вечером создадим в комнате особую атмосферу. Вместо чтения книги тихо спойте вместе с папой ритмичную песню, чтобы помочь малышу заснуть.'),
  ('b2328024-7846-4b25-a276-980c22ebcd52', 'Мама, не забывайте поесть 🥑', 'В повседневной суете не обедайте на ходу. Приготовьте необычный салат, богатый железом и кальцием, сядьте и поешьте с удовольствием. Ваша энергия — двигатель этого дома.'),
  ('e037ab2c-d2a8-49ed-a1df-aac78a584118', 'Первые шаги к дружбе 👫', 'В парке малыш впервые по собственной инициативе поделился игрушкой с другим ребёнком? Это большой шаг в развитии! Эгоцентризм ослабевает, а эмпатия формируется. Порадуйтесь за него и похвалите от всей души.'),
  ('1f9d373c-817c-4a86-9cb9-a9b3d9fac797', '10 минут при свечах 🕯️', 'Малыш уснул, и домашний хаос закончился. Выключите свет, просто смотрите в темноту или на пламя свечи и в течение 10 минут постарайтесь полностью освободить разум от мыслей.'),
  ('7ca4e4fb-3ef6-4d7f-b7a1-18d9264ed8c8', 'Поддержка сообщества 💬', 'Вас душит мысль: «Я уже никогда не стану прежней»? Поделитесь этим временным, но очень тяжёлым чувством с мамами в Сообществе Anacan и получите их поддержку.'),
  ('d270bdfa-5a84-42b7-8b44-3231febd32b3', 'Непослушные косички 🪮', 'Малыш категорически не разрешает собирать или расчёсывать волосы? Прекратите борьбу. Встаньте перед зеркалом и сначала причешите свои волосы так, как он захочет, а затем предложите ему поменяться ролями.'),
  ('b155d377-4b41-487e-b8ee-74a365226635', 'Борьба за дневной сон 🥱', 'Если малыш отказывается, не заставляйте его. Вместо того чтобы снова и снова пытаться уложить его и изматывать себя, установите режим, при котором он спокойно играет с игрушками в комнате.'),
  ('b7283d95-1357-4ff9-9423-db4159e19c31', 'Командная победа 🥂', 'Ещё один трудный день позади. Сядьте напротив партнёра и чокнитесь стаканами чая: вы действительно легендарная команда и отлично со всем справляетесь!'),
  ('c932a08e-a484-4595-8fa6-e57165ffaf96', 'Трудности с умением делиться 🧸', 'Никому не даёт свою игрушку? Это не эгоизм, а этап развития. Ближе к 3 годам важнее научиться не делиться, а играть по очереди. Узнайте больше об этом у Anacan AI.'),
  ('23137ca6-6246-4dc7-b692-cdcd36eeac0f', 'Трёхколёсный велосипед 🚴‍♂️', 'Пытается крутить педали и ехать на велосипеде? Мышцы ног и координация переходят на новый этап развития! Поддерживайте малыша и выбирайте безопасные места для катания.'),
  ('b44d4b2a-f3eb-4e26-aa50-0105efb5648c', 'Витамины для мамы 🥑', 'Вы делаете всё, чтобы малыш был сыт. А как же вы? Выберите в разделе полезных рецептов лёгкий обед, богатый железом и кальцием.'),
  ('f62c402c-4ba9-489a-b6de-dde4e1aa3aae', 'Ночная смена папы 👨‍🍼', 'Не берите все ночные пробуждения на себя. Разбудите партнёра: быть командой — значит поровну делить ответственность.'),
  ('10872122-03c1-4660-aabc-490c724034c9', 'Карманы, полные сокровищ 🍁', 'Вернулись из парка и нашли в карманах малыша 3 камешка, 1 сухой лист и веточку? Для него это настоящие сокровища. Ваша задача — лишь незаметно убрать их, пока они не разлетелись по всему дому.'),
  ('8f84e032-e8dd-4d1f-b3c6-5d57937006dd', 'Не ищите логики 👑', 'Требует на завтрак мороженое или вчерашний чечевичный суп? В доме появился новый диктатор. Быстро переключите внимание, предложив выбор. Например: «Ты хочешь яблоко или банан?»'),
  ('907a5bc5-4a7e-48ec-977c-d9c5440faba0', 'Поводы сбежать из кровати 🏃‍♂️', 'Просит воды, хочет в туалет, собирается поцеловать штору в комнате... Мозг придумывает всё новые способы не засыпать. Установите границы: только 1 стакан воды — и всё. Будьте последовательны.'),
  ('4ab501ea-956f-4adc-a27e-2e2bc99f59c6', 'Татуировки на теле 🖍️', 'Несколько секунд тишины порой бывают опасными. Зашли в комнату и увидели, что малыш разрисовал руки фломастером, словно татуировками? Сделайте глубокий вдох. Мелкая моторика развивается, а фломастер с кожи всё равно смоется.'),
  ('93712bd1-e114-4739-841f-9d8901785feb', 'Папа-партнёр 👨‍👧', 'К вечеру силы на нуле? Скажите: «Я выхожу из игры» — и передайте малыша папе. Убрать комнату, которую они вместе разгромили, легче, чем справляться с ребёнком в одиночку.'),
  ('9a4e49fa-28ce-4422-86d1-9b77699fd24c', 'Потребность в клетчатке 💩', 'Малыш много бегает, но забывает пить воду. Следите за его стулом в горшке. Если есть риск запора, добавьте в меню овсянку и сливу.'),
  ('2743b373-11c6-4a72-a371-988483c30fb4', 'Вражда с тенью 👻', 'Малыш внезапно заплакал на улице или в комнате? Возможно, причина в тени, которая за ним следует! Ближе к 3 годам воображение порой становится причудливым. Обнимите малыша и с улыбкой познакомьте его с тенью.'),
  ('344cf14d-0511-4f06-86bb-38e1e79297c3', 'Пищевой хирург 🥦', 'Не ест блюдо, а лишь с хирургической точностью вылавливает из него маленькие рисинки или зелёные специи? Откройте план питания и узнайте, как можно измельчать овощи до состояния пюре.'),
  ('85bf1b2b-8bd2-41a8-8e81-bd414469ff03', 'Попрощаться со всем 🧸', 'Перед сном малыш хочет пожелать спокойной ночи машинке, стулу и даже дверной ручке? Это один из новых ритуалов отхода ко сну, которые он освоил. Не торопите его.'),
  ('4699f7a7-a05a-4fb5-bcc3-1031cc990173', 'Воображаемые деловые звонки 🍌', 'Берёт банан или пульт и с серьёзным видом разговаривает по телефону на выдуманном языке? Малыш в точности копирует язык вашего тела. Снимите это на видео и сохраните на будущее — потом будете много смеяться.'),
  ('77b18a3d-16c2-454b-9fe4-daea00f5a342', 'Режим сбился? ⏱️', 'Вечером засыпание занимает больше 1 часа? Посмотрите график в таймере сна. Возможно, пришло время полностью отказаться от дневного сна и укладывать малыша вечером раньше.'),
  ('9ed1ae4d-be3f-4fb2-a1fd-f7b060b22469', 'Битва с зубной щёткой 🪥', 'При виде зубной щётки малыш крепко закрывает рот? Не превращайте гигиену в сражение. Загляните в раздел «Рекомендуемые товары», выберите музыкальную щётку и превратите эту мучительную рутину в весёлую игру.'),
  ('3d5dc682-22fb-45d2-8bc6-6a1ae9873a3a', 'Упрямое «ножки не идут» 🛑', 'По дороге из парка малыш вдруг садится на землю, говорит, что ножки больше не идут, и просится на руки? Это не усталость, а манипуляция. Превратите ситуацию в игру, сказав: «Посмотрим, сможешь ли ты допрыгать до дома, как зайчик?»'),
  ('b948ea64-f471-4d36-958a-85e04a0250f1', 'Прятки с горшком 🚽', 'Когда малышу нужно в туалет, он прячется за шторой или диваном? Самое время перейти в раздел «Блоги» и прочитать о научно обоснованных этапах приучения к горшку.'),
  ('b9e8fff7-f7f2-410b-a103-f4cd6c6231f8', 'Выплеснуть злость в дневник 📝', 'Кто-то сказал вам: «Ты же дома, от чего ты устаёшь?» Сразу откройте «Дневник настроения» и выплесните всё раздражение на экран с помощью пальцев. Лучше записать свои истинные чувства, чем натянуто улыбаться.'),
  ('0de1aee1-4ccd-4daa-b9f3-ed4d6ab70bfc', 'Папино сказочное шоу 📖', 'Сегодня вечером в комнате будет звучать не ваш голос, а папин. Пусть он читает сказку и забавно меняет голос, изображая героев. А вы отойдите в сторонку и наслаждайтесь смехом.'),
  ('2fc731d4-47df-4b97-8f67-c7df6aabac96', 'Мамин секретный шоколад 🍫', 'Мама, которая, едва малыш отвернётся, кладёт в рот кусочек шоколада и быстро его жуёт, — эта глюкоза по праву ваша. Вам нужно зарядиться энергией, чтобы выдержать весь этот дневной марафон.'),
  ('edb08c0a-b151-4f7a-9713-c903f3f5c584', 'Необычный лучший друг 🥄', 'Вокруг столько дорогих игрушек, а малыш нашёл на кухне силиконовую лопатку, весь день носит её с собой и даже укладывает спать? Детский мозг удивителен. Не мешайте — пусть любит свою лопатку.'),
  ('36ebb286-2e4d-4e44-a91d-6c026199737c', 'Поиски на природе ⛅', 'Четыре стены уже утомили ваш мозг. Учитывая погоду, подберите подходящую одежду. Выйдите на улицу с простой миссией — найти жёлтый лист: малыш выплеснет энергию, а вы сможете немного подышать свежим воздухом.'),
  ('4b98ee52-d8a1-4d7a-9183-64cdd8482ef0', 'Опасные словечки 🤐', 'Малыш повторяет услышанное где-то плохое слово, смеётся и ждёт вашей реакции? Ваше главное оружие — не реагировать. Не смейтесь, не сердитесь, просто проигнорируйте. Он забудет.'),
  ('c2b89303-d5b8-4b81-97cd-3a091f15bb05', 'Измеряем золотую тишину 🤫', 'Наконец-то малыш уснул! Включите шумомер и следите на экране за абсолютным уровнем шума в комнате (0-10 децибел). Для мозга уставшей мамы нет лучшего массажа, чем видеть эти цифры.'),
  ('45a51286-f051-4f99-a23c-39a189481dfa', 'Упрямая пижама 👗', 'Малыш не хочет снимать испачканную за весь день пижаму? В 3 года эстетика не имеет значения. Если ему не холодно, пусть походит так ещё несколько часов.'),
  ('4c871abf-c886-4fbd-909f-95e344736fa3', 'Я в умной сказке 🪄', 'Вы уже выучили классические книги наизусть. Откройте «Умные сказки», сделайте своего ребёнка главным героем, а его комнату — местом, которое предстоит покорить, и устройте необычный сеанс перед сном.'),
  ('9f3be00e-0091-4500-91da-22dc9ba62d93', 'Критик мультфильмов 📺', 'Малыш пересказывает вам мультфильм по своим правилам грамматики и серьёзно объясняет, кто и куда пошёл. Слушайте его внимательно и с удивлением. Пусть он почувствует себя самым умным человеком на свете.'),
  ('89c52f3b-2e4b-4c88-b0bc-f1bbe0891bb8', 'Те, кто просыпается раньше солнца 🌅', 'В 6 часов утра малыш уже на ногах, а вы без сил? Спросите у Anacan AI, как скорректировать этот режим. Помните: недосып не навсегда, всё пройдёт.'),
  ('e229522e-360b-4392-8cfc-620f6326286c', 'Шампанское для двоих 🥂', 'Малыш уснул. Даже если шампанского нет, налейте в бокалы горячий чай и чокнитесь с партнёром со словами: «Мы благополучно пережили и этот трудный день». Вы прекрасные партнёры.'),
  ('f802a634-da9b-44e2-a965-9f94ea543fd1', 'Сюрприз в списке 🛒', 'Перед походом в магазин вы открыли «Список покупок» и увидели, как подошедший сзади малыш нажал на экран телефона и добавил туда шоколад. Да, они разбираются в технологиях лучше вас!'),
  ('0d0524d6-a4ad-4051-b779-b554d981748f', 'Сморщенные пальчики в ванной 🛀', 'Играть с водой так весело, что малыш не хочет выходить из ванны, даже когда пальчики уже сморщились. Предупредите его за 5 минут и поставьте таймер. Правило «Когда прозвенит таймер — выходим» часто срабатывает.'),
  ('1460be31-c5b7-4f0f-9a6b-7ff5c2085c36', 'Борьба с причёской 🪮', 'Малыш проснулся, а волосы торчат во все стороны, будто их наэлектризовало. Но стоит ему увидеть расчёску — начинается погоня. Вместо расчёсывания смочите ладони водой и пригладьте волосы руками, чтобы избежать борьбы.'),
  ('fc5667d9-2c85-42d4-a92c-e90c3b994a0f', 'Мнение искусственного интеллекта 🤖', 'У вашего ребёнка появилась странная привычка, например грызть ногти, а статьи в интернете вас напугали? Остановитесь. Спросите Anacan AI об истинной причине, подтверждённой педиатрами, и успокойтесь.'),
  ('01349acb-919c-490a-bfce-f75e04518130', 'Доктор уже рядом 🩺', 'Малыш берёт игрушечный стетоскоп, прикладывает его к вашей груди и просит дышать. Вы — пациент, а он — главный врач. Подыграйте ему: прилягте, закройте глаза и отдохните хотя бы 5 минут, пока идёт лечение.'),
  ('d58d064b-a397-425d-9d57-3f6068e31cf1', 'Всплеск энергии 🏃‍♂️', 'Малыш буквально лезет на стены? Проверьте погоду, подберите подходящую одежду и обязательно выйдите на улицу. 30 минут активного бега на свежем воздухе — лучший залог крепкого вечернего сна.'),
  ('d96fbe0f-26f7-4473-9f0b-34109da6a744', 'Магия шёпота 🌙', 'Полностью выключите свет в комнате. Лягте рядом и очень тихо, шёпотом расскажите малышу о том, что произошло за день. Шёпот — один из самых естественных и успокаивающих способов подготовить мозг ко сну.'),
  ('2521dffb-415b-4bec-81f4-b18ee93644d8', 'Привыкаем к темноте 🌙', 'Чтобы малыш быстрее заснул, выключите все дополнительные источники света и экраны планшетов в комнате. Выработка гормона мелатонина ускоряется только в спокойной и тёмной обстановке.'),
  ('8ca17d8b-45e4-4184-b598-9b59778d5b0c', 'Время маме подзарядиться 🔋', 'Малыш самостоятельно собирает пазл и уже 10 минут сидит тихо. А вы хотите потратить это время на уборку дома. Нет! Идите и прилягте на диван. Вам тоже нужно подзарядиться, чтобы сохранить силы до вечера.'),
  ('c145c120-a19a-477b-922c-6f3ffc430787', 'Придуманная грамматика 🗣️', 'Малыш придумывает странные и забавные формы слов и предложений. Его речь развивается! Не смейтесь и не поправляйте его напрямую — просто повторите фразу правильно, подтверждая её смысл.'),
  ('6e5eaf14-24e1-4f23-8d49-63a035b843ff', 'Поддержка в Дневнике настроения 📝', 'Кажется, никто не замечает, насколько вы устали? Дневник настроения в приложении всегда готов вас выслушать. Запишите туда все мелочи, которые сегодня выводили вас из себя, и освободите голову от лишних мыслей.'),
  ('b83f22c8-15c6-43cf-9689-94f8a790e4b9', 'Испытания с едой 🥣', 'Сегодня малыш выплёвывает всё, что ещё вчера ел с удовольствием. Если у него нет проблем с зубами, скорее всего, он просто проверяет границы. Поищите в разделе полезных рецептов вкусные разноцветные котлетки со спрятанными овощами.'),
  ('fe01f44d-664a-4a34-8ce6-39e87f7fdab2', 'Иллюзия 5 минут ⏱️', 'Малыш просит посмотреть ещё всего 5 минут, но пока не понимает, сколько это длится. Поставьте таймер на телефоне и объясните, что после сигнала время закончится. Пусть виноватой будет техника, а не вы.'),
  ('1fc309f5-659f-4b2e-bf6f-e17296d830ff', 'Верхом на папе 🐴', 'Малыш ещё не выплеснул всю энергию и не хочет ложиться спать? Покататься по дому верхом на папиной спине и вдоволь посмеяться — самый быстрый и весёлый способ израсходовать остаток энергии. Теперь дело за папой.'),
  ('69846205-68bb-4476-a7e0-45d4e68fae26', 'Маме нужна тишина 🩸', 'Вас раздражает каждый звук? Загляните в Трекер менструации. Возможно, вашему организму нужен отдых. Приготовьте по одному из полезных рецептов перекус, богатый магнием, и уделите время себе.'),
  ('c6dcd330-d5df-4d87-b7a0-d8ab33a73063', 'Плач без причины 😭', 'Малыш начинает плакать, едва открыв глаза, и вы не понимаете почему? Это не каприз, а эмоциональная перегрузка. Обсудите ситуацию с нашим экспертом Anacan AI и узнайте, как вести себя во время такого кризиса.'),
  ('6ac257ab-47ac-4e61-a9e4-2b538df0a8dc', 'Папина очередь на кухне 👨‍🍳', 'Сегодня готовить обед и кормить малыша — задача папы! А вы посвятите это время себе: просто прилягте или отдохните.'),
  ('ba525880-dd70-46d8-9c0c-f0fb9b49240c', 'Сон под звуки природы 🪄', 'Классическая музыка не помогает? В «Умных сказках» выключите сказку и включите фон со звуками дождя или леса. Монотонные звуки природы словно по волшебству убаюкивают малыша.'),
  ('ba82984e-ccd6-40f9-b991-bf586ff48b9d', 'Взрослые вздохи 😔', 'Сидя на диване, малыш вдруг глубоко вздыхает, совсем как взрослый. Как же хорошо он вас копирует! Просто с улыбкой наблюдайте за его драматичной мимикой.'),
  ('268f32e3-3ad0-45c0-aef4-aba7ce610179', 'Кухонные трагедии 🧑‍🍳', 'Пока вы готовите, малыш непременно хочет помочь у плиты и насыпать соль. Позволите — блюдо будет испорчено, не позволите — он расплачется. Дайте ему пустую миску и воду и предложите приготовить собственный суп.'),
  ('e612b840-bcec-4199-920b-e4d2f37aa7cb', 'Проверка списка 🛒', 'Вы добавили в список покупок всё необходимое для праздничного дня? Убедитесь, что воздушные шары и маленькие сюрпризы тоже там. Отправьте партнёру последнее напоминание из приложения.'),
  ('eb50f918-4009-4323-94a0-e8fd1ccc9f1d', 'Контроль тишины 🤫', 'Первые полчаса после засыпания — время наибольшей активности мозга. Проверьте обстановку в комнате с помощью шумомера. Нейтрализуйте звуки, доносящиеся из окна, и создайте тихую и тёмную обстановку.'),
  ('0cde3d33-fabc-43f7-bcba-b8c6c307e26e', 'Режиссёр сказки 🪄', 'Включите «Умные сказки» и сегодня вечером позвольте малышу направлять сюжет. Спросите: «Куда теперь отправится герой?» — и пусть он заснёт под придуманную им невероятную концовку.'),
  ('60a51ebc-ca29-4910-bc60-cd0880a0539a', 'Нелогичные слёзы 🐶', 'Малыш 15 минут рыдал из-за того, что встреченная на улице собака на него не посмотрела? Не ищите логики. Для него это действительно глубокое огорчение. Признайте его чувства, сказав: «Я знаю, тебе хотелось, чтобы собака на тебя посмотрела».'),
  ('e0a781fd-ff93-41bb-aced-df42a4ca9525', 'Примиритесь с домашним хаосом 🌪️', 'Вся комната завалена игрушками? Сейчас важнее не уборка, а весёлые минуты, проведённые вместе. Игрушки и завтра останутся на месте — не изнуряйте себя. Иногда смириться с беспорядком — лучший способ отдохнуть.'),
  ('0cd42656-20ce-4f47-aca2-4978ae93880d', 'Снова промахи с горшком? 🚽', 'Малыш уже научился ходить на горшок, но снова случаются промахи? Это совершенно нормальный регресс. Не давите на него — спросите у Anacan AI, как преодолеть этот психологический барьер без кризисов.'),
  ('3164bc6c-fe7e-4273-94e8-6750bee50d0a', 'Вдохновение из блогов 📱', 'Какие скачки развития происходят у ребёнка ближе к 35 месяцам? Что он уже должен уметь? Загляните в блоги о развитии в приложении и порадуйтесь тому, как далеко продвинулся ваш малыш.'),
  ('4d45db57-1817-4fc6-ad71-f2aeb4cd1050', 'Подготовка к важному дню 💆‍♂️', 'Когда малыш уснёт, поздравьте друг друга с партнёром с завтрашней важной датой и сделайте друг другу лёгкий массаж плеч. Чтобы встретить праздник полными сил, вам обоим нужно хорошо отдохнуть.'),
  ('41e90866-d00f-459e-8936-e28d83f9d539', 'Забег перед сном 🏃‍♂️', 'Вместо сна малыш прыгает на диване? А просьбы принести ещё немного воды всё не заканчиваются? Включите таймер сна и твёрдо придерживайтесь установленных границ.'),
  ('4f9eced2-7736-4f35-ad7d-6205edaad1e4', 'Папина очередь играть 👨‍👧', 'Материнство не должно быть бесконечным марафоном. Пусть сегодня папа поможет малышу выплеснуть энергию в парке, а вы насладитесь уединением на диване.'),
  ('e18107ed-4459-4f40-b466-2d79ae0ff98c', 'Зимняя шапка летом 🧢', 'Малыш хочет одеться совсем не по погоде? В борьбе за самостоятельность предложите ему несколько небольших вариантов на выбор.'),
  ('37ca7eb9-999f-4245-9a90-94f0e28e6df4', 'Бесконечная машина вопросов 🤔', 'Бесконечные «Почему?» и «Как?» утомляют вас? Спросите у Anacan AI, как давать логичные ответы на вопросы маленького исследователя и не терять терпения. Ваше терпение помогает ему развиваться.'),
  ('70e9f70c-b53f-462f-9274-badc9beebd25', 'Дневник тишины 📝', 'Домашний ураган наконец уснул. Теперь возьмите телефон и напишите в дневнике настроения благодарственное письмо себе за то, что пережили этот день. Вы справляетесь.'),
  ('cac1efaa-10e1-4f19-b586-507cb8610102', '«Я сам(а)!» 🛑', 'Хочет самостоятельно завязать шнурки, и на это уходит 10 минут? Не торопите малыша, дайте ему время. Попытки и ошибки закладывают основу будущих навыков решения проблем.'),
  ('078ff563-48f3-4bd6-81ac-93fc21a3bab7', 'Кофе и медитация ☕', 'Малыш перевернул комнату вверх дном? Забудьте об уборке. Пока он занят своими делами, присядьте на диван, выпейте горячий кофе и 10 минут просто смотрите на стену, позволяя мозгу перезагрузиться.'),
  ('710f54a9-baa0-4889-a361-f7615894b552', 'Играем в профессии 🩺', 'Лечит игрушечного мишку или ремонтирует машинки? Символическая ролевая игра сейчас в самом разгаре.'),
  ('9f105ce0-5653-4d0b-8d96-2ed9abdc7e4a', 'Театр теней 🐰', 'Не хочет засыпать? Полностью затемните комнату и устройте на стене театр теней с помощью рук. Это один из самых весёлых способов преодолеть страх темноты.'),
  ('3a84b553-313a-486c-95e8-2a799895283c', 'Не плачь 🫂', 'Увидев в парке плачущего ребёнка, подходит к нему и гладит? Эмпатия официально включилась! С гордостью наблюдайте со стороны за этим прекрасным проявлением доброты.'),
  ('77ff1ffc-86a7-418d-bad4-4d026f199772', 'Пора переходить на большую кровать? 🛏️', 'Малыш пытается перелезть через бортик кроватки? Возможно, вы уже задумались о переходе. Спросите у Anacan AI о правилах безопасности и наиболее подходящем времени для перехода на детскую кровать.'),
  ('e176efcb-aafc-4480-93eb-e1978282a880', 'Папин час чтения 📖', 'Сегодня вечером дайте своим голосовым связкам отдохнуть. Пусть папа возьмёт на себя чтение любимых книг малыша, озвучивая героев разными голосами.'),
  ('65edab42-e5b4-4da3-8b99-8e271dd3fc16', 'Устанавливает личные границы ✋', 'Отстраняется или говорит «нет», когда кто-то хочет его поцеловать? Уважайте телесные границы малыша и требуйте того же от окружающих. Именно с этого начинается уверенность в себе.'),
  ('c46434f8-d6b6-4038-89e7-8bc38a5332c2', 'Магия умной сказки 🪄', 'Устали от классических сказок? Задайте умной сказке необычную тему: приключения волшебного динозавра, который любит есть овощи.'),
  ('d941dd67-309a-49cb-833c-78b38c4762e7', 'Дипломатия в выборе одежды 👗', 'Хочет надеть летние брюки посреди зимы? Сразу откройте инструмент «Погода и одежда» и с помощью изображений на экране логично объясните малышу, что на улице холодно.'),
  ('0ff4754d-26cd-4a0c-9aad-d8a1cbe8e5a6', 'Цена тишины 🤫', 'Малыш наконец заснул. Теперь даже самый тихий звук в доме действует вам на нервы. Установите допустимый уровень шума в комнате с помощью шумомера и включите на фоне непрерывный белый шум.'),
  ('bf9527d0-d7b0-4cb8-8523-c499e2e95693', 'Начинаем считать 🔢', 'Пытается говорить «один, два, три», поднимаясь по лестнице или расставляя игрушки? Так закладываются основы математического мышления. Вместе громко считайте предметы в комнате.'),
  ('ebcc858d-cfdb-4af6-a7c6-c1e46f778ba5', 'Синдром выгорания 🔋', 'Хочется кричать из-за всего? Вы столкнулись с выгоранием. Зайдите в Сообщество Anacan и напишите: «Я очень устала». Вы увидите, что тысячи женщин в эту самую секунду разделяют ваши чувства.'),
  ('405360f8-7a97-471c-825c-355eafed365d', 'Отказ от дневного сна 🥱', 'Категорически не хочет спать днём и активно сопротивляется? Ближе к 3 годам некоторые дети отказываются от дневного сна. Попробуйте заменить его «тихим часом без сна».'),
  ('6740b19e-f070-42e2-9b6e-76434890c90f', 'Пробуждаются воспоминания 🧠', 'Говорит о прошлом, например: «Вчера мы ходили к бабушке»? Формируются чувство времени и долговременная память. С интересом слушайте эти воспоминания и задавайте вопросы.'),
  ('f0257b2e-d5f4-40d8-9701-488c186af81f', 'Кричит и плачет среди ночи с закрытыми глазами?', 'Не пытайтесь разбудить малыша. Дайте функции «Анализ плача» послушать этот звук, чтобы убедиться, что это всего лишь эпизод ночного ужаса, и спокойно оставайтесь рядом.'),
  ('605d2ada-99ba-4138-bd88-c091a6c53e2b', 'Восторг «Я тебя нашёл!» 🙈', 'Прятки уже стали любимой игрой малыша. Он прячется за шторой и ждёт, пока вы его найдёте. Благодаря таким играм в этом возрасте ещё лучше закрепляется понимание постоянства объектов.'),
  ('c0738cb9-5d1f-47d6-821c-55b543c58b28', 'Как справляться с истериками 🛑', 'Вас смущают истерики в магазине или парке? Помните: важно не то, что думают окружающие, а эмоции, которые переживает ваш ребёнок в этот момент. Спокойно обнимите его.'),
  ('244e81e4-ef8a-4010-a428-229aabe2c4b0', 'Попросите партнёра о помощи 🛒', 'Нет времени на покупки? Откройте список покупок, отметьте всё, чего не хватает дома, и одним нажатием отправьте его партнёру. Распределять обязанности необходимо.'),
  ('e5509d0f-428a-4a25-9b61-f825746504ad', 'Тихое чтение 📖', 'Пусть сегодня вечером в комнате будет слышен только шелест книжных страниц. Устройтесь вдвоём на кровати: малыш будет рассматривать свою книжку с картинками, а вы сможете отдохнуть в тишине.'),
  ('f568dd40-0374-40d2-8f34-9a863c9b7158', 'Опасные прыжки 🧗‍♂️', 'Малыш пытается спрыгнуть с дивана на пол? Он слишком уверен в своих двигательных навыках. Вместо запрета положите на пол мягкие подушки и создайте безопасную зону для прыжков.'),
  ('1222929d-ba35-40ba-92f4-2c3b29988e2e', 'Проверка границ ⚠️', 'Вы просите малыша чего-то не делать, а он смотрит вам прямо в глаза и всё равно это делает? Он не пытается вас разозлить, а проверяет, насколько устойчивы установленные вами границы. Будьте последовательны в правилах.'),
  ('60d686a6-8001-479b-9d53-bcd85bcdffdb', 'Пусть дома останется беспорядок 🌪️', 'Устали каждый день собирать одни и те же игрушки? Сегодня не убирайте их! Беспорядок в доме — не конец света, а вот эмоциональное выгорание мамы — это серьёзно.'),
  ('e7bfaacc-c0cc-4b36-8687-477371b3bc3d', 'Сегодня в умной сказке 🪄', 'Задайте умной сказке особую тему: волшебный медвежонок, который любит убирать свои игрушки. Возможно, завтра эта история поможет вам с уборкой!'),
  ('895f4348-4fb2-4124-9532-acf7d07409f6', 'Папины ритуалы 👨‍🍼', 'У детей часто есть особые ритуалы с папой. Сегодня вечером доверьте укладывание забавным папиным правилам, а сами спокойно выпейте чай за пределами комнаты.'),
  ('aca7ae85-535e-4175-ab27-d1ca390e78cb', 'Открываем мир цветов 🎨', 'Малыш правильно группирует цвета, говоря: «Это красный, а это синий»? Это большой шаг в когнитивном развитии! С гордостью отметьте это достижение в трекере развития.'),
  ('b6ee83b4-0d5f-4791-8483-ed7d1d3aa649', 'Вместе на кухне 🧑‍🍳', 'Малыш хочет заниматься делами вместе с вами? Выберите простой кекс из полезных рецептов и позвольте ему помочь вам насыпать муку или налить воду. Даже если всё испачкается, веселье гарантировано.'),
  ('2009290a-99c2-4bf0-a2b6-174daa69d49d', 'Ночные децибелы 🤫', 'Шум с улицы мешает малышу погрузиться в глубокий сон? Проанализируйте уровень шума в комнате с помощью шумомера.'),
  ('2a0f6e31-8cdc-436b-8432-73cf4dad5b5c', 'Художник за работой 🖍️', 'Стены и двери иногда превращаются в холст для малыша. Вместо того чтобы сердиться, найдите большой лист картона, расстелите его на полу и скажите: «Здесь можно рисовать». Направьте его стремление к творчеству в нужное русло.'),
  ('7750d70c-df5b-48b0-9b2f-522c15391059', 'Поток вопросов 🤖', 'У вас всё больше вопросов о поведении ребёнка ближе к 3 годам? Anacan AI — это цифровой педиатр и психолог, который всегда на связи 7/24. Напишите и получите мгновенный ответ.'),
  ('2859fc00-366b-44b7-ba24-815b9b659125', 'Дайте волю эмоциям 📝', 'Вы чувствуете себя очень одиноко и вам кажется, что вас не понимают? Это совершенно естественное чувство. Искренне опишите свои переживания в дневнике настроения.'),
  ('4f59cf22-ccfa-43b9-8a30-62365a911312', 'Малыш открывает своё «я» 👑', 'Слова «Я сам!» и «Моё!» не сходят у него с языка. Сейчас эгоцентризм проявляется особенно ярко. Относитесь к его индивидуальности с уважением — это этап развития.'),
  ('1da71143-b8dd-434a-bf23-b7f16a2d4a80', 'Водопад самостоятельности 🥛', 'Малыш непременно хочет сам наливать воду или молоко в стакан, а в итоге? Вокруг одни лужи. Сделайте глубокий вдох. Этот хаос — цена развития его зрительно-моторной координации и уверенности в себе. Дайте ему тряпочку и спокойно уберите всё вместе.'),
  ('7f1b27a1-aff6-4522-ba4e-76bb08fa648e', 'Детокс от шума 🎧', 'Крики «Мама, мама, мама!» эхом отдаются у вас в голове? Устройте себе небольшой перерыв. Предложите малышу безопасное занятие на 15 минут, а сами выпейте кофе в полной тишине. Вашей батарейке тоже нужна подзарядка.'),
  ('9ebeb631-4aa4-4310-b78e-47bee6920a4e', 'Как преодолеть упрямство перед купанием 🛁', 'Малыш не хочет идти в ванную, катается по полу и протестует? Вместо «Давай я тебя помою» скажите: «Пойдём купать твои любимые машинки (или куклы)». Любая обязанность, превращённая в игру, становится гораздо привлекательнее для ребёнка.'),
  ('5188ae48-9680-4372-a0c2-b6a14d87d513', 'Кризис из-за обуви дома 👟', 'Малыш плачет, потому что хочет ходить по дому в уличной обуви и ни за что не желает её снимать? Это не стоит войны. Протрите подошвы влажной тряпкой и позвольте ему несколько часов гордо вышагивать по комнате. Иногда осознанно проиграть отдельную битву — на самом деле большая победа мамы.'),
  ('a80b1c35-a6ce-48dc-a430-2268378d43f5', 'Теперь очередь папы 👨‍🍼', 'Вы устали весь день говорить «нет» и устанавливать правила. Сегодня вечером передайте папе сражения из-за пижамы и чистки зубов. Закройте дверь комнаты, запишите в Дневнике настроения, что вы сегодня чувствуете, и полностью посвятите это время себе.'),
  ('f6d030df-f5ef-4ef7-84fc-04dd7126bef2', 'Улыбка в Сообществе 💬', 'Сегодня капризы малыша окончательно лишили вас сил? Сразу откройте Сообщество Anacan и почитайте похожие, а порой ещё более забавные истории других мам о детских кризисах. Осознание того, что вы проходите через одно и то же и не одиноки, — лучшая психологическая поддержка.'),
  ('16b69d4c-feb3-42d5-b458-329c2a13a823', 'В поисках новых друзей 👫', 'Малыш пытается бегать в парке со сверстниками и присоединяться к их играм? Социализация официально начинается! Подбадривайте его и научите здороваться с другими детьми.'),
  ('db813abc-1129-479f-a1e4-e6beaeb2ec95', 'Природная терапия для мамы 🌳', 'Стены дома на вас давят? Берите малыша и отправляйтесь в ближайший парк. Свежий воздух — лучший способ успокоить уставшие нервы не только ребёнка, но и ваши.'),
  ('f7c61cc4-7a2d-48d0-bf89-ec947a89cd75', 'Ответственность папы 👨‍🍼', 'Вы не обязаны делать всё сами. Сегодня вечером полностью передайте папе чистку зубов и переодевание в пижаму, а сами понаблюдайте со стороны.'),
  ('07c7c2cb-58bb-47db-ac0e-f81bd01e602b', 'Сила маминого голоса 🎶', 'Сегодня вечером не используйте никаких устройств. Просто прижмите малыша к груди и прошепчите ему на ушко любимую колыбельную. Ваш голос — его самая надёжная гавань.'),
  ('1acb826a-9b73-413f-b0af-4614a74084bd', 'Быстрая поддержка педиатра 🤖', 'Вас беспокоит график роста и веса ребёнка ближе к 3 годам? Не тратьте часы на поиски в интернете — сразу узнайте у ИИ Anacan точные нормы, подтверждённые педиатрами.'),
  ('5bb344ff-e859-413b-93f7-4f25386f0835', 'Знает своё имя и возраст 🎂', 'Когда вы спрашиваете: «Сколько тебе лет?», малыш пытается показать возраст пальцами? Он прекрасно осознаёт себя как личность. Отметьте этот интеллектуальный скачок в Трекере развития.'),
  ('2c139fbd-2360-47be-8201-67957bcf1684', 'Режиссёр перед зеркалом 🎭', 'Малыш стоит перед зеркалом, строит разные гримасы и разговаривает сам с собой? Он примеряет разные роли. Незаметно понаблюдайте за ним и насладитесь этими забавными моментами.'),
  ('42026a5f-2788-45b9-acb9-1e97ccc1366b', 'Нужно пополнить запас энергии 🍲', 'Бесконечная беготня лишила вас сил. Выберите в разделе полезных рецептов необычное блюдо для обеда, богатое железом и белком, которое понравится и вам, и малышу.'),
  ('f413f7f2-f85e-4bd1-a054-6b9d46b4d341', 'Анализ дня 📝', 'Как только малыш уснёт, откройте вместе с партнёром Дневник настроения. Запишите самый забавный поступок ребёнка за сегодня, улыбнитесь вместе и снимите напряжение.'),
  ('59d23d62-6dca-4962-aec7-eb093810797b', 'Музыкальный переход ко сну 🛀', 'Вечерний ритуал стал сложнее? Во время тёплой ванны включите на фоне спокойную классическую музыку. Гармония воды и музыки смягчит даже самого упрямого малыша.'),
  ('eddd6a67-3ce9-4446-ba23-dba7c167dca2', 'Погода переменчива ⛅', 'Хотите пойти на прогулку, но погода на улице обманчива? Откройте инструмент «Погода и одежда» и подберите подходящий комплект, в котором малыш не вспотеет и будет защищён.'),
  ('009a8d5c-9bba-4789-a6ee-e59d4c647832', 'Гордость команды 🥂', 'Вы пережили непростую неделю. Сядьте напротив партнёра, скажите друг другу: «Мы действительно хорошо растим этого ребёнка» — и поддержите друг друга.'),
  ('d0adf273-d83c-415a-88b8-6fa5f74c5f51', 'Рассказывает сказки предложениями 🗣️', 'Рассматривает книжку с картинками и придумывает собственную сказку целыми предложениями? Воображение и речь развиваются одновременно! Внимательно выслушайте малыша и похвалите его.'),
  ('ff22b088-7f8b-4366-a32b-7bd8cd1aa92f', 'Материнская солидарность 💬', 'Приучение к горшку довело вас до отчаяния? Скорее заходите в Сообщество Anacan. Истории успехов и неудач других мам придадут вам сил.'),
  ('1c47434b-8f04-4342-a73a-e77c7a63eb48', 'Страх темноты 🌙', 'Малыш боится темноты в комнате? Поставьте рядом с кроватью небольшой ночник, но убедитесь, что в комнате достаточно темно для выработки мелатонина.'),
  ('77a1ab3f-8086-4334-93ed-03dab08fb152', 'Хочет сам выбирать одежду 👗', 'Открывает шкаф и хочет сочетать неподходящие цвета и вещи не по сезону? Поддержите самостоятельность малыша, но, чтобы сохранить контроль, предложите ему всего 2 варианта на выбор.'),
  ('b22d0c31-c528-4596-b176-4f64d3f5be5d', 'Кофейная подзарядка ☕', 'Дневного сна больше нет, и вы не можете отдохнуть весь день? Займите малыша безопасным делом на 15 минут и обязательно подзарядитесь чашечкой кофе.'),
  ('9787e3a9-8592-4bb2-8463-c4e695682c99', 'Тяжёлая ноша, упрямое сердце 🛒', 'Возвращаясь с прогулки, малыш непременно хочет сам нести самый тяжёлый предмет или пакет? Даже если не может сдвинуть его с места, он решительно отказывается от вашей помощи. Позвольте ему немного повозиться и испытать свои силы.'),
  ('bdc2ddcb-448f-4cfa-b4a5-c5e56bf2b001', 'Маленький философ 🤔', 'Уже почти закрыв глаза, малыш вдруг поднимает голову и задаёт философский вопрос вроде: «Мама, а куда солнце уходит спать?» Даже при засыпании его мозг продолжает осмысливать мир. Не углубляясь в подробности, дайте короткий сказочный ответ.'),
  ('c2525bad-5158-49a7-81ce-247259a08d2e', 'Невыполнимые требования 🪄', 'Сегодня утром малыш проснулся и с криком потребовал снова сделать нарезанное яблоко целым? Да, ближе к 3 годам детская логика бросает вызов законам физики.'),
  ('1e3f3fa1-dbbc-4651-aa40-6590038f46b0', 'Подражает животным 🐶', 'Малыш не только издаёт звуки, но и ползает как собака, умывается как кошка? Язык тела объединяется с воображением. Присоединитесь к этой игре вместе с ним прямо на ковре.'),
  ('4ac97d09-8bce-44ef-922e-5286afc49815', 'Разборчивость в еде 2.0 🥣', 'Сегодня малыш отказывается от супа, который ещё вчера любил? Не заставляйте. В разделе полезных рецептов найдите необычные альтернативные блюда, в которых можно незаметно спрятать овощи.'),
  ('d8f03ef9-1ea4-48a4-a43d-dc4f633f2d60', 'Волшебная сказка на ночь 🪄', 'В разделе «Умные сказки» создайте историю о смелом герое, который готовится к трёхлетию, чтобы малыш почувствовал, что растёт и становится сильнее.'),
  ('2a9575e0-ee4f-4f27-86a9-25def022748e', 'Я ищу тебя! 👀', 'Малыш снова начинает плакать, как только вы выходите из комнаты? Тревога разлуки иногда возвращается. Успокойте его издалека своим голосом, но помните: вы не обязаны постоянно быть у него на виду.'),
  ('89de8241-ec59-4180-ba30-e03291e0f208', 'Пусть сам закончит сказку 📖', 'Сегодня вечером, читая сказку, не договаривайте предложения до конца — пусть малыш завершит их сам! Спросите Anacan AI, как вести диалог, чтобы поддержать это удивительное развитие воображения.'),
  ('ca321f21-1031-4b14-96c8-69fa4c4201da', 'Без списка не обойтись 🛒', 'Не забудьте всё необходимое для дня рождения! Не перегружайте память: сразу добавляйте всё в список покупок и синхронизируйте его с партнёром.'),
  ('565fda98-0d2c-40b4-8230-13c64e585700', 'Трагедия со швом на носке 🧦', 'Сегодня утром мы проснулись из-за настоящего кризиса: шов внутри носка касается пальчика! Ближе к 3 годам эмоциональная чувствительность достигает пика. Не ищите логики — наденьте носок наизнанку и посмотрите, как этот абсурдный кризис закончится за 10 секунд.'),
  ('acd26d8c-d24f-4082-9973-a1110aefb638', 'Охотник за лужами 🌧️', 'Вы вышли на улицу после дождя, а он прыгнул прямо в грязную лужу? Одежда испачкалась, но взгляните на этот огонёк первооткрывателя в его глазах. Учитывайте погоду и заранее надевайте на него резиновые сапоги — пусть наслаждается детством.'),
  ('b17158eb-f894-42c6-8d84-cab6d30d297a', 'Спокойной ночи, игрушки 🧸', 'Пора ложиться спать, но он по очереди прощается с каждой машинкой и каждым мишкой в комнате. Это настоящий шедевр искусства откладывать сон. Установите таймер и введите правило: за 3 минуты говорим «пока» всем сразу.'),
  ('3b1d044a-5917-48bd-b4f3-847b5ba6d5db', 'Самый странный предмет 🥄', 'У него столько дорогих игрушек, но он нашёл на кухне половник, весь вечер ходит с ним и даже укладывает его спать. Детские привязанности порой необъяснимы. Не мешайте — пусть дарит этому половнику свою любовь.'),
  ('498b3498-4fee-4a00-9b62-ebe43844ae53', 'Хирург над тарелкой супа 🥣', 'Он не ест, а лишь с хирургической точностью откладывает в сторону мелкие кусочки лука или зёрнышки риса. Пора превратить овощи в пюре и сделать их незаметными. Загляните в раздел полезных рецептов и найдите самые изобретательные мамины блюда со спрятанными овощами.'),
  ('a13e9959-a476-4e99-9da8-13f5bff68864', 'Я сам открою шкаф! 🚪', 'Вы утром открыли шкаф, а он расплакался, заставил вас закрыть дверцу и открыл её сам? Да, всё должно быть под его контролем. С улыбкой относитесь к этим невинным попыткам всё сделать самому — он проверяет силу своей воли.'),
  ('0a4a5638-968e-4cce-9213-12c0072354c4', 'Цифровое измерение тишины 🤫', 'Он наконец уснул! Вы не можете поверить в тишину, окутавшую дом. Включите шумомер и, глядя на показатель 0-10 децибел на экране, почувствуйте, как ваш мозг постепенно отдыхает и восстанавливает силы.'),
  ('b5cfbb8a-14cd-4f76-bc5c-26b6d0b9418a', 'Удар словами «Ты плохая мама!» 💔', 'Вы не дали ему желанную конфету, и он сказал, что вы плохая? Не принимайте это близко к сердцу. Он пока не умеет правильно выражать свои чувства словами, а на самом деле хочет сказать: «Я очень злюсь». Установите зрительный контакт и признайте его эмоцию.'),
  ('fabd170d-dc89-4100-b9c1-3acf59e32a5c', 'Разговор с невидимым муравьём 🐜', 'Он наклонился к муравью на полу балкона или на дорожке в парке и очень серьёзно ему что-то рассказывает? Сейчас одновременно работают воображение и сострадание. Сразу запечатлейте этот чудесный момент с помощью «Фотосессии малыша» и сохраните в самом милом уголке архива.'),
  ('a860534c-7167-4781-b298-8321127fd089', 'Папин режим полёта ✈️', 'Он не успел выплеснуть дома всю энергию и отказывается ложиться спать. Позовите папу на помощь. Когда папа поднимает ребёнка в воздух и играет с ним в самолётик, комнату наполняет смех, а всё накопившееся физическое напряжение исчезает за считаные секунды.'),
  ('e0e56f8d-3c51-4c46-90f2-dbfa90060519', 'Свобода кататься по полу 🌪️', 'Он бросился на пол посреди магазина? Не пытайтесь поднять его или что-то объяснять окружающим. Сделайте глубокий вдох. В сообществе Anacan вы увидите, что тысячи мам переживают такие же неловкие, но совершенно естественные моменты.'),
  ('e9ba4911-0212-43aa-9a51-c6bf942facb9', 'Упрямое «Не смотри на меня!» 🙈', 'Вы посмотрели на него и улыбнулись, а он плачет и кричит: «Не смотри на меня!» Вершина абсурдной логики! Отвернитесь и подождите, пока этот забавный каприз пройдёт: иногда дети и сами не знают, чего хотят.'),
  ('3b9f5253-06a7-4aef-bfdf-bb0daf30818e', 'Магия света 🌙', 'Он начал бояться темноты? Полностью затемните комнату и устройте с помощью маленького фонарика игру света на потолке. Превратите пугающую его темноту в развлечение и маленькое исследование перед сном.'),
  ('5d1a2a49-e134-453a-a974-f4cff4de0952', 'Любовь к пижаме 👗', 'Он проснулся и наотрез отказывается снимать испачканную пижаму. Если вы не собираетесь выходить из дома, прекратите борьбу. Иногда душевное спокойствие мамы гораздо важнее опрятного вида ребёнка.'),
  ('c8ffca51-c2fa-4f5a-8090-6c144b596f9c', 'Сокровища из кармана 🍁', 'Вы вернулись из парка, а в его кармане обнаружились 3 камня, 1 сухой лист и веточка. Для вас это мусор, а для него — сокровища. Заведите коробку для коллекции и разрешите складывать находки туда, чтобы они не были разбросаны по дому.'),
  ('176265d3-ef2f-4ec4-923c-4308870e611f', 'Освободиться от эмоционального груза 📝', 'Вам кажется, что никто дома не замечает, насколько вы устали? Дневник настроения — ваш самый молчаливый и надёжный собеседник. Запишите туда все мелочи, которые сегодня выводили вас из себя, и почувствуйте, как становится легче.'),
  ('94fce04c-73e9-47bd-8d9d-3bd3da19122a', 'Я пойду сам! 🚶‍♂️', 'На улице малыш наотрез отказывается держать вас за руку и заявляет о своей самостоятельности. В безопасных местах предоставьте ему эту свободу. Не спускайте с него глаз и позвольте исследовать мир собственными шагами.'),
  ('b24a452c-9588-4b0c-923f-9c455be6d1e2', 'Маленький повар на кухне 🧑‍🍳', 'Когда вы раскатываете тесто, малыш непременно ставит рядом стул и вмешивается в процесс? Дайте ему небольшой кусочек теста. Мука будет повсюду, но его серьёзное, деловитое выражение лица стоит всей последующей уборки.'),
  ('09711673-d0fa-42b5-be98-012bd4b1ed8b', 'Трудности с перерывом от экрана 📺', 'Сегодня из-за своих дел вы позволили малышу посмотреть больше мультфильмов и теперь чувствуете вину? Не ругайте себя. Невозможно каждый день быть идеальной мамой. Иногда цифровая няня спасает вас от эмоционального срыва.'),
  ('8649e4ca-170c-4117-8af8-b0d7e819e84f', 'Живой диктофон 🎙️', 'Сегодня утром малыш повторяет своей игрушке случайное слово, которое услышал вчера во время вашего разговора с партнёром! Его словарный запас растёт с невероятной скоростью, и он во всём вас копирует. Не забывайте, что вы служите для него примером.'),
  ('c0faa467-b596-4471-bbba-6d91e0e37db1', 'Приём с шёпотом 🤫', 'В кровати малыш так активен, что никак не засыпает. Вместо того чтобы повышать голос, внезапно понизьте его и заговорите шёпотом. Когда ребёнок сосредоточится, чтобы вас услышать, его мозг автоматически начнёт переключаться в режим сна.'),
  ('48263ed0-f236-440c-a83e-807da51bd86f', 'Потребность в кислороде ⛅', 'Четыре стены уже затуманили вам разум, а дома один каприз сменяет другой. Оцените погоду, подберите подходящую одежду и отправляйтесь на улицу. Возможность просто побегать поможет малышу выплеснуть энергию, а вам — вздохнуть полной грудью.'),
  ('8fed0a18-52ae-4688-8137-532b6b55726c', 'Пусть малыш управляет сказкой 🪄', 'Классические книжки надоели вам обоим. Включите умные сказки, сделайте главным героем своего ребёнка, а местом, которое нужно спасти, — его комнату. Так вы устроите необычный, спокойный и непринуждённый сеанс подготовки ко сну.'),
  ('c7c388a1-a255-4a7c-a615-22236406e4e2', 'Авангардное творчество 🖍️', 'Несколько секунд тишины обернулись неожиданным сюрпризом. Войдя в комнату, вы обнаружили, что малыш нарисовал фломастером татуировки на руках или животе. Сделайте глубокий вдох. Его мелкая моторика развивается, а кожа всё равно отмоется.'),
  ('15f19421-c415-4b7b-ad4d-54211e4ccb3a', 'Вода, повсюду вода! 💧', 'Малыш непременно хотел сам налить воду в стакан. Разлил её, и всё вокруг промокло. Но посмотрите на эти маленькие ручки, которые взяли тряпку и пытаются всё вытереть. Он учится ответственности на своих ошибках — не сердитесь.'),
  ('6d2f1d1e-d7d7-41c3-b906-1e286aab1a51', 'Папина очередь 👨‍👧', 'Материнство не должно быть бесконечным марафоном. Пусть сегодня прогулку и игры в парке возьмёт на себя папа, а вы насладитесь уединением на диване.'),
  ('cf9e0ee2-2f17-4a55-933b-735bc0754d7e', 'Командный массаж 💆‍♂️', 'Когда ребёнок уснёт, сделайте друг другу массаж плеч, чтобы вместе с партнёром снять накопившийся за день стресс. Вы не просто родители — вы главная опора этого дома и друг для друга.'),
  ('2caa3c21-d2d3-4566-921a-e08cdbce1397', 'Я устала... 🔋', 'Все ждут от вас энергии, но ваша батарейка разрядилась. Сегодня ничего не готовьте: закажите еду или сварите самые простые макароны. Быть Супергероем — не значит быть обязанной справляться со всем в одиночку.'),
  ('48299b62-1108-44e9-af43-b48460ffdfa2', 'Спокойствие в ванне 🛀', 'Весь день прошёл под девизом «Я не хочу!». Тёплая ванна нужна не только для гигиены — она помогает перезагрузить напряжённую нервную систему малыша. Прислушайтесь к звуку воды, и атмосфера в комнате мгновенно изменится.'),
  ('ab5bd705-a57d-40d7-b0a0-86107e824b4d', 'Самостоятельно по лестнице 🧗', 'Малыш пытается подниматься по лестнице без поддержки? Его двигательные навыки сейчас на пике! Наблюдайте со стороны и не вмешивайтесь. Сохраните этот момент самостоятельности с помощью Детской фотосессии.'),
  ('33979ce6-ea09-4adc-ab85-0cf386a73156', 'Волшебное притяжение коробки 📦', 'Вы купили малышу дорогую игрушку со звуком, а он уже 1 час играет с коробкой от неё. Детский мозг предпочитает не готовые конструкции, а простые предметы, которые дают простор воображению. Наблюдайте и учитесь.'),
  ('5b89452a-e411-4130-87b7-6e1e33b0701e', 'Естественный белый шум 🤫', 'В момент засыпания малыш становится особенно чувствительным к звукам. Чтобы нейтрализовать шум с улицы, включите в комнате фоновый звук Шумомера и создайте атмосферу длительного спокойствия.'),
  ('a09d0a7b-0632-4bcf-8833-28f5ef0f9d93', 'Притворный плач 🎭', 'Притворяется, что плачет, не проливая слёз, но дрожащим голосом, чтобы получить желаемое? Малыш учится вами манипулировать. Постарайтесь не рассмеяться, но и не уступайте. Чётко обозначайте свои границы.'),
  ('20e8cb8e-6d52-4362-bb7b-a45ecbfa2cce', 'Внезапное «Я тебя люблю» 💖', 'Играя посреди комнаты, малыш вдруг посмотрел на вас и сказал: «Я тебя о-о-очень люблю»? Ради этого стоили все бессонные ночи и усталость! Насладитесь глубоким, неповторимым умиротворением, которое дарит этот момент.'),
  ('22b5d836-6305-422c-8cf7-c30a523392f2', 'Безумный папин танец 🕺', 'С вечерней вспышкой раздражения порой может справиться только папа. Пусть он включит музыку погромче и потанцует с малышом, прыгая по комнате. А вы с гордостью наблюдайте со стороны за этой весёлой энергией.'),
  ('909bc50f-85b7-40ab-a524-0abbcb0fac9f', '10 минут только для себя ☕', 'Пока малыш увлечён мультфильмом, не спешите загружать посудомоечную машину! Прилягте на диван. Наконец выпейте кофе горячим и хотя бы на 10 минут выйдите из роли мамы, чтобы просто побыть собой.'),
  ('028ed2b5-737d-4edf-81c1-5a9151e5fbf0', 'Шоколадный сюрприз в магазине 🛒', 'Перед походом в магазин вы открыли список покупок, а малыш подошёл сзади, нажал на экран телефона и что-то там начеркал? Да, он копирует даже вашу цифровую жизнь!'),
  ('098cd94b-6989-48a8-9fdc-160a2f819cb0', 'Прелесть выдуманной грамматики 🗣️', 'Малыш придумывает странные, но очень милые формы слов вроде «я ходилил» или «он приходил был»? Его словарный запас растёт как на дрожжах! Сохраните эти особенные словечки в трекере развития на память.'),
  ('50dce5d9-294a-44b8-b1c9-316b84d5df14', 'Что там под кроватью? 👻', 'Малыш верит, что в темноте прячутся чудовища? Возьмите бутылку с обычной водой и распылите её по комнате как «спрей от страхов», чтобы успокоить его. Победите воображение с помощью воображения.'),
  ('2cd29d0d-0cf1-403e-806d-35f84215b2df', 'В 5 утра началась вечеринка! ⏰', 'Солнце ещё не взошло, а малыш уже прыгает на кровати и начинает свой день. Вы всё ещё хотите спать, но он уже готов покорять мир. Присоединяйтесь и позвольте этой безумной энергии разбудить и вас.'),
  ('48550c10-c030-428e-9c25-ccd73ca09c55', 'Ищете детский сад? 🏫', 'Ближе к 3 годам мысли о детском саде всё чаще приходят вам в голову, но вы никак не можете определиться? Если вы устали размышлять в одиночку, присоединяйтесь к Сообществу Anacan и почитайте о реальном опыте других мам.'),
  ('df1cf1ea-2772-44a6-8cb7-33857989fedf', 'Дневник эмоций 📝', 'Кто-то сказал вам: «Ты же дома, от чего ты устаёшь?» Сразу откройте Дневник настроения и выплесните всё раздражение на экран. Записывать свои настоящие чувства полезнее, чем изображать улыбку, — это настоящая терапия.'),
  ('3deb7e49-2093-4c39-a51d-8dd6fd44d138', 'Вражда с овощами продолжается 🥦', 'Малыш снова заметил в супе крошечный кусочек моркови и отказался есть? Составьте план питания, измельчите овощи в пюре и спрячьте их в котлетах — это одна из самых старых и полезных маминых хитростей. Попробуйте!'),
  ('9dd6923c-7dc5-4341-8507-b21e0f3c9ee4', 'Маленький врач вас осматривает 🩺', 'Малыш прикладывает игрушечный стетоскоп к вашей груди и просит сделать вдох. Вы пациент, а он — главный врач. Подыграйте ему: прилягте и хотя бы на 5 минут закройте глаза и отдохните, пока вас «лечат».'),
  ('ebf71c8a-d8a3-4875-8021-e3145bf8ae06', 'На минимальной громкости 🌙', 'Малыш наконец уснул. Теперь вас тревожит даже самый тихий звук в доме. Приглушите свет, выключите телевизор и насладитесь этой редкой, блаженной тишиной в полумраке.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ru = v.t, body_ru = v.b
FROM (VALUES
  ('19419b9a-b627-43ae-9610-e43b875264b1'::uuid, 'Целеустремлённое ползание и бег 🐢', 'Малышу уже недостаточно просто ходить: он быстро убегает от вас, прячется и выглядывает из-за дверей. Уберите из комнаты всё, что может помешать, и присоединяйтесь к игре в догонялки с энергией большого ребёнка.'),
  ('20d0afb1-a487-43f5-b6f3-0f8cd2bca864', 'Выключите свет — впустите сон 🌙', 'Чтобы малыш быстрее заснул, выключите в комнате все лишние источники света и экраны с синим свечением. Гормон сна (мелатонин) активно вырабатывается только в тёмной обстановке без гаджетов.'),
  ('c8f7bf43-25ab-4e4d-96d4-6f6b9ab81f33', 'Искусственный интеллект, настоящий ответ 🤖', 'У вашего ребёнка появилась странная привычка (например, грызть ногти), а интернет-форумы вас напугали? Остановитесь. Спросите у Anacan AI о настоящей причине, подтверждённой педиатрами, и успокойтесь.'),
  ('1bbd92c6-a12a-4c26-a63f-0946e226b656', 'Забывать о себе запрещено! 🥗', 'Вы придумали 3 разных меню, чтобы накормить малыша, а сами снова остались голодны? Выберите среди полезных рецептов богатый железом и кальцием обед, который можно приготовить за 10 минут, и позаботьтесь о себе.'),
  ('31e8c246-42c7-4bad-8ff1-c08af53874b1', 'Внезапная вспышка гнева 💥', 'Во время игры малыш вдруг разозлился и начал разбрасывать игрушки? Он пока не умеет управлять своими эмоциями. Вместо того чтобы кричать, проявите сочувствие и скажите: «Я вижу, что ты злишься. Давай вместе глубоко подышим».'),
  ('96327d67-c216-46e6-b768-6cd8fce23852', 'Шампанское для двоих 🥂', 'Малыш уснул. Даже если шампанского нет, налейте в бокалы горячий чай и чокнитесь с партнёром со словами: «Мы благополучно пережили и этот трудный день». Вы — самые сильные полководцы в доме.'),
  ('3b764723-4ccb-4ab8-a1ed-3b072c5f8a25', 'До 3 лет осталось 5 дней! 🚀', 'Невероятно! До грандиозного трёхлетия осталось всего 5 дней. Именно вы вырастили эту маленькую личность, которая устанавливает в доме собственные правила. Закажите торт в Anacan прямо сейчас и начинайте подготовку.'),
  ('b8850dac-f142-4e24-bc24-56bb7962ebf6', 'Папин режим полёта ✈️', 'Малыш не успел выплеснуть энергию дома и отказывается ложиться спать. Позовите папу на помощь. Когда он поднимает малыша в воздух и изображает самолёт, комнату наполняет смех, а физическое напряжение исчезает за считаные секунды.'),
  ('ee7e813c-5a12-4710-b655-7b294f1ff478', 'Мамина передышка ☕', 'Вы устали разговаривать на детском языке. Найдите среди Мест, дружественных к мамам, кафе с детским уголком, выпейте кофе, поделитесь переживаниями с другими мамами и немного переведите дух.'),
  ('20794d75-b46f-481d-baa5-2b85b8516d4e', 'Свобода в парке 🌳', 'Четыре стены делают малыша раздражительным. Выведите его в парк: пусть испачкается в песке, упадёт на бегу и собирает камешки. Такая свобода на природе — лучшее развивающее лекарство для его мозга.'),
  ('3d4fe78e-9d18-4fa4-b11f-ee7836615ee7', 'Фабрика мелатонина 🌙', 'Чтобы малыш быстрее уснул, выключите все лишние источники света в комнате и экраны планшетов. Мелатонин быстро вырабатывается только в спокойной, слабо освещённой обстановке без экранов.'),
  ('5e21d0fb-8027-46a5-b7ea-7b3a58d0cd11', 'Пришли воображаемые гости ☕', 'Малыш разговаривает в комнате с невидимыми друзьями и наливает им чай? Это вершина развития воображения! С гордостью наблюдайте со стороны за этим великолепным сценаристом — он уже создаёт собственную вселенную.'),
  ('19c93357-3662-4a7d-bd13-a71d938dc00a', 'Сейчас я вам объясню! ☝️', 'Малыш с очень серьёзным и умным выражением лица объясняет вам то, что вы и так знаете. Так он проверяет свои знания. Даже если вам приходится сдерживаться, чтобы не рассмеяться, слушайте его с предельной серьёзностью.'),
  ('6ab81ee1-daa9-4300-97cb-c7dad69d9baf', 'Признание в дневнике настроения 📝', 'Возьмите телефон. Вместо того чтобы листать в социальных сетях чужие жизни, откройте Дневник настроения и сохраните на будущее самый забавный момент сегодняшнего дня с участием малыша. Цифровая терапия работает.'),
  ('ee467fcc-7c51-4e6a-ba68-1e6466be7d10', 'Бунт против дневного сна 🥱', 'Малыш категорически не хочет ложиться спать? Ближе к 3 годам такое сопротивление вполне типично. Не заставляйте его и не доводите до слёз. Приглушите свет в комнате, объявите тихий час для рассматривания книг и измените привычный ритуал.'),
  ('3a35865f-054d-413c-b3ad-81c68c171c47', 'Снова тревога разлуки? 🥺', 'Малыш плачет и идёт за вами, даже если вы вышли из комнаты всего на секунду. Иногда на пороге 3 лет тревога разлуки возвращается. Каждый раз отзывайтесь издалека и успокаивайте его словами: «Я здесь, я на кухне, сейчас приду».'),
  ('96b4e611-59a4-4d8b-a157-87f9d477e265', 'Подтверждение тишины 🤫', 'После шумного дня, когда малыш уснёт, измерьте уровень тишины в комнате с помощью шумомера. Даже один вид цифр, приближающихся к нулю, действует на мозг мамы как лучший визуальный массаж.'),
  ('c1d1539d-38e2-40da-9e66-eb22e0cbbd09', 'Давление идеальности 🛑', 'Другие дети уже называют цвета, а ваш малыш не хочет? Немедленно перестаньте сравнивать! У каждого ребёнка свой темп развития. Ваш малыш развивается в собственном темпе, и это совершенно нормально.'),
  ('08d5ac7d-b540-46e7-9f43-7f771edfd887', 'Подготовка к победе 💆‍♂️', 'Когда малыш уснёт, сделайте друг другу массаж плеч, чтобы вместе с партнёром снять накопившийся за день стресс. Завтра вас ждут трёхлетие и праздничная суета, поэтому вам обоим обязательно нужно быть полными сил!'),
  ('2d61ffa4-9df3-4b29-acca-6b87ebc82745', 'Группа поддержки мам 💬', 'День выдался трудным, и всё кажется слишком сложным? Советы опытных мам из Сообщества Anacan — это самые практичные, проверенные жизнью решения, которых не найти ни в одной книге. Вдохновляйтесь их опытом.'),
  ('dd4c2432-4936-49e7-844c-aec9116027b4', 'На пороге трёхлетия! 🎂', 'Завтра важнейший день! Какой огромный путь вы прошли с тех пор, как малыш впервые толкнулся у вас в животе. Сегодня вдоволь полюбуйтесь им, выберите наряд и освободите память телефона для завтрашней детской фотосессии.'),
  ('36c78cd2-37d5-4665-84a1-551e9c9c2557', 'Отпразднуйте вместе с партнёром 🥂', 'Сегодня вечером вместе с партнёром отметьте три года усталости, слёз и радости. Поставьте на стол свечу и с широкой улыбкой отпразднуйте победу вашей нерушимой команды!'),
  ('6148534d-dac4-4ca6-9b42-87f0242f8cdb', 'Великолепные 3 года! 👑🎉', 'Поздравляем! Малышу уже 3 года! Ровно 1095 дней вы идёте по этому бурному и утомительному, но самому прекрасному пути в мире! Обязательно устройте праздник в этот особенный день и поделитесь своей радостью со всеми!'),
  ('94dba968-6bd5-4b01-b8ef-b33b80729320', 'Вы великолепны! 📈', 'Какой огромный путь прошёл ваш ребёнок! Хрупкая тревога первых дней теперь сменилась уверенностью и опытом. Вы с гордостью прошли эти 3 года! Вы действительно замечательная мама!'),
  ('278a6dcf-b4d5-435f-bebd-984362b1ec54', 'Будни после праздника 🚀', 'После вчерашнего большого праздника сегодня утром вас снова встретили разбросанные игрушки и крики «Не хочу одеваться!». Жизнь вернулась в привычный ритм. Сделайте глубокий вдох: вы лучше всех управляете этим хаосом.'),
  ('5242afc1-567f-496d-81cf-522c0271690e', 'Пусть малыш управляет сказкой 🪄', 'Вам обоим уже надоели классические книги. Откройте Умные сказки, сделайте главным героем вашего ребёнка, а местом, которое нужно спасти, — его комнату. Так вы устроите необычное, спокойное и непринуждённое погружение в сон.'),
  ('d5e65c0a-6f82-4fee-945e-ee1f72e84c4a', 'Настойчивое «Я сам!» 🛑', 'Малыш хочет сам завязать шнурки, и на это уходит 10 минут? Не торопите его, дайте ему время. Попытки и ошибки закладывают основу будущей способности решать проблемы.'),
  ('58d0ef6e-2eed-490f-85f9-8fd8f899a9bd', 'Примиритесь с домашним хаосом 🌪️', 'Вся комната завалена игрушками? Важнее не порядок, а эти озорные минуты, проведённые вместе. Игрушки и завтра будут на месте — не изматывайте себя. Иногда лучший отдых — просто смириться с беспорядком.'),
  ('d52a333c-1a4b-40fd-a11c-b3544628c6df', 'Секретная тактика папы 👨‍🍼', 'Дневной усталости с вас вполне достаточно. Вечером доверьте папиным играм подготовку ребёнка ко сну и чистку зубов, а сами спокойно отдохните в стороне.'),
  ('dbff772c-4b84-4bcd-8132-9e03a5a6d600', 'Странный лучший друг 🥄', 'Вокруг столько дорогих игрушек, а малыш нашёл на кухне силиконовую лопатку, весь день носит её с собой и даже укладывает спать? Детский мозг удивителен. Не мешайте — пусть любит свою лопатку.'),
  ('5e23814c-ef4e-4708-8223-e1ab2ac7daa9', 'Засыпание под шёпот 🌙', 'Полностью выключите свет в комнате. Лягте рядом и очень тихо, на ушко, расскажите о том, что произошло за день. Шёпот — один из самых естественных и действенных способов подготовить мозг ко сну и помочь забыть о шуме.'),
  ('e3d2e3a9-22c5-44f1-a54d-89fc427e1f7c', 'Сюрприз в списке 🛒', 'Перед походом в магазин вы открыли Список покупок, а малыш подошёл сзади, нажал на экран телефона и добавил туда шоколад. Да, они разбираются в технологиях лучше нас!'),
  ('fc07a24b-5d02-4f37-9d95-b46ab5b5f190', 'Разрушение с целью 🧱', 'Малыш с большим трудом строит башню, а затем одним ударом разрушает её со смехом. Так он изучает физику и причинно-следственные связи. Не сердитесь: разрушенные башни — это новые нейронные связи в его мозге.'),
  ('aa798243-c44e-4178-957c-647030916048', 'Погодное предупреждение ⛅', 'Собираясь на прогулку, не доверяйте одному лишь виду из окна. С помощью помощника по погоде и одежде подберите комплект, который лучше всего соответствует реальной температуре и ветру на улице, и выходите из дома спокойно и полностью подготовленными.'),
  ('b3ff48b4-aa5c-406e-999b-73655dca1c90', 'Критик мультфильмов 📺', 'Малыш пересказывает вам мультфильм по правилам собственной грамматики и серьёзно объясняет, кто куда пошёл. Слушайте внимательно и с удивлением. Пусть он почувствует себя самым умным человеком в мире.'),
  ('c83099cc-b126-47d8-b334-d8faf9b45dde', 'Сила темноты 🌙', 'Чтобы малыш быстрее уснул, выключите в комнате все дополнительные источники света и экраны планшетов. Мелатонин активно вырабатывается только в тёмной обстановке без гаджетов.'),
  ('9f30d9e0-ccc5-4b30-b84e-6fc58af9aa3b', 'Маленькие привереды 🥦', 'Сегодня малыш отказывается от блюда, которое любил ещё вчера? Пищевая избирательность в 3 года — это нормально. Поищите полезные рецепты с яркой и необычной подачей, которая его заинтересует.'),
  ('b755d54c-d2cb-47a2-92bb-44a36d855874', 'Воображение отправляется в полёт 🚀', 'Теперь малыш не просто играет, а придумывает целые сюжеты! Картонная коробка в один миг превращается в космический корабль. С гордостью отметьте этот когнитивный скачок в трекере развития и присоединитесь к его игре.'),
  ('ef6fe3c1-b830-477f-93ee-842f8b450ab9', 'Итоги дня 🌙', 'Перед сном приглушите свет и обсудите, что сегодня рассмешило вас больше всего. Такие короткие вечерние беседы развивают способность малыша выражать свои мысли.'),
  ('00481a1e-da97-4621-84c5-0bde2c4df340', 'Невидимый преследователь 👻', 'Малыш увидел свою тень на стене, испугался и заплакал? Борьба с тенями — забавная классика для 3-летнего возраста. Выключите свет, включите фонарик и устройте танец теней, превратив этот страх в весёлый ритуал перед сном.'),
  ('81f8ee8c-8ca4-4260-b2ea-e74f425fe201', 'Палатка из горы одежды ⛺', 'Малыш раскидал стопку чистой одежды, которую вы только что сложили, и построил из неё палатку? Прежде чем сердиться, загляните внутрь. Мир фантазии и радость ребёнка ценнее усилий, потраченных на складывание вещей.'),
  ('c4bb77ab-6874-45a4-8118-c089a7246538', 'Кризис из-за бирки 🏷️', '«Она колет шею!» Маленькая бирка на спинке футболки стала главным врагом этого утра. В 3 года сенсорная чувствительность может быть особенно выраженной. Не спорьте — просто срежьте бирку и дайте этому дню шанс начаться мирно.'),
  ('04cb5d8f-0591-4ccc-8e31-0cf6555eb83a', 'Тонущие корабли в ванной 🛀', 'Вы пришли в ванную поиграть с водой, а малыш пытается утопить игрушки, которые не тонут. Он изучает физику! Пусть вода немного поплещется вокруг: водные игры помогут снять напряжение, накопившееся за день.'),
  ('123c0368-cc37-47f7-bb36-f227dd4d9131', 'Воображаемый питомец 🐕', 'Малыш гладит несуществующую собаку или кошку и придумывает ей имя? Его воображение уже вышло за рамки физического мира. Поставьте в углу комнаты невидимую миску с водой и тоже присоединитесь к этой милой фантазии.'),
  ('ecca6ba2-c00d-4fde-a20b-1268d23c90e0', 'Пир в форме для льда 🧊', 'Что бы вы ни делали, малыш не ест овощи? Полностью измените подачу. Разложите полезные закуски по маленьким ячейкам формы для льда (ice cube tray). Необычная подача часто пробуждает аппетит.'),
  ('56159a04-f4fe-4e35-a3dd-8bcc4853f3c9', 'Папа в режиме полёта ✈️', 'Малыш бегает по дому и отказывается ложиться в кровать. Позовите папу на помощь. Когда он поднимет ребёнка в воздух и устроит полёт на самолёте, комната наполнится смехом, а накопившееся физическое напряжение за считаные секунды выйдет вместе с энергией и потом.'),
  ('69ac9098-fc9c-4474-aa9d-090c0c3f7cdf', 'Режиссура в 6 утра 🎬', 'Вы ещё спите, а малыш уже стоит над вами: «Ты будешь медведем, а я — зайчиком!» Не просыпаясь до конца, изобразите рычание и сыграйте свою роль в этом абсурдном спектакле. Материнство порой требует выдающегося актёрского мастерства.'),
  ('aa6e4c45-6848-4e91-8836-f55617de9313', 'Поддержка сообщества 💬', 'Вы очень устали и не хотите никому ничего объяснять. Зайдите в Сообщество Anacan и просто почитайте. Когда вы видите, что другие мамы испытывают похожую усталость, появляется чувство «я не одна» — и это становится лучшей терапией.'),
  ('7b3c2751-f23f-4467-abdf-9463831a86cb', 'Цифровое наслаждение тишиной 🤫', 'Малыш наконец уснул! Дом погрузился в такую глубокую тишину, что звенит в ушах. Включите измеритель уровня шума и, глядя на цифру 0-10 децибел на экране, ощутите, как ваш мозг постепенно восстанавливается.'),
  ('7d093b24-909b-4f92-b3df-fe627f2322c0', '«Я сам повезу!» в магазине 🛒', 'Малыш непременно хочет сам везти тележку, и в итоге вы врезаетесь в стеллажи. Чтобы не подавлять его самостоятельность, управляйте тележкой вместе. А чтобы ничего не забыть, держите открытым список покупок в приложении.'),
  ('803c4a83-8bb9-4a65-a6e0-a757e4e816cf', 'Закончите фразу 🗣️', 'Забыв слово, малыш показывает что-то жестами и ждёт, пока вы догадаетесь? «А-а, ты говоришь о мячике?» — скажете вы и увидите, как он облегчённо вздохнёт. Его словарный запас растёт — просто мозг пока работает быстрее, чем речь.'),
  ('c30ee50d-9665-4368-af0d-6578c2cc302b', 'Прислушайтесь к телу 🩸', 'Беспричинная усталость и желание плакать? Откройте Трекер менструации. Ваше тело подаёт сигналы. Проявите заботу о себе и приготовьте перекус с магнием из раздела полезных рецептов.'),
  ('c49b057e-0774-42da-aec0-ee5fcc238471', 'Избирательный аппетит 🍝', 'Ребёнок ест только 2-3 любимых блюда? Не переживайте. Проверьте недельный баланс с помощью инструмента контроля питания и старайтесь не давить на ребёнка за столом.'),
  ('462a51f8-d8f0-4c41-8551-81fbd18e8c62', 'Пусть он сам придумает конец сказки 🪄', 'Вам обоим уже надоели классические книги. Откройте умные сказки и сегодня вечером позвольте ему направлять сюжет. Спросите: «Куда теперь поедет машина?» — и пусть он засыпает под придуманный им забавный и нелепый финал.'),
  ('a8ffc7b0-9821-4b11-9ed7-be3302b5f4fb', 'Мифы об идеальной маме 🛑', 'Дети в социальных сетях уже рассказывают стихи, а ваш ребёнок всё ещё путает слова? Немедленно прекратите сравнивать! У каждого ребёнка свой уникальный темп развития. Он идеален в своём собственном темпе.'),
  ('fca7853a-0c3e-4553-8c15-c32fa7564774', 'Олимпиада по надеванию обуви 👟', 'Он надел правый ботинок на левую ногу и категорически не хочет его снимать? Пусть так и остаётся. Чувство самостоятельности и гордость «Я сделал сам!» важнее, чем правильно надетая обувь. Это также закладывает основу для умения решать проблемы в будущем.'),
  ('344d14b0-cfc9-4ff3-af6f-44e0148ab198', 'Трагедия с невидимым мусором 🗑️', 'Он ищет и оплакивает тот ненужный клочок бумаги, который сам выбросил, а вы отправили в мусорное ведро! Такова логика трёхлетнего ребёнка. Поскольку вернуть его уже нельзя, сразу переключите внимание малыша на что-нибудь более яркое.'),
  ('be71bad2-041d-4cb4-a658-89cb36e8a738', 'Время маме подзарядиться 🔋', 'Он уже 10 минут тихо собирает пазл самостоятельно. А вы хотите потратить это время на уборку дома. Нет! Прилягте на диван. Вам тоже нужно подзарядиться, чтобы выдержать такой темп до вечера.'),
  ('d2f93631-6ef4-4ba4-9cac-259dafd2fb22', 'Привыкаем к темноте 🌙', 'Ребёнок беспокоится, когда в спальне гаснет свет? Поставьте в углу комнаты небольшой ночник тёплого цвета (жёлтого или оранжевого). При этом остальная часть комнаты должна оставаться полностью тёмной для глубокого сна.'),
  ('5407f02f-f40a-48e1-b4f8-80cd1fc9345c', 'Утренний диктатор за работой 👑', '«Не садись туда, там будет сидеть мой мишка!» За завтраком он командует всем за столом. Не подавляя резко его волю, сохраняйте равновесие, отвечая: «Хорошо, пусть мишка сидит там, а я сяду здесь».'),
  ('a1a50d57-7314-4042-848d-a89f6c8fc209', 'На природу ⛅', 'Четыре стены уже заставляют нервничать и его, и вас. Проверьте погоду и рекомендации по одежде с помощью соответствующего инструмента и сразу отправляйтесь в парк. Бег и свобода на свежем воздухе помогают быстро остановить даже самый сильный кризис у малыша.'),
  ('e61af62b-257c-41ec-8846-9d470f2646d9', 'Вечерние минуты покоя 🛀', 'Весь день прошёл под лозунгом «Я не хочу!». Тёплая ванна нужна не только для гигиены, но и для успокоения его перевозбуждённой нервной системы. Шум и тепло воды помогут смыть всё упрямство.'),
  ('8169372c-8d17-46fc-bfc3-eda3a929eaa6', 'Забывчивость в магазине 🛒', 'Понадеялись на память, сходили в магазин и вернулись без подгузников? Такое бывает. Возьмите за привычку сразу добавлять всё необходимое в Список покупок — пусть приложение станет вашей цифровой памятью.'),
  ('a15765ea-b7ce-42a7-91ae-209256ee1beb', 'Мама, посмотри на меня! 👀', 'Когда вы смотрите в телефон или чем-то заняты, он подходит, бьёт вас по руке или встаёт перед вами. Его можно понять: ему нужно ваше безраздельное внимание. Всего 5 минут непрерывной игры с постоянным зрительным контактом помогут ему успокоиться.'),
  ('de1347cd-769b-44d4-8aff-75ce2b7d2f0c', 'Подтверждение тишины 🤫', 'После шумного дня, когда ребёнок уснёт, измерьте уровень тишины в комнате с помощью Шумомера. Наблюдение за цифрами, приближающимися к нулю, действует на мозг мамы как прекрасный массаж — настоящее визуальное спокойствие.'),
  ('0ff315d9-2ad1-4c8c-9187-ea4c26042a66', 'Как быстро летит время!', 'Он уже стал самостоятельным человеком со своими решениями. В будущем его сильный характер ещё не раз станет поводом для вашей гордости. Эти дни больше не повторятся — обнимите его с любовью.'),
  ('e4430813-5ad7-446e-9502-6e658d83eddd', 'Овощной хирург 🥦', 'Он откладывает овощи из супа в сторону, словно рассматривает их под микроскопом? Не боритесь с этим. В разделе полезных рецептов вы найдёте самые разнообразные и вкусные способы превратить овощи в пюре и незаметно добавить их в соусы.'),
  ('5625eb93-64b3-45e9-9346-29a2c6af885f', 'Детокс на природе обязателен 🌳', 'В четырёх стенах его энергия превращается в агрессию. Независимо от погоды и одежды, оденьте малыша соответствующим образом и обязательно выведите на улицу. Прикосновения к земле и собирание листьев быстро успокаивают его нервную систему.'),
  ('d33d70dc-19c8-4087-8ed8-270685911bfd', 'Мистическая сила шёпота 🌙', 'Ваши голосовые связки уже устали от чтения сказок. Полностью выключите свет в комнате. Лягте рядом и очень тихо, шёпотом расскажите ему на ушко о том, что произошло за день. Шёпот — один из самых успокаивающих способов подготовить мозг ко сну.'),
  ('e578603f-02ec-4734-b19f-2d0ca949a8e2', 'Удивительное создание 🎈', 'На этом долгом пути вас ждёт ещё много удивительного. Например, вчера он выучил новое слово, а сегодня уже использует его в философском высказывании! Эти дни больше не повторятся.'),
  ('0cdb7f22-d990-414a-b36e-54d6d47e1b4f', 'Тайный шоколадный перерыв 🍫', 'Мама, которая тайком от него ест шоколад, спрятавшись за кухонным шкафом, эта глюкоза положена вам по праву. Не вините себя! Чтобы выдержать эту безумную энергию, вам обязательно нужно подзаряжаться. Вдохните и продолжайте жевать.'),
  ('62a2e4b7-b7ef-4d46-a134-22e1f4da5625', 'Он сам в умной сказке 🪄', 'Сегодня вечером в «Умных сказках» назовите главного героя именем вашего ребёнка. Расскажите, как персонаж сказки не почистил зубы, а потом пожалел об этом, — так вы сможете ненавязчиво привить важные ценности.'),
  ('ce8759a7-ff69-4b27-a788-668b48e71999', 'Инженер туалетной бумаги 🧻', 'Несколько минут тишины... А войдя в комнату, вы обнаруживаете, что вся туалетная бумага размотана и разбросана по дому! Вместо того чтобы сердиться, соберите бумагу и вместе слепите из неё снеговика. Победите хаос с помощью творчества.'),
  ('1f94fede-7afb-4d0a-8e39-07ab7d2da0c4', 'Ты — ребёнок, я — мама 👩‍👧', 'Игра со сменой ролей началась! Он командует вами: «Иди сюда, ешь свою еду». С удовольствием поддержите его первый опыт лидерства и молча сыграйте роль его ребёнка.'),
  ('77330b1b-94b4-4438-9dd4-9ea117490b54', 'Искусственный интеллект, реальное решение 🤖', 'Почему 3-летний ребёнок вдруг начал грызть ногти? Забудьте о пугающих статьях в интернете, где всё объясняют психологической травмой. Спросите у Anacan AI, может ли это быть всего лишь временной реакцией на стресс, и получите научно обоснованный ответ.'),
  ('e7437e5e-38bf-45b1-8db0-74786f20b535', 'Перерыв для пары 🥂', 'Ребёнок уснул. Теперь отложите телефоны и домашние дела. Сядьте напротив партнёра и всего 20 минут поговорите о чём-нибудь, кроме счетов и ребёнка. Вы ведь не только родители, но и пара!'),
  ('3a4c5cc8-5f54-4aef-b016-9394a079ec83', 'Находки из карманов 🪨', 'При стирке брюк вы нашли в кармане 3 камня разного размера и скорлупу каштана? Для него это самая ценная коллекция в мире. Вместо того чтобы выбрасывать находки, сложите их в небольшую коробку и сделайте сундук с сокровищами.'),
  ('68c1a1ff-c119-4521-aae1-9a7a984caad7', 'Выключите свет — пусть приходит сон 🌙', 'Чтобы малыш быстрее уснул, за 1 час до сна выключите все дополнительные источники света в комнате и экраны планшетов. Мелатонин (гормон сна) активно вырабатывается только в тёмной обстановке без гаджетов.'),
  ('9021ef15-5cf5-4f9d-8592-aab7e32c65a0', 'Чувство полного истощения 🔋', 'Вам хочется на всех кричать? Шум буквально сверлит мозг? Это самое настоящее выгорание. Немедленно оставьте ребёнка в безопасном месте (или передайте папе), выйдите в другую комнату и без всяких фильтров выпишите весь стресс в Дневник настроения.'),
  ('a5815a11-4b6f-4f3d-a6ff-4d587c286a65', 'Музыкальное пробуждение 🎶', 'Солнце ещё не взошло до конца, а он уже прыгает на кровати и издаёт ритмичные звуки. Самый громкий, но самый милый будильник в мире! Начните день с улыбки, любуясь его неиссякаемой энергией.'),
  ('afb9fd4f-60e2-4547-87e2-d867963a1345', 'Дневник эмоций 📝', 'После того как ребёнок уснёт, откройте Дневник настроения. Запишите на память самый смешной и абсурдный момент дня, который заставил вас смеяться больше всего. Спустя годы при чтении у вас навернутся слёзы на глаза.'),
  ('db2d884d-1367-4ebc-a61b-9a450673d64d', 'Практика тихого часа 🥱', 'Он не хочет ложиться спать днём, хотя глаза уже слипаются? Классическое сопротивление 3-летнего ребёнка. Не заставляйте его: приглушите свет в комнате и объявите «тихий час с книжками», создав новый ритуал.'),
  ('0f647bd8-9749-4a55-969b-bfc85ddb7152', 'Секретное оружие папы 🤡', 'Когда ваши приёмы уже не работают, странные звуки и смешные рожицы папы мгновенно спасают ситуацию. Во время вечерних кризисов сразу передавайте эстафету ему, а сами отдохните и понаблюдайте со стороны.'),
  ('e44cdd54-2858-49fa-8fd7-06dc369d29b6', 'Массаж от папы 💆‍♂️', 'Сегодня вы долго были на ногах, и от постоянной беготни за малышом у вас болит спина. Как только ребёнок уснёт, попросите партнёра сделать вам 10-минутный массаж плеч. Вы — опора семьи, а опоре тоже обязательно нужно восстанавливаться.'),
  ('9c8523f0-548b-4581-bde4-2a8295db3639', 'Приглашение в темноту 🌙', 'Чтобы малыш быстрее уснул, выключите в комнате все дополнительные источники света и экраны планшетов. В тёмной обстановке без гаджетов мелатонин вырабатывается активнее, облегчая засыпание.'),
  ('b7c3f40e-e406-412b-86a2-1c33a12692d8', 'Мысли о детском саде 🏫', 'Чувствуете, что малышу уже нужно больше общения? Подходящее ли сейчас время для детского сада? Зайдите в Сообщество Anacan и почитайте реальные истории других мам об адаптации — так вам будет легче принять решение.'),
  ('d8d022ce-8e44-42aa-972f-aa293c4341c8', 'Давайте я помогу! 🧽', 'Пока вы моете посуду, малыш непременно пододвигает стул и хочет играть с водой? На самом деле он хочет не столько помочь, сколько быть в центре процесса. Дайте ему небольшую пластиковую миску и позвольте тоже её намыливать.'),
  ('63dc600c-4255-41f7-8695-78dd689a1998', 'Сказки шёпотом 🪄', 'Полностью выключите свет в комнате. Лягте рядом и очень тихо прошепчите малышу на ухо короткий сюжет из Умных сказок. Шёпот — один из самых естественных и успокаивающих способов подготовить мозг ко сну.'),
  ('76d2443b-1074-45cd-a82d-59ba223792bb', 'Живой диктофон 🎙️', 'Сегодня малыш повторяет своей игрушке ту эмоциональную или странную фразу, которую вчера услышал из вашего разговора с подругой! Его словарный запас растёт с невероятной скоростью, и он копирует вас. Теперь вам стоит вдвойне внимательнее следить за своими словами.'),
  ('a624ef08-9c66-462b-82e4-a4aa90f5b17b', 'Цените себя 🥗', 'Вы приготовили яйца 4 разными способами, чтобы накормить малыша, но что поели сами? Порадуйте себя особым блюдом из раздела полезных рецептов — его можно приготовить за 5 минут, и оно богато железом и кальцием.'),
  ('0f7458af-fb58-4fe6-9907-6a5b773bca96', 'Помощь белого шума 🤫', 'В момент засыпания малыш особенно чувствителен к звукам. Чтобы заглушить шум с улицы, включите в комнате фоновый звук из Шумомера и создайте спокойную атмосферу на всю ночь.'),
  ('143f9431-42d8-41e6-9983-ce9dde347219', 'Вся одежда в пятнах 🎨', 'Пижама испачкана едой, а вся одежда — краской? Дети не обязаны всегда оставаться чистыми: исследуя мир, они неизбежно пачкаются. Используйте силиконовые нагрудники, а обо всём остальном позаботится стиральная машина.'),
  ('6aecb8fd-7228-4ba7-9f34-65a8f0cda801', 'Покорение мебели 🧗‍♂️', 'Малыш цепляется за диван или кресло и пытается забраться наверх? Так развиваются равновесие и мышечная сила. Обеспечьте ему безопасность, но не мешайте этим альпинистским попыткам и исследованию законов физики.'),
  ('0db41c26-c87d-4bd7-8650-e9fd07449904', 'Мамам нужно выговориться 💬', 'Вас изматывает мысль, что этот ребёнок никогда не успокоится? Зайдите в Сообщество Anacan — там вы увидите, что ближе к 3 годам каждый ребёнок проходит через такие бурные кризисы, и сможете вздохнуть с облегчением.'),
  ('448fd3b8-143f-4fee-a40b-1b20e42ebbba', 'Один, два, три... десять! 🔢', 'Малыш пытается считать свои пальчики или игрушки? Просыпаются математические способности. Не упустите эти маленькие попытки, которые развиваются с невероятной скоростью.'),
  ('5a020277-4aac-4623-8f46-93168c2f54e5', 'Ночная смена папы 👨‍🍼', 'Не берите все ночные пробуждения и укладывания малыша только на себя. Разбудите партнёра: быть командой — значит поровну делить ответственность. Сегодня укладывает он.'),
  ('026f00f3-6e56-4ac5-a91b-bd5bd82cd187', 'Пробуем тихий час 🥱', 'Малыш не хочет ложиться спать днём и плачет? Не заставляйте его. Приглушите свет в комнате, объявите тихий час для рассматривания книг и создайте новый ритуал, который поможет расслабиться вам обоим.'),
  ('53b445aa-e1d7-4c46-9d5a-07132c91031c', 'Страхи в темноте 🌌', 'Когда гаснет свет, предметы в комнате превращаются в чудовищ? Включите среди Белых шумов звук материнской утробы, чтобы вернуть малышу то знакомое и безграничное чувство безопасности.'),
  ('f4eb03a9-f74f-423a-ab2a-59d54da2db98', 'В поисках логики 🧩', 'Простые игрушки уже не привлекают малыша — теперь он придумывает более сложные игры. Найдите в разделе Рекомендуемых товаров игры, которые бросят вызов его интеллекту и помогут развить логическое мышление.'),
  ('135b57f3-06e7-4fc4-b590-bec1151ee33b', 'Волшебство тёплой воды 🛀', 'Весь день прошёл под бесконечное «не хочу». Тёплая ванна нужна не только для гигиены — она поможет успокоить его перевозбуждённую нервную систему. Шум и тепло воды смоют всё упрямство.'),
  ('57cfce2e-d64c-49cb-9f8b-295055620f21', 'Загадка природы 🍁', 'Скучная домашняя обстановка угнетает вас обоих. Отправляйтесь в парк с миссией найти камень самой необычной формы. Природа для него — огромная лаборатория, которая поможет снять всё напряжение.'),
  ('682b0a2a-83c6-46cb-a100-02da150309f7', 'Подражание животным 🐶', 'Он не только издаёт звуки, но и ползает как собака и ласкается как кошка? Язык тела и воображение удивительным образом объединяются. Присоединитесь к этой игре на ковре и снимите стресс вместе с ним.'),
  ('01a8a883-66ea-4e90-9796-1cd4c7aa4386', 'Offline-час для мамы ☕', 'Когда ребёнок погружён в свой мир и играет, не спешите сразу убирать дом. Налейте себе горячего чая, отложите телефон и 15 минут просто посидите, ни о чём не думая.'),
  ('7fc36514-28e6-4738-b9f6-f0c9cd9fa57d', 'Пауза для пары 🥂', 'Ребёнок уснул. Теперь отложите домашние дела. Хотя бы 20 минут поговорите с партнёром на любую тему, кроме ребёнка и расходов. Ведь вы не только родители, но и пара!'),
  ('8b2d61db-8be9-4916-a184-f14d02885b17', 'Генератор «Что это?» ☝️', 'Показывает пальцем на всё подряд и спрашивает, как это называется? Он просит вас назвать для него окружающий мир. Это большой скачок в развитии общения! Даже если вы устали, продолжайте терпеливо повторять названия предметов.'),
  ('6716e6c0-2c87-4096-9dc2-661b570d83da', 'Пульт в холодильнике 📺', 'Не можете найти пульт от телевизора? Загляните в холодильник или шкаф для обуви. Раскладывая предметы согласно собственной логике, ребёнок исследует мир. Вместо того чтобы сердиться, отнеситесь к этому абсурдному детективу с улыбкой.'),
  ('7e1b9939-5806-440f-9214-8ee42a76c83e', 'В поисках воображаемой ранки 🩹', 'Сразу после пробуждения ребёнок находит на теле невидимую ранку и настойчиво требует наклеить на неё пластырь. Дело не в физической боли, а в потребности во внимании и ласке. Не спорьте: наклейте маленький пластырь, поцелуйте это место — и день будет спасён.'),
  ('ce6bc378-f040-49dc-a292-ef6ffa4a4247', 'Синдром внезапного голода 🥱', 'Стоит лечь в кровать, как ребёнок говорит: «Мама, я голоден» — и хочет бежать на кухню. Настоящий шедевр для отсрочки сна! Заранее включите в вечерний рацион небольшой перекус, способствующий засыпанию, например банан, чтобы предупредить эту отговорку.'),
  ('7a0aa78e-7c5e-4ec5-9361-dc21cc74b32f', 'Тревожная тишина 🤫', 'Он один рассматривает картинки в комнате, а в доме стоит глубокая тишина. Но эта тишина кажется вам подозрительной, и вы в любой момент ждёте катастрофы. Расслабьтесь. Иногда детям тоже хочется побыть одним. Откиньтесь на спинку кресла и насладитесь этим редким моментом offline.'),
  ('7dcdfa61-d4a7-4888-bf22-0453312c6bae', 'Мысли вслух 💭', 'Лёжа в кровати, ребёнок громко рассказывает самому себе о событиях дня. Так он обрабатывает информацию и воспоминания. Откройте трекер развития и с гордостью отметьте, как стремительно растёт его способность самостоятельно придумывать и рассказывать истории.'),
  ('dcfa33ac-90f3-4b1d-b8de-e6f8c966ff39', 'Линии на ковре 📏', 'Он старается ходить, не наступая на линии ковра, и требует того же от вас. Крупная моторика и концентрация внимания прекрасно работают вместе. Не прерывайте игру — сделайте и вы несколько шагов, перепрыгивая вместе с ним через линии.'),
  ('80fe5b22-0f4c-4f31-ac99-30418e5a6c6a', 'Глоток воздуха для мамы 🌬️', 'От домашнего хаоса у вас уже звенит в ушах. Проверьте погоду, тепло оденьтесь и выйдите на улицу хотя бы на 15 минут. Пусть ребёнок собирает камешки, а вы просто глубоко вдыхайте холодный свежий воздух, касающийся вашего лица.'),
  ('93c26bc0-b2a6-4580-91d3-d91792e077a2', 'Язык динозавров 🦖', 'Сегодня утром он не человек, а динозавр и отвечает на все ваши вопросы только рычанием. Ролевые игры — прекрасный инструмент для развития личности. На мгновение станьте не мамой, а другим динозавром и ответьте ему на его языке.'),
  ('b992124a-a4ae-4e30-a81b-b79de4b95a68', 'Признание в усталости 📝', 'Вам кажется, что никто вас не понимает и не замечает ваших усилий? Отбросьте натянутые улыбки. Запишите в дневнике настроения, насколько вы на самом деле сегодня истощены. Каждое слово, появившееся на экране, снимет тяжёлый груз с ваших плеч.'),
  ('075e0950-03bc-496b-a1a2-1172377fb523', 'Искусственный интеллект и тревоги 🤖', 'Вы внезапно встревожились из-за того, что ребёнок не может произносить некоторые звуки? Закройте непрофессиональные и пугающие интернет-форумы. Спросите у Anacan AI о нормах речевого развития к 3 годам и получите научно обоснованный и успокаивающий ответ.'),
  ('9bbc80a7-dd83-4c11-86b7-3f3e1fd0e2b9', 'Цирк в кровати 🎪', 'Когда приходит время спать, кровать мгновенно превращается в цирковую арену. Малыш прыгает, ползает, кричит. Не повышая голоса, приглушите свет. Так он выплёскивает последние остатки энергии. Постепенно успокойте эту бурю с помощью истории с очень медленным ритмом в «Умных сказках».'),
  ('c4897803-48e7-46f1-aca1-db692fe7b9f1', 'Дверная ручка, которой нельзя делиться 🚪', 'Со словами «Я сам открою дверь!» малыш бежит вперёд вас. Если дверь открыли вы, он со слезами просит закрыть её, чтобы открыть самому. В этом возрасте ощущение контроля — самое главное. Позвольте ему открыть дверь: такие маленькие победы укрепляют его пока ещё хрупкую уверенность в себе.'),
  ('2b40e6c9-46bc-4fb2-8d09-1e690e1a478c', 'Сообщество поддержки 💬', 'Сегодня малыш так сильно сопротивлялся всему, что вы чувствуете себя плохой мамой. Сразу загляните в Сообщество Anacan. Прочитав о сегодняшних бунтах детей других мам, вы поймёте, что не одиноки и на самом деле прекрасно справляетесь.'),
  ('4f85a7f5-323c-4830-b901-61f69a9b8176', 'Тайное «и хочется, и колется» 🤔', 'Малыш подходит к вам и произносит совершенно парадоксальные фразы вроде: «Дай мне воды, но не давай». В его голове одновременно существуют два противоположных желания. Не ищите в этом особой логики — просто поставьте воду на стол и оставьте решение за ним.'),
  ('fb64f95e-ceac-49e1-96ee-95e171273ead', 'Попытки ремонта с молотком и шурупами 🛠️', 'Малыш стучит по мебели любой попавшейся под руку твёрдой игрушкой, изображая ремонт. Даже если эти звуки пронизывают ваш мозг, для него это исследование причинно-следственных связей. Дайте ему пустую картонную коробку и деревянную ложку — пусть продолжает свой шумный ремонт там.'),
  ('0b8c858b-4b69-4199-b627-a7a497686efd', 'Не мусор, а искусство 🎨', 'Посреди комнаты малыш создал большое произведение искусства из мелких обрывков бумаги и нарезанных ниток и не разрешает вам его выбрасывать. На время забудьте об идеальной чистоте. Отнеситесь с уважением к созданному им хаосу — уборка может подождать до завтра.'),
  ('5f97fec7-d72f-4377-af18-4420a1663ca4', 'Терапия шумомером 🤫', 'Нескончаемый домашний шум наконец стих. Малыш спит. Включите шумомер и наблюдайте, как цифры на экране опускаются до 0 децибел. Почувствуйте, как абсолютная тишина в комнате словно делает вашему мозгу визуальный массаж.'),
  ('63b3f3e0-ceca-4b44-a2ea-ae171ce3413f', 'Театр перед зеркалом 🎭', 'С самого утра малыш стоит перед зеркалом и репетирует разные выражения лица: плачет, смеётся, удивляется. Так он учится выражать свои эмоции и узнаёт, как при этом меняется его лицо! С гордостью наблюдайте издалека за этой гениальной актёрской игрой.'),
  ('14f4e22b-ebcd-4b44-af1e-7caf9bc49874', 'Волшебные папины руки 🫂', 'От ношения малыша весь день у вас уже отваливаются руки, а он снова просится на ручки. Позовите папу. Полёты в папиных руках удовлетворят потребность ребёнка во внимании, а вашим рукам и спине подарят такой необходимый отдых.'),
  ('8e97dc44-4076-463e-90aa-e9a38f43a406', 'Логика под вопросом 🧐', 'Почему рыбы не ходят? Ранним утром его мозг просыпается с философскими вопросами. Даже если они ставят вас в тупик, терпеливо старайтесь всё объяснить. Ваш голос для него — самый надёжный и прекрасный способ познавать Вселенную.'),
  ('d78d5945-d2b9-4d6b-be69-c36a9e85a337', 'Хаос со списком покупок 🛒', 'Вы стоите у кассы в магазине и понимаете, что снова забыли самое важное. Ваше внимание и без того разрывается между тысячей дел. Возьмите за привычку сразу же записывать всё необходимое в «Список покупок» в приложении — помогите себе.'),
  ('62d4901b-19ff-4b33-a0e0-89d727535d96', 'Гордость за одежду задом наперёд 🧦', 'Пятка носка оказалась сверху стопы, но малыш гордо ходит в нём, потому что надел его сам. Ни в коем случае не вмешивайтесь. Его ощущение «Я смог!» — психологическая основа, которая в миллион раз важнее красоты или правильно надетой одежды.'),
  ('79c5f477-357d-4a5a-a226-aa71c2153c6a', 'Истории шёпотом 🌙', 'Сегодня вам пришлось так много говорить, что голос уже устал. Выключите свет, лягте рядом с малышом и шёпотом расскажите ему на ушко о событиях дня. Шёпот помогает ему сосредоточиться и словно гипнотизирует мозг, подготавливая его к глубокому сну.'),
  ('b3b80c54-4891-4e55-9e0b-d88a4a322bdd', 'Концерт на кухне 🥄', 'Малыш достал кастрюли и деревянные ложки и устроил посреди кухни шумный концерт. Даже если у вас болит голова, так развиваются его чувство ритма и моторика. Скажите ему «Браво!» и надейтесь, что концерт поскорее закончится.'),
  ('26929739-4514-47f4-b2ff-3f79743e2a52', 'Измерение золотой тишины 🤫', 'Домашний хаос наконец утих, и малыш уснул. Не спешите мыть посуду! Включите шумомер и в течение 15 минут смотрите на показатель абсолютной тишины в комнате (0-10 децибел), наглядно ощущая, как отдыхает ваш мозг.'),
  ('691e79df-4ad4-4dc1-80d2-9bb367dfc70e', 'Трагедия с очищенным бананом 🍌', 'В 8 утра в комнате разразилась революция из-за того, что вы сами очистили банан? Золотое правило этого возраста: малыш должен решать всё сам. Приклеить кожуру обратно не получится, поэтому сразу переключите его внимание на что-нибудь другое и не менее нелепое, чтобы погасить кризис.'),
  ('66770f83-ef83-4481-9f8c-e9788791f68a', 'Операция «Спрятать телефон» 📱', 'Вы не можете найти свой телефон, а спустя некоторое время обнаруживаете его в ящике с игрушками. Малыш не хочет делить ваше внимание с телефоном. Отложите устройство и уделите ему 15 минут безраздельного внимания.'),
  ('b18d81af-044b-40e7-b55d-b23baee972a4', 'Тишина в децибелах 🤫', 'Наконец-то малыш уснул! Вы не можете поверить в тишину, воцарившуюся дома. Включите шумомер и, глядя на цифру 0-10 децибел на экране, почувствуйте, как ваш мозг постепенно отдыхает.'),
  ('09d17b10-a60b-4930-b773-b0f5bb7e0366', 'Не отдам свою игрушку! 🧸', 'В парке малыш никому не хочет уступать место на горке или в песочнице и крепко держит свои игрушки. Это не эгоизм, а защита личных границ. Не заставляйте его делиться — лучше в игровой форме научите соблюдать очередность.'),
  ('0a13d571-0f47-4b38-ba09-6279a4e6c3b5', 'Приглашение в темноту 🌙', 'Малыш беспокоится, когда в спальне гаснет свет? Поставьте в углу комнаты небольшой ночник тёплого цвета. При этом остальная часть комнаты должна оставаться полностью тёмной для глубокого сна.'),
  ('f1a7ace3-b71a-47a5-8150-e29d91b1d2f6', 'Когда мама устала 🛑', 'Вы не робот. Если сегодня у вас нет сил готовить, закажите еду или просто сварите макароны. Быть идеальной мамой — не значит делать всё самостоятельно. Позвольте себе это.'),
  ('012a4a46-c01f-4202-b7ec-b6dfb922b323', 'Сюрприз в списке 🛒', 'Перед походом в магазин вы открыли список покупок, а малыш подошёл сзади, нажал на экран телефона и что-то там начеркал. Да, он копирует даже вашу цифровую жизнь!'),
  ('0f7001d8-21ca-493f-95e3-7b29b5f52d2b', 'Признание в дневнике настроения 📝', 'Возьмите телефон. Вместо того чтобы листать в соцсетях чужие публикации, откройте Дневник настроения и сохраните на будущее самый забавный момент с малышом за сегодня. Цифровая терапия работает.'),
  ('507a4882-997e-48f9-8d0c-a6ff5f18c3ac', 'Торг как у адвоката 🗣️', '«Я поиграю ещё всего 5 минут, а потом оденусь», — говорит малыш? Он уже пытается заключить с вами профессиональную сделку. Развитая речь — это прекрасно, но не забывайте с любовью отстаивать свои границы и правила.'),
  ('982b6e37-c6cb-46f9-bd93-9fafd76bcda8', 'Тихий час 🥱', 'Малыш не хочет ложиться спать днём и плачет? Не заставляйте его. Приглушите свет в комнате и объявите тихий час для рассматривания книг — так у вас появится новый ритуал, который поможет отдохнуть вам обоим.'),
  ('dd274cad-cc38-4230-a074-0f529d065804', 'Сегодня я это не ем 🥣', 'Сегодня малыш отказывается даже пробовать суп, который вчера ел с удовольствием. Если у него нет проблем с зубами, то он просто испытывает границы дозволенного. Загляните в план питания и выберите другие рецепты, которые обеспечат его теми же витаминами.'),
  ('ef5d3cbd-0aa0-493b-94cf-cb55ec5a7526', 'Странные звуки папы 🤡', 'Когда ваши способы уже не помогают, странные звуки и смешные рожицы папы мгновенно спасают ситуацию. Во время вечерних капризов сразу передайте ему эстафету, а сами отдохните и понаблюдайте со стороны.'),
  ('805b4060-d925-4469-abb9-000b87b286a1', 'Загадка природы 🍁', 'Скучная домашняя обстановка утомляет вас обоих. Отправляйтесь в парк с миссией найти камень самой необычной формы. Природа — величайшая лаборатория для малыша, и она поможет ему избавиться от стресса.'),
  ('88ec7e91-36e6-4aab-9210-fc0f8e69cab3', 'Воображаемые гости за столом ☕', 'Малыш протягивает вам пустую чашку со словами «Пей чай» и разговаривает с другом, которого нет в комнате? Это настоящий шедевр развивающегося воображения. Не прерывайте представление, которое разворачивается в углу комнаты, — присоединитесь и выпейте этот чай.'),
  ('9c237165-d4a6-41d4-ba0a-333830a89409', 'Я в умной сказке 🪄', 'Вы уже знаете классические книги наизусть. Откройте Умные сказки, сделайте своего ребёнка главным героем, а его комнату — местом, которое предстоит покорить, и устройте необычный ритуал перед сном.'),
  ('62114884-cb2a-44c8-ab0b-33ab815b8e09', 'Мир в ванной 🛀', 'Играть с водой так весело, что малыш не хочет выходить из ванны, даже когда пальчики уже сморщились. Предупредите его за 5 минут и установите таймер. Правило «Когда прозвенит звонок — выходим» часто срабатывает.'),
  ('9f52c47e-5431-4d83-b54d-9c8d7cbf5228', 'Свобода «Не держи меня за руку!» 🚶‍♂️', 'На улице малыш наотрез отказывается держать вас за руку и хочет бегать самостоятельно. В безопасных местах предоставьте ему эту свободу. Не спускайте с него глаз, но позвольте покорять мир своими шагами.'),
  ('222c5b3e-e10d-4be3-be74-5b7c060039a8', 'Вечернее умиротворение 🛁', 'За целый день и малыш, и вы выбились из сил. Во время тёплой ванны включите на фоне успокаивающие звуки природы. Гармония воды поможет подготовиться к глубокому сну даже самому непоседливому ребёнку.'),
  ('658a0f7f-5501-4d36-97c8-25ebf4c2bf93', 'Усталость от прикосновений 🔋', 'Весь день малыш карабкается по вам, просится на руки и играет с вашими волосами. А вам хочется лишь немного личного пространства. Усталость от прикосновений (touched out) действительно существует. Вы имеете право хотя бы на 15 минут уединиться в комнате.'),
  ('fd872988-ca1c-4392-86ef-3fa893d01f3e', 'Страх сливного отверстия 🛀', 'Ребёнок, который раньше не хотел выходить из воды, вдруг начал плакать и бояться сливного отверстия в ванне? По мере развития воображения могут возникать необоснованные страхи. Закройте отверстие пластиковой игрушкой и помогите малышу почувствовать себя в безопасности.'),
  ('380c78ab-6c26-4edf-8c80-e7615f9b4b80', 'Время для пары 🥂', 'Ребёнок уснул. Теперь отложите домашние дела. Хотя бы 20 минут поговорите с партнёром о чём угодно, кроме ребёнка, проблем и расходов. Прежде чем стать родителями, вы были парой!'),
  ('752bc100-4fdb-4f78-84aa-dd9676151255', 'Разговоры с неодушевлёнными предметами 🗣️', 'Малыш с совершенно серьёзным видом что-то рассказывает камню в парке или стулу дома и даже ругает их. С помощью символических игр он осмысливает окружающий мир. Обязательно отмечайте такие необычные сценарии в трекере развития.'),
  ('7bfbea7d-ee3e-4b33-88e0-e90f78f2538d', 'Сеанс массажа от папы 💆‍♂️', 'Сегодня вы много времени провели на ногах, и от постоянной беготни за малышом у вас болит спина. Как только ребёнок уснёт, попросите партнёра сделать вам 10-минутный массаж плеч. Вы — опора дома, а опоре тоже обязательно нужно восстанавливаться.'),
  ('14bae514-5bcb-45ca-923d-75a7333cefe5', 'Тактика откладывания сна ⏱️', 'Когда приходит время спать, малыш вдруг хочет пить, просится в туалет или начинает прощаться со стеной? Установите таймер. Введите правило «когда звенит таймер, все ложатся спать», чтобы терпеливо завершить эти бесконечные прощания.'),
  ('4ec63d29-5d5a-4c61-aeca-3683d2926fad', 'Запас сил для мамы 🥗', 'Вы придумали разные блюда, чтобы накормить малыша, а сами снова остались голодной? Выберите среди полезных рецептов обед, который готовится за 10 минут и богат железом и кальцием. Позаботьтесь о себе — вы этого заслуживаете.'),
  ('d6b3a2c2-7743-47f8-927a-59220b3461a1', 'Помощник по стирке 🧺', 'Вы с трудом складываете одежду, а малыш, уверяя, что помогает, снова разбрасывает всё по комнате. Вместо того чтобы сердиться, превратите дело в игру: посмотрим, кто быстрее забросит эти носки в корзину?'),
  ('95036444-eb4a-4cd7-a33d-678f3daaa180', 'Авангардный взгляд на моду 👗', 'Малыш надел летние шорты поверх зимнего свитера и не хочет их снимать? Ничего страшного. Ребёнок, который выходит на люди в необычном наряде, на самом деле смело отстаивает своё решение. Не подавляйте его волю.'),
  ('98f4059e-feba-4e5c-88c8-f44ceadd630c', 'Как распознать ночной ужас 😭', 'Малыш среди ночи проснулся с закрытыми глазами, плачет и никого не слышит. Проверьте это с помощью анализа плача: если это ночной ужас, не пытайтесь его разбудить. Просто оставайтесь рядом и молча помогите ему почувствовать себя в безопасности.'),
  ('bfca2126-084c-4371-a225-6bbeaa8fe2d1', 'Предупреждение о погоде ⛅', 'Собираясь на прогулку, не полагайтесь только на вид из окна. С помощью помощника по погоде и одежде подберите наряд, который лучше всего соответствует реальной температуре и ветру на улице, чтобы выйти из дома спокойно и во всеоружии.'),
  ('25567149-e2e9-4c4d-aaff-501c9547f638', 'Поддержка сообщества 💬', 'Вы очень устали и не хотите никому ничего объяснять. Зайдите в сообщество Anacan и просто почитайте публикации. Увидеть, что другие мамы испытывают похожую усталость, и почувствовать «я не одна» порой становится лучшей терапией.'),
  ('3df12920-0213-48db-ae96-b67ec62ae28a', 'Живой концерт и соседи 🎤', 'Малыш берёт ложку, встаёт посреди комнаты и во весь голос распевает песню. Не переживайте о том, что подумают соседи. В вашем доме растёт звезда — просто аплодируйте.'),
  ('3f3676c6-cf62-4752-a389-70e0f348c529', 'Музыкальный переход ко сну 🎶', 'Попробуйте успокоить беспричинные вечерние бури с помощью лёгкой классической музыки. Часто этот простой, но действенный приём творит дома чудеса и наполняет комнату умиротворением.'),
  ('3e411b4b-9fe8-4f71-93e2-682182a18dba', 'Чувство вины из-за экранного времени 📺', 'Сегодня из-за своих дел вы позволили малышу посмотреть больше мультфильмов и теперь чувствуете вину? Не корите себя. Иногда цифровая няня — единственный способ уберечь вас от эмоционального срыва.'),
  ('cfe53a47-5049-4180-8a26-333de41ec18f', 'Синдром избирательного слуха 🙉', 'Не слышит, когда вы просите убрать игрушки, но мгновенно улавливает из соседней комнаты шорох обёртки от шоколада? Со слухом всё в порядке — просто малыш слышит то, что ему интересно. Попробуйте произносить правила шёпотом — это привлечёт его внимание.'),
  ('46cb3019-8e96-4dd4-93b2-6c2a4bab0f53', 'Сокровища из карманов 🪨', 'При стирке вы нашли в кармане брюк 2 камня, засохший лист и обломок веточки? Для вас это мусор, а для малыша — ценная коллекция, собранная во время исследования мира. Вместо того чтобы выбрасывать находки, сложите их в небольшую коробку для сокровищ.'),
  ('4c758b24-b5bb-4fba-9fae-76aff0e5119d', 'Маскировка брокколи 🥦', 'Малыш с хирургической точностью вылавливает из супа зелёные овощи? Пищевая избирательность сейчас на пике. Пора заглянуть в план питания и открыть для себя особые хитрые рецепты, которые помогут замаскировать овощи и превратить их в разноцветные котлетки.'),
  ('56a63f2b-c314-4614-a2a4-36e4a75775f5', 'Режиссёр сказки — малыш 🪄', 'Классические книги уже надоели вам обоим. Включите умные сказки и сегодня вечером позвольте малышу направлять сюжет. Спросите: «Куда теперь отправится летающая машина?» — и пусть он уснёт под придуманную им забавную и нелепую концовку.'),
  ('4cbe2cb0-5188-4114-8447-b099245e7121', 'Папа в режиме полёта ✈️', 'Малыш не успел выплеснуть энергию дома и теперь отказывается ложиться. Зовите папу на помощь. Когда он поднимает ребёнка в воздух и изображает самолёт, комнату наполняет смех, а всё накопившееся физическое напряжение исчезает за считаные секунды.'),
  ('9afa0a7d-99d2-4d5f-a4cb-8f47ca178b6a', 'Вдохнуть свободнее в сообществе 💬', 'Вы очень устали и чувствуете себя самой нетерпеливой мамой на свете? Сразу открывайте Сообщество Anacan. Возможность прочитать, что другие мамы сталкиваются с точно такими же абсурдными кризисами, — это огромная психологическая поддержка.'),
  ('bd33d5a6-7358-4409-91cf-48f9ce76cb44', 'Бесконечный круг «Почему?» 🌪️', '«Почему птицы летают?», «Почему вода мочит?», «А почему почему?»... Поезд вопросов несётся прямо на вас. Даже если вы устали, старайтесь отвечать логично и кратко. Малыш познаёт тайны Вселенной через ваши слова и интонацию.'),
  ('5940af77-4cae-40d5-a543-2bf3a6668855', 'Побег на природу ⛅', 'Четыре стены сделали раздражительными и малыша, и вас. Вы устали от домашнего хаоса. Проверьте погоду и рекомендации по одежде — и скорее отправляйтесь в парк. Возможность свободно побегать на свежем воздухе моментально прекращает даже самые сильные истерики малыша.'),
  ('7886ad64-9846-4990-9753-652093d6bac5', 'Катастрофа из-за неправильного цвета 🔴', 'Разразилась настоящая буря лишь потому, что вы налили воду не в синий, а в красный стакан? Это не каприз — малыш просто проверяет ваши границы и возможность управлять окружающим миром. Не вступайте в борьбу, поменяйте стакан и поберегите свои силы.'),
  ('bfa1d504-f493-414c-a978-4ad885726ef7', 'Дайте волю эмоциям 📝', 'Никто не замечает, как сильно вы устаёте дома? Дневник настроения — ваш самый тихий и надёжный собеседник. Запишите туда все мелочи, которые сегодня выводили вас из себя, и почувствуйте, как становится легче.'),
  ('1800a436-63cf-4ef5-8469-ebb0dffa942d', 'Искусственный интеллект, реальное решение 🤖', 'У вашего ребёнка появилась странная привычка (например, накручивать волосы на палец), а статьи в интернете вас напугали? Остановитесь. Спросите у ИИ Anacan о настоящей причине, подтверждённой педиатрами, и избавьтесь от лишней паники.'),
  ('3f147988-5fe0-4104-b53b-bcd1de9eb553', 'Логика игры в прятки 🙈', 'Малыш стоит посреди комнаты, закрыв глаза руками, и ждёт, когда вы его найдёте! Логика в 3 года: если я вас не вижу, значит, и вы меня не видите. Сделайте вид, что поверили в эту невинную иллюзию, и начните шумно искать его по всей комнате.'),
  ('e71a10b9-dee7-4968-a1f7-387196804ef0', 'Выключите свет — пригласите сон 🌙', 'Чтобы малыш быстрее уснул, за 1 час до сна выключите в комнате все дополнительные источники света и экраны планшетов. Мелатонин (гормон сна) активно вырабатывается только в тёмной обстановке без гаджетов.'),
  ('2cc2d175-4d74-4e12-832a-3885acc3e55b', 'Цифровая память 🛒', 'Каждый раз забываете что-нибудь купить в магазине? Список покупок уже ждёт вас в приложении. Сразу записывайте туда всё необходимое, чтобы ваш партнёр мог по пути с работы купить именно то, что нужно, а вам не пришлось держать всё в голове.'),
  ('8949a363-0fca-4998-bc28-ec5b3f0fc9b2', 'Закон «Я сам!» 👟', 'Малыш хочет самостоятельно завязать шнурки, а вы уже на 10 минут опаздываете с выходом из дома. Не торопите его. Для развития ребёнка сохранённая уверенность в себе важнее, чем нарушенное расписание.'),
  ('b6dabad1-9ff8-435e-b107-865df601701d', 'Мистическая сила шёпота 🤫', 'Малыш так активен в кровати, что никак не может уснуть. Вместо того чтобы повышать голос, внезапно понизьте его и начните говорить шёпотом. Когда ребёнок сосредоточится, чтобы вас услышать, его мозг автоматически начнёт переключаться в режим сна.'),
  ('d319859d-6f77-4ec4-b4f9-90c9441fac9e', 'Следы развития 📈', 'В 3 года моторика, словарный запас и эмоциональный интеллект малыша стремительно развиваются. Чтобы не забыть его маленькие открытия, регулярно фиксируйте и сохраняйте их в Трекере развития.'),
  ('01326cb0-274c-49ad-8b92-7ce1373a0568', 'Извиняется и снова делает то же самое 🧸', 'Он искренне извиняется за то, что ударил кого-то или что-то сломал, но через 5 минут повторяет то же самое? Малышу пока трудно контролировать свои импульсы. Терпеливо объясняйте правило снова и снова.'),
  ('1efb2536-bf55-4365-890d-581fbbac3193', 'Когда хочется выговориться 💬', 'Вам нужно принять непростое решение? (Детский сад, горшок, сон). Советы опытных мам из Сообщества Anacan — это самые практичные, проверенные жизнью решения, о которых не прочитаешь ни в одной книге.'),
  ('d2d2c46d-7705-4c59-b1ff-a6a3d0986863', 'Пусть он придумает конец сказки 🪄', 'Вы оба устали от классических книг. На этот раз предложите малышу самому выбрать финал истории в Умных сказках. Спросите: «Как ты думаешь, кто помог герою?» — и перед сном дайте волю его воображению.'),
  ('37e65e72-e2dc-4492-b8ea-92aeab4db745', 'Здоровая мама — здоровый малыш 🥑', 'В ежедневной суете не обедайте на ходу. Сядьте и с удовольствием съешьте необычный салат, богатый железом и кальцием. Ваша энергия — двигатель этого дома, берегите её.'),
  ('9a78401e-398c-45fd-a3a7-dae1cd59ed31', 'Тишина в цифрах 🤫', 'После шумного дня, когда малыш уснёт, измерьте тишину в комнате с помощью Шумомера. Даже вид цифр, приближающихся к нулю, действует на мозг мамы как лучший визуальный массаж.'),
  ('ba7f66f9-da13-4eea-9e4a-a968d14f269b', 'Маленький помощник на кухне 🧑‍🍳', 'Пока вы раскатываете тесто, малыш наверняка придвинет стул и захочет участвовать. Дайте ему пластиковую миску и разрешите насыпать в неё муку. На кухне будет беспорядок, но его серьёзное, деловое выражение лица стоит всей последующей уборки.'),
  ('06f0acb2-a541-42e5-8b33-ed2285d3285f', 'Благодарите друг друга 🥂', 'Непростой день позади. Когда малыш уснёт, налейте себе чаю вместе с партнёром и поблагодарите его: «Ты очень помог мне в этот бурный день». Так рождается командный дух.'),
  ('4217bad1-d028-470b-a2a2-ceacb5b15105', 'Искусственный интеллект, реальный ответ 🤖', 'Каковы научно обоснованные и подтверждённые педиатрами причины кризиса 3 лет? Вместо того чтобы читать пугающие комментарии в интернете, попросите Anacan AI провести точный и профессиональный анализ психологии малыша.'),
  ('50050f6d-75e8-48b1-9632-bcebb31ce6fa', 'Сенсорная перегрузка 🔋', 'Весь день малыш карабкался по вам, тянул за волосы и шумел. Ваша нервная система подаёт сигнал тревоги. Усталость от прикосновений абсолютно реальна. Оставьте малыша с партнёром и ненадолго уединитесь в комнате.'),
  ('0efdad7b-f986-4a21-8e04-fc9cffca1b7d', 'Забавное произношение 🗣️', 'Малыш произносит слова с такими необычными и своеобразными интонациями, что трудно не рассмеяться. Не поправляйте его со смехом. Внимательно выслушайте и просто ответьте, повторив фразу правильно.'),
  ('6d1f309e-d64f-4916-a1e2-48f064024563', 'Как ничего не забыть в магазине 🛒', 'Понадеялись на память, пошли в магазин и вернулись без подгузников? Такое бывает. Возьмите за привычку сразу добавлять всё необходимое в Список покупок — пусть цифровая память выручает вас.'),
  ('b478188b-090e-49fa-8067-44d7985fc9d2', 'Выплесните эмоции на бумагу 📝', 'Никто не замечает, как сильно вы устали? Дневник настроения всегда готов вас выслушать. Запишите в него все мелочи, которые сегодня выводили вас из себя, и освободите голову от лишних мыслей.'),
  ('51755ad7-f4a2-46b5-9170-1977fdac0046', 'Условия для выработки гормона сна 🌙', 'Чтобы малышу было легче уснуть, за 1 час до сна выключите все дополнительные источники света и экраны планшетов. Гормон сна лучше вырабатывается в тёмной обстановке без гаджетов.'),
  ('556d15ad-f396-4daf-9a38-c5bd773f19f0', 'Свобода в парке 🌳', 'В четырёх стенах малыш становится раздражительным. С помощью помощника «Погода и одежда» подберите подходящий для ветреной погоды комплект и отправляйтесь в парк. Пусть малыш испачкается в песке, бегает и падает. Свобода — лучшее средство для его развития.'),
  ('b2f0448e-4bda-4f45-8af5-d1f543150cda', 'Неожиданные объятия 💖', 'Играя посреди комнаты, малыш вдруг смотрит на вас, подбегает и обнимает за шею. Ради этого стоили все бессонные ночи и усталость! Насладитесь глубоким и неповторимым умиротворением, которое дарит этот момент.'),
  ('354da7a1-73e7-4191-ab3d-5f7d75ac4224', 'Появляется понимание времени ⏱️', 'Часто использует слова «завтра», «вчера», «потом», но иногда путает их? Так формируется восприятие времени! С улыбкой слушайте эти попытки.'),
  ('8b9fda41-95cb-4937-8a79-67166a02c4b7', 'Перерыв для мамы ☕', 'Когда малыш играет самостоятельно, не спешите сразу заниматься домашними делами. Беспорядок никуда не убежит, а вот ваша энергия может закончиться. Присядьте и выпейте горячий кофе.'),
  ('c1a7e066-6918-4641-ab6d-c5c20c553974', 'План побега из кроватки 🛌', 'Пытается перелезть через бортик кроватки? Ещё раз проверьте безопасность комнаты. Возможно, уже пора переходить на кровать для детей постарше.'),
  ('46401ae3-aa9a-4ec9-afa2-b6cab38572ff', 'Воображаемые сценарии 🧸', 'Кормит и лечит игрушки? Символические игры закладывают основу эмпатии. С гордостью отметьте этот когнитивный скачок в трекере развития.'),
  ('4cba464d-475d-46de-93c9-1a54b6d0a768', 'Волшебный фон для сна 🪄', 'Малышу трудно заснуть? Превратите новые привычки в увлекательную историю: создайте в «Умных сказках» рассказ о медвежонке-герое, который чистит зубы.'),
  ('7ef518fa-cecf-4467-bd34-eb7fb3a21761', 'Общение в парке 🌳', 'Вместо того чтобы играть с другими детьми, малыш играет в свою игру рядом с ними? Параллельная игра совершенно естественна для этого возраста. Поддерживайте социализацию без давления.'),
  ('85dcc8b6-3ff2-43d3-9d96-7c1edd51dcff', 'Детектив по брокколи 🥦', 'Находит в супе единственный зелёный овощ и отказывается есть? В плане питания найдите самые вкусные способы отвлечь внимание и замаскировать полезные продукты, смешав овощи с разноцветными макаронами.'),
  ('9d17ee0d-df59-4f5d-b9e7-c0b06e40eb21', 'Признание в чувствах 📝', 'Вам тяжело оттого, что весь день приходится на всё отвечать «нет»? Откройте дневник настроения. Сегодня без всяких фильтров запишите даже самую мрачную мысль: «Как же я хочу побыть одна». Не вините себя: каждая мама иногда устаёт и хочет от всего сбежать.'),
  ('df69592f-4c0f-4591-8df6-51164eef4e12', 'Это не моя вина! 🤷‍♂️', 'Намеренно пролил воду на пол, а потом свалил вину на стол, сказав: «Стол сдвинулся»? Это не ложь, а инстинктивная попытка детского мозга избежать ответственности и защитить себя. Не спорьте. Скажите: «Давай поможем столу и вместе всё вытрем», — так вы мягко научите малыша ответственности.'),
  ('7ac03452-73e8-4680-9a3a-f2917f96ee7f', 'Психология четырёх стен ⛅', 'Домашняя обстановка давит на вас, а малыш становится агрессивным. Проверьте погоду, подберите подходящую одежду и скорее отправляйтесь в парк. Свежий воздух и свобода движения станут лучшим детоксом и для детского мозга, и для ваших уставших нервов.'),
  ('ab102c70-f16b-4f7f-8521-b11e20c36d7a', 'Операция «Сложить бельё» 🧺', 'Вы с большим трудом складываете чистое бельё, а малыш за 2 секунды забирается в него и всё разбрасывает. В комнате воцаряется тишина... Нервы на пределе? Глубоко вдохните. Бросьтесь на груду разбросанной одежды и со смехом капитулируйте перед этим хаосом.'),
  ('e3d6247b-8c6f-4322-9f82-93d3245cab38', 'Режиссёр «Умной сказки» 🪄', 'Вам обоим уже надоели герои классических книг. Откройте «Умные сказки» и сегодня вечером позвольте малышу придумать сюжет. Спросите: «Куда теперь отправится летающий динозавр?» — и пусть малыш засыпает в созданном им воображаемом мире.'),
  ('62178f50-5d62-4afb-bacf-33c6e7bf5732', 'Папин режим полёта ✈️', 'Малыш не успел выплеснуть энергию дома и придумывает тысячу причин, лишь бы не ложиться спать. Позовите папу. Когда он поднимает малыша в воздух и изображает полёт самолёта, комната наполняется смехом, а всё накопившееся физическое напряжение исчезает вместе с активным движением.'),
  ('7338bae4-7d68-4f02-8b9f-7e3603f62bb9', 'Удар словами «Ты плохая мама!» 💔', 'Не купили желанную игрушку, и малыш, глядя вам в лицо, сказал: «Ты плохая»? Не принимайте это близко к сердцу. Он пока не умеет правильно выражать чувства словами, а на самом деле хочет сказать: «Я очень злюсь и расстроен». Установите зрительный контакт и просто дайте понять, что принимаете его эмоции.'),
  ('c4d16b0b-f2b1-40f5-8462-8e7c3419883e', '«Я сам повезу!» в магазине 🛒', 'Малыш хочет сам везти тележку, врезается в полки и привлекает всеобщее внимание. А при каждой вашей попытке вмешаться начинает плакать. Везите тележку вместе. А чтобы ничего не забыть, держите активным «Список покупок» в приложении — так ваш мозг будет меньше уставать.'),
  ('159b5a7f-d190-47d4-8cda-ba692f07b0d0', 'Тишина шумомера 🤫', 'Малыш наконец-то уснул! В доме воцарилась такая глубокая тишина, что звенит в ушах. Включите шумомер и, глядя на показатель 0-10 децибел на экране, почувствуйте, как ваш мозг постепенно восстанавливается.'),
  ('c583d30d-5142-4b40-bcb3-399830284928', 'Пачкаться разрешается 🏖️', 'Хочет играть с грязью и песком? Пусть испачкается! Всё необходимое для таких занятий, поддерживающих сенсорное развитие, вы найдёте в разделе «Рекомендуемые товары». Выбирайте то, что проще всего мыть, и позвольте малышу играть в своё удовольствие.'),
  ('0446eb50-5fac-4056-ad65-76a95baf67f3', 'Битва с тенью 👻', 'Малыш пугается своей тени на стене и прячется за вами? Воображение не знает границ. Затемните комнату и с помощью фонарика устройте на стене театр теней, складывая руками разные фигуры.'),
  ('b090e002-92d1-408a-8249-476d9566115b', 'Засыпаем под музыку 🎶', 'Попробуйте успокоить вечерние капризы без видимой причины с помощью лёгкой классической музыки. Этот простой, но действенный приём часто творит дома чудеса и наполняет комнату умиротворяющим спокойствием.'),
  ('ba177a78-642c-483b-9a15-4d4a68a758af', 'Сигналы тела 🩸', 'Не поддавайтесь беспричинной раздражительности и усталости. Загляните в Трекер менструации — ваше тело подаёт сигнал. Вместо того чтобы винить себя, отдохните и перекусите чем-нибудь богатым магнием.'),
  ('1a2422fa-5d4e-4bbc-9f26-d69dd838496d', 'Намеренно меняет слова 🗣️', 'Упорно говорит «шамина» вместо «машина» и ждёт, что вы засмеётесь? Малыш уже открывает для себя чувство юмора. Смейтесь вместе, но не забывайте каждый раз мягко подчёркивать правильное произношение, чтобы мозг запоминал и верный вариант.'),
  ('21b5ead3-32a1-4d0e-96a9-1e38bf19fcec', 'Мама, не забывайте поесть 🥗', 'Вы приготовили малышу яйца 4 разными способами, но что поели сами? Наградите себя особым блюдом из раздела полезных рецептов: оно готовится за 5 минут и богато железом и кальцием. Позаботьтесь о себе и сохраните энергию.'),
  ('cc6b3853-5963-47b7-b4f5-310bfd1919c2', 'Как малыш оттягивает сон ⏱️', 'Когда приходит время спать, малыш внезапно хочет пить, просится в туалет или начинает прощаться со стеной? Поставьте таймер. Введите правило «звонок прозвенел — все ложатся спать», чтобы терпеливо и спокойно завершить это бесконечное прощание.'),
  ('629ea652-62bd-4947-96b6-0e7f4cabb751', 'Совещание с игрушками 🧸', 'Малыш выстроил в ряд всех мишек и машинки и с очень серьёзным видом что-то объясняет им, указывая пальцем? Так формируются лидерские качества и внимание. Постойте в стороне и молча понаблюдайте за этим воображаемым собранием, не мешая малышу.'),
  ('8fdbd74e-0b03-4420-a816-6a0ea6ecdb73', 'Странные звуки папы 🤡', 'Когда ваши приёмы уже не помогают, странные звуки животных и смешные гримасы папы мгновенно спасают ситуацию. Во время вечерних капризов передайте инициативу ему, а сами наблюдайте со стороны за весёлым хохотом.'),
  ('b32c30b6-11a0-4afc-aed3-bdfb0cc56622', 'Бунт против дневного сна 🥱', 'Не хочет ложиться и плачет? Не заставляйте. Приглушите свет в комнате и объявите тихий час для рассматривания книг. Так вы создадите новый ритуал, который поможет отдохнуть и вам, и малышу.'),
  ('07209316-984c-477d-a3c0-ff2c7202c5fa', 'Мысли о детском саде 🏫', 'Чувствуете, что малышу уже нужно больше общения? Подходящее ли сейчас время для детского сада? Вступите в Сообщество Anacan и прочитайте реальные истории других мам об адаптации — это поможет вам принять решение.'),
  ('3f7992d5-c092-46f7-84f8-f10e51f36593', 'Внезапная вспышка гнева 💥', 'Во время игры малыш вдруг разозлился и начал разбрасывать игрушки? Он ещё не умеет управлять своими эмоциями. Вместо крика проявите сочувствие и сохраняйте контакт, сказав: «Я вижу, что ты злишься. Давай вместе глубоко подышим».'),
  ('a376f906-e66c-4618-827e-79f3b75ebd16', 'Беспокоится, когда в спальне гаснет свет? 🌙', 'Поставьте в углу комнаты небольшой ночник тёплого оттенка. При этом остальная часть комнаты должна оставаться полностью тёмной для глубокого сна.'),
  ('171bedf4-3516-44a5-9404-c089661d5bbd', 'Разговоры с неодушевлёнными предметами 🗣️', 'Малыш совершенно серьёзно что-то рассказывает камню в парке или стулу дома и даже ругает их? С помощью символической игры он осмысливает окружающий мир. Обязательно отмечайте такие необычные сценарии в Трекере развития.'),
  ('a74f3aea-565f-455f-bdbe-9ee44f6c7e35', 'Чудо тёплой воды 🛀', 'Иногда ничего не помогает, и малыш просто плачет по любому поводу. Посадите его в ванну с тёплой водой и добавьте немного пены. Волшебная способность воды снимать напряжение мгновенно принесёт спокойствие всей комнате и поможет нервной системе малыша расслабиться.'),
  ('b4c6b7ac-81bd-476f-9816-9e8c14627206', 'Погодное предупреждение ⛅', 'Собираясь на прогулку, не обманывайтесь видом из окна. С помощью помощника по погоде и одежде подберите комплект, который лучше всего соответствует реальной температуре и ветру на улице. Вы сможете выйти из дома спокойно и подготовленно, а малыш — выплеснуть энергию на свежем воздухе.'),
  ('2fc82c8d-f425-4306-866a-3f621177b592', 'Критик мультфильмов 📺', 'Он пересказывает вам просмотренный мультфильм по-своему и с серьёзным видом объясняет, кто и куда пошёл. Слушайте его внимательно и с удивлением. Позвольте ему почувствовать себя самым умным на свете.'),
  ('63daef22-cfd1-421f-8f7d-267873d17f9e', 'Совершенства не существует 🛑', 'Сегодня всё пошло не по плану? Не вините себя. Вы настоящая мама, а не отфильтрованная иллюзия из социальных сетей. Вашему ребёнку нужны лишь ваша улыбка и объятия.'),
  ('e3cb9a40-b6ca-4e32-b4da-ab6d4899625b', 'Разгадка ночного страха 😭', 'Малыш проснулся посреди ночи, плачет с закрытыми глазами и никого не слышит. Проверьте это с помощью анализа плача: если это ночной страх, не пытайтесь его разбудить. Просто будьте рядом и молча дарите чувство безопасности.'),
  ('10d94f4d-5823-4afc-963c-ff0397bf1a29', 'Просто обнимите 🫂', 'Не нужны ни игры, ни книги, ни сказки. Сегодня вечером просто прижмите малыша к груди, вдохните его чудесный запах и прошепчите в темноте, как он вам дорог.'),
  ('3860d960-f463-4c1e-873a-4917b9b7c101', 'Запретные слова 🤐', 'Он со смехом повторяет услышанное где-то плохое слово и ждёт вашей реакции? Ваше главное оружие — отсутствие реакции. Не смейтесь, не сердитесь, просто проигнорируйте. Вскоре он забудет это слово.'),
  ('fbd7d1b9-4e13-463d-80fa-fbbd34869d9e', 'Разрешение на беспорядок 🌪️', 'Устали каждый день собирать одни и те же игрушки? Сегодня не убирайте! Дом — не музей, а место, где кипит жизнь. Отдохните и сосредоточьтесь не на беспорядке, а на радости ребёнка от свободного познания мира.'),
  ('267500b1-a84b-4046-a247-9d2097325550', 'Посмотрите вниз: что он исследует? 👣', 'Ему нравится ходить босиком, касаться ногами ковра или камешков в комнате. Стимуляция нервных окончаний на стопах очень важна для равновесия и моторики, поэтому разрешайте ему ходить без носков.'),
  ('2b6e6b05-f741-49ca-84e3-fa8deb8b2661', 'Перерыв для двоих 🥂', 'Ребёнок уснул. Теперь отложите домашние дела. Хотя бы 20 минут поговорите с партнёром о чём угодно, кроме ребёнка и расходов. Вы не только родители, но ещё и пара!'),
  ('9d8da9d6-f615-4275-a01c-20687a161090', 'Спасение в супермаркете 🛒', 'Отправляясь в супермаркет, вы обязательно забываете самое важное? Список покупок уже ждёт вас в приложении. Записывайте туда всё необходимое, чтобы партнёр по дороге с работы купил именно то, что нужно, а вам не пришлось держать всё в голове.'),
  ('2b451101-7b49-4ea1-a25f-f07ea36f7e85', 'Выплесните раздражение в дневнике 📝', 'Кто-то сказал вам: «Ты же сидишь дома, от чего тебе уставать?» Сразу откройте Дневник настроения и выплесните всё раздражение на экран. Записывать свои настоящие чувства гораздо полезнее, чем изображать улыбку: это своего рода терапия.'),
  ('5163d6f3-dfbf-4dc7-9c33-5c739a29b5c5', 'Сейчас я вам объясню! ☝️', 'Он подходит и с очень серьёзным и умным выражением лица объясняет вам то, что вы и так знаете. Так он проверяет свои знания. Даже если вам трудно удержаться от смеха, выслушайте его со всей серьёзностью и поддержите его мысль.'),
  ('62a5480b-e62d-48dc-a56f-7c512e104949', 'Цифровое измерение тишины 🤫', 'Он наконец-то уснул! Вы не можете поверить в тишину, воцарившуюся дома. Включите шумомер и, глядя на цифру 0-10 децибел на экране, почувствуйте, как ваш мозг постепенно отдыхает.'),
  ('523ef85e-fa2f-49a1-b3f9-34f2d35d22a1', 'Разведка погоды ⛅', 'Не совсем понятно, какая погода на улице? Инструмент погоды и подбора одежды мгновенно подскажет скорость ветра, которую не определить из окна, и поможет выбрать подходящий комплект.'),
  ('5b3dc48b-525e-45b8-ba47-dd1abb851741', 'Сам снимает обувь 👟', 'Одевание уже превратилось в борьбу? Он сам стягивает носки и обувь. Восхититесь его моторными навыками!'),
  ('cd7f1c0e-ee93-462d-ae3c-cb3021a5d6c8', 'Поддержка папы 🫂', 'Когда ребёнок просыпается ночью, вставайте по очереди: один раз вы, другой — ваш партнёр. Разделите нагрузку поровну и действуйте как одна команда.'),
  ('3522ca83-324c-49f9-ba7a-ffdc8c379ba2', 'Туалет, прогоняющий сон 🚽', 'Он уже почти уснул, но внезапно говорит, что хочет в туалет. Вы ведёте его, а ничего не происходит. Это одна из самых тонких тактик искусства откладывать сон. Не кричите, а чётко обозначьте границу: «Идём в последний раз и сразу возвращаемся в постель».'),
  ('ece2fe16-c57e-4a1f-a594-5e39da1118d6', 'Поддержка сообщества 💬', 'Вы очень устали и не хотите никому ничего объяснять. Зайдите в сообщество Anacan и просто побудьте читателем. Похожие истории об усталости других мам и забавных детских истериках подарят вам успокаивающее чувство: «Я не одна».'),
  ('fabbf657-c431-4c98-ba31-613ca3dc8a47', 'Маленький повар на кухне 🧑‍🍳', 'Пока вы раскатываете тесто, малыш непременно придвинет стул и вмешается в процесс. Дайте ему пластиковую миску и разрешите насыпать в неё немного муки. На кухне будет беспорядок, но его серьёзное, деловитое выражение лица и чувство «Я тоже умею!» стоят всей последующей уборки.'),
  ('7e88dfb0-8648-40c5-a6ab-3a3cf4987fb3', 'Гордость за надетое наоборот 🧦', 'Пятка носка оказалась сверху, но малыш гордо ходит в нём, потому что надел его сам. Ни в коем случае не вмешивайтесь. Чувство «Я справился!» — психологическая основа, которая в миллион раз важнее красоты или правильно надетой одежды. Пусть он так и проведёт день.'),
  ('ca2fd133-6b0b-4852-a4b2-b830a12f0bc0', 'Offline-минуты для мамы ☕', 'Малыш уже 10 минут тихо собирает пазл, а вы хотите потратить это время на уборку. Нет! Идите и прилягте на диван. Вам тоже нужно зарядить батарейки, чтобы выдержать такой темп до вечера.'),
  ('e264b682-e7a9-4579-80a1-6e47fe7bccb3', 'Подружиться с темнотой 🐰', 'Малыш не хочет засыпать и говорит, что боится теней в комнате? Полностью выключите свет и покажите на стене тени птицы или собаки, сложив руки. Превратив страх в игру, вы поможете ему подружиться с темнотой и научиться управлять своим воображением.'),
  ('03f9e2c0-9e7a-47b1-892e-0261f73bfa13', 'Искусственный интеллект и тревоги 🤖', 'Вы переживаете из-за того, что ребёнок всё ещё не может правильно произносить некоторые звуки? Закройте пугающие форумы в интернете. Спросите у Anacan AI о нормах развития речи в возрасте около 38 месяцев и получите научно обоснованный и реалистичный ответ.'),
  ('8c0fa05b-b55a-47a2-b4af-b9fb41bdabf9', 'Ты будешь ребёнком, а я — мамой 👩‍👧', 'Игра с обменом ролями началась! Малыш командует вами: «Иди сюда», «Ешь», «Не плачь». С удовольствием поддержите его первый опыт лидерства и молча сыграйте роль его ребёнка. Это один из основных способов развития эмпатии.')
) AS v(id, t, b)
WHERE x.id = v.id;
